func TestStackReparentValidate_Rule14MissingLimitFailure(t *testing.T) {
	cmd := stackReparentCmd()
	if err := cmd.Flags().Set("onto", "main"); err != nil {
		t.Fatal(err)
	}
	if err := cmd.Flags().Set("approve-plan", strings.Repeat("a", 64)); err != nil {
		t.Fatal(err)
