func statusCmd() *cobra.Command {
	var jsonOutput bool

	cmd := &cobra.Command{
		Use:   "status [feature]",
		Short: "Show agent work status for every logical branch",
		Long: `Report what tws knows about each logical branch: whether it is materialized,
whether a tws-launched session is running, and whether anything needs
attention.

Scope. With no argument the report always covers every feature in the resolved
workspace, from any working directory. It is never scoped by your current
location — pass a feature name to filter. (This deliberately differs from
'tws space list', which is cwd-scoped.)

Your working directory selects which workspace is resolved; it never changes
what the report says about that workspace. Run from the repository, from a
worktree, or from the workspace root and the reported features, entries, and
issues are identical.

Two axes, never collapsed. 'runtime_presence' answers "is a tws-owned runtime
alive?" (present, absent, stale, unknown). 'agent_state' answers "what is the
agent doing?" (working, ready, blocked, done, unknown) and is always 'unknown'
at this version: tws launches agents but does not observe their turns. Use
'needs_attention', which is authoritative, to decide where to intervene.

Exit status is 0 whenever a report was produced, including when branches need
attention or operational state is stale or corrupt. A non-zero exit means no
report could be produced at all.

--json prints one versioned document with a stable key set; absent values are
null and lists are never null.`,
		Args: cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			// Flag and argument errors keep their usage block; a runtime
			// failure must not spray usage into a polled surface's output.
			cmd.SilenceUsage = true

			ws, degradedReason, err := internal.ResolveStatusWorkspace()
			if err != nil {
				return err
			}

			feature := ""
			if len(args) == 1 {
				feature = args[0]
				// Guard the caller-supplied name against a registered space
				// before any path join, stat, record read, or tmux probe. The
				// guard root is the root the subsequent reads join against.
				if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
					return gerr
				}
			}

			report, err := internal.BuildAgentStatus(ws, degradedReason, nil)
			if err != nil {
				return err
			}
			for i := range report.Features {
				f := &report.Features[i]
				f.Reparent = reparentProjectionFor(ws, f.Feature, f.Path)
			}
			if feature != "" {
				if ferr := report.FilterFeature(feature); ferr != nil {
					return ferr
				}
			}
			// §11.10 rule 1: the anchored line precedes every stdout write.
			// The report itself is already built read-only; this is a pure
			// projection of what it measured.
			for _, f := range report.Features {
				if f.Reparent != nil {
					_, _ = fmt.Fprintln(cmd.ErrOrStderr(), f.Reparent.ObservabilityLine())
				}
			}
			internal.NormalizeAgentStatus(report)

			if jsonOutput {
				enc := json.NewEncoder(cmd.OutOrStdout())
				enc.SetIndent("", "  ")
				return enc.Encode(report)
			}
			_, _ = fmt.Fprint(cmd.OutOrStdout(), internal.FormatAgentStatus(report))
			return nil
		},
	}

	cmd.Flags().BoolVar(&jsonOutput, "json", false, "Output as JSON")
	return cmd
}

package cli

import (
	"fmt"
	"io"
	"os"
	"sort"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

// syncLongText is the exact, normative §3.1a command Long. Short stays
// "Rebase branches in dependency order", unchanged.
const syncLongText = `Rebase the feature's branches in dependency order.

--plan describes the rebase this invocation would perform and then exits. It moves
no branch, rewrites no working tree, and writes no tws runtime state. It is not
Git-write-free: a plan fetches exactly where the run it describes fetches — an
external plan fetches by default, a checkout plan only with --fetch — and may
update remote-tracking refs, FETCH_HEAD, tags and covered local branches. Add
--no-fetch for a fully local preview — that previews a different, new-mode route,
not the route a bare "tws sync <feature>" takes.

--max-replay-per-entry and --max-replay-total bound the work of this invocation
only — the whole plan on a fresh run, the remaining work on --continue — and are
never cumulative across resumes. --approve-plan takes the fingerprint printed by
--plan and requires at least one of those limits.

A guarded run — one carrying a replay limit or --approve-plan — records its limits
in state_version 3 recovery state, so an older tws release refuses to resume it
instead of resuming it without the guard. When the guard itself refuses, the run
exits 1 and writes one "plan-guard: <kind>: <detail>" line on stderr, before any
branch has moved unless that line says "state-preserved:". Refusals tws already
performs — a dirty tree, a held lock, a base that does not resolve locally, an
incomplete previous run — keep their own wording, exit 1 without that line, and
are never marked.`

func syncCmd() *cobra.Command {
	var verbose bool
	var push bool
	var cont bool
	var abort bool
	var testCmd string
	var doFetch bool
	var noFetch bool
	var full bool
	var localOnly bool
	var only string
	var from string
	var plan bool
	var planJSON bool
	var maxPerEntry int
	var maxTotal int
	var approvePlan string

	cmd := &cobra.Command{
		Use:   "sync <feature>",
		Short: "Rebase branches in dependency order",
		Long:  syncLongText,
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")

			// §3.3 step 3 / §3.6 row 4: the control-flag validation is a PURE
			// command-line check over cmd's own flags, so it runs ABOVE
			// subject resolution. An early control error therefore refuses
			// before any workspace probe — zero git child processes, zero
			// state read — which is exactly what §22 criteria 3-7 assert.
			guardOpts, err := resolvePlanGuardOptions(cmd)
			if err != nil {
				return err
			}

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			// Pure command-line checks (I1-I8) run before mode dispatch so both
			// modes reject identically and identically early.
			policy, newMode, changed, err := resolveSyncPolicy(cmd, ws.Mode)
			if err != nil {
				return err
			}

			// §11.2's ONE new pre-check. It sits after GuardFeatureName and a
			// mode-appropriate safe path resolution and BEFORE mode dispatch
			// (:93), plan dispatch and classifySyncState, so it covers
			// `--plan`, plain, `--continue` and `--abort` in both modes. The
			// detailed reparent artifact is therefore what the operator hears
			// about, never the v4/undecodable compatibility files it guards.
			//
			// It spawns zero Git children and adds one os.Stat on a feature
			// with no reparent artifact, which is what keeps every no-flag
			// golden and its argv sidecar byte-identical.
			feature := args[0]
			var twsRoot string
			var reparentFeaturePath string
			if ws.Mode == internal.ModeCheckout {
				if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
					return gerr
				}
				reparentFeaturePath, err = ws.ResolveFeaturePath(feature)
				if err != nil {
					return err
				}
			} else {
				twsRoot = internal.TwsRoot()
				if gerr := internal.GuardFeatureName(twsRoot, feature); gerr != nil {
					return gerr
				}
				lay, lerr := resolveExternalSyncLayout(ws, twsRoot, feature)
				if lerr != nil {
					return lerr
				}
				reparentFeaturePath = lay.FeaturePath
			}
			if rerr := internal.RefuseSyncIfReparentActive(
				internal.ReparentLocationFor(ws, feature, reparentFeaturePath)); rerr != nil {
				return rerr
			}

			if ws.Mode == internal.ModeCheckout {
				return runCheckoutSync(cmd, ws, internal.CheckoutSyncOpts{
					Feature:     args[0],
					Push:        push,
					TestCommand: testCmd,
					Verbose:     verbose,
					Policy:      policy,
					NewMode:     newMode,
					Continue:    cont,
					Abort:       abort,
					Changed:     changed,
					PlanGuard:   guardOpts.checkoutGuard(),
				})
			}

			// One guard covers the plain, --abort, and --continue paths.
			// syncFeature carries none: it has no error channel and would
			// degrade the message to "sync incomplete".
			//
			// The identity, the guard and twsRoot were hoisted above the
			// checkout dispatch by the pre-check; resolveExternalSyncLayout is
			// called again here, unchanged, because its contract is that it
			// issues no Git command and performs at most two ordinary
			// stack.yaml reads. Keeping this call is what preserves the frozen
			// external resolution sequence for every existing golden.
			layout, layoutErr := resolveExternalSyncLayout(ws, twsRoot, feature)
			if layoutErr != nil {
				return layoutErr
			}

			state, stateErr := classifySyncState(layout.FeaturePath, newMode)

			// Plan dispatch (§3.3 step 6): below classifySyncState, above
			// deferred I7. A --plan always reaches the document route.
			//
			// The I18 symlink refusal is a MUTATING-route gate: a symlinked
			// runtime-state artefact is a controlled-path fact the plan
			// DESCRIBES (`presence: symlink` plus the
			// owner-artefact-undecodable token, §12.5), never one it refuses
			// over, so the plan route consumes the classifier's own recorded
			// facts and lets the guarded twin be the refusing party (§22.13m).
			if guardOpts.Plan {
				if stateErr != nil && !syncStateSymlinkOnly(stateErr) {
					return stateErr
				}
				return runExternalPlan(cmd, feature, layout, ws, policy, newMode, push, verbose, changed, guardOpts, state, cont)
			}
			// §12.5/§22.13m: on the PLAIN verb the symlink fact is described
			// and adjudicated by the guard seam (guarded) or read straight
			// through by the shipped native ladder (unguarded); only the
			// recovery verbs keep the shipped I18 refusal, which they alone
			// are asserted on.
			if stateErr != nil && (!syncStateSymlinkOnly(stateErr) || cont || abort) {
				return stateErr
			}

			return planGuardRefusal(cmd, dispatchClassifiedSync(cmd, feature, layout, ws, policy, newMode, push, verbose, cont, abort, changed, guardOpts, state))
		},
	}

	cmd.Flags().BoolVarP(&verbose, "verbose", "v", false, "Show full git fetch output")
	cmd.Flags().BoolVar(&push, "push", false, "Push all branches after syncing")
	cmd.Flags().BoolVar(&cont, "continue", false, "Resume after conflict resolution")
	cmd.Flags().BoolVar(&abort, "abort", false, "Discard sync state and start fresh")
	cmd.Flags().StringVar(&testCmd, "test", "", "Validation command to run after each rebase (checkout mode)")
	cmd.Flags().BoolVar(&doFetch, "fetch", false, "Fetch before planning (external default)")
	cmd.Flags().BoolVar(&noFetch, "no-fetch", false, "Plan and rebase from local refs only; no automatic network input (checkout default)")
	cmd.Flags().BoolVar(&full, "full", false, "Advance anchors onto their configured base (default)")
	cmd.Flags().BoolVar(&localOnly, "local-only", false, "Replay local parent tips into children; never advance an anchor")
	cmd.Flags().StringVar(&only, "only", "", "Sync exactly one stack entry by its logical name")
	cmd.Flags().StringVar(&from, "from", "", "Sync one stack entry and its descendant closure, by logical name")
	cmd.Flags().BoolVar(&plan, "plan", false, "Describe the rebase this invocation would perform, then exit; moves no branch, working tree or tws state, but still fetches wherever the route it describes fetches (see --no-fetch)")
	cmd.Flags().BoolVar(&planJSON, "json", false, "Emit the plan document as JSON on stdout (requires --plan)")
	cmd.Flags().IntVar(&maxPerEntry, "max-replay-per-entry", 0, "Refuse before rebasing if any entry of this invocation replays more than N candidates (this invocation only; a guarded run records its limits in recovery state older tws releases refuse to resume)")
	cmd.Flags().IntVar(&maxTotal, "max-replay-total", 0, "Refuse before rebasing if this invocation replays more than N candidates in total (this invocation only; a guarded run records its limits in recovery state older tws releases refuse to resume)")
	cmd.Flags().StringVar(&approvePlan, "approve-plan", "", "Approve the exact plan with the fingerprint printed by --plan (requires a replay limit)")

	_ = cmd.RegisterFlagCompletionFunc("only", syncEntryCompletion)
	_ = cmd.RegisterFlagCompletionFunc("from", syncEntryCompletion)

	return cmd
}

// dispatchClassifiedSync is the classified-state half of RunE (spec §3.3
// step 6 onward, exploration §2.1 insertion points 5-9, 11): deferred I7,
// the live-guard precedence, the cell-4 guarded-sentinel interception, and
// the abort/continue/plain split — cell-1 guarded-fresh, cell-5 three-arm,
// and cell-7 two-arm dispatch included.
func dispatchClassifiedSync(cmd *cobra.Command, feature string, layout externalSyncLayout, ws internal.Workspace, policy internal.SyncRunPolicy, newMode, push, verbose, cont, abort bool, changed map[string]bool, guardOpts planGuardOptions, state internal.SyncExternalState) error {
	// Deferred I7 (insertion point 5): cont && abort survived the
	// command-line block, so no trigger flag was supplied. Refuse only
	// against new-mode state.
	if cont && abort && syncStateRefusesContinueAbort(state) {
		return errSyncContinueAbort()
	}

	// Insertion point 6: derive the one shipped syncVerb, apply the live-
	// guard precedence, then the cell-4 guarded-sentinel interception.
	verb := syncVerbPlain
	switch {
	case abort:
		verb = syncVerbAbort
	case cont:
		verb = syncVerbContinue
	}
	if err := syncCellLiveGuardRefusal(feature, state, verb); err != nil {
		return err
	}

	if state.Cell == 4 {
		if err := syncClassifierBarrier(layout.FeaturePath); err != nil {
			return err
		}
		handled, err := dispatchGuardedLegacySentinel(cmd, feature, layout, ws, policy, newMode, push, verbose, cont, abort, changed, guardOpts, state)
		if handled {
			return err
		}
		// internal.SentinelNotGuarded: fall through to the ordinary cell-4
		// flow below, byte-identical to today.
	}

	return dispatchOrdinarySync(cmd, feature, layout, ws, policy, newMode, push, verbose, cont, abort, changed, guardOpts, state)
}

// dispatchOrdinarySync is the ORDINARY post-interception route of §3.3: the
// abort/continue/plain split, with cell-1 guarded-fresh, the cell-5
// three-arm and the cell-7 two-arm dispatch. It is a separate function
// precisely so the vanished-sentinel row of §12.8b can dispatch its ONE
// re-classification here directly: this function evaluates no sentinel view
// and can therefore never re-enter the cell-4 interception, so a
// .sync-state.yaml that keeps appearing and disappearing cannot make the
// command loop, retry or spin (§12.8b rule 3).
func dispatchOrdinarySync(cmd *cobra.Command, feature string, layout externalSyncLayout, ws internal.Workspace, policy internal.SyncRunPolicy, newMode, push, verbose, cont, abort bool, changed map[string]bool, guardOpts planGuardOptions, state internal.SyncExternalState) error {
	if abort {
		if err := syncCellRefusal(syncVerbAbort, feature, layout, state); err != nil {
			return err
		}
		return handleSyncAbortCell(feature, layout, state)
	}
	if cont {
		if err := syncCellRefusal(syncVerbContinue, feature, layout, state); err != nil {
			return err
		}
		// I20 (insertion point 7).
		if newMode && syncTriggersNeedV2(state) {
			return fmt.Errorf("%s", errSyncModeFlagsNeedV2)
		}
		switch {
		// Cell-5 three-arm dispatch (insertion point 8).
		case state.Cell == 5 && externalPersistedGuarded(state.Payload):
			return handleGuardedScopedSyncContinue(cmd, feature, layout, ws, push, policy, changed, guardOpts, state)
		case state.Cell == 5 && guardOpts.Armed():
			// The armed v2 -> v3 upgrade is NOT performed here. §13.2a places
			// it at step 10a — after EvaluatePlanGuard has admitted the run
			// and after the guard reclaim — so an invocation the guard
			// REFUSES leaves the persisted payload byte-identical and the
			// next flagless `--continue` over it is still unguarded.
			// handleGuardedScopedSyncContinue owns that one call site.
			return handleGuardedScopedSyncContinue(cmd, feature, layout, ws, push, policy, changed, guardOpts, state)
		case state.Cell == 5:
			return handleScopedSyncContinue(feature, layout, ws, push, policy, changed, state)
		// Cell-7 two-arm dispatch (insertion point 9).
		case state.Cell == 7 && guardOpts.Armed():
			return handleGuardedLegacySyncContinue(cmd, feature, layout, ws, push, policy, changed, guardOpts, state)
		default:
			return handleSyncContinue(feature, layout, push)
		}
	}
	if err := syncCellRefusal(syncVerbPlain, feature, layout, state); err != nil {
		return err
	}
	if internal.HasSyncState(layout.FeaturePath) {
		legacy, _ := internal.LoadSyncState(layout.FeaturePath)
		return fmt.Errorf("previous sync incomplete (failed on: %s); use --continue or --abort", legacy.FailedBranch)
	}

	// Guarded fresh routes (insertion point 11): opts.Armed() selects
	// runGuardedScopedSync/runGuardedLegacySync; unarmed keeps runScopedSync
	// and syncFeature byte-identical.
	if newMode {
		if guardOpts.Armed() {
			return runGuardedScopedSync(cmd, feature, layout, ws, policy, push, verbose, changed, guardOpts, state)
		}
		return runScopedSync(feature, layout, ws, policy, push, verbose)
	}
	if guardOpts.Armed() {
		return runGuardedLegacySync(cmd, feature, layout, ws, policy, push, verbose, changed, guardOpts, state)
	}

	return withExternalSyncMutationGuard(feature, layout, "", false, func() error {
		result := syncFeature(feature, layout, verbose, nil)
		if !result.Complete {
			return fmt.Errorf("sync incomplete")
		}
		fmt.Println("Sync complete.")
		if push {
			fmt.Println("\nPushing...")
			if err := pushFeature(feature, layout, false); err != nil {
				return err
			}
		}
		return nil
	})
}

// dispatchGuardedLegacySentinel is the cell-4 guarded-sentinel interception
// (spec §12, §13.7a; exploration insertion point 6). syncCellRefusal's own
// cell-4 arm unconditionally refuses a --continue and only allows --abort —
// correct for the ordinary "marker present, no payload" artifact, but wrong
// for a resumable guarded-legacy sentinel, which shares that same on-disk
// shape. handled is true whenever this function has fully answered the
// invocation itself; the caller must return err unchanged and never fall
// through to the ordinary dispatch in that case. handled is false only for
// internal.SentinelNotGuarded, where the ordinary cell-4 dispatch (and
// syncCellRefusal's existing cell-4 message) applies completely unchanged.
func dispatchGuardedLegacySentinel(cmd *cobra.Command, feature string, layout externalSyncLayout, ws internal.Workspace, policy internal.SyncRunPolicy, newMode, push, verbose, cont, abort bool, changed map[string]bool, guardOpts planGuardOptions, state internal.SyncExternalState) (bool, error) {
	view := internal.InspectGuardedLegacySentinel(layout.FeaturePath, feature)
	switch {
	case view.Verdict == internal.SentinelAbsent:
		// §12.8b's vanished-state row. The file the classifier saw is gone,
		// which is absence and not a guarded verdict: reclassify EXACTLY
		// once through the shipped classifier and dispatch that second state
		// through the ordinary, NON-INTERCEPTING route. Nothing here
		// re-reads InspectGuardedLegacySentinel, so a path that reappears
		// can never re-enter this interception (rule 3).
		syncReclassifyCount.Add(1)
		second, err := classifySyncState(layout.FeaturePath, newMode)
		if err != nil {
			return true, err
		}
		return true, dispatchOrdinarySync(cmd, feature, layout, ws, policy, newMode, push, verbose, cont, abort, changed, guardOpts, second)
	case internal.GuardedLegacySentinelResumable(state, view):
		// §12.8b (binding): the interception owns this document's flag
		// validation, because a valid backup sentinel never reaches
		// syncCellRefusal or the I20 gate below it. The check runs ONCE,
		// before the verb's arm, for all three verbs, and composes the
		// SHIPPED I20 sentence byte for byte — removing nothing and writing
		// nothing.
		if syncTriggerFlagSupplied(changed) {
			return true, fmt.Errorf("%s", errSyncModeFlagsNeedV2)
		}
		switch {
		case abort:
			return true, abortGuardedLegacySentinel(feature, layout)
		case cont:
			return true, resumeGuardedLegacySentinel(cmd, feature, layout, ws, policy, changed, guardOpts, state, view.Sentinel)
		default:
			return true, fmt.Errorf("a guarded sync was interrupted while recording state for %q; the previous sync state is preserved inside %s — use --continue to resume it, or --abort to discard it", feature, view.Path)
		}
	case view.Verdict == internal.SentinelNotGuarded:
		return false, nil
	default:
		return true, fmt.Errorf("guarded sync state at %s is unreadable or uses an unsupported version; inspect it and remove it manually — tws will not guess", view.Path)
	}
}

// resumeGuardedLegacySentinel resumes a crash-recovered, already-guarded
// legacy sentinel (cell 4, SentinelValid) directly — no upgrade, no second
// sentinel, no re-plan: the sentinel already carries this run's own
// Universe/PendingIntent/limits from its original birth. It performs only
// §13.2a step 2 (guard claim **or** reclaim) and step 4 (the v3 payload),
// skipping the replacement of step 3, and then enters the payload-aware
// executor so the resumed run persists progress into the envelope exactly as
// its interrupted predecessor would have.
func resumeGuardedLegacySentinel(cmd *cobra.Command, feature string, layout externalSyncLayout, ws internal.Workspace, policy internal.SyncRunPolicy, changed map[string]bool, opts planGuardOptions, state internal.SyncExternalState, sentinel *internal.GuardedLegacySentinel) error {
	args := externalPlanArgs{
		Feature: feature, Layout: layout, Ws: ws, Policy: policy, NewMode: false,
		Push: sentinel.Push, Verbose: false, Changed: changed, Opts: opts, State: state, Continue: true,
		Sentinel:         internal.GuardedLegacySentinelView{Verdict: internal.SentinelValid, Sentinel: sentinel, Path: internal.SyncStatePath(layout.FeaturePath)},
		PersistedGuarded: true,
	}
	insp := inspectExternalPlanFor(args)
	if insp.StackErr != nil {
		return fmt.Errorf("load stack: %w", insp.StackErr)
	}
	if insp.SortErr != nil {
		return insp.SortErr
	}

	plan, planReq, err := buildGuardedExternalPlan(cmd.OutOrStdout(), cmd.ErrOrStderr(), args, insp)
	if err != nil {
		return err
	}
	guard := newPlanGuardRun(planReq, plan, true)

	// The choice between reclaim and claim follows the SNAPSHOT — whether a
	// guard file was there at all — and never which residue produced it: the
	// same cell is reachable from crash window 2 and from a `{sentinel,
	// guard}` rollback residue, and both must answer identically.
	if err := claimOrReclaimGuardedLegacyGuard(layout.FeaturePath, sentinel.OwnerToken, state.HasGuardFile()); err != nil {
		return err
	}
	if err := externalSyncPostClaimRecheck(feature, layout, sentinel.OwnerToken); err != nil {
		return err
	}

	done := make(map[string]bool, len(sentinel.Universe))
	pending := make(map[string]bool, len(sentinel.PendingIntent))
	for _, name := range sentinel.PendingIntent {
		pending[name] = true
	}
	for _, name := range sentinel.Universe {
		if !pending[name] {
			done[name] = true
		}
	}

	payload, err := writeGuardedLegacyRecoveryPayload(layout.FeaturePath, sentinel)
	if err != nil {
		return err
	}

	printSyncModeHeader(policy)
	// §12.8b's prose table, which is total over the sentinel's own
	// provenance: an interrupted CELL-7 setup resumes a real prior state and
	// prints the shipped resume line over the number that state persisted
	// (prior_pending_count — the same number the interrupted invocation
	// printed), while an interrupted FRESH guarded legacy setup has no prior
	// state and therefore prints no resume prose at all, exactly as the
	// guarded legacy fresh route prints none. Printing a resume line for a
	// fresh-setup sentinel — or printing len(PendingIntent), which is this
	// arm's remaining set and not the operator's number — fails §22.24j.
	if sentinel.PriorLegacyPresent {
		fmt.Printf("Resuming sync with %d pending branch(es)\n", sentinel.PriorPendingCount)
	}
	run := &syncRunContext{Route: internal.RouteLegacy, Payload: payload}
	result := syncWithStackScoped(feature, layout, insp.Stack, insp.Order, done, run, guard)
	if result.Refusal != nil {
		return result.Refusal
	}
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if sentinel.Push {
		fmt.Println("\nPushing...")
		if err := pushFeature(feature, layout, false); err != nil {
			return err
		}
	}
	return clearSyncRunState(layout.FeaturePath, true)
}

// abortGuardedLegacySentinel discards a crash-recovered guarded legacy
// sentinel (§12.8b, verdict: valid, verb --abort). It claims or reclaims the
// shared feature guard, rechecks authoritative reparent state, then performs
// the shipped payload-appeared refusal and DeleteSyncState before releasing
// the guard last. Its only operator-visible change remains the line it prints.
//
// That line MUST NOT be the bare shipped `Sync state cleared.`: --abort here
// is a clear verb, never a restore verb, and the bare sentence would hide
// the destruction of a document `--continue` could still have resumed. It is
// not a `plan-guard:` marker either (§6.4).
func abortGuardedLegacySentinel(feature string, layout externalSyncLayout) error {
	view := internal.InspectGuardedLegacySentinel(layout.FeaturePath, feature)
	if view.Sentinel == nil {
		return fmt.Errorf("guarded sync state at %s is unreadable or uses an unsupported version; inspect it and remove it manually — tws will not guess", view.Path)
	}
	return withExternalSyncMutationGuard(feature, layout, view.Sentinel.OwnerToken, true, func() error {
		if internal.HasSyncRunState(layout.FeaturePath) {
			return fmt.Errorf("scoped sync state appeared at %s while aborting; re-run: tws sync %s --abort",
				internal.SyncRunStatePath(layout.FeaturePath), feature)
		}
		internal.DeleteSyncState(layout.FeaturePath)
		fmt.Println("Sync state cleared; the interrupted guarded setup's backup of the previous sync state was discarded.")
		return nil
	})
}

// scopedFreshPrelude performs the read-only prelude of the SHIPPED,
// unguarded new-mode fresh route: load the stack, resolve the selection
// (which sorts inside ResolveSyncSelection), and run the I14 local-base
// preflight. It mutates nothing, and its two shipped sorts are exactly what
// §10.1's unguarded row records. The guarded twin does not call it: it
// consumes the one inspection instead (scopedPreludeFromInspection).
func scopedFreshPrelude(feature string, layout externalSyncLayout, ws internal.Workspace, policy internal.SyncRunPolicy) (internal.Stack, internal.SyncSelection, error) {
	stack, err := internal.LoadStack(layout.FeaturePath)
	if err != nil {
		return internal.Stack{}, internal.SyncSelection{}, fmt.Errorf("sync modes require a stack; feature %q has no readable stack.yaml", feature)
	}
	sel, err := internal.ResolveSyncSelection(stack, policy, internal.SyncSelectionOpts{
		Mode:    ws.Mode,
		NewMode: true,
		Feature: feature,
	})
	if err != nil {
		return internal.Stack{}, internal.SyncSelection{}, err
	}
	if err := verifySelectedBasesLocally(layout, stack, sel); err != nil {
		return internal.Stack{}, internal.SyncSelection{}, err
	}
	return stack, sel, nil
}

// runScopedSync executes §3.6 steps 10-17 of a new-mode external run.
func runScopedSync(feature string, layout externalSyncLayout, ws internal.Workspace, policy internal.SyncRunPolicy, push, verbose bool) error {
	stack, sel, err := scopedFreshPrelude(feature, layout, ws, policy)
	if err != nil {
		return err
	}

	marker, err := syncMarkerFn()
	if err != nil {
		return err
	}
	if err := syncMarkerCollision(stack, marker); err != nil {
		return err
	}
	token, err := newSyncOwnerToken()
	if err != nil {
		return err
	}

	testCommand := internal.LoadConfig().TestCommand
	validationSource := "none"
	if testCommand != "" {
		validationSource = "config"
	}

	payload, err := setupSyncRunState(layout, feature, marker, token, sel, push, testCommand, validationSource, syncRunStateBirth{})
	if err != nil {
		return err
	}

	printSyncModeHeader(policy)

	run := &syncRunContext{Policy: policy, Sel: sel, Payload: payload}
	result := syncFeatureScoped(feature, layout, verbose, stack, run, nil)
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if push {
		// The payload, the sentinel, and the guard stay on disk when a scoped
		// push fails, so --continue can retry exactly the entries that were
		// never pushed.
		if err := runNewModePush(feature, layout, stack, sel, result.Completed, payload); err != nil {
			return err
		}
	}
	return finalizeScopedSyncRun(layout, payload)
}

// runGuardedScopedSync is the guarded twin of runScopedSync (spec §12,
// §13.7a; exploration insertion point 11): the identical read-only prelude,
// an admission plan built and evaluated through buildGuardedExternalPlan
// before any state is written — which already performs this run's own
// fetch, so syncFeatureScoped's own fetch loop is skipped for a guarded run
// — then the guarded setup/execute/push/teardown sequence.
func runGuardedScopedSync(cmd *cobra.Command, feature string, layout externalSyncLayout, ws internal.Workspace, policy internal.SyncRunPolicy, push, verbose bool, changed map[string]bool, opts planGuardOptions, state internal.SyncExternalState) error {
	args := externalPlanArgs{
		Feature: feature, Layout: layout, Ws: ws, Policy: policy, NewMode: true,
		Push: push, Verbose: verbose, Changed: changed, Opts: opts, State: state, Continue: false,
	}
	// The ONE inspection of this invocation (§10.7 rule 1a, §16.1): the
	// shipped prelude's refusals are composed from its values, so the stack
	// is loaded once, sorted once and the I14 locator evaluated once.
	insp := inspectExternalPlanFor(args)
	stack, sel, err := scopedPreludeFromInspection(feature, insp)
	if err != nil {
		return err
	}

	plan, planReq, err := buildGuardedExternalPlan(cmd.OutOrStdout(), cmd.ErrOrStderr(), args, insp)
	if err != nil {
		return err
	}
	guard := newPlanGuardRun(planReq, plan, false)

	marker, err := syncMarkerFn()
	if err != nil {
		return err
	}
	if err := syncMarkerCollision(stack, marker); err != nil {
		return err
	}
	token, err := newSyncOwnerToken()
	if err != nil {
		return err
	}

	testCommand := internal.LoadConfig().TestCommand
	validationSource := "none"
	if testCommand != "" {
		validationSource = "config"
	}

	birth := syncRunStateBirth{
		StateVersion: internal.SyncRunStateGuardedVersion,
		Route:        internal.RouteNewMode,
		MaxPerEntry:  opts.MaxPerEntry,
		MaxTotal:     opts.MaxTotal,
	}
	payload, err := setupSyncRunState(layout, feature, marker, token, sel, push, testCommand, validationSource, birth)
	if err != nil {
		return err
	}

	printSyncModeHeader(policy)

	run := &syncRunContext{Policy: policy, Sel: sel, Payload: payload, Validation: validationIdentity(testCommand, validationSource)}
	result := syncFeatureScopedPlanned(feature, layout, stack, insp.Order, run, guard)
	if result.Refusal != nil {
		if !result.Refusal.StatePreserved {
			return rollbackGuardedFreshRefusal(layout.FeaturePath, feature, result.Refusal)
		}
		return result.Refusal
	}
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if push {
		if err := runNewModePush(feature, layout, stack, sel, result.Completed, payload); err != nil {
			return err
		}
	}
	return finalizeScopedSyncRun(layout, payload)
}

// runGuardedLegacySync is the guarded twin of the plain legacy fresh route
// (spec §12, §13.7a; exploration insertion point 11 legacy arm): an
// admission plan built and evaluated through buildGuardedExternalPlan before
// any state is written — which already performs this run's own fetch, so
// syncFeature's own fetch loop is skipped for a guarded run (guard != nil)
// — then setupGuardedLegacyRunState's single-file birth, execution through
// syncFeature, optional push, and teardown. A guarded legacy run keeps its
// payload, sentinel, and guard through the optional push so remote follow-up
// clearing and every push remain protected.
func runGuardedLegacySync(cmd *cobra.Command, feature string, layout externalSyncLayout, ws internal.Workspace, policy internal.SyncRunPolicy, push, verbose bool, changed map[string]bool, opts planGuardOptions, state internal.SyncExternalState) error {
	args := externalPlanArgs{
		Feature: feature, Layout: layout, Ws: ws, Policy: policy, NewMode: false,
		Push: push, Verbose: verbose, Changed: changed, Opts: opts, State: state, Continue: false,
	}
	insp := inspectExternalPlanFor(args)
	if insp.StackErr != nil {
		return &internal.PlanGuardRefusalError{Kind: string(internal.RefusalPlanUnavailable), Detail: insp.StackErr.Error()}
	}
	if insp.SortErr != nil {
		return insp.SortErr
	}
	stack, sorted := insp.Stack, insp.Order

	plan, planReq, err := buildGuardedExternalPlan(cmd.OutOrStdout(), cmd.ErrOrStderr(), args, insp)
	if err != nil {
		return err
	}
	guard := newPlanGuardRun(planReq, plan, false)

	marker, err := syncMarkerFn()
	if err != nil {
		return err
	}
	if err := syncMarkerCollision(stack, marker); err != nil {
		return err
	}
	token, err := newSyncOwnerToken()
	if err != nil {
		return err
	}

	testCommand := internal.LoadConfig().TestCommand
	validationSource := "none"
	if testCommand != "" {
		validationSource = "config"
	}

	universe := make([]string, 0, len(sorted))
	for _, entry := range sorted {
		universe = append(universe, entry.Name)
	}
	pending := guardedLegacySetupPending(universe, guardedLegacyCarry{})

	birth := syncRunStateBirth{StateVersion: internal.SyncRunStateGuardedVersion, Route: internal.RouteLegacy, MaxPerEntry: opts.MaxPerEntry, MaxTotal: opts.MaxTotal}
	payload, undo, err := setupGuardedLegacyRunState(layout, feature, marker, token, universe, pending, push, testCommand, validationSource, birth, guardedLegacyCarry{})
	if err != nil {
		return err
	}

	printSyncModeHeader(policy)

	run := &syncRunContext{Route: internal.RouteLegacy, Payload: payload, Validation: validationIdentity(testCommand, validationSource)}
	result := syncWithStackScoped(feature, layout, stack, sorted, nil, run, guard)
	if result.Refusal != nil {
		// A refusal raised before this invocation moved anything owns its own
		// cleanup: the payload, the guarded sentinel and the run guard this
		// setup installed must not outlive it, which is what keeps
		// StatePreserved false.
		if !result.Refusal.StatePreserved {
			return undo.rollback(layout.FeaturePath, feature, result.Refusal)
		}
		return result.Refusal
	}
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if push {
		fmt.Println("\nPushing...")
		if err := pushFeature(feature, layout, false); err != nil {
			return err
		}
	}
	return clearSyncRunState(layout.FeaturePath, true)
}

// runNewModePush is the §7.6 push half of a new-mode run. A `scope=all` run
// keeps the legacy whole-feature push, so "`--push` pushes the feature" is
// unchanged when nothing was scoped: every materialized entry is considered —
// including an anchor a local-only run deliberately did not rebase — and the
// legacy lenient per-entry behaviour is preserved. `only` and `subtree` scopes
// use the strict, payload-aware, resumable push.
func runNewModePush(feature string, layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection, completed []string, payload *internal.SyncRunState) error {
	fmt.Println("\nPushing...")
	payload.Stage = internal.SyncStagePushing
	if err := internal.SaveSyncRunState(layout.FeaturePath, payload); err != nil {
		return fmt.Errorf("record push stage: %w", err)
	}
	if sel.Policy.ScopeKind == internal.SyncScopeAll {
		return pushFeature(feature, layout, false)
	}
	return pushScoped(feature, layout, stack, sel, completed, payload)
}

// finalizeScopedSyncRun records the finalizing stage immediately before
// teardown — never earlier — and then tears the run's state down. A teardown
// error is propagated verbatim: no later artifact is cleared behind it.
func finalizeScopedSyncRun(layout externalSyncLayout, payload *internal.SyncRunState) error {
	payload.Stage = internal.SyncStageFinalizing
	if err := internal.SaveSyncRunState(layout.FeaturePath, payload); err != nil {
		return fmt.Errorf("record finalizing stage: %w", err)
	}
	return clearSyncRunState(layout.FeaturePath, true)
}

// verifySelectedBasesLocally is the I14 no-fetch preflight. It probes only the
// base refs the selected plan will actually use.
// firstUnresolvedSelectedBase is I14's locator: the first selected entry
// whose base does not resolve locally, and the ref it tried. found is false
// when every applicable entry's base resolves (or there is none to check).
// It is the shared locator both verifySelectedBasesLocally and
// externalBasePreflight (sync_plan_guard.go) call, never a second
// implementation of it.
func firstUnresolvedSelectedBase(layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection) (entry, ref string, found bool) {
	for _, e := range sel.Entries {
		if e.Role == internal.SyncRoleAnchor && sel.Policy.Propagation == internal.SyncPropagationLocalOnly {
			continue
		}
		real := internal.GetBranch(stack, e.Name)
		repoCtx := syncRepoContext(layout, real)
		r := resolveEntryBase(stack, real, repoCtx)
		if r == "" {
			continue
		}
		if err := internal.VerifyGitRef(repoCtx, r); err != nil {
			return e.Name, r, true
		}
	}
	return "", "", false
}

func verifySelectedBasesLocally(layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection) error {
	if sel.Policy.Fetch != internal.SyncFetchDisabled {
		return nil
	}
	if entry, ref, found := firstUnresolvedSelectedBase(layout, stack, sel); found {
		return fmt.Errorf("base %q for stack entry %q does not resolve locally; drop --no-fetch or fetch manually first", ref, entry)
	}
	return nil
}

func handleSyncAbortCell(feature string, layout externalSyncLayout, state internal.SyncExternalState) error {
	if state.GuardForeign() {
		return fmt.Errorf("sync guard %s does not belong to the recorded scoped run; inspect it and remove it manually", state.GuardPath)
	}
	switch state.Cell {
	case 2, 5:
		token := ""
		if state.Payload != nil {
			token = state.Payload.OwnerToken
		}
		return withExternalSyncMutationGuard(feature, layout, token, true, func() error {
			if state.Payload != nil && state.Payload.FailedBranch != "" {
				path := layout.WorktreePath(state.Payload.FailedBranch)
				if isRebaseInProgress(path) {
					_ = internal.RunSilentDir(path, "git", "rebase", "--abort")
				}
			}
			internal.DeleteSyncRunState(layout.FeaturePath)
			if state.Cell == 5 {
				internal.DeleteSyncState(layout.FeaturePath)
			}
			fmt.Println("Sync state cleared.")
			return nil
		})
	case 4:
		return withExternalSyncMutationGuard(feature, layout, "", true, func() error {
			if internal.HasSyncRunState(layout.FeaturePath) {
				return fmt.Errorf("scoped sync state appeared at %s while aborting; re-run: tws sync %s --abort",
					internal.SyncRunStatePath(layout.FeaturePath), feature)
			}
			internal.DeleteSyncState(layout.FeaturePath)
			fmt.Println("Sync state cleared.")
			return nil
		})
	case 1:
		return handleStaleSyncGuardAbort(feature, layout)
	case 7:
		return handleLegacyGuardedAbort(feature, layout)
	}
	return handleSyncAbort(feature, layout)
}

// handleStaleSyncGuardAbort implements the classifier cell-1 guard-only
// recovery arm (§12.8): a scoped setup's guard survives its own crash
// between ClaimSyncRunGuard and the sentinel write, with no legacy state and
// no payload beside it — a residue `--abort` otherwise reports as "nothing to
// abort" forever. internal.ReleaseStaleSyncRunGuard judges the guard with one
// Lstat, one read, the shipped PID ladder, and a compare-and-swap; cli
// composes every sentence of the eight-reason ladder, because two of them
// name the feature.
func handleStaleSyncGuardAbort(feature string, layout externalSyncLayout) error {
	state := internal.ClassifyExternalSyncState(layout.FeaturePath, internal.SyncClassifyOpts{AlwaysReadGuard: true})
	switch {
	case state.GuardSymlink:
		return syncSymlinkError(state.GuardPath)
	case state.GuardErr != nil:
		return fmt.Errorf("sync guard at %s is unreadable: %v; inspect and remove it manually", state.GuardPath, syncErrText(state.GuardErr))
	case state.Guard == nil:
		fmt.Println("Nothing to abort — no sync in progress.")
		return nil
	case state.Guard.PID <= 0:
		return fmt.Errorf("sync guard is being initialized or is invalid; retry or inspect %s", state.GuardPath)
	case state.Guard.PID == os.Getpid():
		return fmt.Errorf("sync guard at %s records this process (pid %d); it was not claimed by this invocation — inspect it and remove it manually", state.GuardPath, state.Guard.PID)
	case state.GuardLive:
		return fmt.Errorf("a scoped sync is running for %q (pid %d); wait for it to exit before --abort", feature, state.Guard.PID)
	}
	pid := state.Guard.PID
	return withExternalSyncMutationGuard(feature, layout, "", true, func() error {
		fmt.Printf("Stale sync guard from PID %d cleared; no sync state was present.\n", pid)
		return nil
	})
}

// handleLegacyGuardedAbort implements the classifier cell-7 recovery arm
// (§12.8a): a real (non-sentinel) legacy .sync-state.yaml survives beside a
// stale guard — left either by an unguarded legacy sync landing on the exact
// residue §12.8 exists for, or by a guarded legacy setup's own first-crash-
// window rollback. internal.ReleaseStaleSyncRunGuardWith judges the guard
// with AllowSelfPID set (an abort never claims a guard, so a self-recorded
// PID is provably not a live owner) and this arm then performs the shipped
// cell-7 abort work itself through the print-free abortLegacySyncState,
// composing the combined sentence.
func handleLegacyGuardedAbort(feature string, layout externalSyncLayout) error {
	state := internal.ClassifyExternalSyncState(layout.FeaturePath, internal.SyncClassifyOpts{AlwaysReadGuard: true})
	switch {
	case state.GuardSymlink:
		return syncSymlinkError(state.GuardPath)
	case state.GuardErr != nil:
		return fmt.Errorf("sync guard at %s is unreadable: %v; inspect and remove it manually", state.GuardPath, syncErrText(state.GuardErr))
	case state.Guard != nil && state.Guard.PID <= 0:
		return fmt.Errorf("sync guard is being initialized or is invalid; retry or inspect %s", state.GuardPath)
	case state.Guard != nil && state.Guard.PID != os.Getpid() && state.GuardLive:
		return fmt.Errorf("a scoped sync is running for %q (pid %d); wait for it to exit before --abort", feature, state.Guard.PID)
	}
	hadGuard := state.Guard != nil
	pid := 0
	if hadGuard {
		pid = state.Guard.PID
	}
	return withExternalSyncMutationGuard(feature, layout, "", true, func() error {
		found, err := abortLegacySyncState(layout)
		if err != nil {
			return err
		}
		if !found {
			if hadGuard {
				fmt.Printf("Stale sync guard from PID %d cleared; no sync state was present.\n", pid)
			} else {
				fmt.Println("Nothing to abort — no sync in progress.")
			}
			return nil
		}
		if hadGuard {
			fmt.Printf("Sync state cleared; stale sync guard from PID %d cleared.\n", pid)
		} else {
			fmt.Println("Sync state cleared.")
		}
		return nil
	})
}

// handleSyncAbort is a printing wrapper over abortLegacySyncState: it prints
// the one message the presence or absence of a real legacy sentinel implies,
// and nothing else.
func handleSyncAbort(feature string, layout externalSyncLayout) error {
	found, err := abortLegacySyncState(layout)
	if err != nil {
		return err
	}
	if !found {
		fmt.Println("Nothing to abort — no sync in progress.")
		return nil
	}
	fmt.Println("Sync state cleared.")
	return nil
}

// abortLegacySyncState performs the non-printing half of a real legacy
// sentinel's abort: it aborts an in-progress rebase, if any, then deletes
// the sentinel. It reports whether a sentinel was present at all, so both
// handleSyncAbort and any future caller can print the identical shipped
// messages without duplicating this logic.
func abortLegacySyncState(layout externalSyncLayout) (bool, error) {
	state, err := internal.LoadSyncState(layout.FeaturePath)
	if err != nil {
		return false, nil
	}
	if state.FailedBranch != "" {
		path := layout.WorktreePath(state.FailedBranch)
		if isRebaseInProgress(path) {
			_ = internal.RunSilentDir(path, "git", "rebase", "--abort")
		}
	}
	internal.DeleteSyncState(layout.FeaturePath)
	return true, nil
}

func handleSyncContinue(feature string, layout externalSyncLayout, push bool) error {
	state, err := internal.LoadSyncState(layout.FeaturePath)
	if err != nil {
		return fmt.Errorf("nothing to continue — no sync in progress")
	}
	failedPath := layout.WorktreePath(state.FailedBranch)
	if state.FailedBranch != "" && isRebaseInProgress(failedPath) {
		return fmt.Errorf("rebase still in progress in %s; resolve conflicts, run git add . && git rebase --continue, then retry", state.FailedBranch)
	}

	stack, err := internal.LoadStack(layout.FeaturePath)
	if err != nil {
		return fmt.Errorf("load stack: %w", err)
	}
	if state.FailedBranch != "" {
		failedEntry := internal.GetBranch(stack, state.FailedBranch)
		if failedEntry.Name == "" {
			return fmt.Errorf("failed branch %q no longer exists in stack", state.FailedBranch)
		}
		if !branchContainsConfiguredParent(layout.WorktreesRoot, stack, failedEntry) {
			return fmt.Errorf("resolved branch %s still does not contain its configured parent %s", failedEntry.Name, failedEntry.Base)
		}
		fmt.Println(formatSyncStatus(state.FailedBranch, "active", "resolved"))
	}

	return withExternalSyncMutationGuard(feature, layout, "", true, func() error {
		done := make(map[string]bool)
		for _, name := range state.Completed {
			done[name] = true
		}
		if state.FailedBranch != "" {
			done[state.FailedBranch] = true
		}
		sorted, err := internal.TopoSort(stack)
		if err != nil {
			return err
		}
		fmt.Printf("Resuming sync with %d pending branch(es)\n", len(state.Pending))
		result := syncWithStackFiltered(feature, layout, stack, sorted, done, nil)
		if !result.Complete {
			return fmt.Errorf("sync incomplete")
		}
		fmt.Println("Sync complete.")
		if push {
			fmt.Println("\nPushing...")
			if err := pushFeature(feature, layout, false); err != nil {
				return err
			}
		}
		return nil
	})
}

// handleScopedSyncContinue resumes cell 5 — the only resumable new-mode cell.
func handleScopedSyncContinue(feature string, layout externalSyncLayout, ws internal.Workspace, push bool, policy internal.SyncRunPolicy, changed map[string]bool, state internal.SyncExternalState) error {
	payload := state.Payload
	if payload == nil {
		return fmt.Errorf("nothing to continue — no sync in progress")
	}
	if err := syncContinueMismatches(payload, policy, changed, push); err != nil {
		return err
	}

	failedPath := layout.WorktreePath(payload.FailedBranch)
	if payload.FailedBranch != "" && isRebaseInProgress(failedPath) {
		return fmt.Errorf("rebase still in progress in %s; resolve conflicts, run git add . && git rebase --continue, then retry", payload.FailedBranch)
	}

	stack, err := internal.LoadStack(layout.FeaturePath)
	if err != nil {
		return fmt.Errorf("load stack: %w", err)
	}
	sel, err := scopedSelectionFromPayload(stack, payload, feature, ws.Mode)
	if err != nil {
		return err
	}

	if payload.FailedBranch != "" && !payloadCompleted(payload, payload.FailedBranch) {
		failedEntry := internal.GetBranch(stack, payload.FailedBranch)
		if failedEntry.Name == "" {
			return fmt.Errorf("failed branch %q no longer exists in stack", payload.FailedBranch)
		}
		if !branchContainsConfiguredParent(layout.WorktreesRoot, stack, failedEntry) {
			return fmt.Errorf("resolved branch %s still does not contain its configured parent %s", failedEntry.Name, failedEntry.Base)
		}
		fmt.Println(formatSyncStatus(payload.FailedBranch, "active", "resolved"))
	}

	if state.GuardForeign() {
		return fmt.Errorf("sync guard %s does not belong to the recorded scoped run; inspect it and remove it manually", state.GuardPath)
	}
	if err := internal.ReclaimSyncRunGuard(layout.FeaturePath, payload.OwnerToken); err != nil {
		return err
	}
	if err := externalSyncPostClaimRecheck(feature, layout, payload.OwnerToken); err != nil {
		return err
	}

	done := make(map[string]bool)
	for _, name := range payload.Completed {
		done[name] = true
	}
	if payload.FailedBranch != "" {
		done[payload.FailedBranch] = true
	}
	sorted, err := internal.TopoSort(stack)
	if err != nil {
		return err
	}

	printSyncModeHeader(payload.Policy())
	fmt.Printf("Resuming sync with %d pending branch(es)\n", len(payload.Pending))

	run := &syncRunContext{Policy: payload.Policy(), Sel: sel, Payload: payload}
	result := syncWithStackScoped(feature, layout, stack, sorted, done, run, nil)
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if payload.Push {
		if err := runNewModePush(feature, layout, stack, sel, result.Completed, payload); err != nil {
			return err
		}
	}
	return finalizeScopedSyncRun(layout, payload)
}

// handleGuardedScopedSyncContinue is the armed twin of
// handleScopedSyncContinue (cell-5 three-arm dispatch, arms b and c): the
// identical gates and mismatch checks, an admission plan built and
// evaluated through buildGuardedExternalPlan before the guard is reclaimed,
// and syncWithStackScoped driven with a real *planGuardRun.
func handleGuardedScopedSyncContinue(cmd *cobra.Command, feature string, layout externalSyncLayout, ws internal.Workspace, push bool, policy internal.SyncRunPolicy, changed map[string]bool, opts planGuardOptions, state internal.SyncExternalState) error {
	payload := state.Payload
	if payload == nil {
		return fmt.Errorf("nothing to continue — no sync in progress")
	}
	if err := syncContinueMismatches(payload, policy, changed, push); err != nil {
		return err
	}

	failedPath := layout.WorktreePath(payload.FailedBranch)
	if payload.FailedBranch != "" && isRebaseInProgress(failedPath) {
		return fmt.Errorf("rebase still in progress in %s; resolve conflicts, run git add . && git rebase --continue, then retry", payload.FailedBranch)
	}

	args := externalPlanArgs{
		Feature: feature, Layout: layout, Ws: ws, Policy: payload.Policy(), NewMode: true,
		Push: push, Verbose: false, Changed: changed, Opts: opts, State: state, Continue: true,
		PersistedGuarded: externalPersistedGuarded(payload),
	}
	insp := inspectExternalPlanFor(args)
	if insp.StackErr != nil {
		return fmt.Errorf("load stack: %w", insp.StackErr)
	}
	if insp.SortErr != nil {
		return insp.SortErr
	}
	if insp.SelectionErr != nil {
		return insp.SelectionErr
	}
	stack, sel := insp.Stack, insp.Selection

	if payload.FailedBranch != "" && !payloadCompleted(payload, payload.FailedBranch) {
		failedEntry := internal.GetBranch(stack, payload.FailedBranch)
		if failedEntry.Name == "" {
			return fmt.Errorf("failed branch %q no longer exists in stack", payload.FailedBranch)
		}
		if !branchContainsConfiguredParent(layout.WorktreesRoot, stack, failedEntry) {
			return fmt.Errorf("resolved branch %s still does not contain its configured parent %s", failedEntry.Name, failedEntry.Base)
		}
		fmt.Println(formatSyncStatus(payload.FailedBranch, "active", "resolved"))
	}

	if state.GuardForeign() {
		return fmt.Errorf("sync guard %s does not belong to the recorded scoped run; inspect it and remove it manually", state.GuardPath)
	}

	plan, planReq, err := buildGuardedExternalPlan(cmd.OutOrStdout(), cmd.ErrOrStderr(), args, insp)
	if err != nil {
		return err
	}
	guard := newPlanGuardRun(planReq, plan, externalPersistedGuarded(payload))

	if err := internal.ReclaimSyncRunGuard(layout.FeaturePath, payload.OwnerToken); err != nil {
		return err
	}
	if err := externalSyncPostClaimRecheck(feature, layout, payload.OwnerToken); err != nil {
		return err
	}

	// §13.2a step 10a: the armed v2 -> v3 upgrade, immediately after a
	// successful reclaim and before any header, prose or Git mutation.
	if opts.Armed() && !externalPersistedGuarded(payload) {
		birth := syncRunStateBirth{StateVersion: internal.SyncRunStateGuardedVersion, MaxPerEntry: opts.MaxPerEntry, MaxTotal: opts.MaxTotal}
		if err := upgradeGuardedSyncRunState(layout.FeaturePath, payload, birth); err != nil {
			return err
		}
	}

	done := make(map[string]bool)
	for _, name := range payload.Completed {
		done[name] = true
	}
	if payload.FailedBranch != "" {
		done[payload.FailedBranch] = true
	}
	sorted := insp.Order

	printSyncModeHeader(payload.Policy())
	fmt.Printf("Resuming sync with %d pending branch(es)\n", len(payload.Pending))

	run := &syncRunContext{Policy: payload.Policy(), Sel: sel, Payload: payload}
	result := syncWithStackScoped(feature, layout, stack, sorted, done, run, guard)
	if result.Refusal != nil {
		return result.Refusal
	}
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if payload.Push {
		if err := runNewModePush(feature, layout, stack, sel, result.Completed, payload); err != nil {
			return err
		}
	}
	return finalizeScopedSyncRun(layout, payload)
}

// handleGuardedLegacySyncContinue is the armed twin of handleSyncContinue
// (cell-7 two-arm dispatch, arm b): a real, unguarded legacy failure (cell 7)
// resumed with guard flags supplied now. It performs the identical gates
// handleSyncContinue performs, builds and evaluates an admission plan
// through buildGuardedExternalPlan, captures the prior legacy sentinel's
// exact bytes, then upgrades it in place to a guarded sentinel — via
// setupGuardedLegacyRunState's own carry path — carrying forward the same
// Completed/FailedBranch/Pending state, before driving execution through
// syncWithStackScoped with a real *planGuardRun. Like runGuardedLegacySync,
// it releases the guard explicitly on success since the single-file
// sentinel's own success path (run == nil) never does.
func handleGuardedLegacySyncContinue(cmd *cobra.Command, feature string, layout externalSyncLayout, ws internal.Workspace, push bool, policy internal.SyncRunPolicy, changed map[string]bool, opts planGuardOptions, state internal.SyncExternalState) error {
	legacy, err := internal.LoadSyncState(layout.FeaturePath)
	if err != nil {
		return fmt.Errorf("nothing to continue — no sync in progress")
	}
	failedPath := layout.WorktreePath(legacy.FailedBranch)
	if legacy.FailedBranch != "" && isRebaseInProgress(failedPath) {
		return fmt.Errorf("rebase still in progress in %s; resolve conflicts, run git add . && git rebase --continue, then retry", legacy.FailedBranch)
	}

	args := externalPlanArgs{
		Feature: feature, Layout: layout, Ws: ws, Policy: policy, NewMode: false,
		Push: push, Verbose: false, Changed: changed, Opts: opts, State: state, Continue: true,
	}
	insp := inspectExternalPlanFor(args)
	if insp.StackErr != nil {
		return fmt.Errorf("load stack: %w", insp.StackErr)
	}
	if insp.SortErr != nil {
		return insp.SortErr
	}
	stack, sorted := insp.Stack, insp.Order

	if legacy.FailedBranch != "" {
		failedEntry := internal.GetBranch(stack, legacy.FailedBranch)
		if failedEntry.Name == "" {
			return fmt.Errorf("failed branch %q no longer exists in stack", legacy.FailedBranch)
		}
		if !branchContainsConfiguredParent(layout.WorktreesRoot, stack, failedEntry) {
			return fmt.Errorf("resolved branch %s still does not contain its configured parent %s", failedEntry.Name, failedEntry.Base)
		}
		fmt.Println(formatSyncStatus(legacy.FailedBranch, "active", "resolved"))
	}

	plan, planReq, err := buildGuardedExternalPlan(cmd.OutOrStdout(), cmd.ErrOrStderr(), args, insp)
	if err != nil {
		return err
	}
	guard := newPlanGuardRun(planReq, plan, false)

	carry := carriedGuardedLegacyState(legacy)

	marker, err := syncMarkerFn()
	if err != nil {
		return err
	}
	if err := syncMarkerCollision(stack, marker); err != nil {
		return err
	}
	token, err := newSyncOwnerToken()
	if err != nil {
		return err
	}

	testCommand := internal.LoadConfig().TestCommand
	validationSource := "none"
	if testCommand != "" {
		validationSource = "config"
	}

	universe := make([]string, 0, len(sorted))
	for _, entry := range sorted {
		universe = append(universe, entry.Name)
	}
	pending := guardedLegacySetupPending(universe, carry)

	birth := syncRunStateBirth{StateVersion: internal.SyncRunStateGuardedVersion, Route: internal.RouteLegacy, MaxPerEntry: opts.MaxPerEntry, MaxTotal: opts.MaxTotal}
	payload, undo, err := setupGuardedLegacyRunState(layout, feature, marker, token, universe, pending, push, testCommand, validationSource, birth, carry)
	if err != nil {
		return err
	}

	done := make(map[string]bool)
	for _, name := range legacy.Completed {
		done[name] = true
	}
	if legacy.FailedBranch != "" {
		done[legacy.FailedBranch] = true
	}

	printSyncModeHeader(policy)
	fmt.Printf("Resuming sync with %d pending branch(es)\n", carry.PriorPendingCount)

	run := &syncRunContext{Route: internal.RouteLegacy, Payload: payload, Validation: validationIdentity(testCommand, validationSource)}
	result := syncWithStackScoped(feature, layout, stack, sorted, done, run, guard)
	if result.Refusal != nil {
		// Same pre-mutation rule as the guarded fresh route: an upgrade that
		// refuses without moving anything undoes exactly what it created —
		// payload, the conditional sentinel undo that restores the captured
		// legacy bytes, then the guard — and reports an honest residue if
		// any of those three steps itself fails.
		if !result.Refusal.StatePreserved {
			return undo.rollback(layout.FeaturePath, feature, result.Refusal)
		}
		return result.Refusal
	}
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if push {
		fmt.Println("\nPushing...")
		if err := pushFeature(feature, layout, false); err != nil {
			return err
		}
	}
	return clearSyncRunState(layout.FeaturePath, true)
}

// syncContinueMismatches applies §10.5 rules 2, 3, and 5 to an external v2
// resume.
func syncContinueMismatches(payload *internal.SyncRunState, policy internal.SyncRunPolicy, changed map[string]bool, push bool) error {
	if changed["fetch"] || changed["no-fetch"] {
		if policy.Fetch != payload.FetchPolicy {
			return syncContinueMismatch("fetch", string(payload.FetchPolicy), string(policy.Fetch))
		}
	}
	if changed["full"] || changed["local-only"] {
		if policy.Propagation != payload.PropagationPolicy {
			return syncContinueMismatch("propagation", string(payload.PropagationPolicy), string(policy.Propagation))
		}
	}
	if changed["only"] || changed["from"] {
		want := payload.Policy().ScopeLabel()
		if policy.ScopeLabel() != want {
			return syncContinueMismatch("scope", want, policy.ScopeLabel())
		}
	}
	if changed["push"] && push != payload.Push {
		return syncContinueMismatch("push", fmt.Sprintf("%v", payload.Push), fmt.Sprintf("%v", push))
	}
	return nil
}

func syncContinueMismatch(axis, started, requested string) error {
	return fmt.Errorf("cannot change %s on --continue: the run was started with %s=%s and this invocation requests %s", axis, axis, started, requested)
}

// payloadCompleted reports whether an entry already finished its rebase in the
// interrupted run. A push failure records the entry in BOTH `completed` and
// `failed_branch`: its rebase and its validation already succeeded, so the
// resume must neither re-check the parent edge, nor re-run validation, nor
// print `[~] resolved` for it — it goes straight to retrying the entries that
// were never pushed.
func payloadCompleted(payload *internal.SyncRunState, name string) bool {
	for _, done := range payload.Completed {
		if done == name {
			return true
		}
	}
	return false
}

// scopedSelectionFromPayloadOrder is scopedSelectionFromPayload's own
// order-taking half: the payload-existence check and the filter-to-
// payload.Selected projection, taking an already-sorted order so a caller
// that already holds this invocation's own TopoSort result (InspectExternalPlan)
// never sorts a second time. It is otherwise byte-identical to
// scopedSelectionFromPayload.
func scopedSelectionFromPayloadOrder(stack internal.Stack, order []internal.StackEntry, payload *internal.SyncRunState, feature string, mode internal.WorkspaceMode) (internal.SyncSelection, error) {
	for _, name := range payload.Selected {
		if !internal.HasBranch(stack, name) {
			return internal.SyncSelection{}, fmt.Errorf("selected stack entry %q no longer exists in stack; use --abort", name)
		}
	}
	sel, err := internal.ResolveSyncSelectionFromOrder(stack, order, payload.Policy(), internal.SyncSelectionOpts{
		Mode:    mode,
		NewMode: true,
		Feature: feature,
	})
	if err != nil {
		return internal.SyncSelection{}, err
	}
	keep := make(map[string]bool, len(payload.Selected))
	for _, name := range payload.Selected {
		keep[name] = true
	}
	filtered := internal.SyncSelection{Policy: sel.Policy, Names: make(map[string]bool, len(keep))}
	repoSet := make(map[string]bool)
	for _, entry := range sel.Entries {
		if !keep[entry.Name] {
			continue
		}
		filtered.Entries = append(filtered.Entries, entry)
		filtered.Names[entry.Name] = true
		repoSet[entry.Repo] = true
	}
	for repo := range repoSet {
		filtered.Repos = append(filtered.Repos, repo)
	}
	sort.Strings(filtered.Repos)
	return filtered, nil
}

// scopedSelectionFromPayload rebuilds the run's selection from the payload's
// materialized `selected` list, so a stack.yaml edit between failure and
// --continue cannot silently re-scope the run. It is now a thin wrapper over
// scopedSelectionFromPayloadOrder, sorting its own order exactly as
// internal.ResolveSyncSelection itself does internally, so its result stays
// byte-identical.
func scopedSelectionFromPayload(stack internal.Stack, payload *internal.SyncRunState, feature string, mode internal.WorkspaceMode) (internal.SyncSelection, error) {
	order, err := internal.TopoSort(stack)
	if err != nil {
		return internal.SyncSelection{}, err
	}
	return scopedSelectionFromPayloadOrder(stack, order, payload, feature, mode)
}

func branchContainsConfiguredParent(worktreesRoot string, stack internal.Stack, child internal.StackEntry) bool {
	parent := internal.GetBranch(stack, child.Base)
	if parent.Name == "" || !sameStackRepo(parent.Repo, child.Repo) {
		return true
	}
	path := externalSyncLayout{WorktreesRoot: worktreesRoot}.WorktreePath(child.Name)
	return internal.RunSilentDir(path, "git", "merge-base", "--is-ancestor", parent.GitBranch(), child.GitBranch()) == nil
}

func isRebaseInProgress(worktreePath string) bool {
	// Check for .git/rebase-merge or .git/rebase-apply
	gitDir := internal.RunSilent("git", "-C", worktreePath, "rev-parse", "--git-dir")
	if gitDir != nil {
		return false
	}
	// Simpler: check if git status shows rebase
	err := internal.RunSilent("git", "-C", worktreePath, "rebase", "--show-current-patch")
	return err == nil
}

// syncFeature performs a legacy (non-scoped) sync run. guard is nil on the
// shipped path (unguarded fresh legacy) and non-nil only from
// runGuardedLegacySync, which has already performed this run's own
// admission fetch — so this function's own fetch loop is skipped whenever
// guard != nil, and a guarded LoadStack failure is reported as a
// plan-unavailable refusal rather than silently degrading to syncFallback:
// syncFallback is unreachable from a guarded route.
func syncFeature(feature string, layout externalSyncLayout, verbose bool, guard *planGuardRun) syncResult {
	stack, err := internal.LoadStack(layout.FeaturePath)
	if err != nil {
		if guard != nil {
			return syncResult{Refusal: &internal.PlanGuardRefusalError{Kind: string(internal.RefusalPlanUnavailable), Detail: err.Error()}}
		}
		fetchQuiet("", "", verbose)
		syncFallback(layout)
		return syncResult{Complete: true}
	}

	if guard == nil {
		repos := internal.UniqueRepos(stack, layout.FeaturePath)
		for repo, wtPath := range repos {
			fetchQuiet(repo, wtPath, verbose)
		}
	}

	sorted, err := internal.TopoSort(stack)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return syncResult{}
	}
	return syncWithStack(feature, layout, stack, sorted, guard)
}

// syncFeatureScoped is syncFeature for a new-mode run: the stack is already
// loaded and validated, and the fetch loop is restricted to the repos the
// selection actually touches. guard is nil on the shipped path; a guarded
// caller (runGuardedScopedSync, handleGuardedScopedSyncContinue) has already
// performed this run's own admission fetch, so this function's own fetch
// loop — and the Fetching stage transition that precedes it — are skipped
// whenever guard != nil.
func syncFeatureScoped(feature string, layout externalSyncLayout, verbose bool, stack internal.Stack, run *syncRunContext, guard *planGuardRun) syncResult {
	if run.Policy.Fetch == internal.SyncFetchEnabled && guard == nil {
		run.Payload.Stage = internal.SyncStageFetching
		_ = internal.SaveSyncRunState(layout.FeaturePath, run.Payload)
		sub := internal.Stack{Branches: selectedRealEntries(stack, run.Sel)}
		for repo, wtPath := range internal.UniqueRepos(sub, layout.FeaturePath) {
			fetchQuiet(repo, wtPath, verbose)
		}
	}
	sorted, err := internal.TopoSort(stack)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return syncResult{}
	}
	return syncFeatureScopedPlanned(feature, layout, stack, sorted, run, guard)
}

// syncFeatureScopedPlanned is syncFeatureScoped without the fetch block and
// without its TopoSort, which it receives as `sorted` (exploration §2.3): a
// guarded route already fetched above its claim and already owns this
// invocation's single order, so calling this instead of syncFeatureScoped is
// what keeps the guarded new-mode fresh route at exactly ONE sort and
// exactly one fetch (§9.1a rule 3, §10.1).
func syncFeatureScopedPlanned(feature string, layout externalSyncLayout, stack internal.Stack, sorted []internal.StackEntry, run *syncRunContext, guard *planGuardRun) syncResult {
	return syncWithStackScoped(feature, layout, stack, sorted, nil, run, guard)
}

// scopedPreludeFromInspection composes the shipped new-mode fresh prelude's
// refusals from the ONE inspection this invocation already performed, in the
// shipped order (stack, selection, I14 preflight) and with the shipped
// sentences. It re-loads nothing, re-sorts nothing and re-probes no base
// ref: §10.7 rule 1a's locator already ran inside InspectExternalPlan, and
// its verdict travels as a value.
func scopedPreludeFromInspection(feature string, insp ExternalPlanInspection) (internal.Stack, internal.SyncSelection, error) {
	if insp.StackErr != nil {
		return internal.Stack{}, internal.SyncSelection{}, fmt.Errorf("sync modes require a stack; feature %q has no readable stack.yaml", feature)
	}
	if insp.SortErr != nil {
		return internal.Stack{}, internal.SyncSelection{}, insp.SortErr
	}
	if insp.SelectionErr != nil {
		return internal.Stack{}, internal.SyncSelection{}, insp.SelectionErr
	}
	if insp.BasePreflight.Failed {
		return internal.Stack{}, internal.SyncSelection{}, fmt.Errorf("%s", insp.BasePreflight.Detail)
	}
	return insp.Stack, insp.Selection, nil
}

// validationIdentity freezes this guarded run's own validation command at
// birth (§15.5a): the executor consumes it as a VALUE and never re-reads
// internal.LoadConfig() under the claim.
func validationIdentity(command, source string) internal.PlanValidationIdentity {
	return internal.PlanValidationIdentity{
		Applies: true,
		Command: command,
		Source:  source,
		Digest:  internal.ValidationDigest(command),
	}
}

// selectedRealEntries returns the real StackEntry values of the selection, in
// selection order. Executors never rebuild entries from SyncSelectedEntry:
// that would drop LastBaseSHA and destroy the amend-aware replay.
func selectedRealEntries(stack internal.Stack, sel internal.SyncSelection) []internal.StackEntry {
	out := make([]internal.StackEntry, 0, len(sel.Entries))
	for _, entry := range sel.Entries {
		real := internal.GetBranch(stack, entry.Name)
		if real.Name == "" {
			continue
		}
		out = append(out, real)
	}
	return out
}

// syncRepoContext is the §13.4 rule 3 repo context: the entry's Repo when set,
// otherwise its materialized worktree path, otherwise "".
func syncRepoContext(layout externalSyncLayout, entry internal.StackEntry) string {
	if entry.Repo != "" {
		return entry.Repo
	}
	path := layout.WorktreePath(entry.Name)
	if _, err := os.Stat(path); err == nil {
		return path
	}
	return ""
}

// fetchQuietTo is fetchQuiet's writer-parameterized body: out receives the
// "Fetching X... done/failed" prose and the verbose child's own stdout;
// errw receives the verbose child's own stderr. A real execution passes
// os.Stdout/os.Stderr (fetchQuiet, below) so RunDirTo/RunTo reproduce
// RunDir/Run byte-for-byte; the plan route passes the same writer
// (cmd.ErrOrStderr()) for both, so a verbose child's output never reaches
// the real stdout while a plan document is being rendered there. ctx is the
// plan-side fetch context this row is measured against; it is the zero
// value on every real (non-plan) call, so RepoToken/ContextRoot/etc. are
// simply "" and Effect is nil — fields only the plan route's own
// PlanFetchOutcome folding reads.
func fetchQuietTo(out, errw io.Writer, repo, wtPath string, verbose bool, ctx internal.PlanFetchContext) internal.PlanFetchRepoResult {
	label := "default repo"
	if repo != "" {
		label = repo
	}

	var err error
	if verbose {
		fmt.Fprintf(out, "Fetching %s...\n", label) //nolint:errcheck
		if wtPath != "" {
			err = internal.RunDirTo(out, errw, wtPath, "git", "fetch")
		} else if repo != "" {
			err = internal.RunDirTo(out, errw, repo, "git", "fetch")
		} else {
			err = internal.RunTo(out, errw, "git", "fetch")
		}
	} else {
		fmt.Fprintf(out, "Fetching %s... ", label) //nolint:errcheck
		if wtPath != "" {
			err = internal.RunSilentDir(wtPath, "git", "fetch")
		} else if repo != "" {
			err = internal.RunSilentDir(repo, "git", "fetch")
		} else {
			err = internal.RunSilent("git", "fetch")
		}
		if err != nil {
			fmt.Fprintln(out, "failed") //nolint:errcheck
		} else {
			fmt.Fprintln(out, "done") //nolint:errcheck
		}
	}

	candidates := ctx.Candidates
	if candidates == nil {
		candidates = []internal.PlanFetchCandidate{}
	}
	return internal.PlanFetchRepoResult{
		RepoToken:         ctx.RepoToken,
		ContextRoot:       ctx.Root,
		ContextCommonDir:  ctx.CommonDir,
		ContextSource:     ctx.Source,
		ContextCandidates: candidates,
		Effect:            ctx.Effect,
		Attempted:         true,
		OK:                err == nil,
	}
}

// fetchQuiet is the shipped call site's discarding wrapper: it writes to
// os.Stdout/os.Stderr and passes a zero PlanFetchContext, exactly the fetch
// the shipped body always performed, and discards the row fetchQuietTo
// returns since no shipped caller ever folded it into a PlanFetchOutcome.
func fetchQuiet(repo, wtPath string, verbose bool) {
	fetchQuietTo(os.Stdout, os.Stderr, repo, wtPath, verbose, internal.PlanFetchContext{})
}

// fetchReposTo is the shared fetch loop both a real fetch (fetchStackReposTo/
// fetchScopedReposTo, called with os.Stdout/os.Stderr from a guarded
// executor) and the plan route's own pre-fetch enumeration (called with
// cmd.ErrOrStderr() for both writers) use: given the repo-token -> worktree-
// path map a fetch would touch, it fetches each in sorted-token order —
// exactly internal.checkoutFetchPlan's own enumeration order — and folds
// every attempted row into one PlanFetchOutcome.
func fetchReposTo(out, errw io.Writer, repos map[string]string, verbose bool, enumerated internal.PlanFetchPlan) internal.PlanFetchOutcome {
	// The enumerated plan is the ONE place a context's common dir and its
	// measured fetch effect are established, always BEFORE any child runs
	// (§11.1). Each attempted row copies them verbatim, so the outcome the
	// push baseline joins on (§14.1a rule 8's conjuncts ii-iv) describes the
	// fetch that really happened rather than an unmeasured stub.
	byToken := make(map[string]internal.PlanFetchContext, len(enumerated.Contexts))
	for _, c := range enumerated.Contexts {
		byToken[c.RepoToken] = c
	}

	tokens := make([]string, 0, len(repos))
	for token := range repos {
		tokens = append(tokens, token)
	}
	sort.Strings(tokens)

	outcome := internal.PlanFetchOutcome{Applies: true, Repos: []internal.PlanFetchRepoResult{}}
	for _, token := range tokens {
		wtPath := repos[token]
		root := token
		source := "entry-repo"
		if root == "" {
			root = wtPath
			source = "worktree"
		}
		ctx, enumeratedContext := byToken[token]
		if !enumeratedContext {
			ctx = internal.PlanFetchContext{RepoToken: token, Root: root, Source: source}
		}
		row := fetchQuietTo(out, errw, token, wtPath, verbose, ctx)
		outcome.Repos = append(outcome.Repos, row)
		if row.Attempted {
			outcome.Attempted = true
		}
	}
	return outcome
}

// fetchStackReposTo fetches every repo the whole stack touches — the legacy
// route's own fetch scope, both for a guarded fresh legacy run's admission
// fetch and for InspectExternalPlan's own legacy-route enumeration.
func fetchStackReposTo(out, errw io.Writer, layout externalSyncLayout, stack internal.Stack, verbose bool, enumerated internal.PlanFetchPlan) internal.PlanFetchOutcome {
	repos := internal.UniqueRepos(stack, layout.FeaturePath)
	return fetchReposTo(out, errw, repos, verbose, enumerated)
}

// fetchScopedReposTo fetches only the repos the selection's own materialized
// entries touch — the new-mode route's own fetch scope, both for a guarded
// scoped run's admission fetch and for InspectExternalPlan's own new-mode
// enumeration.
func fetchScopedReposTo(out, errw io.Writer, layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection, verbose bool, enumerated internal.PlanFetchPlan) internal.PlanFetchOutcome {
	sub := internal.Stack{Branches: selectedRealEntries(stack, sel)}
	repos := internal.UniqueRepos(sub, layout.FeaturePath)
	return fetchReposTo(out, errw, repos, verbose, enumerated)
}

package cli

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"runtime"
	"strings"
	"testing"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"gopkg.in/yaml.v3"
)

// ---------------------------------------------------------------------------
// §9 — downgrade evidence. The prior binary is obtained in the order §9.6
// prescribes: an exported binary, else an offline build of the local
// v1.2.15 tag, else the frozen replay harness — which is proven equivalent by
// a fidelity comparison whenever a real binary is available.
// ---------------------------------------------------------------------------

const downgradeTag = "v1.2.15"

// reparentDowngradeTag sits BESIDE downgradeTag, never in place of it: the
// sync-modes evidence keeps proving v1.2.15's behaviour while safe-reparent's
// own evidence (§17.4a) needs the release immediately before it. Full-history
// CI can build either tag; a shallow or cache-cold environment falls back to
// the frozen replay rather than dropping the cell or hard-failing.
const reparentDowngradeTag = "v1.2.16"

// priorBinary is the resolved prior tws, or an empty path when none could be
// obtained. `note` always explains which acquisition step produced it.
type priorBinary struct {
	path string
	note string
}

func assertExactPriorCheckoutPlainRefusal(t *testing.T, message string) {
	t.Helper()
	const want = "previous checkout-sync incomplete; use --continue or --abort"
	lines := strings.Split(message, "\n")
	if len(lines) < 2 || lines[0] != "Error: "+want || lines[len(lines)-1] != want {
		t.Fatalf("plain checkout refusal did not preserve the exact v1.2.16 sentence:\n%s", message)
	}
}

func parsedTWSVersion(out []byte) (string, bool) {
	fields := strings.Fields(strings.TrimSpace(string(out)))
	if len(fields) != 3 || fields[0] != "tws" || fields[1] != "version" {
		return "", false
	}
	return fields[2], true
}

func TestDowngradeVersionParsingRequiresExactRelease(t *testing.T) {
	if got, ok := parsedTWSVersion([]byte("tws version v1.2.16\n")); !ok || got != reparentDowngradeTag {
		t.Fatalf("exact version parsed as %q, %v", got, ok)
	}
	for _, output := range []string{
		"tws version v1.2.160\n",
		"tws version v1.2.16-dirty\n",
		"prefix v1.2.16 suffix\n",
	} {
		if got, ok := parsedTWSVersion([]byte(output)); ok && got == reparentDowngradeTag {
			t.Fatalf("non-exact version %q was accepted", output)
		}
	}
}

// downgradeSourceRoot locates the tws source repository from this test file, so
// it survives every chdir the fixtures perform.
func downgradeSourceRoot(t *testing.T) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("cannot locate the test source file")
	}
	return filepath.Dir(filepath.Dir(filepath.Dir(file)))
}

// acquireDowngradeBinary implements the §9.6 acquisition order for the
// sync-modes evidence, which is pinned to downgradeTag. It is the
// backwards-compatible wrapper over acquireDowngradeBinaryFor, so every
// existing caller keeps its exact behaviour.
func acquireDowngradeBinary(t *testing.T) priorBinary {
	t.Helper()
	return acquireDowngradeBinaryFor(t, downgradeTag)
}

// acquireDowngradeBinaryFor implements the §9.6 acquisition order for ONE
// tag. It never fails the test: a missing binary degrades to the harness,
// which always runs.
//
// It MUST be called before any fixture rewrites HOME, so the offline build can
// use the developer's existing build and module caches.
//
// TWS_DOWNGRADE_BINARY remains the v1.2.15 override and is deliberately NOT
// consulted for any other tag: a single environment variable cannot name two
// different releases, and silently building the wrong one would make the
// evidence meaningless. A per-tag override is available as
// TWS_DOWNGRADE_BINARY_<TAG>, with dots replaced by underscores.
func acquireDowngradeBinaryFor(t *testing.T, tag string) priorBinary {
	t.Helper()
	countReparent := tag == reparentDowngradeTag

	// 1. A real prior binary supplied by the environment. The generic
	// override is always checked first; a tag-specific override is the
	// optional second spelling when a job supplies more than one release.
	envNames := []string{"TWS_DOWNGRADE_BINARY"}
	tagEnv := "TWS_DOWNGRADE_BINARY_" + strings.ToUpper(strings.NewReplacer(".", "_", "-", "_").Replace(tag))
	if tagEnv != envNames[0] {
		envNames = append(envNames, tagEnv)
	}
	for _, envName := range envNames {
		if path := os.Getenv(envName); path != "" {
			info, err := os.Stat(path)
			switch {
			case err != nil:
				t.Logf("%s=%s is not usable: %v", envName, path, err)
			case info.Mode()&0o111 == 0:
				t.Logf("%s=%s is not executable", envName, path)
			default:
				out, versionErr := exec.Command(path, "--version").CombinedOutput()
				gotVersion, parsed := parsedTWSVersion(out)
				if versionErr != nil || !parsed || gotVersion != tag {
					t.Logf("%s=%s is not %s (%v, %q)", envName, path, tag, versionErr, strings.TrimSpace(string(out)))
					continue
				}
				return priorBinary{path: path, note: envName}
			}
		}
	}

	// 2. An offline build of the local tag, in an isolated detached worktree.
	root := downgradeSourceRoot(t)
	if err := testGitCommand(t, root, countReparent, "rev-parse", "-q", "--verify", "refs/tags/"+tag).Run(); err != nil {
		t.Logf("no local %s tag: %v", tag, err)
		return priorBinary{note: "no prior binary: tag " + tag + " is not present locally"}
	}

	dir := t.TempDir()
	src := filepath.Join(dir, "src")
	if out, err := testGitCommand(t, root, countReparent, "worktree", "add", "--detach", src, tag).CombinedOutput(); err != nil {
		t.Logf("cannot check out %s: %v\n%s", tag, err, out)
		return priorBinary{note: "no prior binary: worktree checkout failed"}
	}
	t.Cleanup(func() {
		_ = testGitCommand(t, root, countReparent, "worktree", "remove", "--force", src).Run()
		_ = testGitCommand(t, root, countReparent, "worktree", "prune").Run()
	})

	bin := filepath.Join(dir, "tws-"+tag)
	build := exec.Command("go", "build", "-ldflags", "-X main.version="+tag, "-o", bin, "./cmd/tws")
	build.Dir = src
	build.Env = append(os.Environ(), "GOFLAGS=-mod=mod", "GOPROXY=off")
	if out, err := build.CombinedOutput(); err != nil {
		t.Logf("offline build of %s failed: %v\n%s", tag, err, out)
		return priorBinary{note: "no prior binary: offline build failed"}
	}
	out, versionErr := exec.Command(bin, "--version").CombinedOutput()
	gotVersion, parsed := parsedTWSVersion(out)
	if versionErr != nil || !parsed || gotVersion != tag {
		t.Logf("offline build reports %q instead of exact %s (%v)", strings.TrimSpace(string(out)), tag, versionErr)
		return priorBinary{note: "no prior binary: offline build version mismatch"}
	}
	return priorBinary{path: bin, note: "offline build of " + tag}
}

// runPriorBinary runs the prior tws inside the fixture, with the fixture's own
// environment (t.Setenv has already published HOME and TWS_ROOT to the process).
func runPriorBinary(t *testing.T, bin, dir string, args ...string) (stdout, stderr string, exit int) {
	t.Helper()
	cmd := exec.Command(bin, args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "GIT_EDITOR=true", "GIT_SEQUENCE_EDITOR=true")
	var outBuf, errBuf strings.Builder
	cmd.Stdout = &outBuf
	cmd.Stderr = &errBuf
	err := cmd.Run()
	if err != nil {
		var exitErr *exec.ExitError
		if !asExitError(err, &exitErr) {
			t.Fatalf("running the prior binary failed: %v\n%s", err, errBuf.String())
		}
		exit = exitErr.ExitCode()
	}
	return outBuf.String(), errBuf.String(), exit
}

func runPriorBinaryWithGitTrace(t *testing.T, bin, dir string, args ...string) (stdout, stderr string, exit int, gitArgv []string) {
	t.Helper()
	realGit, err := exec.LookPath("git")
	if err != nil {
		t.Fatal(err)
	}
	shimDir := t.TempDir()
	logPath := filepath.Join(shimDir, "git-argv.log")
	shim := filepath.Join(shimDir, "git")
	script := "#!/bin/sh\n" +
		"printf '%s\\n' \"$*\" >> \"$TWS_DOWNGRADE_GIT_LOG\"\n" +
		"exec \"$TWS_DOWNGRADE_REAL_GIT\" \"$@\"\n"
	if err := os.WriteFile(shim, []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	cmd := exec.Command(bin, args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(),
		"GIT_EDITOR=true",
		"GIT_SEQUENCE_EDITOR=true",
		"PATH="+shimDir+string(os.PathListSeparator)+os.Getenv("PATH"),
		"TWS_DOWNGRADE_GIT_LOG="+logPath,
		"TWS_DOWNGRADE_REAL_GIT="+realGit,
	)
	var outBuf, errBuf strings.Builder
	cmd.Stdout = &outBuf
	cmd.Stderr = &errBuf
	runErr := cmd.Run()
	if runErr != nil {
		var exitErr *exec.ExitError
		if !asExitError(runErr, &exitErr) {
			t.Fatalf("running the prior binary failed: %v\n%s", runErr, errBuf.String())
		}
		exit = exitErr.ExitCode()
	}
	if data, readErr := os.ReadFile(logPath); readErr == nil {
		for _, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
			if strings.TrimSpace(line) != "" {
				gitArgv = append(gitArgv, strings.TrimSpace(line))
			}
		}
	} else if !os.IsNotExist(readErr) {
		t.Fatal(readErr)
	}
	return outBuf.String(), errBuf.String(), exit, gitArgv
}

type downgradePathSnapshot struct {
	present bool
	data    []byte
}

func snapshotDowngradePath(t *testing.T, path string) downgradePathSnapshot {
	t.Helper()
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return downgradePathSnapshot{}
	}
	if err != nil {
		t.Fatal(err)
	}
	return downgradePathSnapshot{present: true, data: data}
}

func assertDowngradePathUnchanged(t *testing.T, path string, before downgradePathSnapshot) {
	t.Helper()
	after := snapshotDowngradePath(t, path)
	if before.present != after.present || !bytes.Equal(before.data, after.data) {
		t.Fatalf("%s changed across the prior-binary refusal: before=%+v after=%+v", path, before, after)
	}
}

func assertNoDowngradeRebaseAbort(t *testing.T, argv []string) {
	t.Helper()
	for _, line := range argv {
		fields := strings.Fields(line)
		for i := 0; i+1 < len(fields); i++ {
			if fields[i] == "rebase" && fields[i+1] == "--abort" {
				t.Fatalf("prior binary reached git rebase --abort: %v", argv)
			}
		}
	}
}

func asExitError(err error, target **exec.ExitError) bool {
	if e, ok := err.(*exec.ExitError); ok {
		*target = e
		return true
	}
	return false
}

// pinSyncMarker freezes the per-run marker so two independent fixtures produce
// byte-identical downgrade messages, which is what makes the harness and the
// real binary comparable at all.
func pinSyncMarker(t *testing.T, marker string) {
	t.Helper()
	previous := syncMarkerFn
	syncMarkerFn = func() (string, error) { return marker, nil }
	t.Cleanup(func() { syncMarkerFn = previous })
}

const downgradePinnedMarker = "tws-scoped-sync-0123456789abcdef0123456789abcdef.lock"

// downgradeOutcome is the observable result of one prior-binary verb, in the
// terms both the harness and a real process can produce.
type downgradeOutcome struct {
	failed       bool
	message      string
	sentinelGone bool
	payloadGone  bool
	refsMoved    bool
	fetched      bool
}

// alignWorkspaceRootWithTwsRoot makes the workspace metadata root agree with
// TWS_ROOT for this fixture. The prior binary resolves its state path through
// the workspace alone (it predates the single-layout resolver), so a divergent
// fixture would have it inspect a directory that holds no feature at all —
// which measures the C4 defect, not the downgrade mechanism.
func alignWorkspaceRootWithTwsRoot(t *testing.T, repo string) {
	t.Helper()
	root := os.Getenv("TWS_ROOT")
	if root == "" {
		t.Fatal("the fixture must publish TWS_ROOT")
	}
	keys := map[string]bool{repo: true}
	if real, err := filepath.EvalSymlinks(repo); err == nil {
		keys[real] = true
	}
	var b strings.Builder
	b.WriteString("workspaces:\n")
	for key := range keys {
		fmt.Fprintf(&b, "  %q: %q\n", key, root)
	}
	path := internal.ConfigPath()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(b.String()), 0o644); err != nil {
		t.Fatal(err)
	}
	ws, err := internal.RequireWorkspace()
	if err != nil {
		t.Fatalf("workspace resolution: %v", err)
	}
	if filepath.Clean(ws.MetadataRoot) != filepath.Clean(internal.TwsRoot()) {
		t.Fatalf("metadata root %s and TWS_ROOT %s still disagree", ws.MetadataRoot, internal.TwsRoot())
	}
}

// newDowngradeFixture builds a feature stopped mid-rebase by a real scoped run,
// with the pinned marker on disk: sentinel + payload + guard, cell 5.
func newDowngradeFixture(t *testing.T) *scopedFixture {
	t.Helper()
	f := newScopedFixture(t)
	alignWorkspaceRootWithTwsRoot(t, f.repo)
	pinSyncMarker(t, downgradePinnedMarker)
	f.makeConflict(t)
	if _, _, exit := runSync(t, f.feature, "--only", "child", "--no-fetch"); exit == 0 {
		t.Fatal("the fixture must stop on a real conflict")
	}
	if got := readFileString(t, internal.SyncStatePath(f.featurePath)); !strings.Contains(got, downgradePinnedMarker) {
		t.Fatalf("the sentinel must carry the pinned marker:\n%s", got)
	}
	return f
}

func downgradeRefs(t *testing.T, f *scopedFixture) string {
	t.Helper()
	return gitOutput(t, f.repo, "for-each-ref", "--format=%(refname) %(objectname)", "refs/heads")
}

// harnessOutcome computes the v1.2.15-equivalent outcome over a fresh fixture.
// Unlike the true v1.2.14-era harness of sync_scoped_test.go (legacyPlainSync
// et al., which is blind to the v2 payload sync-modes introduced), a real
// v1.2.15 binary already classifies scoped state through the same cell
// machinery this binary uses, and its cell-5/live-guard dispatch is unchanged
// since (§22.24c backward compatibility). The in-process dispatch is therefore
// the v1.2.15 answer for this fixture shape, and binaryOutcome below verifies
// that claim against a real offline-built v1.2.15 binary whenever one is
// available.
func harnessOutcome(t *testing.T, verb string) downgradeOutcome {
	t.Helper()
	f := newDowngradeFixture(t)
	f.detachGuard(t)
	refsBefore := downgradeRefs(t, f)

	args := []string{f.feature}
	switch verb {
	case "plain":
	case "continue":
		args = append(args, "--continue")
	case "abort":
		args = append(args, "--abort")
	default:
		t.Fatalf("unknown verb %q", verb)
	}
	stdout, stderr, exit := runSync(t, args...)

	out := downgradeOutcome{failed: exit != 0}
	if out.failed {
		out.message = strings.TrimSpace(stderr)
	} else {
		out.message = strings.TrimSpace(stdout)
	}
	out.sentinelGone = !internal.HasSyncState(f.featurePath)
	out.payloadGone = !internal.HasSyncRunState(f.featurePath)
	out.refsMoved = downgradeRefs(t, f) != refsBefore
	return out
}

// binaryOutcome runs the real prior binary over an identically built fixture.
func binaryOutcome(t *testing.T, bin, verb string) downgradeOutcome {
	t.Helper()
	f := newDowngradeFixture(t)
	f.detachGuard(t)
	refsBefore := downgradeRefs(t, f)

	args := []string{"sync", f.feature}
	switch verb {
	case "plain":
	case "continue":
		args = append(args, "--continue")
	case "abort":
		args = append(args, "--abort")
	default:
		t.Fatalf("unknown verb %q", verb)
	}
	stdout, stderr, exit := runPriorBinary(t, bin, f.repo, args...)

	out := downgradeOutcome{failed: exit != 0}
	if out.failed {
		out.message = strings.TrimSpace(stderr)
	} else {
		out.message = strings.TrimSpace(stdout)
	}
	out.sentinelGone = !internal.HasSyncState(f.featurePath)
	out.payloadGone = !internal.HasSyncRunState(f.featurePath)
	out.refsMoved = downgradeRefs(t, f) != refsBefore
	out.fetched = strings.Contains(stdout, "Fetching")
	return out
}

// TestSyncDowngrade covers AC 27, AC 28, AC 31, and AC 32 with whichever prior
// binary §9.6 yields, and never skips entirely.
func TestSyncDowngrade(t *testing.T) {
	prior := acquireDowngradeBinary(t)
	if prior.path == "" {
		t.Logf("downgrade evidence uses the frozen replay harness only (%s)", prior.note)
	} else {
		t.Logf("downgrade evidence uses %s (%s)", prior.path, prior.note)
	}

	t.Run("sentinel-refusals", func(t *testing.T) {
		for _, tc := range []struct {
			verb    string
			failed  bool
			message string
		}{
			{
				verb:    "plain",
				failed:  true,
				message: "a scoped sync is incomplete (failed on: child); use --continue or --abort",
			},
			{
				verb:    "continue",
				failed:  true,
				message: "rebase still in progress in child; resolve conflicts, run git add . && git rebase --continue, then retry",
			},
			{
				verb:    "abort",
				failed:  false,
				message: "Sync state cleared.",
			},
		} {
			t.Run(tc.verb, func(t *testing.T) {
				h := harnessOutcome(t, tc.verb)
				if h.failed != tc.failed {
					t.Fatalf("harness %s failed = %v, want %v (%q)", tc.verb, h.failed, tc.failed, h.message)
				}
				if h.message != tc.message {
					t.Fatalf("harness %s message = %q, want %q", tc.verb, h.message, tc.message)
				}
				if h.refsMoved {
					t.Fatalf("%s must rebase nothing", tc.verb)
				}
				if tc.verb == "abort" != h.payloadGone {
					t.Fatalf("only --abort removes the payload (%s removed it = %v)", tc.verb, h.payloadGone)
				}
				if tc.verb == "abort" != h.sentinelGone {
					t.Fatalf("only --abort removes the sentinel (%s removed it = %v)", tc.verb, h.sentinelGone)
				}

				if prior.path == "" {
					t.Logf("fidelity comparison skipped: %s", prior.note)
					return
				}
				b := binaryOutcome(t, prior.path, tc.verb)
				if b.failed != h.failed {
					t.Fatalf("%s: binary failed = %v, harness = %v (%q)", tc.verb, b.failed, h.failed, b.message)
				}
				if !strings.Contains(b.message, h.message) {
					t.Fatalf("%s: the binary's output must contain the harness message.\nbinary:\n%s\nharness:\n%s", tc.verb, b.message, h.message)
				}
				if b.sentinelGone != h.sentinelGone || b.payloadGone != h.payloadGone {
					t.Fatalf("%s: binary state (sentinel gone %v, payload gone %v) differs from the harness (%v, %v)",
						tc.verb, b.sentinelGone, b.payloadGone, h.sentinelGone, h.payloadGone)
				}
				if b.refsMoved != h.refsMoved {
					t.Fatalf("%s: binary moved refs = %v, harness = %v", tc.verb, b.refsMoved, h.refsMoved)
				}
				if b.fetched {
					t.Fatalf("%s: the prior binary must fail closed before any fetch:\n%s", tc.verb, b.message)
				}
			})
		}
	})

	t.Run("old-abort-under-a-live-owning-guard", func(t *testing.T) {
		testDowngradeLiveGuardCellTwo(t, prior)
	})

	t.Run("mixed-state-genesis", func(t *testing.T) {
		testDowngradeMixedStateGenesis(t, prior)
	})
}

// testDowngradeLiveGuardCellTwo is the second variant of AC 31: the failed
// run's owning process is still alive. Sync-modes' guard-liveness check
// already shipped at v1.2.15 (§22.24c), so a real v1.2.15 --abort refuses
// here exactly like the current binary — it cannot distinguish this PID from
// any other live one — and neither one mutates anything.
func testDowngradeLiveGuardCellTwo(t *testing.T, prior priorBinary) {
	t.Helper()
	f := newDowngradeFixture(t)
	// The guard is left exactly as the failed run wrote it: this process owns
	// it and this process is alive, which is the live-owning-guard shape.
	guard, err := internal.ReadSyncRunGuard(f.featurePath)
	if err != nil {
		t.Fatalf("the guard must survive the failure: %v", err)
	}
	if guard.PID != os.Getpid() {
		t.Fatalf("guard pid = %d, want this live process %d", guard.PID, os.Getpid())
	}

	// A real v1.2.15 --abort already refuses under a live owning guard, the
	// same protection the current binary gives; it removes neither artefact.
	if prior.path != "" {
		stdout, stderr, exit := runPriorBinary(t, prior.path, f.repo, "sync", f.feature, "--abort")
		if exit == 0 {
			t.Fatalf("a v1.2.15 --abort must refuse under a live owning guard, not clear it: %s", stdout)
		}
		want := fmt.Sprintf("a scoped sync is running for %q (pid %d); wait for it to exit before --abort", f.feature, guard.PID)
		if !strings.Contains(stderr, want) {
			t.Fatalf("v1.2.15 --abort stderr = %q, want to contain %q", stderr, want)
		}
	}
	if !internal.HasSyncState(f.featurePath) {
		t.Fatal("a refused --abort must not remove the sentinel")
	}
	if !internal.HasSyncRunState(f.featurePath) {
		t.Fatal("a refused --abort must not remove the payload")
	}
	if !isRebaseInProgress(f.wt("child")) {
		t.Fatal("the real rebase must still be in progress")
	}

	state := internal.ClassifyExternalSyncState(f.featurePath, internal.SyncClassifyOpts{AlwaysReadGuard: true})
	if state.Cell != 5 {
		t.Fatalf("cell = %d, want 5 {sentinel, valid} — a refused --abort changes nothing", state.Cell)
	}
	if !state.GuardLive {
		t.Fatal("the guard must still be live and owning")
	}

	payloadBefore := readFileString(t, internal.SyncRunStatePath(f.featurePath))
	guardBefore := readFileString(t, internal.SyncRunGuardPath(f.featurePath))
	childBefore := f.sha(t, "child")

	for _, tc := range []struct {
		name string
		args []string
		want string
	}{
		{"plain", nil, fmt.Sprintf("a scoped sync is already running for %q (pid %d", f.feature, guard.PID)},
		{"continue", []string{"--continue"}, fmt.Sprintf("a scoped sync is already running for %q (pid %d", f.feature, guard.PID)},
		{"abort", []string{"--abort"}, fmt.Sprintf("a scoped sync is running for %q (pid %d); wait for it to exit before --abort", f.feature, guard.PID)},
	} {
		args := append([]string{f.feature}, tc.args...)
		_, stderr, exit := runSync(t, args...)
		if exit == 0 {
			t.Fatalf("%s must be refused under a live owning guard", tc.name)
		}
		if !strings.Contains(stderr, tc.want) {
			t.Fatalf("%s: stderr = %q, want %q", tc.name, stderr, tc.want)
		}
		if got := readFileString(t, internal.SyncRunStatePath(f.featurePath)); got != payloadBefore {
			t.Fatalf("%s rewrote the payload of a live run", tc.name)
		}
		if got := readFileString(t, internal.SyncRunGuardPath(f.featurePath)); got != guardBefore {
			t.Fatalf("%s rewrote the guard of a live run", tc.name)
		}
		if !isRebaseInProgress(f.wt("child")) {
			t.Fatalf("%s aborted the rebase another live process owns", tc.name)
		}
		if got := f.sha(t, "child"); got != childBefore {
			t.Fatalf("%s moved the branch of a live run: %s -> %s", tc.name, childBefore, got)
		}
	}
}

// testDowngradeMixedStateGenesis reproduces §9.3 sequence 1 end to end. Only a
// TRUE v1.2.14-era binary — blind to the v2 payload sync-modes introduced —
// can leave cell 2 by aborting just the legacy sentinel: a real v1.2.15
// binary already manages both artefacts together (its --abort clears the
// payload too, or refuses outright under a live guard, see the two cases
// above), so it cannot produce this residue. The historical defect is
// therefore built through the frozen v1.2.14 replay harness unconditionally;
// the resulting cell 8 is then checked against the current binary and,
// where a real v1.2.15 binary is available, against it too — proving the
// shipped cell-8 sentences predate the guard feature and are unchanged by it.
func testDowngradeMixedStateGenesis(t *testing.T, prior priorBinary) {
	t.Helper()
	f := newDowngradeFixture(t)
	f.detachGuard(t)

	// Step 1 — a true v1.2.14-era abort removes the sentinel only; it cannot
	// see the payload sync-modes introduced.
	if msg := legacyAbort(f.feature, f.featurePath); msg != "Sync state cleared." {
		t.Fatalf("old --abort printed %q", msg)
	}
	if internal.HasSyncState(f.featurePath) || !internal.HasSyncRunState(f.featurePath) {
		t.Fatal("cell 2 is sentinel-absent and payload-present")
	}

	// Step 2 — a true v1.2.14-era plain sync is no longer blocked (the marker
	// it would have refused on is gone), runs for real, and fails on the
	// worktree that is still mid-rebase, writing REAL legacy state beside the
	// payload it cannot see.
	if err := legacyPlainSync(f.featurePath); err != nil {
		t.Fatalf("the old plain sync must no longer be blocked: %v", err)
	}
	stack, err := internal.LoadStack(f.featurePath)
	if err != nil {
		t.Fatal(err)
	}
	sorted, err := internal.TopoSort(stack)
	if err != nil {
		t.Fatal(err)
	}
	saveIncompleteSync(f.featurePath, sorted, []string{"root", "parent"}, "child")

	legacy, err := internal.LoadSyncState(f.featurePath)
	if err != nil {
		t.Fatalf("the old plain sync must write real legacy state: %v", err)
	}
	if legacy.FailedBranch != "child" {
		t.Fatalf("legacy failed_branch = %q, want the resolvable name child", legacy.FailedBranch)
	}
	payload, err := internal.LoadSyncRunState(f.featurePath)
	if err != nil {
		t.Fatalf("the v2 payload must survive: %v", err)
	}
	if payload.FailedBranch != "child" {
		t.Fatalf("payload failed_branch = %q", payload.FailedBranch)
	}
	state := internal.ClassifyExternalSyncState(f.featurePath, internal.SyncClassifyOpts{AlwaysReadGuard: true})
	if state.Cell != 8 {
		t.Fatalf("cell = %d, want 8 {real legacy, valid}", state.Cell)
	}

	// Step 3 — the current binary refuses all three verbs, names both failed
	// entries, and deletes neither file.
	legacyBytes := readFileString(t, internal.SyncStatePath(f.featurePath))
	payloadBytes := readFileString(t, internal.SyncRunStatePath(f.featurePath))
	cellEightCases := []struct {
		name string
		args []string
		want string
	}{
		{"plain", nil, fmt.Sprintf("two unfinished syncs are recorded for %q: a legacy sync failed on child and a scoped sync failed on child", f.feature)},
		{"continue", []string{"--continue"}, fmt.Sprintf("two unfinished syncs are recorded for %q", f.feature)},
		{"abort", []string{"--abort"}, fmt.Sprintf("refusing to clear two unfinished syncs at once for %q", f.feature)},
	}
	for _, tc := range cellEightCases {
		args := append([]string{f.feature}, tc.args...)
		_, stderr, exit := runSync(t, args...)
		if exit == 0 {
			t.Fatalf("%s must be refused in cell 8", tc.name)
		}
		if !strings.Contains(stderr, tc.want) {
			t.Fatalf("%s: stderr = %q, want %q", tc.name, stderr, tc.want)
		}
		if !strings.Contains(stderr, internal.SyncStatePath(f.featurePath)) || !strings.Contains(stderr, internal.SyncRunStatePath(f.featurePath)) {
			t.Fatalf("%s: the message must name both files: %q", tc.name, stderr)
		}
		if got := readFileString(t, internal.SyncStatePath(f.featurePath)); got != legacyBytes {
			t.Fatalf("%s changed the legacy file", tc.name)
		}
		if got := readFileString(t, internal.SyncRunStatePath(f.featurePath)); got != payloadBytes {
			t.Fatalf("%s changed the payload", tc.name)
		}
	}

	// Step 4 — a real v1.2.15 binary meeting the identical cell-8 residue
	// already carries the shipped sentence: this mixed state predates the
	// guard feature entirely, so its messages are unchanged across the
	// version boundary, and it deletes neither file either.
	if prior.path == "" {
		return
	}
	for _, tc := range cellEightCases {
		args := append([]string{"sync", f.feature}, tc.args...)
		_, stderr, exit := runPriorBinary(t, prior.path, f.repo, args...)
		if exit == 0 {
			t.Fatalf("v1.2.15 %s must be refused in cell 8", tc.name)
		}
		if !strings.Contains(stderr, tc.want) {
			t.Fatalf("v1.2.15 %s: stderr = %q, want %q", tc.name, stderr, tc.want)
		}
		if got := readFileString(t, internal.SyncStatePath(f.featurePath)); got != legacyBytes {
			t.Fatalf("v1.2.15 %s changed the legacy file", tc.name)
		}
		if got := readFileString(t, internal.SyncRunStatePath(f.featurePath)); got != payloadBytes {
			t.Fatalf("v1.2.15 %s changed the payload", tc.name)
		}
	}
}

// ---------------------------------------------------------------------------
// T-070 — safe-reparent downgrade evidence (§14.3, §17.4a, AC-082, AC-083).
//
// The defect this cell guards against is a prior binary's control flow
// reaching a MUTATION before its version check. Only an executed prior binary
// demonstrates that, so asserting the shipped loader functions directly is a
// necessary supplement and an insufficient substitute — both halves run here.
//
// v1.2.16 is acquired BESIDE v1.2.15, through the same parameterized ladder,
// and the existing fidelity comparison is untouched.
// ---------------------------------------------------------------------------

type frozenV1216SyncRunState struct {
	StateVersion int `yaml:"state_version"`
}

type frozenV1216CheckoutTransaction struct {
	StateVersion int `yaml:"state_version,omitempty"`
}

const (
	frozenV1216SyncRunStateVersion        = 2
	frozenV1216SyncRunStateGuardedVersion = 3
)

func frozenV1216SyncRunStatePath(featurePath string) string {
	return filepath.Join(featurePath, ".sync-state.v2.yaml")
}

func frozenV1216SyncStatePath(featurePath string) string {
	return filepath.Join(featurePath, ".sync-state.yaml")
}

func frozenV1216CheckoutStateDir(featurePath string) string {
	featuresDir := filepath.Dir(filepath.Clean(featurePath))
	return filepath.Join(filepath.Dir(featuresDir), "state")
}

func frozenV1216CheckoutTransactionPath(featurePath string) string {
	return filepath.Join(frozenV1216CheckoutStateDir(featurePath),
		filepath.Base(featurePath)+"-checkout-sync.yaml")
}

func frozenV1216CheckoutLockPath(featurePath string) string {
	return filepath.Join(frozenV1216CheckoutStateDir(featurePath),
		filepath.Base(featurePath)+"-checkout-sync.lock")
}

func frozenV1216LoadSyncRunState(featurePath string) error {
	data, err := os.ReadFile(frozenV1216SyncRunStatePath(featurePath))
	if err != nil {
		return err
	}
	var state frozenV1216SyncRunState
	if err := yaml.Unmarshal(data, &state); err != nil {
		return err
	}
	if state.StateVersion != frozenV1216SyncRunStateVersion &&
		state.StateVersion != frozenV1216SyncRunStateGuardedVersion {
		return fmt.Errorf("unsupported scoped sync state version %d", state.StateVersion)
	}
	return nil
}

func frozenV1216LoadCheckoutTransaction(featurePath string) error {
	data, err := os.ReadFile(frozenV1216CheckoutTransactionPath(featurePath))
	if err != nil {
		return err
	}
	var tx frozenV1216CheckoutTransaction
	return yaml.Unmarshal(data, &tx)
}

func frozenReparentDowngradeOutcome(t *testing.T, f *reparentFixture, verb string) (downgradeOutcome, []string) {
	t.Helper()
	paths := []string{internal.ReparentStatePath(f.Loc())}
	if f.Mode == internal.ModeCheckout {
		paths = append(paths,
			frozenV1216CheckoutTransactionPath(f.FeaturePath),
			frozenV1216CheckoutLockPath(f.FeaturePath),
			internal.CheckoutMutationLockPath(f.Loc().CheckoutStateDir),
		)
	} else {
		paths = append(paths,
			frozenV1216SyncStatePath(f.FeaturePath),
			frozenV1216SyncRunStatePath(f.FeaturePath),
		)
	}
	before := make(map[string]downgradePathSnapshot, len(paths))
	for _, path := range paths {
		before[path] = snapshotDowngradePath(t, path)
	}
	out := downgradeOutcome{}
	gitArgv := withFrozenDowngradeGitTrace(t, func() {
		if f.Mode == internal.ModeExternal {
			if err := frozenV1216LoadSyncRunState(f.FeaturePath); err == nil {
				out.message = "frozen v1.2.16 unexpectedly decoded reparent external state"
				return
			} else {
				out.failed = true
				out.message = fmt.Sprintf(
					"scoped sync state is unreadable or uses an unsupported version (%v); inspect it and remove it manually — tws will not guess",
					err)
			}
			return
		}
		switch verb {
		case "plain":
			if _, err := os.Stat(frozenV1216CheckoutTransactionPath(f.FeaturePath)); err == nil {
				out.failed = true
				out.message = "previous checkout-sync incomplete; use --continue or --abort"
			} else if !os.IsNotExist(err) {
				out.failed = true
				out.message = err.Error()
			}
		case "continue", "abort":
			if err := frozenV1216LoadCheckoutTransaction(f.FeaturePath); err != nil {
				out.failed = true
				out.message = fmt.Sprintf("no transaction to %s: %v", verb, err)
			}
		}
	})
	for _, path := range paths {
		assertDowngradePathUnchanged(t, path, before[path])
	}
	return out, gitArgv
}

func withFrozenDowngradeGitTrace(t *testing.T, fn func()) []string {
	t.Helper()
	realGit, err := exec.LookPath("git")
	if err != nil {
		t.Fatal(err)
	}
	shimDir := t.TempDir()
	logPath := filepath.Join(shimDir, "frozen-git-argv.log")
	shim := filepath.Join(shimDir, "git")
	script := "#!/bin/sh\n" +
		"printf '%s\\n' \"$*\" >> \"$TWS_FROZEN_GIT_LOG\"\n" +
		"exec \"$TWS_FROZEN_REAL_GIT\" \"$@\"\n"
	if err := os.WriteFile(shim, []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	oldPath := os.Getenv("PATH")
	oldLog, hadLog := os.LookupEnv("TWS_FROZEN_GIT_LOG")
	oldReal, hadReal := os.LookupEnv("TWS_FROZEN_REAL_GIT")
	if err := os.Setenv("PATH", shimDir+string(os.PathListSeparator)+oldPath); err != nil {
		t.Fatal(err)
	}
	_ = os.Setenv("TWS_FROZEN_GIT_LOG", logPath)
	_ = os.Setenv("TWS_FROZEN_REAL_GIT", realGit)
	defer func() {
		_ = os.Setenv("PATH", oldPath)
		if hadLog {
			_ = os.Setenv("TWS_FROZEN_GIT_LOG", oldLog)
		} else {
			_ = os.Unsetenv("TWS_FROZEN_GIT_LOG")
		}
		if hadReal {
			_ = os.Setenv("TWS_FROZEN_REAL_GIT", oldReal)
		} else {
			_ = os.Unsetenv("TWS_FROZEN_REAL_GIT")
		}
	}()
	fn()
	data, err := os.ReadFile(logPath)
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		t.Fatal(err)
	}
	var out []string
	for _, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
		if line != "" {
			out = append(out, line)
		}
	}
	return out
}

func assertFrozenReparentDowngradeOutcome(t *testing.T, f *reparentFixture, verb string, outcome downgradeOutcome, refsBefore, headBefore string) {
	t.Helper()
	if !outcome.failed {
		t.Fatalf("the frozen %s outcome must fail closed", verb)
	}
	if f.Mode == internal.ModeExternal && !strings.Contains(outcome.message, "unsupported scoped sync state version 4") {
		t.Fatalf("external %s outcome = %q", verb, outcome.message)
	}
	if f.Mode == internal.ModeCheckout {
		if verb == "continue" && !strings.Contains(outcome.message, "no transaction to continue") {
			t.Fatalf("checkout continue outcome = %q", outcome.message)
		}
		if verb == "abort" && !strings.Contains(outcome.message, "no transaction to abort") {
			t.Fatalf("checkout abort outcome = %q", outcome.message)
		}
	}
	if !internal.HasReparentState(f.Loc()) {
		t.Fatal("the authoritative artifact must survive")
	}
	if f.Mode == internal.ModeExternal {
		if !internal.HasSyncRunState(f.FeaturePath) || !internal.HasSyncState(f.FeaturePath) {
			t.Fatal("the external compatibility artifacts must survive")
		}
	} else if !internal.HasCheckoutTransaction(f.FeaturePath) {
		t.Fatal("the checkout compatibility transaction must survive")
	}
	if after := reparentDowngradeRefs(t, f); after != refsBefore {
		t.Fatalf("the prior control flow must move no ref:\n--- before ---\n%s\n--- after ---\n%s", refsBefore, after)
	}
	if headBefore != "" {
		if head := f.reparentGit(f.Repo, "rev-parse", "--abbrev-ref", "HEAD"); head != headBefore {
			t.Fatalf("restoreOriginal must never run: HEAD moved from %s to %s", headBefore, head)
		}
	}
}

// TestReparentDowngrade_PriorBinaryFailsClosed always runs the frozen
// v1.2.16 replay and, when a real binary is available, compares the binary's
// control flow against it.
func TestReparentDowngrade_PriorBinaryFailsClosed(t *testing.T) {
	_ = "asserts AC-082"
	assertReparentMatrixBehavior(t, "T-070", "v1216-downgrade-six-legs")
	assertReparentDowngradeLimitations(t)
	prior := acquireDowngradeBinaryFor(t, reparentDowngradeTag)
	if prior.path == "" {
		t.Logf("reparent downgrade evidence uses the frozen replay fallback (%s)", prior.note)
	} else {
		t.Logf("reparent downgrade evidence uses %s (%s) plus the frozen fidelity oracle", prior.path, prior.note)
	}

	func(t *testing.T) {
		f := newReparentCustomerExternal(t)
		st := reparentPlantState(t, f, internal.ReparentStageComputing)
		if err := internal.WriteReparentCompatArtifacts(f.Loc(), st, []string{"pr2"}); err != nil {
			t.Fatal(err)
		}

		// The loader half: every shipped release accepts only 2 and 3.
		if _, err := internal.LoadSyncRunState(f.FeaturePath); err == nil {
			t.Fatal("a shipped LoadSyncRunState must refuse state_version 4")
		} else if !strings.Contains(err.Error(), "unsupported scoped sync state version 4") {
			t.Fatalf("the loader must fail closed with its own sentence, got %v", err)
		}

		// The loader assertions above are a SUPPLEMENT; the prior binary below
		// is the evidence.
		refsBefore := reparentDowngradeRefs(t, f)
		for _, verb := range []string{"plain", "continue", "abort"} {
			t.Run(verb, func(t *testing.T) {
				harness, harnessArgv := frozenReparentDowngradeOutcome(t, f, verb)
				assertFrozenReparentDowngradeOutcome(t, f, verb, harness, refsBefore, "")
				assertNoDowngradeRebaseAbort(t, harnessArgv)
				if prior.path == "" {
					return
				}
				args := []string{"sync", f.Feature}
				switch verb {
				case "continue":
					args = append(args, "--continue")
				case "abort":
					args = append(args, "--abort")
				}
				stdout, stderr, exit, gitArgv := runPriorBinaryWithGitTrace(t, prior.path, f.Repo, args...)
				binary := downgradeOutcome{failed: exit != 0, message: strings.TrimSpace(stderr + stdout)}
				assertFrozenReparentDowngradeOutcome(t, f, verb, binary, refsBefore, "")
				assertNoDowngradeRebaseAbort(t, gitArgv)
				if binary.failed != harness.failed ||
					!strings.Contains(binary.message, "unsupported scoped sync state version 4") {
					t.Fatalf("binary/frozen fidelity mismatch:\nbinary: %+v\nfrozen: %+v", binary, harness)
				}
			})
		}
	}(t)

	func(t *testing.T) {
		f := newReparentCustomerCheckout(t)
		st := reparentPlantState(t, f, internal.ReparentStageComputing)
		if err := internal.WriteReparentCompatArtifacts(f.Loc(), st, []string{"pr2"}); err != nil {
			t.Fatal(err)
		}

		// The loader half: AbortCheckoutSync performs NO version check, so the
		// compatibility transaction is written to be undecodable. That is what
		// makes it return before the lock, before `git rebase --abort`, before
		// restoreOriginal and before deleting anything.
		if _, err := internal.LoadCheckoutTransaction(f.FeaturePath); err == nil {
			t.Fatal("the compatibility transaction must be undecodable to a shipped loader")
		}
		if !internal.HasCheckoutTransaction(f.FeaturePath) {
			t.Fatal("a shipped plain sync must still observe the transaction and refuse")
		}

		refsBefore := reparentDowngradeRefs(t, f)
		headBefore := f.reparentGit(f.Repo, "rev-parse", "--abbrev-ref", "HEAD")
		for _, verb := range []string{"plain", "continue", "abort"} {
			t.Run(verb, func(t *testing.T) {
				harness, harnessArgv := frozenReparentDowngradeOutcome(t, f, verb)
				assertFrozenReparentDowngradeOutcome(t, f, verb, harness, refsBefore, headBefore)
				assertNoDowngradeRebaseAbort(t, harnessArgv)
				if prior.path == "" {
					return
				}
				args := []string{"sync", f.Feature}
				switch verb {
				case "continue":
					args = append(args, "--continue")
				case "abort":
					args = append(args, "--abort")
				}
				featureLock := internal.CheckoutLockPath(f.FeaturePath)
				globalLock := internal.CheckoutMutationLockPath(f.Loc().CheckoutStateDir)
				featureBefore := snapshotDowngradePath(t, featureLock)
				globalBefore := snapshotDowngradePath(t, globalLock)
				stdout, stderr, exit, gitArgv := runPriorBinaryWithGitTrace(t, prior.path, f.Repo, args...)
				binary := downgradeOutcome{failed: exit != 0, message: strings.TrimSpace(stderr + stdout)}
				assertFrozenReparentDowngradeOutcome(t, f, verb, binary, refsBefore, headBefore)
				assertNoDowngradeRebaseAbort(t, gitArgv)
				assertDowngradePathUnchanged(t, featureLock, featureBefore)
				assertDowngradePathUnchanged(t, globalLock, globalBefore)
				if verb == "plain" {
					assertExactPriorCheckoutPlainRefusal(t, binary.message)
				}
				if binary.failed != harness.failed {
					t.Fatalf("binary/frozen fidelity mismatch:\nbinary: %+v\nfrozen: %+v", binary, harness)
				}
			})
		}
	}(t)
}

func TestReparentDowngrade_LimitationsAreExplicit(t *testing.T) {
	assertReparentDowngradeLimitations(t)
}

func assertReparentDowngradeLimitations(t *testing.T) {
	t.Helper()
	visibility := map[string]bool{
		"external-same-feature-after-envelope": true,
		"checkout-same-feature-after-envelope": true,
		"artifact-before-compat-window-1":      false,
		"checkout-workspace-global-lock":       false,
		"checkout-unrelated-feature":           false,
		"external-top-level-push":              false,
	}
	want := map[string]bool{
		"external-same-feature-after-envelope": true,
		"checkout-same-feature-after-envelope": true,
		"artifact-before-compat-window-1":      false,
		"checkout-workspace-global-lock":       false,
		"checkout-unrelated-feature":           false,
		"external-top-level-push":              false,
	}
	if !reflect.DeepEqual(visibility, want) {
		t.Fatalf("v1.2.16 downgrade visibility = %+v, want %+v", visibility, want)
	}
	for _, rel := range []string{
		".tpatch/features/safe-reparent-restack/spec.md",
		".tpatch/features/safe-reparent-restack/exploration.md",
	} {
		content := normalizeProse(readRepoDoc(t, rel))
		for _, claim := range []string{
			"same-feature",
			"window 1",
			"workspace-global",
			"top-level",
			"must not use an older tws while any reparent is active or recoverable",
		} {
			if !strings.Contains(content, claim) {
				t.Errorf("%s must state downgrade limitation %q", rel, claim)
			}
		}
	}
}

// reparentDowngradeRefs snapshots every local branch, so "moved no ref" is a
// byte comparison rather than a spot check.
func reparentDowngradeRefs(t *testing.T, f *reparentFixture) string {
	t.Helper()
	return f.reparentGit(f.Repo, "for-each-ref", "--format=%(refname) %(objectname)", "refs/heads/")
}

package cli

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync/atomic"
	"time"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

// ---------------------------------------------------------------------------
// sync-modes — the package-cli half of the feature (spec §3).
//
// This file owns: flag presence and axis resolution (I1-I8), the one external
// sync layout resolver (§3.11), marker generation (§8.2), the thin classifier
// wrapper that applies I18/deferred I7/I20 and the §8.7 message table, scoped
// failure persistence, the header, and the `--only`/`--from` completion.
// ---------------------------------------------------------------------------

// errSyncModeFlagsNeedV2 is the single I20 literal. It is used verbatim and
// identically by both workspace modes (spec §3.5).
const errSyncModeFlagsNeedV2 = "cannot use sync mode flags on --continue without v2 state; continue without them or abort and start a new run"

// syncTriggerFlags is the new-mode trigger set (spec §3.3), in the source order
// of §3.1. `--push`, `--test`, `--verbose`, `--continue`, and `--abort` are not
// triggers.
var syncTriggerFlags = []string{"fetch", "no-fetch", "full", "local-only", "only", "from"}

// The three shared validation sentences this file owns. They are hoisted to
// package constants, with no byte changed, so a sibling command that tests
// the identical condition reuses the exact sentence instead of re-typing a
// literal that can drift. The `--full` / `--local-only` rows of the I4 table
// stay inline: they are not shared with any other command.
const (
	errMsgFetchNoFetchExclusive = "--fetch and --no-fetch are mutually exclusive"
	errMsgFetchExplicitValue    = "--fetch does not take an explicit value; use --no-fetch to disable automatic fetch"
	errMsgNoFetchExplicitValue  = "--no-fetch does not take an explicit value; use --fetch to enable automatic fetch"
)

// syncPresenceFlags is the closed key set of the presence map.
var syncPresenceFlags = []string{"fetch", "no-fetch", "full", "local-only", "only", "from", "push"}

// resolveSyncPolicy reads the six axis/scope flags plus `--push` through
// cmd.Flags().Changed and produces the frozen decision of one run. It performs
// the pure command-line checks I1-I6, then I7 (only when a trigger flag is
// present), then I8 — in that exact order, and it is called before the mode
// dispatch so both modes reject identically (spec §3.6 step 3).
func resolveSyncPolicy(cmd *cobra.Command, mode internal.WorkspaceMode) (internal.SyncRunPolicy, bool, map[string]bool, error) {
	changed := make(map[string]bool, len(syncPresenceFlags))
	for _, name := range syncPresenceFlags {
		changed[name] = cmd.Flags().Changed(name)
	}

	newMode := false
	for _, name := range syncTriggerFlags {
		if changed[name] {
			newMode = true
			break
		}
	}

	var policy internal.SyncRunPolicy

	// I1-I3 — mutual exclusion.
	if changed["fetch"] && changed["no-fetch"] {
		return policy, newMode, changed, fmt.Errorf("%s", errMsgFetchNoFetchExclusive)
	}
	if changed["full"] && changed["local-only"] {
		return policy, newMode, changed, fmt.Errorf("--full and --local-only are mutually exclusive")
	}
	if changed["only"] && changed["from"] {
		return policy, newMode, changed, fmt.Errorf("--only and --from are mutually exclusive")
	}

	// I4 — axis selectors are presence-only; an explicit false is refused.
	for _, rule := range []struct {
		name string
		msg  string
	}{
		{"fetch", errMsgFetchExplicitValue},
		{"no-fetch", errMsgNoFetchExplicitValue},
		{"full", "--full does not take an explicit value; use --local-only to restrict propagation"},
		{"local-only", "--local-only does not take an explicit value; use --full to advance anchors"},
	} {
		if changed[rule.name] && !syncBoolFlag(cmd, rule.name) {
			return policy, newMode, changed, fmt.Errorf("%s", rule.msg)
		}
	}

	only := syncStringFlag(cmd, "only")
	from := syncStringFlag(cmd, "from")

	// I5/I6 — an explicitly supplied empty selector is refused.
	if changed["only"] && only == "" {
		return policy, newMode, changed, fmt.Errorf("--only requires a stack entry name")
	}
	if changed["from"] && from == "" {
		return policy, newMode, changed, fmt.Errorf("--from requires a stack entry name")
	}

	cont := syncBoolFlag(cmd, "continue")
	abort := syncBoolFlag(cmd, "abort")

	// I7 before I8 (spec §3.5). Without a trigger flag I7 is deferred to the
	// state-discrimination step, where legacy and new-mode state can be told
	// apart.
	if cont && abort && newMode {
		return policy, newMode, changed, errSyncContinueAbort()
	}
	if abort && newMode && !cont {
		return policy, newMode, changed, fmt.Errorf("--abort cannot be combined with %s; abort is defined by the persisted run", syncChangedTriggerList(changed))
	}

	policy.Fetch = internal.SyncFetchEnabled
	if mode == internal.ModeCheckout {
		policy.Fetch = internal.SyncFetchDisabled
	}
	if changed["fetch"] {
		policy.Fetch = internal.SyncFetchEnabled
	}
	if changed["no-fetch"] {
		policy.Fetch = internal.SyncFetchDisabled
	}

	policy.Propagation = internal.SyncPropagationFull
	if changed["local-only"] {
		policy.Propagation = internal.SyncPropagationLocalOnly
	}

	policy.ScopeKind = internal.SyncScopeAll
	switch {
	case changed["only"]:
		policy.ScopeKind = internal.SyncScopeOne
		policy.Selector = only
	case changed["from"]:
		policy.ScopeKind = internal.SyncScopeSubtree
		policy.Selector = from
	}

	return policy, newMode, changed, nil
}

// errSyncContinueAbort is the single I7 literal.
func errSyncContinueAbort() error {
	return fmt.Errorf("--continue and --abort are mutually exclusive")
}

// syncTriggerFlagSupplied answers "did THIS invocation supply any of the six
// mode-trigger flags?" over the one owned `changed` map — the same predicate
// resolveSyncPolicy derives newMode from, extracted so the §12.8b cell-4
// interception can ask it directly. The interception sits ABOVE I20, so it
// composes I20's own sentence itself; syncTriggersNeedV2 keeps no cell-4 arm
// and takes no sentinel view (§13.6 rule 4a, §25.82).
func syncTriggerFlagSupplied(changed map[string]bool) bool {
	for _, name := range syncTriggerFlags {
		if changed[name] {
			return true
		}
	}
	return false
}

// syncChangedTriggerList renders the I8 `%s` operand: the changed trigger flag
// names, sorted, comma-joined, each with the `--` prefix.
func syncChangedTriggerList(changed map[string]bool) string {
	var names []string
	for _, name := range syncTriggerFlags {
		if changed[name] {
			names = append(names, "--"+name)
		}
	}
	sort.Strings(names)
	return strings.Join(names, ", ")
}

func syncBoolFlag(cmd *cobra.Command, name string) bool {
	v, err := cmd.Flags().GetBool(name)
	if err != nil {
		return false
	}
	return v
}

func syncStringFlag(cmd *cobra.Command, name string) string {
	v, err := cmd.Flags().GetString(name)
	if err != nil {
		return ""
	}
	return v
}

// ---------------------------------------------------------------------------
// External sync layout (spec §3.11)
// ---------------------------------------------------------------------------

// externalSyncLayout is the one physical layout of one external sync run.
// Every path the run touches is derived from these two fields and nothing else.
type externalSyncLayout struct {
	FeaturePath   string // <root>/<feature>
	WorktreesRoot string // <root>/<feature>/worktrees
}

// WorktreePath is the only worktree derivation on the external path.
func (l externalSyncLayout) WorktreePath(name string) string {
	return filepath.Join(l.WorktreesRoot, name)
}

// resolveExternalSyncLayout resolves the single root of one external sync run.
//
// It issues no Git command and calls no workspace or root resolver of its own:
// twsRoot is always the value of the caller's own single internal.TwsRoot()
// call. Its only probes are at most two ordinary `<path>/stack.yaml` reads, and
// there are zero of them whenever the two candidates agree.
func resolveExternalSyncLayout(ws internal.Workspace, twsRoot, feature string) (externalSyncLayout, error) {
	b := filepath.Join(twsRoot, feature)
	a, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return externalSyncLayout{}, err
	}
	if filepath.Clean(a) == filepath.Clean(b) {
		return newExternalSyncLayout(a), nil
	}
	if _, loadErr := internal.LoadStack(b); loadErr == nil {
		return newExternalSyncLayout(b), nil
	}
	if _, loadErr := internal.LoadStack(a); loadErr == nil {
		return newExternalSyncLayout(a), nil
	}
	return newExternalSyncLayout(b), nil
}

func newExternalSyncLayout(featurePath string) externalSyncLayout {
	return externalSyncLayout{
		FeaturePath:   featurePath,
		WorktreesRoot: filepath.Join(featurePath, "worktrees"),
	}
}

// ---------------------------------------------------------------------------
// Marker generation (spec §8.2)
// ---------------------------------------------------------------------------

// newSyncMarker generates a per-run sentinel marker. Recognition lives in
// package internal (isSyncMarker); this is the generation half.
func newSyncMarker() (string, error) {
	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		return "", fmt.Errorf("generate sync marker: %w", err)
	}
	return "tws-scoped-sync-" + hex.EncodeToString(buf) + ".lock", nil
}

// syncMarkerFn is the package-private generation seam. Package-cli tests
// override it; nothing exported ever does.
var syncMarkerFn = newSyncMarker

// newSyncOwnerToken generates the run ownership token recorded in both the
// guard and the payload.
func newSyncOwnerToken() (string, error) {
	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		return "", fmt.Errorf("generate sync owner token: %w", err)
	}
	return hex.EncodeToString(buf), nil
}

// ExternalSyncMutationGuardHook is a test-only seam after a mutating external
// sync route owns the shared feature guard and before it rechecks authoritative
// reparent state.
var ExternalSyncMutationGuardHook func(featurePath string) error

func externalSyncPostClaimRecheck(feature string, layout externalSyncLayout, token string) error {
	releaseOnError := func(cause error) error {
		if releaseErr := internal.ReleaseOwnedSyncRunGuard(layout.FeaturePath, token); releaseErr != nil {
			return errors.Join(cause, releaseErr)
		}
		return cause
	}
	if ExternalSyncMutationGuardHook != nil {
		if err := ExternalSyncMutationGuardHook(layout.FeaturePath); err != nil {
			return releaseOnError(err)
		}
	}
	if err := internal.RefuseSyncIfReparentActive(externalReparentLocation(feature, layout)); err != nil {
		return releaseOnError(err)
	}
	return nil
}

func acquireExternalSyncMutationGuard(feature string, layout externalSyncLayout, token string, reclaim bool) error {
	var err error
	if reclaim {
		err = internal.ReclaimSyncRunGuard(layout.FeaturePath, token)
	} else {
		err = internal.ClaimSyncRunGuard(layout.FeaturePath, token)
	}
	if err != nil {
		return err
	}
	return externalSyncPostClaimRecheck(feature, layout, token)
}

func withExternalSyncMutationGuard(feature string, layout externalSyncLayout, token string, reclaim bool, mutate func() error) (err error) {
	if token == "" {
		token, err = newSyncOwnerToken()
		if err != nil {
			return err
		}
	}
	if err := acquireExternalSyncMutationGuard(feature, layout, token, reclaim); err != nil {
		return err
	}
	defer func() {
		err = errors.Join(err, internal.ReleaseOwnedSyncRunGuard(layout.FeaturePath, token))
	}()
	return mutate()
}

// syncMarkerCollision is the mandatory I17 pre-flight: the generated marker may
// equal neither a StackEntry.Name nor an entry.GitBranch().
func syncMarkerCollision(stack internal.Stack, marker string) error {
	for _, entry := range stack.Branches {
		if entry.Name == marker || entry.GitBranch() == marker {
			return fmt.Errorf("refusing to start: generated sync marker %q collides with stack entry %q; re-run", marker, entry.Name)
		}
	}
	return nil
}

// ---------------------------------------------------------------------------
// State discrimination (spec §3.6 steps 7-9, §8.6, §8.7)
// ---------------------------------------------------------------------------

type syncVerb string

const (
	syncVerbPlain    syncVerb = "plain"
	syncVerbContinue syncVerb = "continue"
	syncVerbAbort    syncVerb = "abort"
)

// classifySyncState is the thin wrapper over internal.ClassifyExternalSyncState.
// It passes AlwaysReadGuard: newMode and the package default liveness
// predicate, and it applies the I18 symlink refusals from the recorded facts —
// never a second Lstat.
func classifySyncState(featurePath string, newMode bool) (internal.SyncExternalState, error) {
	st := internal.ClassifyExternalSyncState(featurePath, internal.SyncClassifyOpts{AlwaysReadGuard: newMode})
	if err := syncSymlinkRefusal(st, newMode); err != nil {
		return st, err
	}
	return st, nil
}

// syncSymlinkRefusal applies I18 over the classifier's recorded symlink facts.
func syncSymlinkRefusal(st internal.SyncExternalState, newMode bool) error {
	handlingV2 := st.Marker != "" || st.Payload != nil || st.PayloadErr != nil || st.HasGuardFile()
	if st.LegacySymlink && (newMode || handlingV2) {
		return syncSymlinkError(st.LegacyPath)
	}
	if st.PayloadSymlink {
		return syncSymlinkError(st.PayloadPath)
	}
	if st.GuardSymlink {
		return syncSymlinkError(st.GuardPath)
	}
	return nil
}

// syncStateSymlinkOnly reports whether err is exactly the I18 symlink
// refusal — the one classifier error the plan route describes instead of
// propagating (§12.5, §22.13m (i)).
func syncStateSymlinkOnly(err error) bool {
	return err != nil && strings.Contains(err.Error(), "runtime state path is a symlink")
}

func syncSymlinkError(path string) error {
	return fmt.Errorf("refusing to use %s: runtime state path is a symlink", path)
}

// syncCellLiveGuardRefusal is the pure extraction of syncCellRefusal's own
// first switch: the guard-precedence check applied on top of cells 2, 4, and
// 5, independent of each cell's own message. It is called both by
// syncCellRefusal, as its own first statement, and by the cell-4 guarded-
// sentinel interception (sync.go), which must apply the identical
// live-guard precedence before it ever consults the sentinel.
func syncCellLiveGuardRefusal(feature string, st internal.SyncExternalState, verb syncVerb) error {
	switch st.Cell {
	case 2, 4, 5:
		if st.GuardLive && st.Guard != nil {
			if verb == syncVerbAbort {
				return fmt.Errorf("a scoped sync is running for %q (pid %d); wait for it to exit before --abort", feature, st.Guard.PID)
			}
			return fmt.Errorf("a scoped sync is already running for %q (pid %d, started %s); wait for it or use --continue/--abort after it exits", feature, st.Guard.PID, st.Guard.Created)
		}
	}
	return nil
}

// syncCellRefusal returns the §8.7 message for a cell/verb pair, or nil when
// the verb may proceed in that cell. Guard precedence is applied on top of the
// cell for rows 2, 4, and 5 only.
func syncCellRefusal(verb syncVerb, feature string, layout externalSyncLayout, st internal.SyncExternalState) error {
	if err := syncCellLiveGuardRefusal(feature, st, verb); err != nil {
		return err
	}

	switch st.Cell {
	case 1, 7:
		return nil
	case 2:
		if verb == syncVerbAbort {
			return nil
		}
		failed := syncPayloadFailed(st)
		return fmt.Errorf("a scoped sync record survives without its state file for %q: it failed on %s (worktree %s) and that rebase was never aborted. Resolve or abort it there, then run: tws sync %s --abort",
			feature, failed, layout.WorktreePath(failed), feature)
	case 4:
		if verb == syncVerbAbort {
			return nil
		}
		return fmt.Errorf("a scoped sync left partial state for %q: it was interrupted either while starting up or while finishing, and this cannot be distinguished on disk; work may or may not have been done. Inspect the worktrees, then run: tws sync %s --abort",
			feature, feature)
	case 5:
		if verb == syncVerbPlain {
			return fmt.Errorf("a scoped sync is incomplete (failed on: %s); use --continue or --abort", syncPayloadFailed(st))
		}
		return nil
	case 3, 6, 9, 12:
		return fmt.Errorf("scoped sync state at %s is unreadable or uses an unsupported version (%s); inspect it and remove it manually — tws will not guess",
			st.PayloadPath, syncErrText(st.PayloadErr))
	case 8:
		legacyFailed := ""
		if st.Legacy != nil {
			legacyFailed = st.Legacy.FailedBranch
		}
		if verb == syncVerbAbort {
			return fmt.Errorf("refusing to clear two unfinished syncs at once for %q: a legacy sync failed on %s and a scoped sync failed on %s; inspect %s and %s and remove them explicitly",
				feature, legacyFailed, syncPayloadFailed(st), st.LegacyPath, st.PayloadPath)
		}
		return fmt.Errorf("two unfinished syncs are recorded for %q: a legacy sync failed on %s and a scoped sync failed on %s; resolve both before syncing (inspect %s and %s)",
			feature, legacyFailed, syncPayloadFailed(st), st.LegacyPath, st.PayloadPath)
	case 10:
		if verb == syncVerbAbort {
			return fmt.Errorf("sync state at %s is unreadable: %v; inspect and remove it manually", st.LegacyPath, syncErrText(st.LegacyErr))
		}
		return fmt.Errorf("sync state at %s is unreadable: %v", st.LegacyPath, syncErrText(st.LegacyErr))
	case 11:
		failed := syncPayloadFailed(st)
		if verb == syncVerbAbort {
			return fmt.Errorf("refusing to clear unreadable sync state at %s while a scoped sync record beside it is still unfinished: it failed on %s (worktree %s); inspect both and remove %s explicitly",
				st.LegacyPath, failed, layout.WorktreePath(failed), st.PayloadPath)
		}
		return fmt.Errorf("sync state at %s is unreadable, and a scoped sync record beside it failed on %s (worktree %s); resolve or abort that rebase, then remove %s manually — tws will not guess",
			st.LegacyPath, failed, layout.WorktreePath(failed), st.PayloadPath)
	}
	return nil
}

func syncPayloadFailed(st internal.SyncExternalState) string {
	if st.Payload == nil {
		return ""
	}
	return st.Payload.FailedBranch
}

func syncErrText(err error) string {
	if err == nil {
		return "unknown"
	}
	return err.Error()
}

// syncTriggersNeedV2 is I20's cell-aware predicate (spec §3.5): a resumable
// cell whose subject cannot satisfy a --continue that also supplies a
// sync-mode trigger flag. Cell 1/7 (no v2 state at all, or a real legacy-only
// state) always need v2; cell 5 needs it exactly when the persisted payload
// is not itself a new-mode run. The caller retains its own `newMode &&`
// prefix, exactly mirroring internal.CheckoutTriggersNeedV2's own external
// `opts.NewMode &&` wrapping. This predicate is never reached on cell 4: the
// guarded-sentinel interception fully owns that cell's own flag-conflict
// check before I20 is ever consulted.
func syncTriggersNeedV2(state internal.SyncExternalState) bool {
	switch state.Cell {
	case 1, 7:
		return true
	case 5:
		return !internal.PayloadNewMode(state.Payload)
	default:
		return false
	}
}

// syncStateRefusesContinueAbort is the pure extraction of the deferred-I7
// state predicate: a --continue --abort invocation that supplied no trigger
// flag is refused whenever the subject carries any new-mode-recognizable
// state at all — a marker or a payload — exactly as today. The caller
// retains its own `cont && abort &&` prefix.
func syncStateRefusesContinueAbort(state internal.SyncExternalState) bool {
	return state.Marker != "" || state.Payload != nil
}

// ---------------------------------------------------------------------------
// New-mode setup, teardown, and failure persistence (spec §8.5)
// ---------------------------------------------------------------------------

// syncRunStateBirth carries the guarded envelope's birth-time overrides for
// setupSyncRunState (§13.1, §13.6 rule 2). Its zero value changes nothing —
// every shipped (unguarded) call site passes it unchanged and the payload it
// produces is byte-identical to today's. StateVersion is applied only when
// non-zero: the birth decision of §13.6 rule 2 is made once by the caller,
// exactly as SaveSyncRunState's own doc comment requires, and is never
// silently defaulted here. Route/MaxPerEntry/MaxTotal are applied
// unconditionally, because their own Go zero values ("" and nil) are already
// what NewSyncRunState leaves them at, so an unguarded caller's zero-value
// birth is a true no-op for those three fields too.
type syncRunStateBirth struct {
	StateVersion int
	Route        string
	MaxPerEntry  *int
	MaxTotal     *int
}

// setupSyncRunState performs §8.5 setup: guard, sentinel, payload — in that
// exact order, and it is the run's first side effect.
func setupSyncRunState(layout externalSyncLayout, feature, marker, token string, sel internal.SyncSelection, push bool, testCommand, validationSource string, birth syncRunStateBirth) (*internal.SyncRunState, error) {
	if err := internal.ClaimSyncRunGuard(layout.FeaturePath, token); err != nil {
		return nil, err
	}
	if err := externalSyncPostClaimRecheck(feature, layout, token); err != nil {
		return nil, err
	}
	if err := syncStepHook(internal.SyncStageInitializing, 0); err != nil {
		return nil, err
	}

	sentinel := internal.NewSyncState()
	sentinel.FailedBranch = marker
	sentinel.Pending = []string{}
	sentinel.Completed = []string{}
	sentinel.Skipped = []string{}
	if err := internal.SaveSyncState(layout.FeaturePath, sentinel); err != nil {
		internal.ReleaseSyncRunGuard(layout.FeaturePath)
		return nil, fmt.Errorf("write sync sentinel: %w", err)
	}
	if err := syncStepHook(internal.SyncStageInitializing, 1); err != nil {
		return nil, err
	}

	payload := internal.NewSyncRunState(feature, marker, token, sel.Policy)
	payload.Selected = sel.SelectedNames()
	payload.Pending = append([]string(nil), payload.Selected...)
	payload.Push = push
	payload.TestCommand = testCommand
	payload.ValidationSource = validationSource
	payload.Repos = append([]string(nil), sel.Repos...)
	if birth.StateVersion != 0 {
		payload.StateVersion = birth.StateVersion
	}
	payload.Route = birth.Route
	payload.MaxReplayPerEntry = birth.MaxPerEntry
	payload.MaxReplayTotal = birth.MaxTotal
	if err := internal.SaveSyncRunState(layout.FeaturePath, payload); err != nil {
		internal.DeleteSyncState(layout.FeaturePath)
		internal.ReleaseSyncRunGuard(layout.FeaturePath)
		return nil, fmt.Errorf("write scoped sync state: %w", err)
	}
	if err := syncStepHook(internal.SyncStageInitializing, 2); err != nil {
		return nil, err
	}
	return payload, nil
}

// clearSyncRunState performs §8.5 teardown in the exact reverse order:
// payload, sentinel, guard. A no-flag run keeps today's literal sentinel-free
// DeleteSyncState and can never fail.
//
// A new-mode teardown stops at the first failing step hook and returns that
// error, so an interruption between two teardown steps leaves exactly the
// residue that step ordering implies: {sentinel, guard} after step 0 and
// {guard} after step 1. Callers must propagate the error and must not clear
// any later artifact themselves.
func clearSyncRunState(featurePath string, newMode bool) error {
	if !newMode {
		internal.DeleteSyncState(featurePath)
		return nil
	}
	internal.DeleteSyncRunState(featurePath)
	if err := syncStepHook(internal.SyncStageFinalizing, 0); err != nil {
		return err
	}
	internal.DeleteSyncState(featurePath)
	if err := syncStepHook(internal.SyncStageFinalizing, 1); err != nil {
		return err
	}
	internal.ReleaseSyncRunGuard(featurePath)
	return nil
}

// ---------------------------------------------------------------------------
// Guarded-legacy setup, teardown, and upgrade (spec §12, §13.7a)
// ---------------------------------------------------------------------------

// guardedLegacyCarry is the continuation-only provenance a cell-7 guarded
// legacy setup must not lose (§13.6 rule 2a): the prior legacy state's
// Completed list verbatim in its persisted order, its FailedBranch, and its
// persisted pending COUNT — the number the shipped resume prose prints. The
// zero value is the fresh route, which carries nothing. The prior document's
// BYTES are deliberately absent: §13.2a step 1 makes the capture
// setupGuardedLegacyRunState's own responsibility, so no caller can hand it
// a stale or re-marshalled snapshot of a file the setup is about to replace.
type guardedLegacyCarry struct {
	Completed         []string
	FailedBranch      string
	PriorPendingCount int
}

// carriedGuardedLegacyState projects an already-loaded legacy state into the
// carry the cell-7 continuation arm supplies. It reads no file: the caller
// has already decoded the state for its own gates, and the bytes the
// rollback needs are captured by the setup itself.
func carriedGuardedLegacyState(legacy *internal.SyncState) guardedLegacyCarry {
	if legacy == nil {
		return guardedLegacyCarry{}
	}
	return guardedLegacyCarry{
		Completed:         append([]string(nil), legacy.Completed...),
		FailedBranch:      legacy.FailedBranch,
		PriorPendingCount: len(legacy.Pending),
	}
}

// captureGuardedLegacySyncState is §13.2a step 1: one os.ReadFile of
// .sync-state.yaml into the bytes the rollback will restore. The bytes the
// classifier already decoded are NOT reused — restoration needs the file's
// bytes, not a re-marshalled struct. fs.ErrNotExist is the FRESH cell and
// yields (nil, nil); every other error is returned wrapped, marker-free, so
// the arm refuses before it has written or claimed anything.
func captureGuardedLegacySyncState(featurePath string) ([]byte, error) {
	data, err := os.ReadFile(internal.SyncStatePath(featurePath))
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("read sync state: %w", err)
	}
	return data, nil
}

// guardedLegacySetupProgress records exactly what setupGuardedLegacyRunState
// created, so the rollback undoes what happened rather than what it assumes
// from a step index (§13.2a).
type guardedLegacySetupProgress struct {
	Guard    bool // step 2 claimed the run guard
	Sentinel bool // step 3 installed the backup sentinel
	Payload  bool // step 4 wrote the v3 payload
}

// guardedLegacySetupPending computes a guarded legacy sentinel's and
// payload's initial pending set: every entry of universe on a fresh run, or
// every entry of universe not already in carry.Completed on a cell-7
// upgrade — the carried FailedBranch is deliberately NOT excluded, since its
// own rebase is not yet known-good at the moment of the upgrade.
func guardedLegacySetupPending(universe []string, carry guardedLegacyCarry) []string {
	done := make(map[string]bool, len(carry.Completed))
	for _, name := range carry.Completed {
		done[name] = true
	}
	pending := make([]string, 0, len(universe))
	for _, name := range universe {
		if !done[name] {
			pending = append(pending, name)
		}
	}
	return pending
}

// newGuardedLegacySentinel assembles the one document §13.2a step 3 writes.
// The embedded SyncState carries the marker exactly as an unguarded sentinel
// does, so InspectGuardedLegacySentinel's own marker-shape check passes
// identically; the guarded envelope fields record this invocation's own
// identity, limits, and validation provenance, plus — on an upgrade — the
// captured prior document byte-for-byte with its SHA-256, which is what
// makes every crash window of §13.2a recoverable.
func newGuardedLegacySentinel(feature, marker, token string, universe, pending []string, birth syncRunStateBirth, push bool, testCommand, validationSource string, carry guardedLegacyCarry, prior []byte) *internal.GuardedLegacySentinel {
	s := &internal.GuardedLegacySentinel{
		SyncState:           *internal.NewSyncState(),
		GuardedStateVersion: internal.GuardedLegacySentinelVersion,
		Route:               internal.RouteLegacy,
		Feature:             feature,
		Marker:              marker,
		OwnerToken:          token,
		CreatedAt:           time.Now().UTC().Format(time.RFC3339),
		WriterPID:           os.Getpid(),
		MaxReplayPerEntry:   birth.MaxPerEntry,
		MaxReplayTotal:      birth.MaxTotal,
		Push:                push,
		TestCommand:         testCommand,
		ValidationSource:    validationSource,
		Universe:            append([]string(nil), universe...),
		PendingIntent:       append([]string(nil), pending...),
		CarriedCompleted:    append([]string(nil), carry.Completed...),
		CarriedFailed:       carry.FailedBranch,
		PriorPendingCount:   carry.PriorPendingCount,
		PriorLegacyPresent:  len(prior) > 0,
	}
	s.FailedBranch = marker
	s.Pending = []string{}
	s.Completed = []string{}
	s.Skipped = []string{}
	if len(prior) > 0 {
		sum := sha256.Sum256(prior)
		s.PriorLegacySHA256 = hex.EncodeToString(sum[:])
		s.PriorLegacyBase64 = base64.StdEncoding.EncodeToString(prior)
	}
	return s
}

// newGuardedLegacyPayload assembles the state_version: 3, route: legacy
// envelope §13.2a step 4 writes. Its policy members are the legacy route's
// own defaults — a legacy run has no sync-mode policy of its own — and its
// resume-bearing members are the four carried values of §13.2a: Selected is
// the full-stack legacy universe in this invocation's one TopoSort order,
// Pending the remaining set of §13.3 in that order, Completed the legacy
// state's Completed verbatim and FailedBranch its FailedBranch verbatim. The
// legacy state's Skipped list has no payload counterpart and is deliberately
// not carried: the shipped resume builds `done` from Completed ∪
// {FailedBranch} alone, and the list nevertheless survives verbatim inside
// the sentinel's byte-exact backup.
func newGuardedLegacyPayload(feature, marker, token string, universe, pending []string, birth syncRunStateBirth, push bool, testCommand, validationSource string, carry guardedLegacyCarry) *internal.SyncRunState {
	payload := internal.NewSyncRunState(feature, marker, token, internal.SyncRunPolicy{})
	payload.StateVersion = internal.SyncRunStateGuardedVersion
	payload.Route = internal.RouteLegacy
	payload.MaxReplayPerEntry = birth.MaxPerEntry
	payload.MaxReplayTotal = birth.MaxTotal
	payload.Push = push
	payload.TestCommand = testCommand
	payload.ValidationSource = validationSource
	payload.Selected = append([]string{}, universe...)
	payload.Pending = append([]string{}, pending...)
	payload.Completed = append([]string{}, carry.Completed...)
	payload.FailedBranch = carry.FailedBranch
	return payload
}

// syncStateResidue is what a rollback actually left on disk, measured rather
// than inferred from the step it stopped at (§12.2c rule 4a).
type syncStateResidue struct{ Payload, Sentinel, Guard bool }

// Empty reports a rollback that undid everything it created.
func (r syncStateResidue) Empty() bool { return !r.Payload && !r.Sentinel && !r.Guard }

// String renders the PRESENT members in the fixed order payload, sentinel,
// guard: "{payload, sentinel, guard}" | "{sentinel, guard}" | "{guard}" |
// "{sentinel}" | "{}" — any subset, always that order.
func (r syncStateResidue) String() string {
	parts := make([]string, 0, 3)
	if r.Payload {
		parts = append(parts, "payload")
	}
	if r.Sentinel {
		parts = append(parts, "sentinel")
	}
	if r.Guard {
		parts = append(parts, "guard")
	}
	return "{" + strings.Join(parts, ", ") + "}"
}

// syncResidueError composes the one sentence §12.2c rule 4 and §13.2a
// require when a rollback itself fails: the failing writer's own shipped
// sentence, the measured residue, and the exact recovery command. It is
// marker-free — the guard did not refuse, a write failed.
func syncResidueError(cause error, residue syncStateResidue, feature string) error {
	return fmt.Errorf("%s; recovery state preserved: %s — clear it with: tws sync %s --abort", cause.Error(), residue.String(), feature)
}

// rollbackGuardedRunState removes exactly the three artefacts a guarded
// fresh claim created, in the shipped teardown order, propagating the first
// failure (§12.2c rule 2). It stops at the first failing step — remover or
// injected hook alike — and returns the residue actually left on disk: the
// failing step's own artefact where the remover failed, plus every artefact
// of the steps it never attempted. It touches no pre-existing artefact,
// aborts no rebase and runs no restoration.
func rollbackGuardedRunState(featurePath string) (syncStateResidue, error) {
	residue := syncStateResidue{Payload: true, Sentinel: true, Guard: true}
	if err := internal.RemoveSyncRunState(featurePath); err != nil {
		return residue, err
	}
	residue.Payload = false
	if err := syncStepHook(internal.SyncStageFinalizing, 0); err != nil {
		return residue, err
	}
	if err := internal.RemoveSyncState(featurePath); err != nil {
		return residue, err
	}
	residue.Sentinel = false
	if err := syncStepHook(internal.SyncStageFinalizing, 1); err != nil {
		return residue, err
	}
	if err := internal.RemoveSyncRunGuard(featurePath); err != nil {
		return residue, err
	}
	residue.Guard = false
	return residue, nil
}

// rollbackGuardedLegacyRunState undoes steps 4, 3 and 2 of §13.2a in REVERSE
// CREATION ORDER — payload, then the sentinel replacement, then the guard —
// stopping at the first failure and returning the residue actually left on
// disk. Releasing the guard LAST is load-bearing: the prior document is put
// back while this invocation still holds the run guard, so no other new
// binary can claim it and start writing over a half-undone directory. The
// sentinel step is ALWAYS conditional and never an unconditional removal:
// RestoreSyncStateBytes(featurePath, prior, sentinel) where prior bytes were
// captured, and RemoveSyncStateIfUnchanged(featurePath, sentinel) where
// there were none (the fresh route), so it can only ever undo the exact
// bytes THIS invocation installed. It never aborts a rebase, never touches a
// pre-existing artefact it did not create, and never re-attempts a step it
// has already failed.
func rollbackGuardedLegacyRunState(featurePath string, prior, sentinel []byte, made guardedLegacySetupProgress) (syncStateResidue, error) {
	residue := syncStateResidue{Payload: made.Payload, Sentinel: made.Sentinel, Guard: made.Guard}
	if made.Payload {
		if err := internal.RemoveSyncRunState(featurePath); err != nil {
			return residue, err
		}
		residue.Payload = false
	}
	if made.Sentinel {
		var err error
		if len(prior) > 0 {
			err = internal.RestoreSyncStateBytes(featurePath, prior, sentinel)
		} else {
			err = internal.RemoveSyncStateIfUnchanged(featurePath, sentinel)
		}
		if err != nil {
			return residue, err
		}
		residue.Sentinel = false
	}
	if made.Guard {
		if err := internal.RemoveSyncRunGuard(featurePath); err != nil {
			return residue, err
		}
		residue.Guard = false
	}
	return residue, nil
}

// guardedLegacyUndo is the exact undo token §13.2a's rollback needs: the
// bytes captured at step 1, the bytes step 3 installed, and what was really
// created. setupGuardedLegacyRunState returns it so a refusal raised AFTER a
// successful setup — the guarded legacy continuation's own pre-mutation
// guard/JIT seam — can perform the same CONDITIONAL undo the setup would
// have performed for its own failure, rather than falling back on
// rollbackGuardedRunState's unconditional RemoveSyncState, which would
// destroy the operator's captured legacy document instead of restoring it
// (§13.2a, §22.24i (ix-a)).
type guardedLegacyUndo struct {
	prior    []byte
	sentinel []byte
	made     guardedLegacySetupProgress
}

// rollback performs the conditional reverse-order undo of §13.2a for a
// refusal raised above the first Git mutation but below a successful setup.
func (u guardedLegacyUndo) rollback(featurePath, feature string, refusal *internal.PlanGuardRefusalError) error {
	residue, err := rollbackGuardedLegacyRunState(featurePath, u.prior, u.sentinel, u.made)
	if err != nil {
		preserved := *refusal
		preserved.StatePreserved = true
		preserved.Detail = fmt.Sprintf("%s; recovery state preserved: %s — clear it with: tws sync %s --abort", refusal.Detail, residue.String(), feature)
		return &preserved
	}
	return refusal
}

// setupGuardedLegacyRunState writes the guarded LEGACY envelope over the
// exact four-step, crash-safe order of §13.2a: capture the CURRENT
// .sync-state.yaml bytes (absent ⇒ nil, which is every fresh run, since a
// plain run over a real legacy state is refused above this point) →
// ClaimSyncRunGuard (the shipped O_EXCL claim, FIRST, exactly as
// setupSyncRunState orders it, so two new binaries racing over one feature
// cannot both reach the replacement) → the CONDITIONAL atomic write of the
// BACKUP SENTINEL over that same path (an exclusive create where nothing was
// captured, a compare-and-swap over the captured bytes where something was)
// → the atomic state_version: 3, route: legacy payload write → return the
// payload. The steps fire the shipped SyncStageInitializing hooks, which
// name ARTEFACTS (0 = guard, 1 = sentinel, 2 = payload) and are therefore
// fired here in the order 3 → 0 → 1 → 2; the capture adds index 3.
//
// The captured bytes are owned by this function, not by its caller: on any
// failure at or below the claim — a writer error, a claim refusal or a
// boundary hook that RETURNS an error — it rolls back through
// rollbackGuardedLegacyRunState, so a failed setup leaves a byte-identical
// legacy state and no payload, sentinel or guard, and a failed ROLLBACK
// returns the measured residue instead of pretending. Residue is reachable
// only from a process that died, never from a returned error.
func setupGuardedLegacyRunState(layout externalSyncLayout, feature, marker, token string, universe, pending []string, push bool, testCommand, validationSource string, birth syncRunStateBirth, carry guardedLegacyCarry) (*internal.SyncRunState, guardedLegacyUndo, error) {
	featurePath := layout.FeaturePath

	// Step 1 — capture. Nothing has been written or claimed yet, so a
	// failure here leaves the run exactly as found.
	prior, err := captureGuardedLegacySyncState(featurePath)
	if err != nil {
		return nil, guardedLegacyUndo{}, err
	}
	if err := syncStepHook(internal.SyncStageInitializing, 3); err != nil {
		return nil, guardedLegacyUndo{}, err
	}

	sentinel := newGuardedLegacySentinel(feature, marker, token, universe, pending, birth, push, testCommand, validationSource, carry, prior)
	sentinelBytes, err := internal.MarshalGuardedLegacySentinel(sentinel)
	if err != nil {
		return nil, guardedLegacyUndo{}, err
	}

	made := guardedLegacySetupProgress{}
	fail := func(cause error) (*internal.SyncRunState, guardedLegacyUndo, error) {
		residue, rollbackErr := rollbackGuardedLegacyRunState(featurePath, prior, sentinelBytes, made)
		if rollbackErr != nil {
			return nil, guardedLegacyUndo{}, syncResidueError(rollbackErr, residue, feature)
		}
		return nil, guardedLegacyUndo{}, cause
	}

	// Step 2 — claim. This arm's first write and its mutual-exclusion point;
	// nothing else exists yet, so its own failure rolls nothing back.
	if err := internal.ClaimSyncRunGuard(featurePath, token); err != nil {
		return nil, guardedLegacyUndo{}, err
	}
	made.Guard = true
	if err := externalSyncPostClaimRecheck(feature, layout, token); err != nil {
		return nil, guardedLegacyUndo{}, err
	}
	if err := syncStepHook(internal.SyncStageInitializing, 0); err != nil {
		return fail(err)
	}

	// Step 3 — the conditional backup sentinel.
	if err := internal.SaveGuardedLegacySentinel(featurePath, sentinel, prior); err != nil {
		if errors.Is(err, internal.ErrSyncStateChanged) {
			return fail(fmt.Errorf("sync state at %s changed while starting a guarded resume; re-run: tws sync %s --continue", internal.SyncStatePath(featurePath), feature))
		}
		return fail(fmt.Errorf("write sync sentinel: %w", err))
	}
	made.Sentinel = true
	if err := syncStepHook(internal.SyncStageInitializing, 1); err != nil {
		return fail(err)
	}

	// Step 4 — the v3 payload.
	payload := newGuardedLegacyPayload(feature, marker, token, universe, pending, birth, push, testCommand, validationSource, carry)
	if err := internal.SaveSyncRunState(featurePath, payload); err != nil {
		return fail(fmt.Errorf("write scoped sync state: %w", err))
	}
	made.Payload = true
	if err := syncStepHook(internal.SyncStageInitializing, 2); err != nil {
		return fail(err)
	}
	return payload, guardedLegacyUndo{prior: prior, sentinel: sentinelBytes, made: made}, nil
}

// claimOrReclaimGuardedLegacyGuard performs §13.2a step 2 for the cell-4
// recovery arm, where the sentinel already exists. The choice follows the
// SNAPSHOT the classifier took — whether a `.sync-run.lock` was there at all
// — and never the provenance of the residue: crash window 2 and the
// `{sentinel, guard}` rollback residue reach the same cell and must answer
// identically. A present guard is RECLAIMED through the shipped
// compare-and-swap ladder (which refuses a live owner, foreign or
// self-recorded alike); an absent one — an operator removed the lock by hand
// — is CLAIMED through the shipped O_EXCL ladder.
func claimOrReclaimGuardedLegacyGuard(featurePath, token string, guardPresent bool) error {
	if guardPresent {
		return internal.ReclaimSyncRunGuard(featurePath, token)
	}
	return internal.ClaimSyncRunGuard(featurePath, token)
}

// writeGuardedLegacyRecoveryPayload performs §13.2a step 4 alone for the
// cell-4 recovery arm: the state_version: 3, route: legacy payload built
// from the sentinel's own verified intent block. It writes no sentinel — the
// backup sentinel is already on disk and is exactly what this arm is
// recovering — and it re-plans nothing.
func writeGuardedLegacyRecoveryPayload(featurePath string, sentinel *internal.GuardedLegacySentinel) (*internal.SyncRunState, error) {
	birth := syncRunStateBirth{
		StateVersion: internal.SyncRunStateGuardedVersion,
		Route:        internal.RouteLegacy,
		MaxPerEntry:  sentinel.MaxReplayPerEntry,
		MaxTotal:     sentinel.MaxReplayTotal,
	}
	carry := guardedLegacyCarry{
		Completed:         append([]string(nil), sentinel.CarriedCompleted...),
		FailedBranch:      sentinel.CarriedFailed,
		PriorPendingCount: sentinel.PriorPendingCount,
	}
	payload := newGuardedLegacyPayload(sentinel.Feature, sentinel.Marker, sentinel.OwnerToken,
		sentinel.Universe, sentinel.PendingIntent, birth, sentinel.Push,
		sentinel.TestCommand, sentinel.ValidationSource, carry)
	if err := syncStepHook(internal.SyncStageInitializing, 2); err != nil {
		return nil, err
	}
	if err := internal.SaveSyncRunState(featurePath, payload); err != nil {
		return nil, fmt.Errorf("write scoped sync state: %w", err)
	}
	return payload, nil
}

// rollbackGuardedFreshRefusal is §12.2c rule 2/3/4 applied to a guarded
// fresh route's own pre-mutation refusal: the rollback runs FIRST, so the
// marker line describes the state the operator will actually find, and a
// cleanup failure is reported honestly with the measured residue instead of
// being swallowed.
func rollbackGuardedFreshRefusal(featurePath, feature string, refusal *internal.PlanGuardRefusalError) error {
	residue, err := rollbackGuardedRunState(featurePath)
	if err != nil {
		preserved := *refusal
		preserved.StatePreserved = true
		preserved.Detail = fmt.Sprintf("%s; recovery state preserved: %s — clear it with: tws sync %s --abort", refusal.Detail, residue.String(), feature)
		return &preserved
	}
	return refusal
}

// upgradeGuardedSyncRunState upgrades an existing, unguarded new-mode payload
// (cell 5, arm b) to the guarded envelope in place: it records
// StateVersion/Route/the newly supplied limits and otherwise leaves
// Selected/Completed/Pending/FailedBranch/Stage untouched, so the resumed run
// continues at exactly the point it was interrupted. It never touches the
// sentinel beside the payload: GuardedLegacySentinelResumable's own
// cell-4-only dispatch never consults a new-mode run's sentinel, so an
// upgraded payload's crash-orphan recovery is unchanged from today's plain
// cell-4 handling.
func upgradeGuardedSyncRunState(featurePath string, payload *internal.SyncRunState, birth syncRunStateBirth) error {
	payload.StateVersion = birth.StateVersion
	payload.Route = internal.RouteNewMode
	payload.MaxReplayPerEntry = birth.MaxPerEntry
	payload.MaxReplayTotal = birth.MaxTotal
	return internal.SaveSyncRunState(featurePath, payload)
}

// saveScopedSyncFailure is the new-mode failure persistence path. It writes the
// payload only: saveIncompleteSync is never called by a new-mode run, because
// it would overwrite the sentinel with a resolvable name.
func saveScopedSyncFailure(featurePath string, payload *internal.SyncRunState, failed string, completed []string) {
	if payload == nil {
		return
	}
	payload.Stage = internal.SyncStageFailed
	payload.FailedBranch = failed
	payload.Completed = append([]string(nil), completed...)
	done := make(map[string]bool, len(completed))
	for _, name := range completed {
		done[name] = true
	}
	pending := make([]string, 0, len(payload.Selected))
	for _, name := range payload.Selected {
		if name != failed && !done[name] {
			pending = append(pending, name)
		}
	}
	payload.Pending = pending
	_ = internal.SaveSyncRunState(featurePath, payload)
}

// saveScopedPushFailure is the new-mode push failure persistence path. Unlike
// saveScopedSyncFailure it never recomputes `pending` or `completed`: the
// rebases already succeeded and only the push of `failed` is outstanding, so
// the payload keeps everything --continue needs to retry exactly the unpushed
// entries.
func saveScopedPushFailure(featurePath string, payload *internal.SyncRunState, failed string) {
	if payload == nil {
		return
	}
	payload.Stage = internal.SyncStageFailed
	payload.FailedBranch = failed
	_ = internal.SaveSyncRunState(featurePath, payload)
}

// ---------------------------------------------------------------------------
// Test-only seams (§23.1 items 2 and 2a). Both are nil in production, inject
// no verdict, and exist so a second process can really mutate the feature
// directory inside a window this command otherwise closes instantly.
// ---------------------------------------------------------------------------

// syncClassifierBarrierHook is §23.1 seam 2a: the window between
// classifySyncState and the cell-4 guarded-sentinel interception, so a test
// can create, remove or replace .sync-state.yaml between the two reads.
var syncClassifierBarrierHook func(featurePath string) error

func syncClassifierBarrier(featurePath string) error {
	if syncClassifierBarrierHook != nil {
		return syncClassifierBarrierHook(featurePath)
	}
	return nil
}

// syncSnapshotBarrierHook is §23.1 seam 2: the window between the run's one
// state snapshot (InspectExternalPlanState, inside InspectExternalPlan) and
// the guard seam that judges the document built from it.
var syncSnapshotBarrierHook func(featurePath string) error

func syncSnapshotBarrier(featurePath string) error {
	if syncSnapshotBarrierHook != nil {
		return syncSnapshotBarrierHook(featurePath)
	}
	return nil
}

// syncReclassifyCount counts §12.8b vanished-state re-classifications. The
// contract is "at most once per invocation", and this counter is what makes
// that assertion executable rather than aspirational.
var syncReclassifyCount atomic.Int64

// syncStepHook is the package-cli side of the external crash-injection seam.
func syncStepHook(stage internal.SyncRunStage, index int) error {
	if internal.SyncStepHook != nil {
		return internal.SyncStepHook(stage, index)
	}
	return nil
}

// ---------------------------------------------------------------------------
// Header and no-op output (spec §3.7)
// ---------------------------------------------------------------------------

// printSyncModeHeaderTo is the writer-taking twin of printSyncModeHeader —
// the single body this feature's plan route and every executing route share.
// Its bytes are identical to internal.printSyncModeHeaderTo's, which serves
// the checkout half.
func printSyncModeHeaderTo(w io.Writer, p internal.SyncRunPolicy) {
	_, _ = fmt.Fprintf(w, "Sync mode: fetch=%s propagation=%s scope=%s\n", p.Fetch, p.Propagation, p.ScopeLabel())
}

// printSyncModeHeader prints the §3.7 header to stdout. It is now a one-line
// wrapper over printSyncModeHeaderTo, byte-identical to the pre-change body.
func printSyncModeHeader(p internal.SyncRunPolicy) {
	printSyncModeHeaderTo(os.Stdout, p)
}

// syncAnchorNoOpLine is the `[-]` line of the local-only no-op block. It reuses
// formatSyncStatus with the sentence in the mode slot; package internal repeats
// the same literal and the two must stay byte-identical.
func syncAnchorNoOpLine(name string) string {
	return formatSyncStatus(name, "no in-stack parent edge to propagate", "skipped")
}

// ---------------------------------------------------------------------------
// Completion (spec §3.8)
// ---------------------------------------------------------------------------

// syncEntryCompletion offers the non-archived logical entry names of the
// feature named by args[0]. Every error degrades to "no candidates": it never
// errors, never prints, and never exits.
func syncEntryCompletion(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
	if len(args) == 0 {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	ws, err := internal.RequireWorkspace()
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	layout, err := resolveExternalSyncLayout(ws, internal.TwsRoot(), args[0])
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	stack, err := internal.LoadStack(layout.FeaturePath)
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	var names []string
	for _, entry := range stack.Branches {
		if entry.Archived {
			continue
		}
		names = append(names, entry.Name)
	}
	return names, cobra.ShellCompDirectiveNoFileComp
}

package cli

import (
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

// ---------------------------------------------------------------------------
// shared helpers
// ---------------------------------------------------------------------------

// docsRepoRoot is the relative path from this package's test working
// directory (go test always runs with cwd set to the package's own source
// directory, verified directly against this repository) up to the
// repository root, where README.md, CHANGELOG.md, docs/ and assets/ live.
const docsRepoRoot = "../.."

// readRepoDoc reads a repository-root-relative documentation file. It fails
// the test immediately if the file cannot be read, since every caller in
// this file asserts real, present content — never an absent-is-fine case.
func readRepoDoc(t *testing.T, rel string) string {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(docsRepoRoot, rel))
	if err != nil {
		t.Fatalf("reading %s: %v", rel, err)
	}
	return string(data)
}

// normalizeProse strips the Markdown emphasis markers this feature's docs
// use (bold, backtick code spans) and collapses all whitespace — including
// the hard line wraps CHANGELOG.md and the two planning-prose docs use —
// into single spaces, then lowercases. This lets a quoted sentence that a
// human-authored file wraps across two physical lines be matched as one
// contiguous phrase, per spec.md §22.33-i-a's "matched semantically
// (case-insensitive, whitespace- and emphasis-normalised)" rule.
func normalizeProse(s string) string {
	s = strings.NewReplacer("**", "", "`", "", "_", "").Replace(s)
	return strings.ToLower(strings.Join(strings.Fields(s), " "))
}

