func TestSyncScoped_ScopedRunDropsUpdateRefs(t *testing.T) {
	f := newScopedFixture(t)
	f.advanceRoot(t)
	before := gitOutput(t, f.repo, "for-each-ref", "--format=%(refname) %(objectname)")

