func readFileString(t *testing.T, path string) string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return string(data)
}

func resolveRebase(t *testing.T, worktree string) {
	t.Helper()
	if !isRebaseInProgress(worktree) {
		return
	}
	if err := os.WriteFile(filepath.Join(worktree, "conflict.txt"), []byte("resolved\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	gitRun(t, worktree, "add", "conflict.txt")
	cmd := internal.RunSilentDir(worktree, "git", "-c", "core.editor=true", "rebase", "--continue")
	if cmd != nil {
		t.Fatalf("could not finish the rebase in %s: %v", worktree, cmd)
	}
}

func diffRefLines(before, after string) []string {
	old := make(map[string]bool)
	for _, line := range strings.Split(before, "\n") {
		if strings.TrimSpace(line) != "" {
			old[line] = true
		}
	}
	var changed []string
	for _, line := range strings.Split(after, "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		if !old[line] {
			changed = append(changed, line)
		}
	}
	return changed
}

// assertUnselectedStackEntriesUnchanged compares the serialized per-entry
// blocks of stack.yaml and requires every block that does not belong to a
// selected entry to be byte-identical.
func assertUnselectedStackEntriesUnchanged(t *testing.T, before, after string, selected ...string) {
	t.Helper()
	sel := make(map[string]bool, len(selected))
	for _, name := range selected {
		sel[name] = true
	}
	beforeBlocks := stackEntryBlocks(before)
	afterBlocks := stackEntryBlocks(after)
	for name, block := range beforeBlocks {
		if sel[name] {
			continue
		}
		if afterBlocks[name] != block {
			t.Fatalf("unselected entry %q changed:\n--- before ---\n%s\n--- after ---\n%s", name, block, afterBlocks[name])
		}
	}
}

func stackEntryBlocks(doc string) map[string]string {
	blocks := make(map[string]string)
	var name string
	var buf []string
	flush := func() {
		if name != "" {
			blocks[name] = strings.Join(buf, "\n")
		}
		name, buf = "", nil
	}
	for _, line := range strings.Split(doc, "\n") {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "- name:") {
			flush()
			name = strings.TrimSpace(strings.TrimPrefix(trimmed, "- name:"))
		}
		if name != "" {
			buf = append(buf, line)
		}
	}
	flush()
	return blocks
}

package internal

import (
	"maps"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

type Config struct {
	Workspaces    map[string]string `yaml:"workspaces"`
	AgentCommand  string            `yaml:"agent_command"`
	UseTmux       *bool             `yaml:"use_tmux"`
	InjectInto    string            `yaml:"inject_into"`
	TestCommand   string            `yaml:"test_command"`
	AutoHooks     *bool             `yaml:"auto_hooks"`
	BranchPrefix  string            `yaml:"branch_prefix"`
	WorkspaceMode string            `yaml:"workspace_mode,omitempty"`
}

func (c Config) GetAgentCommand() string {
	if c.AgentCommand != "" {
		return c.AgentCommand
	}
	return "claude"
}

// ConfigPath returns the global config path.
func ConfigPath() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".config", "tws", "config.yaml")
}

func repoConfigPath() string {
	root, err := RepoRoot()
	if err != nil {
		return ""
	}
	return filepath.Join(root, ".tws", "config.yaml")
}

func loadConfigFile(path string) Config {
	if path == "" {
		return Config{}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}
	}
	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return Config{}
	}
	return cfg
}

func mergeConfig(base, repo Config) Config {
	cfg := base
	if repo.AgentCommand != "" {
		cfg.AgentCommand = repo.AgentCommand
	}
	if repo.UseTmux != nil {
		cfg.UseTmux = repo.UseTmux
	}
	if repo.InjectInto != "" {
		cfg.InjectInto = repo.InjectInto
	}
	if repo.TestCommand != "" {
		cfg.TestCommand = repo.TestCommand
	}
	if repo.AutoHooks != nil {
		cfg.AutoHooks = repo.AutoHooks
	}
	if repo.BranchPrefix != "" {
		cfg.BranchPrefix = repo.BranchPrefix
	}
	if repo.WorkspaceMode != "" {
		cfg.WorkspaceMode = repo.WorkspaceMode
	}
	if len(repo.Workspaces) > 0 {
		if cfg.Workspaces == nil {
			cfg.Workspaces = make(map[string]string)
		}
		maps.Copy(cfg.Workspaces, repo.Workspaces)
	}
	return cfg
}

// LoadConfig loads the global config, then merges per-repo config on top.
// Per-repo values override global values when set.
func LoadConfig() Config {
	return mergeConfig(loadConfigFile(ConfigPath()), loadConfigFile(repoConfigPath()))
}

func LoadConfigForRepo(repoRoot string) Config {
	return mergeConfig(loadConfigFile(ConfigPath()), loadConfigFile(RepoConfigPathFor(repoRoot)))
}

func RepoConfigPathFor(repoRoot string) string {
	if repoRoot == "" {
		return ""
	}
	return filepath.Join(repoRoot, ".tws", "config.yaml")
}

// SaveConfigFile writes a config to the given path.
func SaveConfigFile(path string, cfg Config) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	data, err := yaml.Marshal(&cfg)
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

// RepoConfigPath exports the per-repo config path for the config command.
func RepoConfigPath() string {
	return repoConfigPath()
}

// LoadConfigFile loads a single config file (exported for the config command).
func LoadConfigFile(path string) Config {
	return loadConfigFile(path)
}

// LoadRepoConfig loads a per-repo config from the given path.
func LoadRepoConfig(path string) Config {
	return loadConfigFile(path)
}

// SaveRepoConfig writes a per-repo config to the given path.
func SaveRepoConfig(path string, cfg Config) error {
	return SaveConfigFile(path, cfg)
}

// TemplatePath returns the template directory path.
// Per-repo (.tws/templates/) takes priority over global (~/.config/tws/templates/).
// Returns empty string if neither exists.
func TemplatePath() string {
	// Per-repo first
	repoPath := repoConfigPath()
	if repoPath != "" {
		repoTemplates := filepath.Join(filepath.Dir(repoPath), "templates")
		if info, err := os.Stat(repoTemplates); err == nil && info.IsDir() {
			return repoTemplates
		}
	}

	// Global
	home, _ := os.UserHomeDir()
	globalTemplates := filepath.Join(home, ".config", "tws", "templates")
	if info, err := os.Stat(globalTemplates); err == nil && info.IsDir() {
		return globalTemplates
	}

	return ""
}

package internal

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

const externalSessionIntentSchema = 1

const (
	ExternalSessionIntentBranches = "branches"
	ExternalSessionIntentFeature  = "feature"
)

const externalSessionIntentsDirName = ".session-intents"

type ExternalSessionIntent struct {
	SchemaVersion int      `json:"schema_version"`
	Token         string   `json:"token"`
	Feature       string   `json:"feature"`
	Scope         string   `json:"scope"`
	Names         []string `json:"names,omitempty"`
	OwnerPID      int      `json:"owner_pid"`
	CreatedAt     string   `json:"created_at"`
}

type LoadedExternalSessionIntent struct {
	Record  ExternalSessionIntent
	File    string
	State   DirectRecordState
	Problem string
}

func ExternalSessionIntentsDir(featurePath string) string {
	return filepath.Join(featurePath, externalSessionIntentsDirName)
}

func externalSessionIntentFile(featurePath, token string) string {
	return filepath.Join(ExternalSessionIntentsDir(featurePath), token+".json")
}

func CreateExternalSessionIntent(featurePath, feature string, names []string, featureWide bool) (string, error) {
	if featurePath == "" || feature == "" {
		return "", fmt.Errorf("external session intent requires a feature path and feature")
	}
	scope := ExternalSessionIntentBranches
	names = normalizedExternalSessionIntentNames(names)
	if featureWide {
		scope = ExternalSessionIntentFeature
		names = nil
	} else if len(names) == 0 {
		return "", fmt.Errorf("branch-scoped external session intent requires at least one branch name")
	}
	token, err := newExternalSessionIntentToken()
	if err != nil {
		return "", err
	}
	dir := ExternalSessionIntentsDir(featurePath)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return "", fmt.Errorf("creating external session intent directory: %w", err)
	}
	rec := ExternalSessionIntent{
		SchemaVersion: externalSessionIntentSchema,
		Token:         token,
		Feature:       feature,
		Scope:         scope,
		Names:         names,
		OwnerPID:      os.Getpid(),
		CreatedAt:     time.Now().UTC().Format(time.RFC3339),
	}
	data, err := json.MarshalIndent(rec, "", "  ")
	if err != nil {
		return "", err
	}
	path := externalSessionIntentFile(featurePath, token)
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return "", fmt.Errorf("creating external session intent: %w", err)
	}
	_, writeErr := file.Write(data)
	closeErr := file.Close()
	if writeErr != nil || closeErr != nil {
		_ = os.Remove(path)
		return "", errors.Join(writeErr, closeErr)
	}
	return token, nil
}

func RemoveOwnedExternalSessionIntent(featurePath, token string) error {
	path := externalSessionIntentFile(featurePath, token)
	data, err := os.ReadFile(path)
	if errors.Is(err, fs.ErrNotExist) {
		pruneExternalSessionIntentDir(featurePath)
		return nil
	}
	if err != nil {
		return err
	}
	var rec ExternalSessionIntent
	if err := json.Unmarshal(data, &rec); err != nil {
		return fmt.Errorf("parsing external session intent: %w", err)
	}
	if rec.Token != token {
		return nil
	}
	if err := os.Remove(path); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return err
	}
	pruneExternalSessionIntentDir(featurePath)
	return nil
}

func LoadExternalSessionIntents(featurePath, feature string, affected []string, proc ProcessProber) (blocking, stale []LoadedExternalSessionIntent, err error) {
	if proc == nil {
		proc = NewProcessProber()
	}
	dir := ExternalSessionIntentsDir(featurePath)
	entries, err := os.ReadDir(dir)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil, nil
	}
	if err != nil {
		return nil, nil, fmt.Errorf("reading external session intent directory: %w", err)
	}
	affectedSet := make(map[string]bool, len(affected))
	for _, name := range affected {
		affectedSet[name] = true
	}
	for _, entry := range entries {
		if entry.IsDir() || !directRecordFileRe.MatchString(entry.Name()) {
			blocking = append(blocking, LoadedExternalSessionIntent{
				File: filepath.Join(dir, entry.Name()), State: DirectRecordInvalid,
				Problem: "unexpected entry in external session intent directory",
			})
			continue
		}
		path := filepath.Join(dir, entry.Name())
		loaded := LoadedExternalSessionIntent{File: path, State: DirectRecordOK}
		info, infoErr := entry.Info()
		if infoErr != nil || !info.Mode().IsRegular() {
			loaded.State = DirectRecordInvalid
			loaded.Problem = "intent is not a verifiable regular file"
			blocking = append(blocking, loaded)
			continue
		}
		data, readErr := os.ReadFile(path)
		if errors.Is(readErr, fs.ErrNotExist) {
			continue
		}
		if readErr != nil {
			loaded.State = DirectRecordInvalid
			loaded.Problem = "unreadable: " + readErr.Error()
			blocking = append(blocking, loaded)
			continue
		}
		if err := json.Unmarshal(data, &loaded.Record); err != nil {
			loaded.State = DirectRecordInvalid
			loaded.Problem = "unparseable: " + err.Error()
			blocking = append(blocking, loaded)
			continue
		}
		stem := strings.TrimSuffix(entry.Name(), ".json")
		switch {
		case loaded.Record.SchemaVersion != externalSessionIntentSchema:
			loaded.State = DirectRecordUnsupported
			loaded.Problem = fmt.Sprintf("schema version %d is not supported", loaded.Record.SchemaVersion)
		case loaded.Record.Token != stem:
			loaded.State = DirectRecordInvalid
			loaded.Problem = "token mismatch"
		case loaded.Record.Feature != feature:
			loaded.State = DirectRecordInvalid
			loaded.Problem = "feature mismatch"
		case loaded.Record.OwnerPID <= 0:
			loaded.State = DirectRecordInvalid
			loaded.Problem = "invalid owner pid"
		case !validExternalSessionIntentCreatedAt(loaded.Record.CreatedAt):
			loaded.State = DirectRecordInvalid
			loaded.Problem = "invalid created_at"
		case loaded.Record.Scope == ExternalSessionIntentFeature:
		case loaded.Record.Scope == ExternalSessionIntentBranches && validExternalSessionIntentNames(loaded.Record.Names):
		default:
			loaded.State = DirectRecordInvalid
			loaded.Problem = "invalid scope or branch names"
		}
		if loaded.State != DirectRecordOK {
			blocking = append(blocking, loaded)
			continue
		}
		applies := loaded.Record.Scope == ExternalSessionIntentFeature
		if !applies {
			for _, name := range loaded.Record.Names {
				if affectedSet[name] {
					applies = true
					break
				}
			}
		}
		if !applies {
			continue
		}
		switch proc.Probe(loaded.Record.OwnerPID) {
		case ProcessLive, ProcessUnknown:
			blocking = append(blocking, loaded)
		default:
			stale = append(stale, loaded)
		}
	}
	sort.Slice(blocking, func(i, j int) bool { return blocking[i].File < blocking[j].File })
	sort.Slice(stale, func(i, j int) bool { return stale[i].File < stale[j].File })
	return blocking, stale, nil
}

func RemoveStaleExternalSessionIntents(featurePath string, stale []LoadedExternalSessionIntent) (int, error) {
	removed := 0
	var errs []error
	for _, intent := range stale {
		if intent.Record.Token == "" {
			continue
		}
		if err := RemoveOwnedExternalSessionIntent(featurePath, intent.Record.Token); err != nil {
			errs = append(errs, err)
			continue
		}
		removed++
	}
	return removed, errors.Join(errs...)
}

func normalizedExternalSessionIntentNames(names []string) []string {
	seen := map[string]bool{}
	out := make([]string, 0, len(names))
	for _, name := range names {
		name = strings.TrimSpace(name)
		if name == "" || seen[name] {
			continue
		}
		seen[name] = true
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

func validExternalSessionIntentNames(names []string) bool {
	if len(names) == 0 {
		return false
	}
	seen := map[string]bool{}
	for _, name := range names {
		if name == "" || name != strings.TrimSpace(name) || seen[name] {
			return false
		}
		seen[name] = true
	}
	return true
}

func validExternalSessionIntentCreatedAt(value string) bool {
	_, err := time.Parse(time.RFC3339, value)
	return err == nil
}

func newExternalSessionIntentToken() (string, error) {
	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		return "", fmt.Errorf("generating external session intent token: %w", err)
	}
	return hex.EncodeToString(buf), nil
}

func pruneExternalSessionIntentDir(featurePath string) {
	_ = os.Remove(ExternalSessionIntentsDir(featurePath))
}

package internal

import (
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// ============================================================================
// GitVersion and the locked §16 rule 2 parser
// ============================================================================

// GitVersion is the locked §16 rule 2 probe result. Probed is always true
// once ProbeGitVersion has run — the act of asking is itself the fact — and
// OK is true only when a version could be parsed from the first line of
// `git --version`. Raw is that first line, verbatim, kept so a rank 5.9
// probe-failed detail can quote exactly what the host printed even when
// parsing fails.
type GitVersion struct {
	Probed bool
	OK     bool
	Raw    string
	Major  int
	Minor  int
	Patch  int
}

// gitVersionPattern is the locked parser. Git's own first line has always
// been "git version X.Y[.Z]" followed by an arbitrary packager suffix on the
// same line — "git version 2.39.5 (Apple Git-154)", "2.30.1.windows.1", a
// Debian/Homebrew build tag, or nothing at all. Only the leading numeric
// major.minor[.patch] token is consumed; anything after it is intentionally
// left unmatched rather than rejected, so a real host is never misclassified
// as unparseable merely because its packager appended free text.
var gitVersionPattern = regexp.MustCompile(`^git version (\d+)\.(\d+)(?:\.(\d+))?`)

// ProbeGitVersion runs `git --version` once and applies the locked parser to
// its first line. An exec failure or an unparseable first line both yield
// Probed: true, OK: false, every Major/Minor/Patch left at zero — the caller
// (§16 rule 1) is the one that raises the document-level rank 5.9
// probe-failed blocker and treats every capability gate as unknown; this
// function only reports what it observed and never performs that
// classification itself.
func ProbeGitVersion() (GitVersion, error) {
	out, err := exec.Command("git", "--version").Output()
	if err != nil {
		return GitVersion{Probed: true, OK: false}, err
	}

	text := string(out)
	if idx := strings.IndexByte(text, '\n'); idx >= 0 {
		text = text[:idx]
	}
	raw := strings.TrimRight(text, "\r")

	v := GitVersion{Probed: true, Raw: raw}
	m := gitVersionPattern.FindStringSubmatch(raw)
	if m == nil {
		return v, nil
	}

	major, majErr := strconv.Atoi(m[1])
	minor, minErr := strconv.Atoi(m[2])
	if majErr != nil || minErr != nil {
		// Unreachable for the pattern's own \d+ groups, but guarded anyway so
		// a malformed match can never silently masquerade as OK: true.
		return v, nil
	}
	patch := 0
	if m[3] != "" {
		if p, patchErr := strconv.Atoi(m[3]); patchErr == nil {
			patch = p
		}
	}

	v.OK = true
	v.Major = major
	v.Minor = minor
	v.Patch = patch
	return v, nil
}

// ============================================================================
// GitCapabilities — the closed §16 rule 3 six-gate table
// ============================================================================

// GitCapabilities is the closed §16 rule 3 six-gate table, one bool per gate,
// each named for the Git version at which this feature's own behaviour
// changes. An unknown GitVersion (Probed && !OK) yields every gate false via
// GitCapabilitiesForVersion; a caller MUST read that as "unknown", never as
// "absent on this host" — §16 rule 1 already raises the document-level rank
// 5.9 probe-failed blocker in that case, so no gate here is ever consulted
// for a real decision once that blocker has fired.
type GitCapabilities struct {
	// CapPruneTags is `fetch --prune-tags`, Git >= 2.17.
	CapPruneTags bool

	// CapConfigShowScope is `git config --list --show-scope`, Git >= 2.26.
	// Below this gate — or with an unknown version — the plan/guard route
	// cannot tell a key's scope apart from its value at all, so it refuses
	// with rank 5.9 probe-failed rather than publish a scope-less inventory
	// as though it were scoped, and rather than silently drop
	// config_issues[].source (§11.7).
	CapConfigShowScope bool

	// CapDefaultBackendMerge is Git >= 2.26, the version at which
	// rebase.backend — and the merge-backed default effective_backend row 3-5
	// model when it is set or absent — first exists. Kept as its own field,
	// never collapsed with CapConfigShowScope even though both gate at 2.26,
	// because the two have opposite consequences: one refuses the
	// invocation outright, the other only changes how an older host's
	// built-in apply-backend default is modelled (§16 rule 3a).
	CapDefaultBackendMerge bool

	// CapSoleRemoteFallback is Git's own "exactly one configured remote"
	// rung of the remote-resolution ladder (§11.4), Git >= 2.37.
	CapSoleRemoteFallback bool

	// CapRebaseUpdateRefs is `git rebase --update-refs`, Git >= 2.38. Its
	// predicate is argv-derived (§16 rule 3b): a row is gated on it only
	// where the argv THAT ROW publishes actually carries --update-refs, so a
	// host below this gate cannot run that specific argv at all and the
	// controlled route refuses with rank 5.9 probe-failed above any
	// effective_backend classification of it.
	CapRebaseUpdateRefs bool

	// CapFetchAll is `fetch.all`, Git >= 2.44.
	CapFetchAll bool
}

// atLeast reports whether v is a known version at or above major.minor.
// Patch is deliberately excluded: none of the six §16 gates are patch-level,
// so comparing it would let a distro's backport patch release
// (2.25.<huge>, say) masquerade as meeting a minor-level gate it does not.
func (v GitVersion) atLeast(major, minor int) bool {
	if !v.OK {
		return false
	}
	if v.Major != major {
		return v.Major > major
	}
	return v.Minor >= minor
}

// GitCapabilitiesForVersion derives the six §16 rule 3 gates from a probed
// GitVersion. An unknown version (Probed && !OK, or Probed: false) yields the
// zero value — every gate false — which callers must read as "unknown", not
// "confirmed absent".
func GitCapabilitiesForVersion(v GitVersion) GitCapabilities {
	return GitCapabilities{
		CapPruneTags:           v.atLeast(2, 17),
		CapConfigShowScope:     v.atLeast(2, 26),
		CapDefaultBackendMerge: v.atLeast(2, 26),
		CapSoleRemoteFallback:  v.atLeast(2, 37),
		CapRebaseUpdateRefs:    v.atLeast(2, 38),
		CapFetchAll:            v.atLeast(2, 44),
	}
}

// ============================================================================
// ReparentGitCapabilities — safe-reparent's additive gate pair (§9.10)
//
// The six-gate GitCapabilities table above is frozen and MUST NOT be
// extended. The two facts below sit BESIDE it because neither is part of
// safe-reparent's required minimum: that minimum is the existing
// GitCapabilities.CapRebaseUpdateRefs gate (Git >= 2.38), which is already a
// sufficient floor for every core requirement — update-ref --stdin's
// start/prepare/commit verbs (2.27), --end-of-options (2.24),
// --no-rebase-merges (2.34), --disambiguate (long-standing), git switch
// (2.23) and the merge backend default (2.26) are all older — so no new
// version gate is invented for them.
// ============================================================================

// ReparentGitCapabilities is safe-reparent's own two-fact table. Each field
// gates exactly one optional behaviour and never the run as a whole:
// CapForceIfIncludes gates only the remote follow-up lease rule, and
// CapRefBackendKnown gates only which probe the ref-backend question uses.
// An unknown GitVersion yields the zero value — both false — which callers
// MUST read as "unknown" and resolve by taking the conservative branch, never
// by assuming absence and never by refusing.
type ReparentGitCapabilities struct {
	// CapForceIfIncludes is `git push --force-if-includes`, Git >= 2.30.
	CapForceIfIncludes bool

	// CapRefBackendKnown is `git rev-parse --show-ref-format`, Git >= 2.45.
	// When it is false the ref backend is probed with
	// `git config --get extensions.refStorage` instead, and an unresolved
	// answer is reported as "unknown" and treated exactly as "files".
	CapRefBackendKnown bool
}

// ReparentGitCapabilitiesForVersion derives the two additive gates from a
// probed GitVersion, reusing the same deliberately patch-blind atLeast
// comparison the frozen table uses. It never consults, changes or shadows
// GitCapabilitiesForVersion.
func ReparentGitCapabilitiesForVersion(v GitVersion) ReparentGitCapabilities {
	return ReparentGitCapabilities{
		CapForceIfIncludes: v.atLeast(2, 30),
		CapRefBackendKnown: v.atLeast(2, 45),
	}
}

// ProbeGitCapabilities composes ProbeGitVersion and GitCapabilitiesForVersion,
// the one call a controlled route needs to obtain both the raw probe (for its
// own rank 5.9 probe-failed detail, §16 rule 1) and the derived gate table in
// a single step.
func ProbeGitCapabilities() (GitCapabilities, GitVersion, error) {
	v, err := ProbeGitVersion()
	return GitCapabilitiesForVersion(v), v, err
}

package internal

import (
	"os"
	"path/filepath"
	"testing"
)

// ============================================================================
// git_capability_test.go — TestGitCapability*
//
// The locked §16 rule 2 version parser over real-world version strings,
// ProbeGitVersion's Probed/OK semantics (successful probe, exec failure,
// unparseable output), and the six independent §16 rule 3 capability gates
// at their exact boundaries (2.17, 2.26, 2.26, 2.37, 2.38, 2.44).
// ============================================================================

// ---------------------------------------------------------------------------
// The locked parser (gitVersionPattern), exercised directly against
// real-world `git --version` first lines without shelling out — this is the
// pure-function half of "the locked parser over real-world version strings".
// ---------------------------------------------------------------------------

func TestGitCapability_VersionPatternRealWorldStrings(t *testing.T) {
	cases := []struct {
		name      string
		raw       string
		wantMatch bool
		wantMajor int
		wantMinor int
		wantPatch int
	}{
		{name: "macOS Xcode packager suffix", raw: "git version 2.39.5 (Apple Git-154)", wantMatch: true, wantMajor: 2, wantMinor: 39, wantPatch: 5},
		{name: "plain three-component", raw: "git version 2.43.0", wantMatch: true, wantMajor: 2, wantMinor: 43, wantPatch: 0},
		{name: "Git-for-Windows four-component", raw: "git version 2.30.1.windows.1", wantMatch: true, wantMajor: 2, wantMinor: 30, wantPatch: 1},
		{name: "minor-only, no patch component", raw: "git version 2.17", wantMatch: true, wantMajor: 2, wantMinor: 17, wantPatch: 0},
		{name: "Debian packager suffix", raw: "git version 2.30.2", wantMatch: true, wantMajor: 2, wantMinor: 30, wantPatch: 2},
		{name: "release-candidate patch suffix", raw: "git version 3.0.0-rc1", wantMatch: true, wantMajor: 3, wantMinor: 0, wantPatch: 0},
		{name: "future major version", raw: "git version 3.1.4", wantMatch: true, wantMajor: 3, wantMinor: 1, wantPatch: 4},
		{name: "empty string", raw: "", wantMatch: false},
		{name: "wrong case", raw: "GIT VERSION 2.30.0", wantMatch: false},
		{name: "non-numeric version", raw: "git version abc.def", wantMatch: false},
		{name: "unrelated program", raw: "some other program 2.3.4", wantMatch: false},
		{name: "missing minor component", raw: "git version 2", wantMatch: false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			m := gitVersionPattern.FindStringSubmatch(tc.raw)
			if tc.wantMatch != (m != nil) {
				t.Fatalf("gitVersionPattern.FindStringSubmatch(%q) match = %v, want %v", tc.raw, m != nil, tc.wantMatch)
			}
			if !tc.wantMatch {
				return
			}
			gotMajor, gotMinor, gotPatch := parseCapturedVersionGroups(t, m)
			if gotMajor != tc.wantMajor || gotMinor != tc.wantMinor || gotPatch != tc.wantPatch {
				t.Errorf("%q parsed as %d.%d.%d, want %d.%d.%d", tc.raw, gotMajor, gotMinor, gotPatch, tc.wantMajor, tc.wantMinor, tc.wantPatch)
			}
		})
	}
}

// parseCapturedVersionGroups mirrors ProbeGitVersion's own group-to-int
// conversion (major/minor required, patch defaults to 0 when the optional
// third group did not participate), so this test exercises the same
// conversion rule the shipped function applies, not a reinvented one.
func parseCapturedVersionGroups(t *testing.T, m []string) (major, minor, patch int) {
	t.Helper()
	atoi := func(s string) int {
		if s == "" {
			return 0
		}
		n := 0
		for _, r := range s {
			n = n*10 + int(r-'0')
		}
		return n
	}
	return atoi(m[1]), atoi(m[2]), atoi(m[3])
}

// ---------------------------------------------------------------------------
// ProbeGitVersion's Probed/OK semantics, end to end (real exec.Command, no
// regex bypass) — successful real-host probe, exec failure (git not on
// PATH), and unparseable-but-successful output (a shimmed fake git).
// ---------------------------------------------------------------------------

func TestGitCapability_ProbeGitVersion_RealHost(t *testing.T) {
	v, err := ProbeGitVersion()
	if err != nil {
		t.Fatalf("ProbeGitVersion on the real host git: %v", err)
	}
	if !v.Probed {
		t.Error("Probed = false after a successful invocation, want true")
	}
	if !v.OK {
		t.Errorf("OK = false for real host git, want true (Raw=%q)", v.Raw)
	}
	if v.Major < 2 {
		t.Errorf("Major = %d, want >= 2 for any git installation this suite can run against", v.Major)
	}
	wantPrefix := "git version "
	if len(v.Raw) < len(wantPrefix) || v.Raw[:len(wantPrefix)] != wantPrefix {
		t.Errorf("Raw = %q, want it to start with %q", v.Raw, wantPrefix)
	}
}

func TestGitCapability_ProbeGitVersion_ExecFailure(t *testing.T) {
	// An empty PATH directory has no git binary at all: exec.Command itself
	// fails to start the process, which must still yield Probed:true (the
	// act of asking is itself the fact) alongside OK:false and a non-nil
	// error.
	t.Setenv("PATH", t.TempDir())

	v, err := ProbeGitVersion()
	if err == nil {
		t.Fatal("ProbeGitVersion with no git on PATH: want a non-nil error")
	}
	if !v.Probed {
		t.Error("Probed = false after an exec failure, want true")
	}
	if v.OK {
		t.Error("OK = true after an exec failure, want false")
	}
	if v.Major != 0 || v.Minor != 0 || v.Patch != 0 {
		t.Errorf("Major/Minor/Patch = %d/%d/%d after an exec failure, want all zero", v.Major, v.Minor, v.Patch)
	}
}

// installFakeGit points PATH at a directory containing only a `git` shell
// script that prints firstLine (optionally followed by more lines) to
// stdout and exits 0 — a real external process (never a Go-level mock of
// exec.Command), used only to observe ProbeGitVersion's own line-splitting
// and \r-trimming against output the real host's git cannot be made to
// produce on demand (an unparseable line, or a CRLF line ending).
func installFakeGit(t *testing.T, output string) {
	t.Helper()
	binDir := t.TempDir()
	outFile := filepath.Join(binDir, "version-output.txt")
	if err := os.WriteFile(outFile, []byte(output), 0o644); err != nil {
		t.Fatal(err)
	}
	script := "#!/bin/sh\ncat '" + outFile + "'\n"
	if err := os.WriteFile(filepath.Join(binDir, "git"), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	// Prepend, never replace: the script's own shebang needs the rest of
	// PATH to resolve `cat`. Only the git *lookup* itself needs binDir to
	// win, which prepending guarantees.
	t.Setenv("PATH", binDir+string(os.PathListSeparator)+os.Getenv("PATH"))
}

func TestGitCapability_ProbeGitVersion_UnparseableOutput(t *testing.T) {
	installFakeGit(t, "not a git version string at all\n")

	v, err := ProbeGitVersion()
	if err != nil {
		t.Fatalf("ProbeGitVersion: %v", err)
	}
	if !v.Probed {
		t.Error("Probed = false, want true (the invocation itself succeeded)")
	}
	if v.OK {
		t.Error("OK = true for an unparseable first line, want false")
	}
	if v.Raw != "not a git version string at all" {
		t.Errorf("Raw = %q, want the verbatim (newline-stripped) first line", v.Raw)
	}
	if v.Major != 0 || v.Minor != 0 || v.Patch != 0 {
		t.Errorf("Major/Minor/Patch = %d/%d/%d, want all zero when unparseable", v.Major, v.Minor, v.Patch)
	}
}

func TestGitCapability_ProbeGitVersion_FakeRealWorldStrings(t *testing.T) {
	cases := []struct {
		name      string
		output    string // full fake stdout, CRLF/multi-line included
		wantRaw   string
		wantMajor int
		wantMinor int
		wantPatch int
	}{
		{
			name:      "CRLF line ending is trimmed from Raw",
			output:    "git version 2.40.0\r\n",
			wantRaw:   "git version 2.40.0",
			wantMajor: 2, wantMinor: 40, wantPatch: 0,
		},
		{
			name:      "only the first line is consulted",
			output:    "git version 2.41.0\nsome other trailer line\n",
			wantRaw:   "git version 2.41.0",
			wantMajor: 2, wantMinor: 41, wantPatch: 0,
		},
		{
			name:      "Apple packager suffix survives end to end",
			output:    "git version 2.39.5 (Apple Git-154)\n",
			wantRaw:   "git version 2.39.5 (Apple Git-154)",
			wantMajor: 2, wantMinor: 39, wantPatch: 5,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			installFakeGit(t, tc.output)
			v, err := ProbeGitVersion()
			if err != nil {
				t.Fatalf("ProbeGitVersion: %v", err)
			}
			if !v.Probed || !v.OK {
				t.Fatalf("Probed/OK = %v/%v, want true/true (Raw=%q)", v.Probed, v.OK, v.Raw)
			}
			if v.Raw != tc.wantRaw {
				t.Errorf("Raw = %q, want %q", v.Raw, tc.wantRaw)
			}
			if v.Major != tc.wantMajor || v.Minor != tc.wantMinor || v.Patch != tc.wantPatch {
				t.Errorf("parsed %d.%d.%d, want %d.%d.%d", v.Major, v.Minor, v.Patch, tc.wantMajor, tc.wantMinor, tc.wantPatch)
			}
		})
	}
}

// ---------------------------------------------------------------------------
// The six independent §16 rule 3 gate calculations, at their exact
// major.minor boundaries. Constructed GitVersion values are used directly
// (no exec needed) so every boundary — including ones this host's own
// installed git may not straddle — is covered deterministically.
// ---------------------------------------------------------------------------

func TestGitCapability_GateBoundaries(t *testing.T) {
	below := func(major, minor int) GitVersion {
		return GitVersion{Probed: true, OK: true, Major: major, Minor: minor}
	}

	cases := []struct {
		name string
		v    GitVersion
		gate func(GitCapabilities) bool
		want bool
	}{
		{"prune-tags below 2.17", below(2, 16), func(c GitCapabilities) bool { return c.CapPruneTags }, false},
		{"prune-tags at 2.17", below(2, 17), func(c GitCapabilities) bool { return c.CapPruneTags }, true},

		{"config-show-scope below 2.26", below(2, 25), func(c GitCapabilities) bool { return c.CapConfigShowScope }, false},
		{"config-show-scope at 2.26", below(2, 26), func(c GitCapabilities) bool { return c.CapConfigShowScope }, true},

		{"default-backend-merge below 2.26", below(2, 25), func(c GitCapabilities) bool { return c.CapDefaultBackendMerge }, false},
		{"default-backend-merge at 2.26", below(2, 26), func(c GitCapabilities) bool { return c.CapDefaultBackendMerge }, true},

		{"sole-remote-fallback below 2.37", below(2, 36), func(c GitCapabilities) bool { return c.CapSoleRemoteFallback }, false},
		{"sole-remote-fallback at 2.37", below(2, 37), func(c GitCapabilities) bool { return c.CapSoleRemoteFallback }, true},

		{"rebase-update-refs below 2.38", below(2, 37), func(c GitCapabilities) bool { return c.CapRebaseUpdateRefs }, false},
		{"rebase-update-refs at 2.38", below(2, 38), func(c GitCapabilities) bool { return c.CapRebaseUpdateRefs }, true},

		{"fetch-all below 2.44", below(2, 43), func(c GitCapabilities) bool { return c.CapFetchAll }, false},
		{"fetch-all at 2.44", below(2, 44), func(c GitCapabilities) bool { return c.CapFetchAll }, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := tc.gate(GitCapabilitiesForVersion(tc.v))
			if got != tc.want {
				t.Errorf("gate(%d.%d) = %v, want %v", tc.v.Major, tc.v.Minor, got, tc.want)
			}
		})
	}
}

func TestGitCapability_GateBoundaries_ConfigShowScopeAndDefaultBackendAreIndependentFields(t *testing.T) {
	// Both CapConfigShowScope and CapDefaultBackendMerge gate at the same
	// 2.26 boundary, but the doc comment on GitCapabilities is explicit that
	// they must never be collapsed into a shared field: assert both are
	// present and both actually equal true at 2.26, as two distinct
	// observations, not one.
	caps := GitCapabilitiesForVersion(GitVersion{Probed: true, OK: true, Major: 2, Minor: 26})
	if !caps.CapConfigShowScope {
		t.Error("CapConfigShowScope = false at 2.26, want true")
	}
	if !caps.CapDefaultBackendMerge {
		t.Error("CapDefaultBackendMerge = false at 2.26, want true")
	}
}

func TestGitCapability_GateBoundaries_PatchLevelNeverConsulted(t *testing.T) {
	// atLeast compares major.minor only: a huge patch on a version one minor
	// below a gate's threshold must not let that gate fire (no distro
	// backport can masquerade as meeting a minor-level gate).
	v := GitVersion{Probed: true, OK: true, Major: 2, Minor: 16, Patch: 999}
	if GitCapabilitiesForVersion(v).CapPruneTags {
		t.Errorf("CapPruneTags = true for 2.16.999, want false (patch must never bridge a minor gate)")
	}
}

func TestGitCapability_GateBoundaries_UnknownVersionYieldsAllGatesFalse(t *testing.T) {
	// An unknown version (Probed && !OK, or the zero value) yields every
	// gate false, which callers must read as "unknown", never "confirmed
	// absent" — GitCapabilitiesForVersion itself has no way to encode that
	// distinction, so this test only proves the all-false shape.
	for _, v := range []GitVersion{
		{},                                  // never probed
		{Probed: true, OK: false},           // probed, unparseable
		{Probed: true, OK: false, Major: 9}, // OK false must dominate even if Major/Minor were somehow set
	} {
		caps := GitCapabilitiesForVersion(v)
		if caps != (GitCapabilities{}) {
			t.Errorf("GitCapabilitiesForVersion(%+v) = %+v, want the all-false zero value", v, caps)
		}
	}
}

func TestGitCapability_GateBoundaries_VersionWellAboveAllGates(t *testing.T) {
	caps := GitCapabilitiesForVersion(GitVersion{Probed: true, OK: true, Major: 3, Minor: 0})
	want := GitCapabilities{
		CapPruneTags:           true,
		CapConfigShowScope:     true,
		CapDefaultBackendMerge: true,
		CapSoleRemoteFallback:  true,
		CapRebaseUpdateRefs:    true,
		CapFetchAll:            true,
	}
	if caps != want {
		t.Errorf("GitCapabilitiesForVersion(3.0) = %+v, want every gate true (%+v)", caps, want)
	}
}

// ---------------------------------------------------------------------------
// ProbeGitCapabilities composes ProbeGitVersion and GitCapabilitiesForVersion.
// ---------------------------------------------------------------------------

func TestGitCapability_ProbeGitCapabilities_ComposesProbeAndDerive(t *testing.T) {
	caps, v, err := ProbeGitCapabilities()
	if err != nil {
		t.Fatalf("ProbeGitCapabilities on the real host git: %v", err)
	}
	if !v.Probed || !v.OK {
		t.Fatalf("ProbeGitCapabilities returned Probed=%v OK=%v for the real host git, want true/true", v.Probed, v.OK)
	}
	want := GitCapabilitiesForVersion(v)
	if caps != want {
		t.Errorf("ProbeGitCapabilities capabilities = %+v, want GitCapabilitiesForVersion(returned version) = %+v", caps, want)
	}
}

// ---------------------------------------------------------------------------
// ReparentGitCapabilities — safe-reparent's additive gate pair (§9.10).
//
// The six-gate table above is frozen; these cells assert the new pair sits
// BESIDE it, gates at its own versions, and changes nothing about it.
// ---------------------------------------------------------------------------

func TestReparentGitCapabilities_GateBoundaries(t *testing.T) {
	cases := []struct {
		name           string
		version        GitVersion
		forceIfInclude bool
		refBackend     bool
	}{
		{"2.29 is below force-if-includes", GitVersion{Probed: true, OK: true, Major: 2, Minor: 29}, false, false},
		{"2.30 is exactly force-if-includes", GitVersion{Probed: true, OK: true, Major: 2, Minor: 30}, true, false},
		{"2.44 is below show-ref-format", GitVersion{Probed: true, OK: true, Major: 2, Minor: 44}, true, false},
		{"2.45 is exactly show-ref-format", GitVersion{Probed: true, OK: true, Major: 2, Minor: 45}, true, true},
		{"3.0 is above both", GitVersion{Probed: true, OK: true, Major: 3, Minor: 0}, true, true},
		{"1.99 is below both", GitVersion{Probed: true, OK: true, Major: 1, Minor: 99}, false, false},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			caps := ReparentGitCapabilitiesForVersion(tc.version)
			if caps.CapForceIfIncludes != tc.forceIfInclude {
				t.Errorf("CapForceIfIncludes = %v, want %v", caps.CapForceIfIncludes, tc.forceIfInclude)
			}
			if caps.CapRefBackendKnown != tc.refBackend {
				t.Errorf("CapRefBackendKnown = %v, want %v", caps.CapRefBackendKnown, tc.refBackend)
			}
		})
	}
}

func TestReparentGitCapabilities_UnknownVersionYieldsAllFalse(t *testing.T) {
	for _, v := range []GitVersion{
		{},
		{Probed: true, OK: false, Raw: "git version (unparseable)"},
	} {
		caps := ReparentGitCapabilitiesForVersion(v)
		if caps != (ReparentGitCapabilities{}) {
			t.Fatalf("ReparentGitCapabilitiesForVersion(%+v) = %+v, want the zero value read as unknown", v, caps)
		}
	}
}

func TestReparentGitCapabilities_PatchLevelNeverConsulted(t *testing.T) {
	low := ReparentGitCapabilitiesForVersion(GitVersion{Probed: true, OK: true, Major: 2, Minor: 44, Patch: 9999})
	if low.CapRefBackendKnown {
		t.Fatal("a 2.44 patch release must not satisfy the 2.45 gate")
	}
}

func TestReparentGitCapabilities_FrozenSixGateTableIsUnchanged(t *testing.T) {
	v := GitVersion{Probed: true, OK: true, Major: 2, Minor: 45}
	before := GitCapabilities{
		CapPruneTags:           true,
		CapConfigShowScope:     true,
		CapDefaultBackendMerge: true,
		CapSoleRemoteFallback:  true,
		CapRebaseUpdateRefs:    true,
		CapFetchAll:            true,
	}
	if got := GitCapabilitiesForVersion(v); got != before {
		t.Fatalf("GitCapabilitiesForVersion(2.45) = %+v, want the frozen %+v", got, before)
	}
	// The required minimum is the existing 2.38 gate, not a new one.
	if GitCapabilitiesForVersion(GitVersion{Probed: true, OK: true, Major: 2, Minor: 37}).CapRebaseUpdateRefs {
		t.Fatal("2.37 must not satisfy the CapRebaseUpdateRefs floor safe-reparent requires")
	}
}

package internal

import (
	"os"
	"sort"
	"strings"
)

// ============================================================================
// rebase_planner.go — the pure rebase-plan decision layer (§9-§11, §14.1a).
//
// Every function here either (a) decides an output from facts its caller
// already measured, with no I/O of its own, or (b) is one of the six named
// push producers, which legitimately call the read-helpers of
// internal/rebase_plan_probe.go because measuring a push context's remote
// facts IS their job. Nothing in this file re-implements a probe that file
// already owns, and nothing here re-implements §7.1/§7.2 precedence outside
// SelectPrimaryRefusal.
//
// internal/rebase_plan_build.go is the one caller: BuildRebasePlan composes
// these functions per entry and assembles the twenty-five document keys. It
// does not exist in this file, and this file declares no document-assembly
// logic of its own.
// ============================================================================

// ============================================================================
// EntryContexts (§4.4, §9.1a Group A) — per-entry role, materialization and
// the base_context/execution_context pair.
// ============================================================================

// EntryContextInput is one stack entry's already-known facts EntryContexts
// needs to resolve its Group-A context members. It never re-loads the stack
// or the selection: both are handed in, exactly as BuildRebasePlan already
// holds them from RebasePlanRequest.
type EntryContextInput struct {
	Entry     StackEntry
	Mode      WorkspaceMode
	Layout    RebasePlanLayout
	Selection SyncSelection
}

// EntryContextResult is EntryContexts' total output: the Group-A members of
// one entries[] row, plus the concrete PlanContextIdentity BuildRebasePlan
// accumulates into the document's one shared identity table (§14.1a).
type EntryContextResult struct {
	Role            string // anchor | propagated (mirrors SyncSelectedEntry.Role)
	Materialization string // materialized | archived-metadata | worktree-missing | prunable

	ExecutionDir      string // the directory measured for ExecutionContext; "" iff unusable
	ExecutionSource   string
	ExecutionIdentity PlanContextIdentity
	ExecutionContext  PlanContext
	ExecutionErr      error // non-nil iff the context could not be established at all

	// The base half is measured in its OWN directory, which is NOT always the
	// execution directory: §4.2's context-source table splits them on exactly
	// one arm — external pass 1 with a non-empty Repo, where the base is
	// resolved in `entry-repo` while the command runs in `worktree`. That is
	// the same ladder the shipped executor's own resolveEntryBase uses
	// (§10.7 rule 3), mirrored rather than guessed.
	BaseDir      string // "" iff the base context is not-applicable or the process cwd
	BaseSource   string
	BaseIdentity PlanContextIdentity
	BaseContext  PlanContext
	BaseErr      error // non-nil iff the base context could not be established

	// StoreDivergent is rank 5.15 base-execution-store-divergent (external
	// only): both contexts established, and their measured canonical common
	// dirs differ. SameStoreSplit is the non-blocking warning
	// base-execution-context-split: two DISTINCT contexts sharing one common
	// dir. The two are mutually exclusive by construction.
	StoreDivergent bool
	SameStoreSplit bool
}

// classifyMaterialization is the one §3 four-value materialization
// classifier, shared by EntryContexts and ExecutionOrder so the two never
// disagree about which of an entry's two passes it belongs to. Checkout mode
// has no separate worktree tree, so its one repository is always
// materialized; external mode consults the stack's own Archived flag first —
// a retired entry is always inert at plan time, independent of whatever a
// stale directory on disk might still say — then the worktree directory,
// then the administrative git-worktree-prune state (internal/exec.go's
// IsPrunableWorktree, the same predicate pass 2 of the shipped executor
// consults, internal/cli/sync_helpers.go).
func classifyMaterialization(mode WorkspaceMode, entry StackEntry, layout RebasePlanLayout) string {
	if mode == ModeCheckout {
		return "materialized"
	}
	if entry.Archived {
		return "archived-metadata"
	}
	if path := layout.WorktreePath(entry.Name); path != "" {
		if _, err := os.Stat(path); err == nil {
			return "materialized"
		}
	}
	if IsPrunableWorktree(entry.GitBranch()) {
		return "prunable"
	}
	return "worktree-missing"
}

// EntryContexts resolves one entries[] row's role, materialization and
// context pair (§9.1a, §14.1a). It performs exactly one context measurement
// (EstablishContextIdentity, internal/rebase_plan_probe.go) — the same
// primitive the six push producers and the config/holder probes key their
// own context_id lookups from.
func EntryContexts(in EntryContextInput) EntryContextResult {
	role := string(in.Selection.Role(in.Entry.Name))
	materialization := classifyMaterialization(in.Mode, in.Entry, in.Layout)

	var dir, source string
	switch {
	case in.Mode == ModeCheckout:
		dir, source = in.Layout.RepoRoot, "workspace-repo-root"
	case materialization == "materialized":
		dir, source = in.Layout.WorktreePath(in.Entry.Name), "worktree"
	case in.Entry.Repo != "":
		dir, source = in.Entry.Repo, "entry-repo"
	default:
		dir, source = "", "process-cwd"
	}

	// §4.2's base-context ladder, mirrored from the shipped executor's own
	// resolveEntryBase call sites (§10.7 rule 3): the entry's Repo, else its
	// materialized worktree, else the process cwd. Checkout resolves both
	// halves in the one workspace repository root.
	baseDir, baseSource := dir, source
	if in.Mode == ModeExternal {
		switch {
		case in.Entry.Repo != "":
			baseDir, baseSource = in.Entry.Repo, "entry-repo"
		case materialization == "materialized":
			baseDir, baseSource = in.Layout.WorktreePath(in.Entry.Name), "worktree"
		default:
			baseDir, baseSource = "", "process-cwd"
		}
	}

	result := EntryContextResult{
		Role: role, Materialization: materialization,
		ExecutionDir: dir, ExecutionSource: source,
		BaseDir: baseDir, BaseSource: baseSource,
	}

	identity, err := EstablishContextIdentity(dir, source)
	if err != nil {
		result.ExecutionErr = err
		result.ExecutionContext = PlanContext{Source: source}
	} else {
		result.ExecutionIdentity = identity
		result.ExecutionContext = PlanContext{ContextID: &identity.ContextID, RepoRoot: &identity.RepoRoot, Source: source}
	}

	if in.Entry.Base == "" {
		result.BaseContext = PlanContext{Source: "not-applicable"}
		result.BaseDir, result.BaseSource = "", "not-applicable"
		return result
	}

	if baseDir == dir && baseSource == source {
		// One directory, one measurement: the two halves are the same
		// context and MUST NOT cost a second probe.
		result.BaseIdentity, result.BaseErr = result.ExecutionIdentity, result.ExecutionErr
		result.BaseContext = result.ExecutionContext
		return result
	}

	baseIdentity, baseErr := EstablishContextIdentity(baseDir, baseSource)
	if baseErr != nil {
		result.BaseErr = baseErr
		result.BaseContext = PlanContext{Source: baseSource}
		return result
	}
	result.BaseIdentity = baseIdentity
	result.BaseContext = PlanContext{ContextID: &baseIdentity.ContextID, RepoRoot: &baseIdentity.RepoRoot, Source: baseSource}

	if result.ExecutionErr == nil && baseIdentity.ContextID != identity.ContextID {
		if baseIdentity.CommonDir != identity.CommonDir {
			// Rank 5.15 base-execution-store-divergent: external only,
			// blocking. Two different object stores on one row means the
			// SHA the base half resolves is not a commit the execution half
			// can even name.
			result.StoreDivergent = in.Mode == ModeExternal
		} else {
			// Two distinct contexts sharing one common dir: the
			// non-blocking base-execution-context-split warning.
			result.SameStoreSplit = true
		}
	}
	return result
}

// ============================================================================
// ResolveSyncBase (§10) — mirrors internal/cli/sync_helpers.go's
// resolveEntryBase/resolveBase exactly, without importing package cli.
// ============================================================================

// ResolveSyncBaseResult is ResolveSyncBase's total output.
type ResolveSyncBaseResult struct {
	Base             string // "" iff Kind == "none"
	IsRemoteTracking bool   // true iff Base was rewritten to "<remote>/<default-branch>"
	Kind             string // stack-entry | literal-ref | none (PlanEntryBase.Kind)
	DependsOnName    string // the configured stack parent's logical name; "" unless Kind == stack-entry
}

// ResolveSyncBase mirrors package cli's resolveEntryBase/resolveBase
// (internal/cli/sync_helpers.go) exactly: a same-repo stack parent's own
// GitBranch() wins outright; otherwise the configured base is resolved
// through resolveBase's default-branch-to-remote-tracking rewrite. repoCtx is
// the directory DefaultBranchIn resolves the repository default branch in —
// entry.Repo for external pass 2, the worktree path for pass 1, Layout.
// RepoRoot for checkout — exactly as the two mirrored call sites use it.
func ResolveSyncBase(stack Stack, entry StackEntry, repoCtx string) ResolveSyncBaseResult {
	if entry.Base == "" {
		return ResolveSyncBaseResult{Kind: "none"}
	}
	parent := GetBranch(stack, entry.Base)
	if parent.Name != "" && SameStackRepo(parent.Repo, entry.Repo) {
		return ResolveSyncBaseResult{Base: parent.GitBranch(), Kind: "stack-entry", DependsOnName: parent.Name}
	}
	var defaultBranch string
	if repoCtx == "" {
		defaultBranch = DefaultBranch()
	} else {
		defaultBranch, _ = DefaultBranchIn(repoCtx)
	}
	return ResolveSyncBaseWithDefaultBranch(stack, entry, defaultBranch)
}

// ResolveSyncBaseWithDefaultBranch is the pure half of ResolveSyncBase. Sync
// keeps measuring its default branch exactly as before; reparent supplies the
// same already-measured fact through its Dir-based Git runner so no hidden
// process can add `-C` to the reparent boundary.
func ResolveSyncBaseWithDefaultBranch(stack Stack, entry StackEntry, defaultBranch string) ResolveSyncBaseResult {
	if entry.Base == "" {
		return ResolveSyncBaseResult{Kind: "none"}
	}
	parent := GetBranch(stack, entry.Base)
	if parent.Name != "" && SameStackRepo(parent.Repo, entry.Repo) {
		return ResolveSyncBaseResult{Base: parent.GitBranch(), Kind: "stack-entry", DependsOnName: parent.Name}
	}
	kind, dependsOn := "literal-ref", ""
	if parent.Name != "" {
		// A same-named stack entry exists but in a different repository:
		// still a configured stack dependency, just not one resolveEntryBase
		// can use directly (§10) — resolveBase treats entry.Base as a
		// literal ref from here on, exactly as the shipped executor does.
		kind, dependsOn = "stack-entry", parent.Name
	}
	if entry.Base == defaultBranch {
		return ResolveSyncBaseResult{Base: "origin/" + defaultBranch, IsRemoteTracking: true, Kind: kind, DependsOnName: dependsOn}
	}
	return ResolveSyncBaseResult{Base: entry.Base, Kind: kind, DependsOnName: dependsOn}
}

// ============================================================================
// ExecutionOrder (§10, §13.3) — the two-pass active/missing execution
// sequence, mirroring internal/cli/sync_helpers.go's syncWithStackScoped
// exactly: one full topo-ordered pass over active worktrees, then a second
// full topo-ordered pass over archived/missing ones.
// ============================================================================

// OrderedExecution is one selected entry's place in the run, annotated with
// everything RebaseStrategy needs to pick its pass-dependent argv shape.
type OrderedExecution struct {
	Entry           StackEntry
	Pass            int    // 1 (active worktree, implicit HEAD) | 2 (archived/missing, explicit branch)
	Materialization string // materialized | archived-metadata | worktree-missing | prunable
	SkipAnchor      bool   // role == anchor && propagation == local-only (§10)
	UpdatedByRef    bool   // this row's ref already moves transitively via an earlier pass-1 --update-refs rebase
}

// ExecutionOrder resolves the run's ordered execution sequence over the
// caller's own TopoSort result (order), restricted to the selection. mode ==
// ModeCheckout always yields every selected entry as Pass 1 (checkout has no
// separate archived/missing worktree concept — the transaction's own Plan
// order already reflects it, internal/checkout_sync.go's BuildCheckoutPlan).
func ExecutionOrder(mode WorkspaceMode, stack Stack, order []StackEntry, layout RebasePlanLayout, sel SyncSelection) []OrderedExecution {
	scoped := sel.Policy.Scoped()
	localOnly := sel.Policy.Propagation == SyncPropagationLocalOnly

	out := make([]OrderedExecution, 0, len(order))
	idx := make(map[string]int, len(order))
	for _, entry := range order {
		if !sel.Names[entry.Name] {
			continue
		}
		materialization := classifyMaterialization(mode, entry, layout)
		pass := 1
		if mode == ModeExternal && materialization != "materialized" {
			pass = 2
		}
		role := sel.Role(entry.Name)
		idx[entry.Name] = len(out)
		out = append(out, OrderedExecution{
			Entry:           entry,
			Pass:            pass,
			Materialization: materialization,
			SkipAnchor:      role == SyncRoleAnchor && localOnly,
		})
	}

	// A pass-1, unscoped rebase always runs with --update-refs (§10, mirrored
	// from sync_helpers.go's unconditional rebaseArgs construction), which
	// carries every same-repo ancestor still "underneath" it in the replayed
	// range along for the ride — exactly the set markUpdatedAncestors marks
	// incrementally at runtime. A plan can compute the same set up front,
	// since every pass-1 row is assumed to succeed on the intended path.
	if mode == ModeExternal && !scoped {
		for i := range out {
			if out[i].Pass != 1 || out[i].SkipAnchor {
				continue
			}
			current := out[i].Entry
			for {
				parent := GetBranch(stack, current.Base)
				if parent.Name == "" || !SameStackRepo(parent.Repo, current.Repo) {
					break
				}
				if j, ok := idx[parent.Name]; ok && out[j].Pass != 1 {
					out[j].UpdatedByRef = true
				}
				current = parent
			}
		}
	}
	return out
}

// ============================================================================
// DestinationDeferred (§10) — the propagated-and-still-pending predicate.
// ============================================================================

// DestinationDeferred reports entries[].destination.deferred: true exactly
// when this is a propagated row whose configured parent is itself part of
// this run's execution set, so the final destination SHA depends on an
// outcome this plan cannot observe yet (the parent's own rebase has not run).
func DestinationDeferred(role string, parentName string, execution []OrderedExecution) bool {
	if role != string(SyncRolePropagated) || parentName == "" {
		return false
	}
	for _, oe := range execution {
		if oe.Entry.Name == parentName {
			return true
		}
	}
	return false
}

// ============================================================================
// ReplayUpstream (§5, §2.15 Group D) — the fourteen-member replay row.
// ============================================================================

// ReplayUpstreamInput is everything ReplayUpstream needs to resolve one
// entries[].replay row for one entry. Every boolean names a precondition in
// firstReplayHazard's own rank order (§5); the four candidate probes
// (internal/rebase_plan_probe.go) run only once every precondition clears.
type ReplayUpstreamInput struct {
	Skipped bool // this row's own strategy is one of the four skipped-* tokens ⇒ not-executed

	RebaseMergesConfigValid bool // repositories[].config.rebase_merges.Status == "valid" for this context
	RebaseMergesRecreates   bool // that config value, decoded, says merges are recreated along this arm

	ContextUsable bool   // the execution context resolved (repo available)
	ExecDir       string // where the four candidate probes run; "" iff !ContextUsable

	HeadUsable bool // entries[].head.state == "present" (branch resolves to a SHA)
	GitBranch  string

	BaseUnset      bool // PlanEntryBase.Kind == "none"
	BaseRefMissing bool // Base resolved to a string but does not exist as a ref
	UpstreamRef    string
	UpstreamSHA    string // "" iff BaseRefMissing

	Deferred bool // DestinationDeferred's verdict for this row

	CutoffUsage string // "used" | "not_used" (entries[].cutoff.usage)
	CutoffState string // absent | present | unresolvable; "" when CutoffUsage == "not_used"
	// CutoffResolvedSHA is entries[].cutoff.resolved_sha — the peeled recorded
	// cutoff. It is "" unless CutoffState == "present".
	CutoffResolvedSHA string
}

// effectiveUpstream is §10.1 rule 1: where a recorded cutoff is present AND
// this arm really hands it to Git (cutoff.usage == "used"), the replay's
// source boundary is that cutoff in BOTH workspace modes — never the
// destination. Every other row falls back to the base ref's own current
// resolution. The returned pair is (upstream_ref, upstream_sha); the ref is
// the cutoff for an `onto` arm and base.ref for a plain one (§4.2).
func effectiveUpstream(in ReplayUpstreamInput) (ref, sha string) {
	if in.CutoffUsage == "used" && in.CutoffState == "present" && in.CutoffResolvedSHA != "" {
		return in.CutoffResolvedSHA, in.CutoffResolvedSHA
	}
	return in.UpstreamRef, in.UpstreamSHA
}

// ReplayUpstreamResult is ReplayUpstream's total output: the fourteen
// entries[].replay members.
type ReplayUpstreamResult struct {
	UpstreamRef            *string
	UpstreamSHA            *string
	UpstreamProvenance     string
	Determinacy            string
	Reason                 *string
	Range                  *string
	CandidateCount         *int
	FirstCandidate         *PlanReplayCandidate
	Commits                []string
	CommitsListed          *int
	CommitsTruncated       *bool
	CandidateDigest        *string
	MayDropPatchEquivalent *bool
	MayDropBecomesEmpty    bool // always true (§5)
}

// firstReplayHazard is the ONE §5 eleven-token precedence ladder: the first
// hazard that applies, checked in rank order, decides both determinacy and
// reason. Nothing else in this tree re-implements this order.
func firstReplayHazard(in ReplayUpstreamInput) (determinacy string, reason *string) {
	tok := func(s string) *string { return &s }
	switch {
	case in.Skipped:
		return "not-applicable", tok("not-executed")
	case in.RebaseMergesConfigValid && in.RebaseMergesRecreates:
		return "unknown", tok("merge-recreation")
	case !in.ContextUsable:
		return "unknown", tok("repo-unavailable")
	case !in.HeadUsable:
		return "unknown", tok("head-ref-missing")
	case in.BaseUnset:
		return "unknown", tok("base-unset")
	case in.BaseRefMissing:
		return "unknown", tok("base-ref-missing")
	case in.CutoffUsage == "used" && in.CutoffState == "unresolvable":
		return "unknown", tok("cutoff-unresolvable")
	case in.Deferred:
		return "unknown", tok("upstream-deferred")
	case in.CutoffUsage == "used" && in.CutoffState == "absent":
		return "snapshot", tok("no-recorded-cutoff")
	case in.CutoffUsage == "not_used" && in.CutoffState == "present":
		return "snapshot", tok("cutoff-not-used-on-arm")
	default:
		return "exact", nil
	}
}

// upstreamProvenanceFor derives replay.upstream_provenance from the same
// hazard reason firstReplayHazard already computed (§5's four-value domain):
// a recorded cutoff actually consumed, a live read of the base ref standing
// in for one, a deferred upstream, or unknown for every other hazard.
func upstreamProvenanceFor(reason *string, cutoffUsage string) string {
	if reason == nil {
		if cutoffUsage == "used" {
			return "recorded-cutoff"
		}
		return "base-ref-snapshot"
	}
	switch *reason {
	case "upstream-deferred":
		return "base-ref-deferred"
	case "no-recorded-cutoff", "cutoff-not-used-on-arm":
		return "base-ref-snapshot"
	default:
		return "unknown"
	}
}

// ReplayUpstream resolves one entries[].replay row (§5). determinacy ==
// "exact" or "snapshot" both attempt the four candidate probes — a snapshot
// is still a real, best-effort candidate list, just not cutoff-anchored;
// every other determinacy publishes null candidate data outright. A
// candidate-probe failure encountered after committing to exact/snapshot
// downgrades this row to (unknown, probe-failed) rather than propagating a
// Go error: one entry's transient probe failure must never abort the whole
// plan build.
func ReplayUpstream(in ReplayUpstreamInput) ReplayUpstreamResult {
	determinacy, reason := firstReplayHazard(in)
	result := ReplayUpstreamResult{Determinacy: determinacy, Reason: reason, MayDropBecomesEmpty: true}
	result.UpstreamProvenance = upstreamProvenanceFor(reason, in.CutoffUsage)

	if determinacy != "exact" && determinacy != "snapshot" {
		return result
	}
	upstreamRef, upstreamSHA := effectiveUpstream(in)
	if upstreamRef != "" {
		ref := upstreamRef
		result.UpstreamRef = &ref
	}
	if upstreamSHA != "" {
		sha := upstreamSHA
		result.UpstreamSHA = &sha
	}

	// Every candidate probe takes the FULL upstream SHA as its boundary
	// operand (§5 rule 1), never a ref name or an abbreviation: a ref would
	// re-resolve inside Git and could name a different commit than the one
	// this row published.
	count, err := ProbeCandidateCount(in.ExecDir, upstreamSHA, in.GitBranch)
	if err != nil {
		return downgradeReplayToProbeFailed(result)
	}
	first, err := ProbeFirstCandidate(in.ExecDir, upstreamSHA, in.GitBranch, count)
	if err != nil {
		return downgradeReplayToProbeFailed(result)
	}
	stream, err := ProbeCandidateStream(in.ExecDir, upstreamSHA, in.GitBranch)
	if err != nil {
		return downgradeReplayToProbeFailed(result)
	}
	mayDrop, err := ProbeMayDropPatchEquivalent(in.ExecDir, upstreamSHA, in.GitBranch)
	if err != nil {
		return downgradeReplayToProbeFailed(result)
	}

	rng := upstreamSHA + ".." + in.GitBranch
	result.Range = &rng
	result.CandidateCount = &count
	result.FirstCandidate = first
	result.Commits = stream.Commits
	if result.Commits == nil {
		result.Commits = []string{}
	}
	listed := stream.Listed
	result.CommitsListed = &listed
	truncated := stream.Truncated
	result.CommitsTruncated = &truncated
	digest := stream.CandidateDigest
	result.CandidateDigest = &digest
	result.MayDropPatchEquivalent = mayDrop
	return result
}

// downgradeReplayToProbeFailed collapses an exact/snapshot row that failed a
// candidate probe partway through into the rank-2f (unknown, probe-failed)
// total value, discarding any partial candidate data already attached.
func downgradeReplayToProbeFailed(result ReplayUpstreamResult) ReplayUpstreamResult {
	reason := "probe-failed"
	return ReplayUpstreamResult{
		UpstreamRef:         result.UpstreamRef,
		UpstreamSHA:         result.UpstreamSHA,
		UpstreamProvenance:  "unknown",
		Determinacy:         "unknown",
		Reason:              &reason,
		MayDropBecomesEmpty: true,
	}
}

// ============================================================================
// RemainingRebaseEntries (§13.3) — the continuation-aware selection filter.
// ============================================================================

// RemainingEntriesState is the "state" RemainingRebaseEntries reads to tell
// already-completed selection members apart from ones a continuation still
// owes. It is this file's own carrier, not a redeclaration of either
// producer type in internal/rebase_plan_state.go: a single positional
// parameter must serve both workspace modes, and ExternalPlanState /
// CheckoutPlanState are distinct, mutually exclusive types neither of which
// alone can.
type RemainingEntriesState struct {
	Mode     WorkspaceMode
	External ExternalPlanState
	Checkout CheckoutPlanState
}

// RemainingRebaseEntries is §13.3: on a fresh run every selected name is
// remaining, in selection order (never re-sorted — §4.8 keeps several
// producer-ordered arrays as-is, and the executors consume Remaining as a
// sequence, not a set); on --continue, the already-recorded completion state
// removes whatever it names. layout and order are accepted to match the
// caller's fixed five-parameter signature; this implementation derives
// completion from state's own artefacts rather than the filesystem or the
// raw topo order, both already folded into sel.
func RemainingRebaseEntries(route string, layout RebasePlanLayout, state RemainingEntriesState, order []StackEntry, sel SyncSelection) []string {
	remaining := make([]string, 0, len(sel.Entries))
	for _, e := range sel.Entries {
		remaining = append(remaining, e.Name)
	}

	var done map[string]bool
	switch state.Mode {
	case ModeCheckout:
		done = doneNamesForCheckout(state.Checkout)
	default:
		done = doneNamesForRoute(route, state.External)
	}
	if len(done) == 0 {
		return remaining
	}
	out := make([]string, 0, len(remaining))
	for _, name := range remaining {
		if !done[name] {
			out = append(out, name)
		}
	}
	return out
}

// doneNamesForCheckout reads the persisted transaction's own progress
// cursor (§12.5a): every plan row strictly before CurrentIndex has already
// been rebased.
func doneNamesForCheckout(state CheckoutPlanState) map[string]bool {
	if !state.Applicable {
		return nil
	}
	tx := state.Files.CheckoutTransaction
	if tx.Presence != PlanPresenceReadable || tx.Transaction == nil {
		return nil
	}
	plan := tx.Transaction.Plan
	cutoff := tx.Transaction.CurrentIndex
	if cutoff > len(plan) {
		cutoff = len(plan)
	}
	if cutoff <= 0 {
		return nil
	}
	done := make(map[string]bool, cutoff)
	for i := 0; i < cutoff; i++ {
		name := plan[i].Name
		if name == "" {
			name = plan[i].Branch
		}
		done[name] = true
	}
	return done
}

// doneNamesForRoute selects the one file shape route actually persists
// completion into (§12.5a): the new-mode v2 payload's own Completed list on
// RouteNewMode, the legacy sentinel's Completed list otherwise.
func doneNamesForRoute(route string, state ExternalPlanState) map[string]bool {
	if !state.Applicable {
		return nil
	}
	var names []string
	if route == RouteNewMode {
		if p := state.Files.Payload; p.Presence == PlanPresenceReadable && p.Payload != nil {
			names = p.Payload.Completed
		}
	} else {
		if l := state.Files.LegacyState; l.Presence == PlanPresenceReadable && l.State != nil {
			names = l.State.Completed
		}
	}
	if len(names) == 0 {
		return nil
	}
	done := make(map[string]bool, len(names))
	for _, n := range names {
		done[n] = true
	}
	return done
}

// ============================================================================
// RebaseStrategy (§2.15 Group C) — the nine-token strategy totality.
// ============================================================================

// RebaseStrategyInput is everything RebaseStrategy needs to decide one
// entries[] row's Group C members. Every field is already resolved by the
// caller (ResolveSyncBase, ExecutionOrder, EntryContexts, GetBranchSHA, the
// config probes) — RebaseStrategy performs no I/O of its own.
type RebaseStrategyInput struct {
	Mode WorkspaceMode

	// Skip is "" when a real strategy must be computed; otherwise it is one
	// of the four skipped-* tokens, decided by the caller from
	// OrderedExecution/ResolveSyncBase facts (skipped-no-base, skipped-
	// anchor, skipped-archived, skipped-updated-ref).
	Skip string

	// Pass is 1 (active worktree, implicit HEAD, --update-refs-eligible) or
	// 2 (archived/missing worktree, explicit branch argument). Ignored for
	// Mode == ModeCheckout.
	Pass int

	GitBranch      string
	BaseResolved   bool
	Base           string
	LastBaseSHA    string
	CurrentBaseSHA string // "" when unresolvable

	// HeadUsable is entries[].head.state == "present" (§9.3's "missing/
	// unresolvable head" row). It only changes ModeCheckout's outcome —
	// `BuildCheckoutPlan`'s own gitResolveRef fails eagerly, so a plan
	// mirrors that with `unknown` — external still computes its normal arm
	// and lets the caller attach the blocking head-ref-missing blocker
	// instead (§9.3).
	HeadUsable bool

	Scoped bool

	// BaseMayMoveBeforeExecution is true exactly when Base names a
	// remote-tracking ref this run's own fetch policy could still move
	// between plan and execution — the condition that turns an otherwise
	// deterministic onto/plain choice into `conditional` (§10, §11.3).
	BaseMayMoveBeforeExecution bool

	ContextUsable bool

	// CheckoutOnto is the checkout-only onto/plain predicate, already
	// resolved by the caller from one CheckoutPlanEntry exactly as
	// internal/checkout_sync.go's doRebase computes it:
	// entry.LastBaseSHA != "" && entry.LastBaseSHA != entry.NewBaseSHA.
	CheckoutOnto bool

	// Effective-backend inputs (§11.7's total seven-row table, §16 rule 3a).
	//
	// BackendConfigReadable is row 2's own input: false exactly when the
	// ordered config inventory for this EXECUTION CONTEXT could not be read,
	// which makes effective_backend null whatever else is known.
	// BackendConfigValue/BackendConfigValid carry the effective
	// `rebase.backend` value and whether its final occurrence parsed;
	// an absent or invalid value takes row 5.
	BackendConfigReadable bool
	BackendConfigValue    string
	BackendConfigValid    bool

	// CapDefaultBackendMerge is TRI-STATE, because rows 3-5, row 6 and row 7
	// are three different answers: Known false means the host predates 2.26
	// (row 6, apply); Known true opens rows 3-5; !Known is row 7 (null),
	// an unparseable or unobtainable `git --version`.
	CapDefaultBackendMerge      bool
	CapDefaultBackendMergeKnown bool
}

// RebaseStrategyResult is RebaseStrategy's total output.
type RebaseStrategyResult struct {
	Strategy         string
	Condition        *string
	Argv             []string     // nullable — [] for every skipped-* row, null for conditional/unknown
	ArgvAlternatives *[2][]string // non-nil only for conditional
	EffectiveBackend *string      // nil unless a strategy actually runs
}

// rebaseArgv freezes the exact tokenized argv the shipped executors run:
// internal/cli/sync_helpers.go's two rebase-arg-building blocks (external),
// internal/checkout_sync.go's gitRebaseOnto/gitPlainRebase (checkout). This
// is the one place either could drift from what RebaseStrategy publishes.
func rebaseArgv(mode WorkspaceMode, base, branch, lastBaseSHA string, onto, scoped bool) []string {
	if mode == ModeCheckout {
		if onto {
			return []string{"rebase", "--no-fork-point", "--onto", base, lastBaseSHA}
		}
		return []string{"rebase", "--no-fork-point", base}
	}
	if branch != "" {
		// external pass 2: explicit branch, never --update-refs, never --onto.
		return []string{"rebase", base, branch}
	}
	// external pass 1: implicit HEAD.
	if scoped {
		if onto {
			return []string{"rebase", "--onto", base, lastBaseSHA}
		}
		return []string{"rebase", base}
	}
	if onto {
		return []string{"rebase", "--update-refs", "--onto", base, lastBaseSHA}
	}
	return []string{"rebase", "--update-refs", base}
}

// mergeForcingArgvOptions is §11.7 row 1's closed token list: the options
// `git rebase` itself refuses under the apply backend, so an argv carrying
// any one of them runs under the merge backend whatever the configuration
// says. `--keep-base` is deliberately ABSENT: it is not in git rebase's
// merge-backend incompatibility list and is itself incompatible with
// `--onto`, which every tws `onto` argv carries. `--root` forces merge only
// WITHOUT `--onto`, which is why it is handled separately below rather than
// listed here.
var mergeForcingArgvOptions = []string{
	"--update-refs", "--rebase-merges", "-r", "--interactive", "-i",
	"--exec", "-x", "--autosquash", "--merge", "-m",
	"--strategy", "--strategy-option", "-X",
	"--no-keep-empty", "--reapply-cherry-picks", "--no-reapply-cherry-picks",
	"--trailer",
}

// argvForcesMergeBackend is §11.7 row 1's predicate over the argv THIS ROW
// PUBLISHES. It matches exact tokens plus the two `=`-taking spellings
// (`--empty=`, and the `--exec=`/`--strategy=` families), so a row whose
// argv carries none of them falls through to the configuration rows. Only
// the `--update-refs` token is reachable from a tws-issued argv in v1 (the
// external `scope=all` arm's materialized pass-1 rows); the rest are listed
// for totality, so a later feature that builds one is classified correctly
// rather than silently misclassified.
func argvForcesMergeBackend(argv []string) bool {
	for _, tok := range argv {
		if strings.HasPrefix(tok, "--empty=") {
			return true
		}
		for _, opt := range mergeForcingArgvOptions {
			if tok == opt || (strings.HasPrefix(opt, "--") && strings.HasPrefix(tok, opt+"=")) {
				return true
			}
		}
	}
	// `--root` forces merge only when no `--onto` accompanies it.
	if argvHasFlag(argv, "--root") && !argvHasFlag(argv, "--onto") {
		return true
	}
	return false
}

// publishedArgv is the argv a row really publishes: the single argv for a
// determinate strategy, and the FIRST alternative for a `conditional` row,
// whose two alternatives always agree on whether they carry a merge-forcing
// option (both unscoped pass-1 alternatives carry --update-refs; neither
// scoped alternative does).
func publishedArgv(r RebaseStrategyResult) []string {
	if r.Argv != nil {
		return r.Argv
	}
	if r.ArgvAlternatives != nil {
		return r.ArgvAlternatives[0]
	}
	return nil
}

// effectiveBackendFor is §11.7's TOTAL seven-row table, evaluated top-down,
// first match wins. It answers exactly one question: which rebase backend
// will run the command THIS ROW publishes?
//
//  1. the published argv carries a merge-forcing option           -> merge
//  2. this execution context's ordered config inventory was unread -> null
//  3. effective rebase.backend == "apply", 2.26 capability true    -> apply
//  4. effective rebase.backend == "merge", 2.26 capability true    -> merge
//  5. rebase.backend absent/invalid,       2.26 capability true    -> merge
//  6. the 2.26 capability is known FALSE                           -> apply
//  7. the 2.26 capability is UNKNOWN                               -> null
//
// Configuration NEVER forces the merge backend: `rebase.updateRefs` and
// `rebase.rebaseMerges` are not inputs to this table in any cell, because
// Git selects the merge backend from the command line it is given and from
// `rebase.backend` alone. Publishing `merge` for a configured
// `rebase.updateRefs = true` under `rebase.backend = apply` would invert the
// two rules this value exists to gate.
func effectiveBackendFor(in RebaseStrategyInput, argv []string) *string {
	merge, apply := "merge", "apply"
	if argvForcesMergeBackend(argv) {
		return &merge
	}
	if !in.BackendConfigReadable {
		return nil
	}
	if !in.CapDefaultBackendMergeKnown {
		return nil
	}
	if !in.CapDefaultBackendMerge {
		return &apply
	}
	if in.BackendConfigValid {
		switch in.BackendConfigValue {
		case "apply":
			return &apply
		case "merge":
			return &merge
		}
	}
	return &merge
}

// RebaseStrategy is the total nine-token strategy decision (§2.15 Group C):
// skipped-no-base | skipped-anchor | skipped-archived | skipped-updated-ref |
// onto | plain | plain-explicit-branch | conditional | unknown.
func RebaseStrategy(in RebaseStrategyInput) RebaseStrategyResult {
	if in.Skip != "" {
		return RebaseStrategyResult{Strategy: in.Skip, Argv: []string{}}
	}
	if !in.ContextUsable {
		return RebaseStrategyResult{Strategy: "unknown"}
	}
	// §9.3's "missing/unresolvable head" row: only checkout turns this into
	// `unknown` (BuildCheckoutPlan's own gitResolveRef fails eagerly);
	// external keeps computing its normal arm below and the caller attaches
	// the blocking head-ref-missing blocker separately.
	if in.Mode == ModeCheckout && !in.HeadUsable {
		return RebaseStrategyResult{Strategy: "unknown"}
	}
	if !in.BaseResolved {
		// §9.3 row "unset base": checkout skips (non-blocking); external
		// keeps Base == "" and falls through to compute plain / plain-
		// explicit-branch over the quoted empty token, blocking base-unset
		// is the caller's job (never this function's).
		if in.Mode == ModeCheckout {
			return RebaseStrategyResult{Strategy: "skipped-no-base", Argv: []string{}}
		}
	}
	if in.Mode == ModeCheckout && in.BaseResolved && in.CurrentBaseSHA == "" {
		// §9.3 row "materialized/present cutoff/unresolvable destination":
		// checkout fails eagerly (`unknown`); external still returns `plain`
		// below (onto's own predicate already requires CurrentBaseSHA != "")
		// and lets Git itself fail at execution time.
		return RebaseStrategyResult{Strategy: "unknown"}
	}

	if in.Mode == ModeCheckout {
		strategy := "plain"
		ontoOperand := in.Base
		if in.CheckoutOnto {
			strategy = "onto"
			// §9.3's frozen checkout shape is
			// `rebase --no-fork-point --onto <NewBaseSHA> <LastBaseSHA>`:
			// internal/checkout_sync.go's executor calls
			// gitRebaseOnto(opts.RepoDir, entry.NewBaseSHA, entry.LastBaseSHA),
			// so the published --onto operand is the resolved destination
			// SHA, never the base ref name. The plain arm keeps entry.Base
			// verbatim, exactly as gitPlainRebase passes it.
			ontoOperand = in.CurrentBaseSHA
		}
		argv := rebaseArgv(ModeCheckout, ontoOperand, "", in.LastBaseSHA, in.CheckoutOnto, false)
		return RebaseStrategyResult{Strategy: strategy, Argv: argv, EffectiveBackend: effectiveBackendFor(in, argv)}
	}

	if in.Pass == 2 {
		argv := rebaseArgv(ModeExternal, in.Base, in.GitBranch, "", false, false)
		return RebaseStrategyResult{Strategy: "plain-explicit-branch", Argv: argv, EffectiveBackend: effectiveBackendFor(in, argv)}
	}

	// Pass 1: the onto/plain choice depends on comparing LastBaseSHA against
	// the base's current position (§10, mirrored from sync_helpers.go's
	// rebaseArgs construction).
	onto := in.LastBaseSHA != "" && in.CurrentBaseSHA != "" && in.LastBaseSHA != in.CurrentBaseSHA
	if !onto {
		argv := rebaseArgv(ModeExternal, in.Base, "", in.LastBaseSHA, false, in.Scoped)
		return RebaseStrategyResult{Strategy: "plain", Argv: argv, EffectiveBackend: effectiveBackendFor(in, argv)}
	}
	ontoArgv := rebaseArgv(ModeExternal, in.Base, "", in.LastBaseSHA, true, in.Scoped)
	if in.BaseMayMoveBeforeExecution {
		plainArgv := rebaseArgv(ModeExternal, in.Base, "", in.LastBaseSHA, false, in.Scoped)
		alts := [2][]string{ontoArgv, plainArgv}
		condition := "base-may-move-before-execution"
		// A conditional row publishes two argvs; both alternatives of a tws
		// argv agree on whether they carry a merge-forcing option (the
		// unscoped pass-1 pair both carry --update-refs, the scoped pair
		// neither), so the row's backend is that shared answer.
		return RebaseStrategyResult{Strategy: "conditional", Condition: &condition, ArgvAlternatives: &alts, EffectiveBackend: effectiveBackendFor(in, ontoArgv)}
	}
	return RebaseStrategyResult{Strategy: "onto", Argv: ontoArgv, EffectiveBackend: effectiveBackendFor(in, ontoArgv)}
}

// ============================================================================
// GateBlockers, GateControlledTokens (§4.6, §7.1, §7.5) — the
// controlled-path gate ladder's projection into blockers[] and
// guard.execute_blocked_by[].
// ============================================================================

// PlanGateVerdict is one controlled-path gate's own verdict for one
// candidate row: whether it fired, which RefusalKind names it under §7.1,
// which ControlledPathBlocker token owns it under §4.6, the entry it
// concerns (nil for a document-level gate), a sanitized detail sentence, and
// whether the described route's own ladder actually consults this gate at
// all. §4.6 fixes guard.execute_blocked_by[] membership by ownership, never
// by consequence, and blockers[] membership by whether the described route's
// own ladder would refuse on it — a verdict can be Fired without
// OnGuardedRoute (a route that never reaches this precondition), and
// GateBlockers/GateControlledTokens apply exactly that distinction.
type PlanGateVerdict struct {
	Fired          bool
	Kind           RefusalKind
	Controlled     ControlledPathBlocker
	Entry          *string
	Detail         string
	OnGuardedRoute bool
}

// GateBlockers projects the fired, on-route verdicts into blockers[] rows:
// a verdict contributes a row exactly where the route's own ladder would
// actually refuse on it, never merely because the underlying condition is
// true. Sorting/deduplication is SelectPrimaryRefusal's job, not this one's.
func GateBlockers(verdicts []PlanGateVerdict) []PlanBlocker {
	out := make([]PlanBlocker, 0, len(verdicts))
	for _, v := range verdicts {
		if !v.Fired || !v.OnGuardedRoute {
			continue
		}
		out = append(out, PlanBlocker{Kind: v.Kind, Entry: v.Entry, Detail: v.Detail})
	}
	return out
}

// GateControlledTokens projects the fired verdicts into
// guard.execute_blocked_by[]: every fired gate contributes its
// ControlledPathBlocker token regardless of whether this route's own ladder
// consults it, because the five controlled-path tokens are non-waivable
// preconditions the guard owns outright. The result is sorted and
// deduplicated in the canonical ControlledPathBlockers order (§4.8), never
// nil.
func GateControlledTokens(verdicts []PlanGateVerdict) []ControlledPathBlocker {
	fired := make(map[ControlledPathBlocker]bool, len(verdicts))
	for _, v := range verdicts {
		if v.Fired {
			fired[v.Controlled] = true
		}
	}
	out := make([]ControlledPathBlocker, 0, len(fired))
	for _, tok := range ControlledPathBlockers {
		if fired[tok] {
			out = append(out, tok)
		}
	}
	return out
}

// ============================================================================
// The six push producers (§14.1a) — ResolvePushContext, MeasurePushRemoteFacts,
// RefreshPushTrackingRefs, PushContextRefreshed, ResolvePushLease and
// PushTargets. The first five build up one PlanPushFacts value (the ONE
// push-fact carrier, RebasePlanRequest.PushFacts); PushTargets is the one of
// the six BuildRebasePlan calls directly, over the resulting facts.
//
// PlanPushFacts.Materialization and .Remotes are both keyed by repo token
// (StackEntry.Repo / PlanPushTarget.Repo — "" names the default repository,
// exactly as it does throughout this package), a convention fixed here by
// this file as the sole implementer of the code that populates and reads
// both maps: no other file in this tree writes to either map.
// ============================================================================

// ResolvePushContext is producer 1 of 6: it resolves one push context's
// identity and its own remote-resolution ladder answer, mirroring the same
// head-branch/remote-name ladder ResolveFetchEffect's remote resolution
// already uses (internal/rebase_plan_probe.go), so push and fetch can never
// disagree about which remote a context targets.
func ResolvePushContext(dir, rootSource, materialization string, inv GitConfigInventory, caps GitCapabilities) (ctx PlanPushContext, identity PlanContextIdentity, remoteName string, err error) {
	identity, err = EstablishContextIdentity(dir, rootSource)
	if err != nil {
		return PlanPushContext{}, PlanContextIdentity{}, "", err
	}
	headBranch := ResolveHeadBranch(dir)
	remoteName = ResolveRemoteName(inv, headBranch, caps)
	ctx = PlanPushContext{
		ContextID:       &identity.ContextID,
		RepoRoot:        identity.RepoRoot,
		Source:          rootSource,
		Materialization: materialization,
	}
	return ctx, identity, remoteName, nil
}

// MeasurePushRemoteFacts is producer 2 of 6 (§14.1a phase one): the ordered
// fetch-refspec read for one context/remote pair, before any tracking-ref
// read. TrackingReadOK/TrackingRefs/FetchedThisRun stay at their zero values
// here — RefreshPushTrackingRefs is the only producer that ever sets them —
// so a caller that skips that second phase (no push intent, or a policy that
// never refreshes tracking refs) still gets a well-formed, honestly
// "not yet read" facts value.
func MeasurePushRemoteFacts(contextID *string, commonDir, remoteName string, inv GitConfigInventory, caps GitCapabilities) PlanPushRemoteFacts {
	facts := PlanPushRemoteFacts{
		ContextID:     contextID,
		CommonDir:     commonDir,
		RemoteName:    remoteName,
		TrackingPhase: "not-applicable",
	}
	// §14.1a rule 5a: MappingReadOK asserts that BOTH halves of the mapping
	// question were really answered — the context's identity was established
	// (a nil ContextID is exactly "it was not") and the ordered config
	// inventory this mapping is derived from was readable. Where either is
	// missing there is no mapping to report: the facts stay
	// {MappingReadOK: false, RemoteExists: false, FetchRefspecs: []}, which
	// is what puts the row in §14.2's `expectation: unknown` cell beside its
	// rank 5.9 `probe-failed` blocker, rather than in the null-OID `absent`
	// cell a "read and empty" answer would claim.
	//
	// The inventory is the caller's OWN already-held ordered read (§22.27a's
	// one-inventory-per-context budget): this producer never re-probes it.
	if contextID == nil || !inv.Available {
		facts.FetchRefspecs = []PlanRefspec{}
		return facts
	}
	remote, found := ResolveFetchRemote(inv, commonDir, remoteName, caps)
	facts.MappingReadOK = true
	facts.RemoteExists = found
	if found {
		facts.FetchRefspecs = remote.Refspecs
	} else {
		facts.FetchRefspecs = []PlanRefspec{}
	}
	return facts
}

// RefreshPushTrackingRefs is producer 3 of 6 (§14.1a rule 7): the ONE
// remote-tracking baseline read of this invocation, performed over the WHOLE
// PlanPushFacts value that MeasurePushRemoteFacts's phase-one reads produced,
// and placed immediately after this route's fetch decision has been carried
// out — after the fetch child on a fetching arm, at the plan point on a
// no-fetch, suppressed, refusing or continuation arm — and always BEFORE
// BuildRebasePlan, because the lease's expectation/ref/SHA are approval-tuple
// members (§8.3): a pre-fetch baseline would bind a token to refs this same
// invocation then moved.
//
// A value whose Applies is false is neither measured nor refreshed: it keeps
// Phase "not-applicable" and travels to the builder unchanged, at a cost of
// zero ref reads.
//
// Per context it stamps TrackingPhase from a three-value ladder, first match
// wins — `unread` when the inventory could not be read, else `post-fetch`
// when this invocation really attempted a fetch child, else `plan-point` —
// and sets FetchedThisRun from PushContextRefreshed conjoined with
// MappingReadOK && TrackingReadOK && TrackingPhase == "post-fetch", so an
// unread half can never be labelled fresh. A context whose ContextID is nil
// has no mapping and therefore no destination to baseline: it is visited like
// any other, reads NOTHING, and keeps TrackingReadOK false with TrackingPhase
// `unread` — rule 5a's already-declared unknown cell, never a second one.
func RefreshPushTrackingRefs(facts PlanPushFacts, fetched PlanFetchOutcome) PlanPushFacts {
	if !facts.Applies {
		return facts
	}
	phase := "plan-point"
	if fetched.Attempted {
		phase = "post-fetch"
	}
	refreshed := make(map[string]PlanPushRemoteFacts, len(facts.Remotes))
	for token, rf := range facts.Remotes {
		if rf.ContextID == nil {
			rf.TrackingReadOK = false
			rf.TrackingRefs = nil
			rf.TrackingPhase = "unread"
			rf.FetchedThisRun = false
			refreshed[token] = rf
			continue
		}
		refs, err := ReadRemoteTrackingRefs(facts.Identities[*rf.ContextID].RepoRoot, rf.RemoteName)
		rf.TrackingReadOK = err == nil
		if err == nil {
			rf.TrackingRefs = refs
			rf.TrackingPhase = phase
		} else {
			rf.TrackingRefs = nil
			rf.TrackingPhase = "unread"
		}
		rf.FetchedThisRun = rf.MappingReadOK && rf.TrackingReadOK &&
			rf.TrackingPhase == "post-fetch" && PushContextRefreshed(fetched, rf.CommonDir)
		refreshed[token] = rf
	}
	facts.Remotes = refreshed
	facts.Phase = phase
	return facts
}

// PushContextRefreshed is the closed four-conjunct predicate behind
// FetchedThisRun (§14.1a rule 8). It joins on the CANONICAL COMMON DIR, not
// on context_id: a context_id hashes the canonical top level as well, so two
// linked worktrees of one repository carry two different ids while sharing
// one set of remote-tracking refs — and both are therefore refreshed by the
// single fetch §11.4's collapse rule performs.
//
// All four conjuncts are required of the SAME row: (i) a fetch child really
// ran there and exited 0; (ii) it resolved a remote and contacted it, since
// an unresolved-remote fetch writes no remote-tracking ref; (iii) one of the
// remotes it contacted is named `origin`, because the lease baseline is
// origin's tracking ref — a context whose branch.<name>.remote is `upstream`
// leaves origin exactly as stale as it was; (iv) the row's canonical common
// dir is this push context's.
func PushContextRefreshed(fetched PlanFetchOutcome, commonDir string) bool {
	if commonDir == "" {
		return false
	}
	want := canonicalPath(commonDir)
	for _, repo := range fetched.Repos {
		if !repo.Attempted || !repo.OK || repo.Effect == nil || !repo.Effect.Contacted {
			continue
		}
		if repo.ContextCommonDir == "" || canonicalPath(repo.ContextCommonDir) != want {
			continue
		}
		for _, r := range repo.Effect.Remotes {
			if r.Name == "origin" {
				return true
			}
		}
	}
	return false
}

// mapThroughRefspec maps ref through one fetch refspec's src pattern to its
// dst pattern, applying Git's single trailing "*" wildcard substitution. It
// reuses refMatchesPattern (internal/rebase_plan_probe.go) for the match test
// itself, so the two can never disagree about what "matches" means.
func mapThroughRefspec(rs PlanRefspec, ref string) (string, bool) {
	if !refMatchesPattern(rs.Src, ref) {
		return "", false
	}
	if !strings.HasSuffix(rs.Dst, "*") || !strings.HasSuffix(rs.Src, "*") {
		return rs.Dst, true
	}
	wildcard := strings.TrimPrefix(ref, strings.TrimSuffix(rs.Src, "*"))
	return strings.TrimSuffix(rs.Dst, "*") + wildcard, true
}

// ResolvePushLease is producer 5 of 6 (§2.9, §14.1a): the with-lease
// expectation derivation. mode is always "implicit-remote-tracking" (the
// only mode this feature ever publishes). It reproduces §14.2's five closed
// cells and no others:
//
//  1. positive mapping + mapped tracking ref present  -> sha,     mapped ref, value, fresh only post-fetch+fetched
//  2. positive mapping + mapped tracking ref absent   -> absent,  mapped ref, null,  fresh (the absence was read)
//  3. positive mapping + tracking inventory unread    -> absent,  mapped ref, null,  possibly-stale
//  4. mapping read, no positive mapping               -> absent,  null,       null,  fresh (it really maps nothing)
//  5. mapping unreadable (MappingReadOK: false)       -> unknown, null,       null,  possibly-stale
//
// `unknown` is reachable in EXACTLY cell 5 — an unread mapping, which always
// accompanies that context's rank 5.9 `probe-failed` blocker. A mapping that
// WAS read and matched nothing is `absent`, never `unknown`: publishing
// `unknown` there would report a real null-OID expectation as unmodelled.
// A matching negative refspec never removes the mapping (Git's refspec query
// ignores negative entries); it forces `possibly-stale` unconditionally,
// because no fetch of that configuration can ever refresh the baseline.
func ResolvePushLease(facts PlanPushRemoteFacts, gitBranch string) PlanLease {
	lease := PlanLease{Mode: "implicit-remote-tracking", Expectation: "unknown", ExpectedSHAFreshness: "possibly-stale"}
	if !facts.MappingReadOK {
		return lease // cell 5
	}
	src := "refs/heads/" + gitBranch

	negativeMatch := false
	var dst string
	mapped := false
	for _, rs := range facts.FetchRefspecs {
		if rs.Negative {
			if refMatchesPattern(rs.Src, src) {
				negativeMatch = true
			}
			continue
		}
		if !mapped {
			if d, ok := mapThroughRefspec(rs, src); ok {
				dst, mapped = d, true
			}
		}
	}

	switch {
	case !mapped:
		// Cell 4: the configuration really was read and it really maps
		// nothing, so Git expects the null OID and the read is this
		// invocation's own.
		lease.Expectation = "absent"
		lease.ExpectedSHAFreshness = "fresh"
	case !facts.TrackingReadOK:
		// Cell 3: Git's second step cannot be performed, so it falls back to
		// the null OID — but nothing was read, so nothing may be called
		// fresh.
		expectedRef := dst
		lease.ExpectedRef = &expectedRef
		lease.Expectation = "absent"
	default:
		expectedRef := dst
		lease.ExpectedRef = &expectedRef
		short := strings.TrimPrefix(dst, "refs/remotes/"+facts.RemoteName+"/")
		if sha, ok := facts.TrackingRefs[short]; ok {
			// Cell 1.
			sha := sha
			lease.Expectation, lease.ExpectedSHA = "sha", &sha
			if facts.TrackingPhase == "post-fetch" && facts.FetchedThisRun {
				lease.ExpectedSHAFreshness = "fresh"
			}
		} else {
			// Cell 2: the absence itself was read by this invocation, after
			// its own fetch decision was carried out.
			lease.Expectation = "absent"
			lease.ExpectedSHAFreshness = "fresh"
		}
	}

	if negativeMatch {
		lease.ExpectedSHAFreshness = "possibly-stale"
	}
	return lease
}

// PushTargets is producer 6 of 6 (§14.1a): the ordered push.targets[]
// projection over the run's own remaining, not-yet-pushed entries. It is the
// one push producer BuildRebasePlan calls directly; the other five feed
// req.Facts before BuildRebasePlan ever runs.
func PushTargets(req PlanPushRequest) []PlanPushTarget {
	if !req.Intent {
		return []PlanPushTarget{}
	}
	remainingSet := make(map[string]bool, len(req.Remaining))
	for _, n := range req.Remaining {
		remainingSet[n] = true
	}

	out := make([]PlanPushTarget, 0, len(req.Selection.Entries))
	for _, e := range req.Selection.Entries {
		if !remainingSet[e.Name] || req.AlreadyPushed[e.Name] {
			continue
		}
		repoToken := e.Repo
		remoteFacts := req.Facts.Remotes[repoToken]
		var contextID, repoRoot *string
		if remoteFacts.ContextID != nil {
			if identity, ok := req.Facts.Identities[*remoteFacts.ContextID]; ok {
				cid, root := identity.ContextID, identity.RepoRoot
				contextID, repoRoot = &cid, &root
			}
		}
		target := PlanPushTarget{
			Repo:            repoToken,
			ContextID:       contextID,
			RepoRoot:        repoRoot,
			Materialization: req.Facts.Materialization[repoToken],
			GitBranch:       e.GitBranch,
			Remote:          "origin",
			Ref:             "refs/heads/" + e.GitBranch,
			Force:           "with-lease",
			Lease:           ResolvePushLease(remoteFacts, e.GitBranch),
			Scope:           req.Scope,
		}
		if req.Mode == ModeCheckout {
			// §2.8 row 1: push.targets[].repo is "" on every checkout-mode row.
			target.Repo = ""
		}
		out = append(out, target)
	}
	sort.SliceStable(out, func(i, j int) bool {
		a, b := out[i], out[j]
		if (a.ContextID == nil) != (b.ContextID == nil) {
			return a.ContextID == nil
		}
		if a.ContextID != nil && *a.ContextID != *b.ContextID {
			return *a.ContextID < *b.ContextID
		}
		return a.GitBranch < b.GitBranch
	})
	return out
}

// ============================================================================
// SelectPrimaryRefusal (§7.1, §7.2) — the SOLE precedence + collapse
// implementation. Nothing else in this tree re-implements it.
// ============================================================================

// refusalRank is RefusalKinds' own index, computed once so
// SelectPrimaryRefusal's comparisons are O(1) rather than a linear scan per
// blocker.
var refusalRank = buildRefusalRank()

func buildRefusalRank() map[RefusalKind]int {
	m := make(map[RefusalKind]int, len(RefusalKinds))
	for i, k := range RefusalKinds {
		m[k] = i
	}
	return m
}

// sortAndDedupBlockers applies §4.8's blockers[] rule: sort by (rank, entry
// nil-first, sanitized detail), then collapse exact-tuple duplicates. It
// never mutates its argument's backing array and never returns nil.
func sortAndDedupBlockers(blockers []PlanBlocker) []PlanBlocker {
	cp := make([]PlanBlocker, len(blockers))
	copy(cp, blockers)
	sort.SliceStable(cp, func(i, j int) bool {
		a, b := cp[i], cp[j]
		if ra, rb := refusalRank[a.Kind], refusalRank[b.Kind]; ra != rb {
			return ra < rb
		}
		if (a.Entry == nil) != (b.Entry == nil) {
			return a.Entry == nil
		}
		if a.Entry != nil && b.Entry != nil && *a.Entry != *b.Entry {
			return *a.Entry < *b.Entry
		}
		return a.Detail < b.Detail
	})
	out := make([]PlanBlocker, 0, len(cp))
	for i, b := range cp {
		if i > 0 {
			p := cp[i-1]
			if p.Kind == b.Kind && blockerEntryEqual(p.Entry, b.Entry) && p.Detail == b.Detail {
				continue
			}
		}
		out = append(out, b)
	}
	return out
}

// blockerEntryEqual compares two blockers[].entry values, both of which are
// nil exactly for document-level facts.
func blockerEntryEqual(a, b *string) bool {
	if a == nil || b == nil {
		return a == b
	}
	return *a == *b
}

// SelectPrimaryRefusal is the SOLE implementation of §7.1 precedence and §7.2
// collapse. It returns the single highest-precedence kind among blockers —
// the zero value when blockers is empty — and the exact-tuple-deduplicated,
// §4.8-ordered blockers slice every caller must publish verbatim as
// RebasePlan.Blockers.
func SelectPrimaryRefusal(blockers []PlanBlocker) (kind RefusalKind, ordered []PlanBlocker) {
	ordered = sortAndDedupBlockers(blockers)
	if len(ordered) == 0 {
		return "", ordered
	}
	return ordered[0].Kind, ordered
}

package internal

import (
	"errors"
	"fmt"
	"regexp"
	"sort"
	"strings"
)

// ============================================================================
// Destination and cutoff resolution (§4.1–§4.3c, §5.1–§5.3)
//
// Every probe in this file goes through runReparentGit, so every argv it
// emits selects its directory with exec.Cmd.Dir and never with `git -C`.
// reparentIsAncestor reproduces mergeBaseIsAncestor's exit-0/exit-1/error
// trichotomy for exactly that reason; mergeBaseIsAncestor itself stays
// untouched with every existing caller and is cited as the pattern only.
//
// One deliberate exception is recorded here rather than hidden: §4.3c
// requires the agreement adapter to call the shipped ResolveSyncBase
// UNMODIFIED, and that function reaches DefaultBranchIn, which does emit a
// `-C` argv. That argv belongs to the frozen shipped resolver the spec
// mandates consulting — the same way AC-031 scopes the frozen
// ancestryMergeBase out of this feature's boundary — and never to a
// reparent-emitted rebase, ref-transaction or push argv. Its answer cannot
// change the verdict either: §4.3b stores a full ref or a full OID, and
// neither can ever equal a short default-branch name, so the origin/<default>
// rewrite has nothing to rewrite.
// ============================================================================

// reparentHexToken is §4.3 step 2's candidate-object-id shape. Recognition is
// case-insensitive; the canonical form this feature stores and compares is
// always lowercase.
var reparentHexToken = regexp.MustCompile(`^[0-9a-fA-F]{4,64}$`)

// reparentPseudoRefs is the closed set of tokens that are NOT a reparent
// destination and not a cutoff. A destination that moves whenever Git moves
// it is not a topology decision, which is also why the gitrevisions
// $GIT_DIR/<refname> rung is deliberately not enumerated below.
var reparentPseudoRefs = map[string]bool{
	"HEAD":             true,
	"FETCH_HEAD":       true,
	"ORIG_HEAD":        true,
	"MERGE_HEAD":       true,
	"CHERRY_PICK_HEAD": true,
	"REVERT_HEAD":      true,
	"REBASE_HEAD":      true,
	"AUTO_MERGE":       true,
	"BISECT_HEAD":      true,
}

// reparentPseudoRefDetail is the exact sentence a pseudo-ref token refuses
// with, for a destination and for a cutoff alike.
const reparentPseudoRefDetail = "pseudo refs are not a reparent destination; name a branch, a full ref, or an object id"

// ReparentDestination is ResolveReparentDestination's total output: the one
// source of the published destination facts. The plan, the executor, the CAS
// values, the metadata write and the post-condition all read this one result,
// so none of them can resolve the destination a second, differing way.
type ReparentDestination struct {
	// RequestedToken is exactly what the operator typed.
	RequestedToken string
	// StoredToken is the canonical token written to StackEntry.Base (§4.3b).
	// It is never the short token the operator typed.
	StoredToken string
	// Kind is stack-entry or literal-ref.
	Kind string
	// Ref is the full resolved ref; nil for an object-id destination.
	Ref *string
	// SHA is the pinned destination commit, canonical lowercase.
	SHA string
	// Repo is the normalized repo of a stack-entry parent; nil for a literal.
	Repo *string
	// Resolution is the §4.3b resolution token.
	Resolution string
	// Candidates carries every surviving enumerated candidate ref, sorted;
	// empty when the resolution was unambiguous.
	Candidates []string
	// EntryName is the destination stack entry's logical Name; "" for a
	// literal-ref destination.
	EntryName string
}

// Parent projects the destination into the document's new_parent block. The
// resolver-agreement verdict is filled in separately by the caller that runs
// §4.3c, so this projection never claims an agreement it did not check.
func (d ReparentDestination) Parent() ReparentParent {
	requested := d.RequestedToken
	stored := d.StoredToken
	sha := d.SHA
	parent := ReparentParent{
		RequestedToken: &requested,
		StoredToken:    &stored,
		Kind:           d.Kind,
		Ref:            d.Ref,
		SHA:            &sha,
		Repo:           d.Repo,
		Resolution:     d.Resolution,
		Candidates:     ensureSlice(d.Candidates),
	}
	return parent
}

// ============================================================================
// Primitive probes
// ============================================================================

// reparentIsAncestor reproduces mergeBaseIsAncestor's trichotomy through
// runReparentGit with Cmd.Dir: exit 0 is (true, nil), exit 1 is (false, nil),
// and anything else — including a failure to spawn git at all — is an error a
// caller surfaces as probe-failed. It is the ONLY form in which this feature
// ever emits `git merge-base`.
func reparentIsAncestor(dir, ancestor, descendant string) (bool, error) {
	res, err := runReparentGit(dir, nil, "merge-base", "--is-ancestor", ancestor, descendant)
	if err == nil {
		return true, nil
	}
	if res.ExitCode == 1 {
		return false, nil
	}
	return false, fmt.Errorf("merge-base --is-ancestor %s %s: %w", ancestor, descendant, err)
}

// reparentOIDWidth determines the repository's canonical OID width once per
// run (§4.3a step 1). sha1 means 40 and sha256 means 64; any other or
// unreadable value refuses capability-unsupported, because no other width is
// ever assumed.
func reparentOIDWidth(repoDir string) (int, error) {
	res, err := runReparentGit(repoDir, nil, "rev-parse", "--show-object-format")
	if err != nil {
		return 0, reparentRefusal(ReparentRefusalCapabilityUnsupported,
			fmt.Sprintf("git rev-parse --show-object-format failed: %s", reparentGitMessage(res, err)))
	}
	switch format := strings.TrimSpace(string(res.Stdout)); format {
	case "sha1":
		return 40, nil
	case "sha256":
		return 64, nil
	default:
		return 0, reparentRefusal(ReparentRefusalCapabilityUnsupported,
			fmt.Sprintf("unsupported object format %q; reparent supports sha1 and sha256 only", format))
	}
}

// reparentGitMessage renders a failed probe's own words for a refusal detail:
// Git's stderr when it wrote any, else the Go error.
func reparentGitMessage(res reparentGitResult, err error) string {
	if msg := strings.TrimSpace(string(res.Stderr)); msg != "" {
		return msg
	}
	return err.Error()
}

// reparentPeelCommit runs `git rev-parse --verify --quiet --end-of-options
// <spec>^{commit}`. It returns (sha, true, nil) when spec names a commit,
// ("", false, nil) when it does not, and an error only for a probe failure —
// --quiet exits 1 for both "unknown" and "ambiguous", so a caller that needs
// to tell those apart must have disambiguated first (§4.3a).
func reparentPeelCommit(repoDir, spec string) (string, bool, error) {
	res, err := runReparentGit(repoDir, nil, "rev-parse", "--verify", "--quiet", "--end-of-options", spec+"^{commit}")
	if err != nil {
		if res.ExitCode == 1 {
			return "", false, nil
		}
		return "", false, reparentRefusal(ReparentRefusalProbeFailed,
			fmt.Sprintf("git rev-parse --verify %s^{commit} failed: %s", spec, reparentGitMessage(res, err)))
	}
	sha := strings.TrimSpace(string(res.Stdout))
	if sha == "" {
		return "", false, nil
	}
	return strings.ToLower(sha), true, nil
}

// reparentRefCandidates is §4.3 step 3's five candidate full refs, in the
// order they are enumerated. The order is part of the contract: it is the
// order a candidate list is built in before sorting for display.
func reparentRefCandidates(token string) [5]string {
	return [5]string{
		"refs/" + token,
		"refs/tags/" + token,
		"refs/heads/" + token,
		"refs/remotes/" + token,
		"refs/remotes/" + token + "/HEAD",
	}
}

// reparentForEachRef runs ONE `git for-each-ref --format=%(refname)`
// invocation over the given patterns and returns every line it printed.
func reparentForEachRef(repoDir string, patterns ...string) ([]string, error) {
	args := append([]string{"for-each-ref", "--format=%(refname)"}, patterns...)
	res, err := runReparentGit(repoDir, nil, args...)
	if err != nil {
		return nil, reparentRefusal(ReparentRefusalProbeFailed,
			fmt.Sprintf("git for-each-ref failed: %s", reparentGitMessage(res, err)))
	}
	var out []string
	for _, line := range strings.Split(string(res.Stdout), "\n") {
		if line = strings.TrimSpace(line); line != "" {
			out = append(out, line)
		}
	}
	return out, nil
}

// reparentSurvivingCandidates enumerates the five candidates of §4.3 step 3
// in one for-each-ref call and keeps only lines that are EXACTLY equal to one
// of them, sorted. for-each-ref treats its operands as patterns, so an
// unfiltered result can contain refs the operator never named; this filter is
// the whole reason rev-parse is not used here.
func reparentSurvivingCandidates(repoDir, token string) ([]string, error) {
	candidates := reparentRefCandidates(token)
	lines, err := reparentForEachRef(repoDir, candidates[:]...)
	if err != nil {
		return nil, err
	}
	allowed := make(map[string]bool, len(candidates))
	for _, candidate := range candidates {
		allowed[candidate] = true
	}
	seen := make(map[string]bool, len(lines))
	var surviving []string
	for _, line := range lines {
		if allowed[line] && !seen[line] {
			seen[line] = true
			surviving = append(surviving, line)
		}
	}
	sort.Strings(surviving)
	return surviving, nil
}

// reparentFullRefExists verifies a `^refs/` token exists EXACTLY, by asking
// for-each-ref for that one pattern and requiring the identical string back.
// No enumeration is performed for a full ref.
func reparentFullRefExists(repoDir, token string) (bool, error) {
	lines, err := reparentForEachRef(repoDir, token)
	if err != nil {
		return false, err
	}
	for _, line := range lines {
		if line == token {
			return true, nil
		}
	}
	return false, nil
}

// reparentDisambiguate returns every object id whose name begins with prefix
// (§4.3a step 3). The count deliberately includes every object type: a prefix
// matching one commit and one blob is ambiguous even though a later ^{commit}
// peel could pick the commit, because reparent requires a globally
// unambiguous object spelling.
func reparentDisambiguate(repoDir, prefix string) ([]string, error) {
	res, err := runReparentGit(repoDir, nil, "rev-parse", "--disambiguate="+strings.ToLower(prefix))
	if err != nil {
		// An empty answer with a non-zero status is Git reporting "no such
		// object", which is a normal answer here, not a probe failure.
		if strings.TrimSpace(string(res.Stdout)) == "" && res.ExitCode > 0 {
			return nil, nil
		}
		return nil, reparentRefusal(ReparentRefusalProbeFailed,
			fmt.Sprintf("git rev-parse --disambiguate=%s failed: %s", prefix, reparentGitMessage(res, err)))
	}
	var out []string
	for _, line := range strings.Split(string(res.Stdout), "\n") {
		if line = strings.TrimSpace(line); line != "" {
			out = append(out, strings.ToLower(line))
		}
	}
	sort.Strings(out)
	return out, nil
}

// ============================================================================
// Literal-token resolution (§4.3, §4.3a, §4.3b)
// ============================================================================

// reparentLiteral is one literal token's resolution.
type reparentLiteral struct {
	Ref         *string
	SHA         string
	Resolution  string
	StoredToken string
	Candidates  []string
}

// resolveReparentLiteral resolves a literal token — a destination's or a
// cutoff's — through the identical namespace enumeration and object-id rules.
//
// ambiguousKind is the caller's own ambiguity kind: a destination refuses
// destination-ambiguous, while a cutoff refuses cutoff-unresolvable for every
// ambiguity it can exhibit (§5.3), because the cutoff is a boundary, not a
// destination, and one kind with a complete candidate list is more useful
// than two kinds with split details.
func resolveReparentLiteral(repoDir, token string, oidWidth int, unresolvableKind, ambiguousKind ReparentRefusalKind) (reparentLiteral, error) {
	if reparentPseudoRefs[token] {
		return reparentLiteral{Resolution: ReparentResolutionUnresolved},
			reparentRefusal(unresolvableKind, reparentPseudoRefDetail)
	}

	// 1. A full ref must exist exactly; no enumeration is performed.
	if strings.HasPrefix(token, "refs/") {
		exists, err := reparentFullRefExists(repoDir, token)
		if err != nil {
			return reparentLiteral{}, err
		}
		if !exists {
			return reparentLiteral{Resolution: ReparentResolutionUnresolved},
				reparentRefusal(unresolvableKind, fmt.Sprintf("ref %q does not exist", token))
		}
		sha, ok, err := reparentPeelCommit(repoDir, token)
		if err != nil {
			return reparentLiteral{}, err
		}
		if !ok {
			return reparentLiteral{Resolution: ReparentResolutionUnresolved},
				reparentRefusal(unresolvableKind, fmt.Sprintf("ref %q does not name a commit", token))
		}
		ref := token
		return reparentLiteral{Ref: &ref, SHA: sha, Resolution: ReparentResolutionRefFull, StoredToken: token}, nil
	}

	// 2/3. A hex token may be an object id; §4.3a decides, and falls through
	// to the short-name rung when it is not an object at all. The object
	// rung's own partial facts travel with its refusal: a refused token still
	// publishes a resolution inside the closed domain, and an ambiguous one
	// still publishes what it was ambiguous between.
	if reparentHexToken.MatchString(token) {
		object, isObject, err := resolveReparentObjectID(repoDir, token, oidWidth, unresolvableKind, ambiguousKind)
		if err != nil {
			return object, err
		}
		if isObject {
			// §4.3a step 4: an object id that is ALSO a ref name is
			// ambiguous, whichever rung recognized it.
			surviving, err := reparentSurvivingCandidates(repoDir, token)
			if err != nil {
				return reparentLiteral{}, err
			}
			if len(surviving) > 0 {
				return reparentLiteral{Resolution: ReparentResolutionAmbiguous, Candidates: surviving},
					reparentRefusal(ambiguousKind,
						fmt.Sprintf("%q is both object %s and ref %s; name the full object id or the full ref",
							token, object.SHA, strings.Join(surviving, ", ")))
			}
			return object, nil
		}
	}

	// 3. Short name: exactly five candidates, exact-equality filtered.
	surviving, err := reparentSurvivingCandidates(repoDir, token)
	if err != nil {
		return reparentLiteral{}, err
	}
	switch len(surviving) {
	case 0:
		return reparentLiteral{Resolution: ReparentResolutionUnresolved},
			reparentRefusal(unresolvableKind, fmt.Sprintf("%q does not resolve to a ref or an object id", token))
	case 1:
		// resolved below
	default:
		return reparentLiteral{Resolution: ReparentResolutionAmbiguous, Candidates: surviving},
			reparentRefusal(ambiguousKind,
				fmt.Sprintf("%q matches %s; re-run with the full ref", token, strings.Join(surviving, ", ")))
	}

	ref := surviving[0]
	sha, ok, err := reparentPeelCommit(repoDir, ref)
	if err != nil {
		return reparentLiteral{}, err
	}
	if !ok {
		return reparentLiteral{Resolution: ReparentResolutionUnresolved, Candidates: surviving},
			reparentRefusal(unresolvableKind, fmt.Sprintf("ref %q does not name a commit", ref))
	}
	return reparentLiteral{
		Ref:         &ref,
		SHA:         sha,
		Resolution:  reparentRefResolution(ref),
		StoredToken: ref,
	}, nil
}

// reparentRefResolution maps a resolved full ref to its §4.3b resolution
// token. The order matters: refs/remotes/ and refs/tags/ and refs/heads/ are
// checked before the refs/<other> catch-all.
func reparentRefResolution(ref string) string {
	switch {
	case strings.HasPrefix(ref, "refs/heads/"):
		return ReparentResolutionRefHead
	case strings.HasPrefix(ref, "refs/tags/"):
		return ReparentResolutionRefTag
	case strings.HasPrefix(ref, "refs/remotes/"):
		return ReparentResolutionRefRemote
	default:
		return ReparentResolutionRefOther
	}
}

// resolveReparentObjectID implements §4.3a steps 2 and 3.
//
// It returns a reparentLiteral in EVERY outcome, so no caller has to
// reconstruct what the rung learned:
//
//   - object id resolved: ({SHA, raw-oid, StoredToken}, true, nil);
//   - not an object at all: (zero literal, false, nil) — the caller falls
//     through to the short-name rung, where the empty resolution is replaced;
//   - multi-match abbreviation: ({ambiguous, sorted candidate OIDs}, false,
//     refusal);
//   - non-committish or unresolvable object: ({unresolved}, false, refusal).
//
// The second result is meaningful only when the error is nil. Publishing the
// partial literal matters because resolution and candidates are closed-domain
// document cells: a refused token must never publish an empty resolution.
func resolveReparentObjectID(repoDir, token string, oidWidth int, unresolvableKind, ambiguousKind ReparentRefusalKind) (reparentLiteral, bool, error) {
	lowered := strings.ToLower(token)

	if len(token) == oidWidth {
		sha, ok, err := reparentPeelCommit(repoDir, lowered)
		if err != nil {
			return reparentLiteral{}, false, err
		}
		if !ok {
			return reparentLiteral{Resolution: ReparentResolutionUnresolved}, false,
				reparentRefusal(unresolvableKind,
					fmt.Sprintf("object %q does not resolve to a commit", token))
		}
		return reparentLiteral{SHA: sha, Resolution: ReparentResolutionRawOID, StoredToken: sha}, true, nil
	}

	matches, err := reparentDisambiguate(repoDir, lowered)
	if err != nil {
		return reparentLiteral{}, false, err
	}
	switch len(matches) {
	case 0:
		// Not an object id: the short-name rung decides.
		return reparentLiteral{}, false, nil
	case 1:
		// resolved below
	default:
		// The candidate list carries the sorted full OIDs the prefix matched,
		// which is what "re-run with the full object id" refers to; a ref
		// ambiguity carries refs in the same cell.
		return reparentLiteral{Resolution: ReparentResolutionAmbiguous, Candidates: matches}, false,
			reparentRefusal(ambiguousKind,
				fmt.Sprintf("%q matches %d objects (%s); name the full object id",
					token, len(matches), strings.Join(matches, ", ")))
	}

	sha, ok, err := reparentPeelCommit(repoDir, matches[0])
	if err != nil {
		return reparentLiteral{}, false, err
	}
	if !ok {
		// A single, unambiguous match that is not a commit: unresolved, with
		// no candidate list, because nothing was ambiguous.
		return reparentLiteral{Resolution: ReparentResolutionUnresolved}, false,
			reparentRefusal(unresolvableKind,
				fmt.Sprintf("object %s does not resolve to a commit", matches[0]))
	}
	return reparentLiteral{SHA: sha, Resolution: ReparentResolutionRawOID, StoredToken: sha}, true, nil
}

// ============================================================================
// ResolveReparentDestination (§4.1, §4.2, §4.3, §4.3b)
// ============================================================================

// ResolveReparentDestination resolves --onto into the single pinned
// destination this run uses everywhere.
//
// kind selects how the token is read: auto is entry-first (a token equal to
// some StackEntry.Name is that entry, otherwise it is a literal), entry
// requires an entry, and ref never consults entry names at all. Storing the
// full ref is what makes --onto-kind ref safe against an entry name that
// happens to match, and what stops ResolveSyncBase's origin/<default> rewrite
// from ever re-interpreting a token this feature chose.
//
// It never performs that rewrite itself: a reparent destination is exactly
// what the operator named, stored canonically.
func ResolveReparentDestination(repoDir string, stack Stack, target StackEntry, token, kind string, oidWidth int) (ReparentDestination, error) {
	return resolveReparentDestination(repoDir, stack, target, token, kind, oidWidth,
		func(parent, target StackEntry) bool { return SameStackRepo(parent.Repo, target.Repo) })
}

func ResolveReparentDestinationByRepoIdentity(repoDir string, stack Stack, target StackEntry, token, kind string, oidWidth int, identities map[string]string) (ReparentDestination, error) {
	if kind != "ref" {
		if parent, ok := reparentLookupEntry(stack, token); ok &&
			!SameStackRepo(parent.Repo, target.Repo) &&
			identities[parent.Name] != "" &&
			identities[parent.Name] == identities[target.Name] {
			return ReparentDestination{
					RequestedToken: token,
					Kind:           ReparentParentKindStackEntry,
					EntryName:      parent.Name,
					Resolution:     ReparentResolutionEntry,
				}, reparentEntryRefusal(ReparentRefusalDestinationResolverDivergent, parent.Name,
					fmt.Sprintf("destination entry %q uses repository token %q while target %q uses %q; aliases of one repository are unsupported until every stack resolver compares canonical repository identity",
						parent.Name, parent.Repo, target.Name, target.Repo))
		}
	}
	return resolveReparentDestination(repoDir, stack, target, token, kind, oidWidth,
		func(parent, target StackEntry) bool {
			parentID, parentOK := identities[parent.Name]
			targetID, targetOK := identities[target.Name]
			if parentOK && targetOK && parentID != "" && targetID != "" {
				return parentID == targetID
			}
			return SameStackRepo(parent.Repo, target.Repo)
		})
}

func resolveReparentDestination(repoDir string, stack Stack, target StackEntry, token, kind string, oidWidth int, sameRepo func(StackEntry, StackEntry) bool) (ReparentDestination, error) {
	if strings.TrimSpace(token) == "" {
		return ReparentDestination{}, reparentRefusal(ReparentRefusalDestinationUnset, "--onto requires a destination")
	}

	entry, isEntry := reparentLookupEntry(stack, token)
	switch kind {
	case "entry":
		if !isEntry {
			return ReparentDestination{}, reparentRefusal(ReparentRefusalDestinationKindMismatch,
				fmt.Sprintf("--onto-kind entry requires a stack entry name; %q is not an entry in this feature's stack.yaml", token))
		}
		return resolveReparentEntryDestination(repoDir, target, entry, token, sameRepo)
	case "ref":
		isEntry = false
	case "auto", "":
		// entry-first, decided by isEntry above
	default:
		return ReparentDestination{}, reparentRefusal(ReparentRefusalDestinationKindMismatch,
			fmt.Sprintf("--onto-kind must be one of: auto, entry, ref (got %q)", kind))
	}

	if isEntry {
		return resolveReparentEntryDestination(repoDir, target, entry, token, sameRepo)
	}

	literal, err := resolveReparentLiteral(repoDir, token, oidWidth,
		ReparentRefusalDestinationUnresolvable, ReparentRefusalDestinationAmbiguous)
	if err != nil {
		// The partially-resolved facts travel with the refusal so an
		// unavailable plan can publish resolution and candidates instead of
		// dropping what the run did learn. resolution is a closed-domain
		// document cell, so a rung that learned nothing at all — a failed
		// read-only probe — still publishes `unresolved` rather than an
		// empty string outside the domain.
		resolution := literal.Resolution
		if resolution == "" {
			resolution = ReparentResolutionUnresolved
		}
		return ReparentDestination{
			RequestedToken: token,
			Kind:           ReparentParentKindLiteralRef,
			Resolution:     resolution,
			Candidates:     literal.Candidates,
		}, err
	}
	return ReparentDestination{
		RequestedToken: token,
		StoredToken:    literal.StoredToken,
		Kind:           ReparentParentKindLiteralRef,
		Ref:            literal.Ref,
		SHA:            literal.SHA,
		Resolution:     literal.Resolution,
		Candidates:     literal.Candidates,
	}, nil
}

// reparentLookupEntry finds an entry by exact Name.
func reparentLookupEntry(stack Stack, name string) (StackEntry, bool) {
	for _, e := range stack.Branches {
		if e.Name == name {
			return e, true
		}
	}
	return StackEntry{}, false
}

// resolveReparentEntryDestination is §4.2: an in-stack parent resolves
// through refs/heads/<parent.GitBranch()>, matching stackBaseRef exactly.
func resolveReparentEntryDestination(repoDir string, target, parent StackEntry, requested string, sameRepo func(StackEntry, StackEntry) bool) (ReparentDestination, error) {
	if !sameRepo(parent, target) {
		return ReparentDestination{}, reparentEntryRefusal(ReparentRefusalCrossRepoClosure, parent.Name,
			fmt.Sprintf("destination entry %q is configured in repo %q but the target is in repo %q", parent.Name, parent.Repo, target.Repo))
	}
	if parent.Archived {
		return ReparentDestination{}, reparentEntryRefusal(ReparentRefusalAffectedArchived, parent.Name,
			fmt.Sprintf("destination entry %q is archived", parent.Name))
	}

	ref := "refs/heads/" + parent.GitBranch()
	exists, err := reparentFullRefExists(repoDir, ref)
	if err != nil {
		return ReparentDestination{}, err
	}
	if !exists {
		return ReparentDestination{}, reparentEntryRefusal(ReparentRefusalDestinationUnresolvable, parent.Name,
			fmt.Sprintf("ref %q does not exist", ref))
	}
	sha, ok, err := reparentPeelCommit(repoDir, ref)
	if err != nil {
		return ReparentDestination{}, err
	}
	if !ok {
		return ReparentDestination{}, reparentEntryRefusal(ReparentRefusalDestinationUnresolvable, parent.Name,
			fmt.Sprintf("ref %q does not name a commit", ref))
	}

	repo := parent.Repo
	return ReparentDestination{
		RequestedToken: requested,
		StoredToken:    parent.Name,
		Kind:           ReparentParentKindStackEntry,
		Ref:            &ref,
		SHA:            sha,
		Repo:           &repo,
		Resolution:     ReparentResolutionEntry,
		EntryName:      parent.Name,
	}, nil
}

// ============================================================================
// Cutoff ladders (§5.1, §5.2, §5.3)
//
// merge-base is never a cutoff. Every rung below either reads a recorded
// boundary, resolves an operator-supplied one, or takes the OLD PARENT's
// pre-image tip and proves it is an ancestor of the row's branch first.
// ============================================================================

// resolveReparentTargetCutoff walks §5.1's closed ladder for the target row.
//
// recordedSHA is the target's LastBaseSHA as the PRE-IMAGE snapshot captured
// it, never a live re-read: a cutoff that changes underneath a run is exactly
// the failure this ladder exists to prevent. suppliedToken is --cutoff's raw
// value, "" when absent.
func resolveReparentTargetCutoff(repoDir string, stack Stack, target StackEntry, recordedSHA, suppliedToken string, oidWidth int) (ReparentPlanCutoff, error) {
	cutoff := ReparentPlanCutoff{
		RecordedState: ReparentCutoffRecordAbsent,
		Provenance:    ReparentCutoffNone,
	}
	if recordedSHA != "" {
		recorded := recordedSHA
		cutoff.RecordedSHA = &recorded
	}
	if suppliedToken != "" {
		supplied := suppliedToken
		cutoff.SuppliedToken = &supplied
	}
	branchRef := "refs/heads/" + target.GitBranch()

	// Rungs 1 and 2: a recorded boundary is authoritative, and an
	// unresolvable one is fatal — a supplied token MUST NOT override it.
	if recordedSHA != "" {
		resolved, ok, err := reparentPeelCommit(repoDir, recordedSHA)
		if err != nil {
			return cutoff, err
		}
		if !ok {
			cutoff.RecordedState = ReparentCutoffRecordUnresolvable
			return cutoff, reparentEntryRefusal(ReparentRefusalCutoffUnresolvable, target.Name,
				fmt.Sprintf("recorded cutoff %s no longer resolves; restore or fetch the missing object before reparenting", recordedSHA))
		}
		cutoff.RecordedState = ReparentCutoffRecordPresent
		cutoff.ResolvedSHA = &resolved
		cutoff.Provenance = ReparentCutoffRecordedBySync

		if suppliedToken != "" {
			literal, err := resolveReparentLiteral(repoDir, suppliedToken, oidWidth,
				ReparentRefusalCutoffUnresolvable, ReparentRefusalCutoffUnresolvable)
			if err != nil {
				return cutoff, reparentAttributeEntry(err, target.Name)
			}
			suppliedSHA := literal.SHA
			cutoff.SuppliedSHA = &suppliedSHA
			if suppliedSHA != resolved {
				conflict := fmt.Sprintf("--cutoff resolves to %s but the recorded boundary is %s", suppliedSHA, resolved)
				cutoff.Conflict = &conflict
				return cutoff, reparentEntryRefusal(ReparentRefusalCutoffConflict, target.Name, conflict)
			}
		}
		return cutoff, nil
	}

	// Rung 3: an operator-supplied boundary, resolved by §5.3.
	if suppliedToken != "" {
		literal, err := resolveReparentLiteral(repoDir, suppliedToken, oidWidth,
			ReparentRefusalCutoffUnresolvable, ReparentRefusalCutoffUnresolvable)
		if err != nil {
			return cutoff, reparentAttributeEntry(err, target.Name)
		}
		suppliedSHA := literal.SHA
		cutoff.SuppliedSHA = &suppliedSHA
		cutoff.ResolvedSHA = &suppliedSHA
		cutoff.Provenance = ReparentCutoffOperatorSupplied
		return cutoff, nil
	}

	// Rung 4: the old parent's pre-image tip, usable only when it resolves
	// AND is an ancestor of the target's branch.
	tip, ok, err := resolveReparentOldParentTip(repoDir, stack, target, oidWidth)
	if err != nil {
		return cutoff, err
	}
	if ok {
		isAncestor, err := reparentIsAncestor(repoDir, tip, branchRef)
		if err != nil {
			return cutoff, reparentEntryRefusal(ReparentRefusalProbeFailed, target.Name, err.Error())
		}
		cutoff.AncestorOfBranch = &isAncestor
		if isAncestor {
			resolved := tip
			cutoff.ResolvedSHA = &resolved
			cutoff.Provenance = ReparentCutoffOldParentTip
			return cutoff, nil
		}
	}

	// Rung 5.
	return cutoff, reparentEntryRefusal(ReparentRefusalCutoffAbsent, target.Name,
		fmt.Sprintf("no replay boundary is recorded for %q; supply --cutoff <ref>, or establish a baseline with: tws sync <feature> --only %s", target.Name, target.Name))
}

// resolveReparentDescendantCutoff walks §5.2's closed ladder. --cutoff never
// applies to a descendant: a descendant MUST use its own snapshotted
// boundary, and the target's old tip is never substituted for it.
func resolveReparentDescendantCutoff(repoDir string, stack Stack, row StackEntry, recordedSHA string, oidWidth int) (ReparentPlanCutoff, error) {
	cutoff := ReparentPlanCutoff{
		RecordedState: ReparentCutoffRecordAbsent,
		Provenance:    ReparentCutoffNone,
	}
	if recordedSHA != "" {
		recorded := recordedSHA
		cutoff.RecordedSHA = &recorded
	}
	branchRef := "refs/heads/" + row.GitBranch()

	if recordedSHA != "" {
		resolved, ok, err := reparentPeelCommit(repoDir, recordedSHA)
		if err != nil {
			return cutoff, err
		}
		if !ok {
			cutoff.RecordedState = ReparentCutoffRecordUnresolvable
			return cutoff, reparentEntryRefusal(ReparentRefusalCutoffUnresolvable, row.Name,
				fmt.Sprintf("recorded cutoff %s for %q no longer resolves; restore or fetch the missing object before reparenting", recordedSHA, row.Name))
		}
		cutoff.RecordedState = ReparentCutoffRecordPresent
		cutoff.ResolvedSHA = &resolved
		cutoff.Provenance = ReparentCutoffRecordedBySync
		return cutoff, nil
	}

	tip, ok, err := resolveReparentOldParentTip(repoDir, stack, row, oidWidth)
	if err != nil {
		return cutoff, err
	}
	if ok {
		isAncestor, err := reparentIsAncestor(repoDir, tip, branchRef)
		if err != nil {
			return cutoff, reparentEntryRefusal(ReparentRefusalProbeFailed, row.Name, err.Error())
		}
		cutoff.AncestorOfBranch = &isAncestor
		if isAncestor {
			resolved := tip
			cutoff.ResolvedSHA = &resolved
			cutoff.Provenance = ReparentCutoffOldParentTip
			return cutoff, nil
		}
	}

	return cutoff, reparentEntryRefusal(ReparentRefusalDescendantCutoffAbsent, row.Name,
		fmt.Sprintf("no replay boundary is recorded for descendant %q; establish descendant baselines first with: tws sync <feature> --from %s", row.Name, row.Name))
}

// resolveReparentOldParentTip resolves an entry's CONFIGURED parent to its
// pre-image commit, applying §4.2's entry rule and §4.3's literal rules to
// the old token. An unresolvable or ambiguous old token is not an error here:
// it simply means this rung produced no boundary and the ladder moves on. A
// genuine probe failure is still returned.
func resolveReparentOldParentTip(repoDir string, stack Stack, entry StackEntry, oidWidth int) (string, bool, error) {
	if entry.Base == "" {
		return "", false, nil
	}
	if parent, found := reparentLookupEntry(stack, entry.Base); found && SameStackRepo(parent.Repo, entry.Repo) {
		return reparentPeelCommit(repoDir, "refs/heads/"+parent.GitBranch())
	}
	literal, err := resolveReparentLiteral(repoDir, entry.Base, oidWidth,
		ReparentRefusalCutoffUnresolvable, ReparentRefusalCutoffUnresolvable)
	if err != nil {
		var refusal *ReparentRefusalError
		if asReparentRefusal(err, &refusal) && refusal.Kind != ReparentRefusalProbeFailed {
			return "", false, nil
		}
		return "", false, err
	}
	return literal.SHA, true, nil
}

// reparentAttributeEntry stamps an entry name onto a document-level reparent
// refusal, so a cutoff refusal raised by the shared literal resolver is
// reported against the row that asked for it.
func reparentAttributeEntry(err error, entry string) error {
	var refusal *ReparentRefusalError
	if !asReparentRefusal(err, &refusal) {
		return err
	}
	if refusal.Entry != nil {
		return err
	}
	name := entry
	return &ReparentRefusalError{Kind: refusal.Kind, Entry: &name, Detail: refusal.Detail, StatePreserved: refusal.StatePreserved}
}

// asReparentRefusal is errors.As for *ReparentRefusalError, kept as one
// helper so every call site spells the assertion identically.
func asReparentRefusal(err error, target **ReparentRefusalError) bool {
	return errors.As(err, target)
}

// ============================================================================
// Resolver agreement (§4.3c)
// ============================================================================

// resolveReparentAgreement confirms that all four base resolvers, given the
// STORED token, agree on the pinned destination commit.
//
// postImage is the stack this run would write — the target's Base already
// replaced by the stored token — because that is the graph the very next
// `tws sync` and `tws stack status` will read. Resolvers 2-4 return ref or
// token spellings rather than a uniformly peeled OID, so each answer is
// normalized with `rev-parse --verify --quiet --end-of-options <answer>^{commit}`
// before comparison. That normalization is load-bearing for annotated tags:
// the checkout resolver's bare rev-parse observes the TAG OBJECT's id, while
// the normalized answer must be the peeled commit.
//
// The shipped resolvers themselves are called unmodified.
func reparentSyncDefaultBranch(repoDir string) string {
	if res, err := runReparentGit(repoDir, nil, "rev-parse", "--abbrev-ref", "origin/HEAD"); err == nil {
		return strings.TrimPrefix(strings.TrimSpace(string(res.Stdout)), "origin/")
	}
	if res, err := runReparentGit(repoDir, nil, "symbolic-ref", "--short", "HEAD"); err == nil {
		return strings.TrimSpace(string(res.Stdout))
	}
	return "main"
}

func resolveReparentAgreement(repoDir string, postImage Stack, target StackEntry, destinationKind, storedToken, pinnedSHA string) (ReparentResolverAgreement, error) {
	agreement := ReparentResolverAgreement{Checked: true}
	if destinationKind != ReparentParentKindStackEntry {
		for _, entry := range postImage.Branches {
			if entry.Name != storedToken {
				continue
			}
			return agreement, reparentRefusal(ReparentRefusalDestinationResolverDivergent, fmt.Sprintf(
				"canonical literal destination %q is also the logical stack entry name %q; sync and status resolve stack entry names first, so this stored token would change meaning when that entry moves",
				storedToken, entry.Name))
		}
	}
	agreed := true

	record := func(name, rawAnswer string, normalized string, ok bool, failure string) {
		verdict := ReparentResolverVerdict{Name: name}
		if ok {
			sha := normalized
			verdict.SHA = &sha
			verdict.Agrees = normalized == pinnedSHA
			if !verdict.Agrees {
				detail := fmt.Sprintf("resolver %s answered %q for stored token %q, which normalizes to %s, not the pinned %s",
					name, rawAnswer, storedToken, normalized, pinnedSHA)
				verdict.Detail = &detail
			}
		} else {
			detail := failure
			verdict.Detail = &detail
		}
		if !verdict.Agrees {
			agreed = false
		}
		agreement.Resolvers = append(agreement.Resolvers, verdict)
	}

	// 1. ResolveReparentDestination — already a peeled OID by construction.
	record(ReparentResolverDestination, storedToken, pinnedSHA, true, "")

	// 2. ResolveSyncBase's pure half, fed by the default branch measured
	// through reparent's Dir-based runner so this boundary never emits `-C`.
	syncBase := ResolveSyncBaseWithDefaultBranch(postImage, target, reparentSyncDefaultBranch(repoDir))
	if syncBase.Base == "" {
		record(ReparentResolverSyncBase, "", "", false,
			fmt.Sprintf("resolver %s produced no base for stored token %q (kind %s); expected %s",
				ReparentResolverSyncBase, storedToken, syncBase.Kind, pinnedSHA))
	} else {
		normalized, ok, err := reparentPeelCommit(repoDir, syncBase.Base)
		if err != nil {
			return agreement, err
		}
		record(ReparentResolverSyncBase, syncBase.Base, normalized, ok,
			fmt.Sprintf("resolver %s answered %q for stored token %q, which does not resolve to a commit; expected %s",
				ReparentResolverSyncBase, syncBase.Base, storedToken, pinnedSHA))
	}

	// 3. stackBaseRef.
	baseRef, baseKind := stackBaseRef(postImage, target)
	if baseKind == StackBaseNone || baseRef == "" {
		record(ReparentResolverStackBase, "", "", false,
			fmt.Sprintf("resolver %s produced no base ref for stored token %q; expected %s",
				ReparentResolverStackBase, storedToken, pinnedSHA))
	} else {
		normalized, ok, err := reparentPeelCommit(repoDir, baseRef)
		if err != nil {
			return agreement, err
		}
		record(ReparentResolverStackBase, baseRef, normalized, ok,
			fmt.Sprintf("resolver %s answered %q for stored token %q, which does not resolve to a commit; expected %s",
				ReparentResolverStackBase, baseRef, storedToken, pinnedSHA))
	}

	// 4. The checkout executor's base pick, through the extracted selector so
	// a future divergence is a compile error rather than a silent mismatch.
	checkoutToken, hasToken := checkoutBaseTokenFor(postImage, target)
	if !hasToken {
		record(ReparentResolverCheckout, "", "", false,
			fmt.Sprintf("resolver %s produced no base token for stored token %q; expected %s",
				ReparentResolverCheckout, storedToken, pinnedSHA))
	} else {
		// The shipped executor resolves its token with a bare rev-parse, so
		// the raw answer is deliberately the unpeeled object id.
		raw, rawOK, err := reparentRevParse(repoDir, checkoutToken)
		if err != nil {
			return agreement, err
		}
		if !rawOK {
			record(ReparentResolverCheckout, checkoutToken, "", false,
				fmt.Sprintf("resolver %s answered %q for stored token %q, which does not resolve; expected %s",
					ReparentResolverCheckout, checkoutToken, storedToken, pinnedSHA))
		} else {
			normalized, ok, err := reparentPeelCommit(repoDir, raw)
			if err != nil {
				return agreement, err
			}
			record(ReparentResolverCheckout, raw, normalized, ok,
				fmt.Sprintf("resolver %s answered %q (%s) for stored token %q, which does not peel to a commit; expected %s",
					ReparentResolverCheckout, checkoutToken, raw, storedToken, pinnedSHA))
		}
	}

	agreement.Agreed = &agreed
	if !agreed {
		for _, verdict := range agreement.Resolvers {
			if verdict.Agrees {
				continue
			}
			detail := fmt.Sprintf("resolver %s disagrees about stored token %q", verdict.Name, storedToken)
			if verdict.Detail != nil {
				detail = *verdict.Detail
			}
			return agreement, reparentRefusal(ReparentRefusalDestinationResolverDivergent, detail)
		}
	}
	return agreement, nil
}

// reparentRevParse runs a bare `git rev-parse <token>` — the exact shape the
// shipped checkout executor uses — and reports whether it resolved. It is
// used only to capture that resolver's RAW answer for the agreement block;
// every comparison is made on the normalized, peeled value.
func reparentRevParse(repoDir, token string) (string, bool, error) {
	res, err := runReparentGit(repoDir, nil, "rev-parse", token)
	if err != nil {
		if res.ExitCode > 0 {
			return "", false, nil
		}
		return "", false, reparentRefusal(ReparentRefusalProbeFailed,
			fmt.Sprintf("git rev-parse %s failed: %s", token, reparentGitMessage(res, err)))
	}
	answer := strings.TrimSpace(string(res.Stdout))
	if answer == "" {
		return "", false, nil
	}
	return strings.ToLower(answer), true, nil
}

