func hasReparentBlocker(plan ReparentPlan, kind ReparentRefusalKind) bool {
	for _, b := range plan.Blockers {
		if b.Kind == kind {
			return true
		}
	}
	return false
}

func hasReparentWarning(plan ReparentPlan, kind string) bool {
	for _, w := range plan.Warnings {
		if w.Kind == kind {
			return true
		}
	}
	return false
}

