func testReparentFreshRefusesWindowOneState(t *testing.T) {
	w := newReparentWorkspace(t, ModeExternal)
	rec := ReparentRemoteRecord{
		Feature: w.Loc.Feature,
		RunID:   strings.Repeat("a", 32),
		Entries: []ReparentRemoteEntry{{
