				t.Fatalf("%s setup = %v", verb, err)
			}
			ReparentStepHook = nil
			st := LoadReparentState(w.Loc).State
			if st.OriginalHeadPinRef == "" {
				t.Fatal("originally detached checkout has no run-owned HEAD pin")
			}
