package internal

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"gopkg.in/yaml.v3"
)

type StackEntry struct {
	Name        string `yaml:"name"`
	Branch      string `yaml:"branch,omitempty"`   // git branch name (defaults to Name if empty)
	Archived    bool   `yaml:"archived,omitempty"` // true when branch is archived (metadata only)
	Base        string `yaml:"base"`
	Repo        string `yaml:"repo,omitempty"`          // source repo path (empty = default/current repo)
	LastBaseSHA string `yaml:"last_base_sha,omitempty"` // SHA of base branch at last sync
}

// GitBranch returns the actual git branch name for this entry.
func (e StackEntry) GitBranch() string {
	if e.Branch != "" {
		return e.Branch
	}
	return e.Name
}

type Stack struct {
	Branches []StackEntry `yaml:"branches"`
}

// UniqueRepos returns a set of unique repo paths referenced in the stack.
// Empty string represents the default repo. Returns worktree paths for
// each repo (to use as git context) alongside the repo path.
func UniqueRepos(s Stack, featurePath string) map[string]string {
	repos := make(map[string]string)
	for _, e := range s.Branches {
		repo := e.Repo
		if _, ok := repos[repo]; !ok {
			// Find an active worktree from this repo to use as git context
			wtPath := filepath.Join(featurePath, "worktrees", e.Name)
			if _, err := os.Stat(wtPath); err == nil {
				repos[repo] = wtPath
			} else {
				repos[repo] = "" // no active worktree, will need fallback
			}
		}
	}
	return repos
}

// HasBranch checks if a branch name already exists in the stack.
func HasBranch(s Stack, name string) bool {
	for _, e := range s.Branches {
		if e.Name == name {
			return true
		}
	}
	return false
}

// GetBranch returns the StackEntry for a branch name. Returns empty entry if not found.
func GetBranch(s Stack, name string) StackEntry {
	for _, e := range s.Branches {
		if e.Name == name {
			return e
		}
	}
	return StackEntry{}
}

// UpdateBaseSHA updates the last_base_sha for a branch in the stack.
func UpdateBaseSHA(s *Stack, branchName, sha string) {
	for i := range s.Branches {
		if s.Branches[i].Name == branchName {
			s.Branches[i].LastBaseSHA = sha
			return
		}
	}
}

// GetBranchSHA returns the current HEAD SHA of a branch using git.
func GetBranchSHA(gitContext, branch string) string {
	args := []string{"rev-parse", branch}
	if gitContext != "" {
		args = []string{"-C", gitContext, "rev-parse", branch}
	}
	out, err := exec.Command("git", args...).Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

// RenameBranch renames a branch in the stack, updating both Name and Base references.
func RenameBranch(s *Stack, oldName, newName string) bool {
	found := false
	for i := range s.Branches {
		if s.Branches[i].Name == oldName {
			s.Branches[i].Name = newName
			found = true
		}
		if s.Branches[i].Base == oldName {
			s.Branches[i].Base = newName
		}
	}
	return found
}

func StackPath(featurePath string) string {
	return filepath.Join(featurePath, "stack.yaml")
}

func LoadStack(featurePath string) (Stack, error) {
	data, err := os.ReadFile(StackPath(featurePath))
	if err != nil {
		return Stack{}, err
	}
	var s Stack
	if err := yaml.Unmarshal(data, &s); err != nil {
		return Stack{}, err
	}
	return s, nil
}

func SaveStack(featurePath string, s Stack) error {
	data, err := yaml.Marshal(&s)
	if err != nil {
		return err
	}
	return os.WriteFile(StackPath(featurePath), data, 0644)
}

// ============================================================================
// Byte-exact durable stack writers (safe-reparent §10.3, §10.3a)
//
// SaveStack above is deliberately untouched: it is not atomic, not durable,
// and every one of its callers keeps it. The three functions below are the
// reparent boundary's only metadata writers.
// ============================================================================

// WriteStackBytesAtomic writes exactly these bytes to the feature's
// stack.yaml, atomically and durably. It is the primitive both the forward
// metadata write and the abort restore use, because a pre-image restored by
// re-marshalling a decoded struct is not a restore: YAML round-tripping can
// reorder keys, drop comments and change quoting, so only the captured bytes
// are ever written back.
func WriteStackBytesAtomic(featurePath string, data []byte) error {
	return durableWriteFileFault(SyncIOWriteStack, StackPath(featurePath), data, 0644)
}

// SaveStackAtomic marshals s exactly as SaveStack does and delegates to
// WriteStackBytesAtomic, so a caller that holds a struct rather than bytes
// still gets the atomic, durable writer.
func SaveStackAtomic(featurePath string, s Stack) error {
	data, err := yaml.Marshal(&s)
	if err != nil {
		return err
	}
	return WriteStackBytesAtomic(featurePath, data)
}

// durableWriteFile writes data to path through a same-directory temp file
// that is fsynced, closed and renamed over the destination, after which the
// PARENT DIRECTORY is opened and fsynced too. The shipped atomicWriteFile
// (internal/checkout_sync.go) fsyncs the temp file but never the directory,
// so the renamed directory entry it produces is outside a machine-crash
// durability claim; this helper is added beside it, never inside it, and
// atomicWriteFile keeps every one of its callers.
//
// Every artifact whose loss would strip a reparent run of its only record of
// what it did is written through this helper: stack.yaml (via
// WriteStackBytesAtomic), the reparent state artifact, the compatibility
// artifacts, and the remote follow-up record.
func durableWriteFile(path string, data []byte, mode os.FileMode) error {
	return durableWriteFileFault("", path, data, mode)
}

// durableWriteFileFault is durableWriteFile with the §10.3b fault token
// bound. It consults syncIOFault(op, path) at exactly two points — before
// the rename, and after the rename but before the parent-directory fsync —
// so a test can assert that the previous file survives the first window and
// that a run stays recoverable after the second. op == "" disables the seam
// entirely, which is what the tokenless durableWriteFile passes.
func durableWriteFileFault(op, path string, data []byte, mode os.FileMode) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0700); err != nil {
		return fmt.Errorf("create state directory: %w", err)
	}
	tmp, err := os.CreateTemp(dir, ".tws-durable-*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName) //nolint:errcheck
	if err := tmp.Chmod(mode); err != nil {
		_ = tmp.Close()
		return err
	}
	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if op != "" {
		// Window 1: the destination still holds its previous bytes.
		if err := syncIOFault(op, path); err != nil {
			return err
		}
	}
	if err := os.Rename(tmpName, path); err != nil {
		return err
	}
	if op != "" {
		// Window 2: the rename landed but the directory entry is not yet
		// durable. The caller MUST treat this as "may or may not have been
		// written", never as "not written".
		if err := syncIOFault(op, path); err != nil {
			return err
		}
	}
	return syncDir(dir)
}

// syncDir opens dir read-only and fsyncs it, which is what makes a completed
// rename durable across a machine crash. A directory that cannot be opened
// or synced is reported, never ignored.
func syncDir(dir string) error {
	handle, err := os.Open(dir)
	if err != nil {
		return err
	}
	syncErr := handle.Sync()
	closeErr := handle.Close()
	if syncErr != nil {
		return syncErr
	}
	return closeErr
}

var reparentRecoverySyncDir = syncDir

func confirmReparentRenameDurable(path string) error {
	return reparentRecoverySyncDir(filepath.Dir(path))
}

// TopoSort returns branches in dependency order (parents before children).
// Returns an error if the graph contains a cycle.
func TopoSort(s Stack) ([]StackEntry, error) {
	// Build adjacency: base → children
	entryMap := make(map[string]StackEntry)
	children := make(map[string][]string)
	inDegree := make(map[string]int)

	for _, e := range s.Branches {
		entryMap[e.Name] = e
		inDegree[e.Name] = 0
	}

	for _, e := range s.Branches {
		// Only count edges where the base is also a tracked branch
		if _, ok := entryMap[e.Base]; ok {
			children[e.Base] = append(children[e.Base], e.Name)
			inDegree[e.Name]++
		}
	}

	// Kahn's algorithm
	var queue []string
	for name, deg := range inDegree {
		if deg == 0 {
			queue = append(queue, name)
		}
	}

	var sorted []StackEntry
	for len(queue) > 0 {
		name := queue[0]
		queue = queue[1:]
		sorted = append(sorted, entryMap[name])
		for _, child := range children[name] {
			inDegree[child]--
			if inDegree[child] == 0 {
				queue = append(queue, child)
			}
		}
	}

	if len(sorted) != len(s.Branches) {
		return nil, fmt.Errorf("cycle detected in stack.yaml")
	}
	return sorted, nil
}

// ReparentClosureOrder returns the target and its transitive logical
// descendants in the stable order safe-reparent replays them (§6.1a).
//
// It is deliberately NOT TopoSort, is never called by it, and never modifies
// it. Two differences are load-bearing:
//
//  1. TopoSort seeds its ready queue by ranging over a Go map, so its initial
//     root order is randomized per run. A fingerprint and a replay sequence
//     both need an order that never changes between a --plan and its
//     execution, so the ready set here is a min-heap keyed by the entry's
//     index in Stack.Branches: stack.yaml declaration order is the sole
//     sibling tie-break, and it is a stable, operator-visible, byte-durable
//     property of the very file the run rewrites.
//  2. An edge exists only where child.Base == parent.Name AND the two entries
//     share a repository (SameStackRepo). TopoSort ignores Repo entirely, so
//     an unrelated stack in another repository whose Base merely spells the
//     same name would be pulled in; here it is not a child at all.
//
// The function is pure: it reads only stack, issues no Git command and
// touches no filesystem. An unknown target returns an error, as does a cycle
// among the reachable vertices — callers surface the latter as
// stack-unsortable (current stack) or destination-cycle (post-image graph).
// The target is always element 0.
func ReparentClosureOrder(stack Stack, target string) ([]StackEntry, error) {
	return reparentClosureOrder(stack, target, func(child, parent StackEntry) bool {
		return SameStackRepo(child.Repo, parent.Repo)
	})
}

// ReparentClosureOrderByRepoIdentity is the production reparent graph. The
// identity map is keyed by entry name and contains canonical Git common-dir
// identities measured before graph construction. Missing identities fall back
// to the raw comparison so an unreadable same-token row remains in scope and
// can surface its repo-unavailable blocker instead of disappearing.
func ReparentClosureOrderByRepoIdentity(stack Stack, target string, identities map[string]string) ([]StackEntry, error) {
	return reparentClosureOrder(stack, target, func(child, parent StackEntry) bool {
		if SameStackRepo(child.Repo, parent.Repo) {
			return true
		}
		childID, childOK := identities[child.Name]
		parentID, parentOK := identities[parent.Name]
		if childOK && parentOK && childID != "" && parentID != "" {
			return childID == parentID
		}
		return false
	})
}

func reparentClosureOrder(stack Stack, target string, sameRepo func(StackEntry, StackEntry) bool) ([]StackEntry, error) {
	index := make(map[string]int, len(stack.Branches))
	for i, e := range stack.Branches {
		if _, dup := index[e.Name]; dup {
			return nil, fmt.Errorf("duplicate stack entry %q", e.Name)
		}
		index[e.Name] = i
	}
	if _, ok := index[target]; !ok {
		return nil, fmt.Errorf("entry %q is not in stack.yaml", target)
	}

	children := make(map[string][]string, len(stack.Branches))
	for _, child := range stack.Branches {
		parentIdx, ok := index[child.Base]
		if !ok {
			continue
		}
		parent := stack.Branches[parentIdx]
		if !sameRepo(child, parent) {
			continue
		}
		children[parent.Name] = append(children[parent.Name], child.Name)
	}

	// Vertex set: the target plus everything reachable from it through those
	// edges. The closure is computed first so in-degrees count only edges
	// inside it — an ancestor of the target is not part of the replay.
	member := map[string]bool{target: true}
	stackQueue := []string{target}
	for len(stackQueue) > 0 {
		name := stackQueue[len(stackQueue)-1]
		stackQueue = stackQueue[:len(stackQueue)-1]
		for _, child := range children[name] {
			if member[child] {
				continue
			}
			member[child] = true
			stackQueue = append(stackQueue, child)
		}
	}

	inDegree := make(map[string]int, len(member))
	for name := range member {
		inDegree[name] = 0
	}
	for name := range member {
		for _, child := range children[name] {
			if member[child] {
				inDegree[child]++
			}
		}
	}

	ready := &stackIndexHeap{}
	for name := range member {
		if inDegree[name] == 0 {
			ready.push(index[name])
		}
	}

	ordered := make([]StackEntry, 0, len(member))
	for ready.len() > 0 {
		idx := ready.pop()
		entry := stack.Branches[idx]
		ordered = append(ordered, entry)
		for _, child := range children[entry.Name] {
			if !member[child] {
				continue
			}
			inDegree[child]--
			if inDegree[child] == 0 {
				ready.push(index[child])
			}
		}
	}

	if len(ordered) != len(member) {
		return nil, fmt.Errorf("cycle detected in stack.yaml")
	}
	if ordered[0].Name != target {
		// Unreachable while the closure is rooted at the target, which has
		// in-degree zero inside it; guarded so a future edge rule change can
		// never silently demote the target from row 0.
		return nil, fmt.Errorf("closure order did not start at %q", target)
	}
	return ordered, nil
}

// stackIndexHeap is ReparentClosureOrder's ready set: a min-heap of
// Stack.Branches indices, so the smallest declaration index is always emitted
// first. It is a local, dependency-free binary heap rather than container/heap
// so the ordering rule reads in one place.
type stackIndexHeap struct {
	items []int
}

func (h *stackIndexHeap) len() int { return len(h.items) }

func (h *stackIndexHeap) push(v int) {
	h.items = append(h.items, v)
	i := len(h.items) - 1
	for i > 0 {
		parent := (i - 1) / 2
		if h.items[parent] <= h.items[i] {
			break
		}
		h.items[parent], h.items[i] = h.items[i], h.items[parent]
		i = parent
	}
}

func (h *stackIndexHeap) pop() int {
	top := h.items[0]
	last := len(h.items) - 1
	h.items[0] = h.items[last]
	h.items = h.items[:last]
	i := 0
	for {
		left, right := 2*i+1, 2*i+2
		smallest := i
		if left < len(h.items) && h.items[left] < h.items[smallest] {
			smallest = left
		}
		if right < len(h.items) && h.items[right] < h.items[smallest] {
			smallest = right
		}
		if smallest == i {
			break
		}
		h.items[i], h.items[smallest] = h.items[smallest], h.items[i]
		i = smallest
	}
	return top
}

// Descendants returns all transitive children of the given branch.
func Descendants(s Stack, branch string) map[string]bool {
	children := make(map[string][]string)
	for _, e := range s.Branches {
		children[e.Base] = append(children[e.Base], e.Name)
	}

	result := make(map[string]bool)
	queue := []string{branch}
	for len(queue) > 0 {
		name := queue[0]
		queue = queue[1:]
		for _, child := range children[name] {
			if !result[child] {
				result[child] = true
				queue = append(queue, child)
			}
		}
	}
	return result
}

// PrintTree prints the stack as an indented dependency tree.
func PrintTree(s Stack) {
	children := make(map[string][]string)
	roots := make(map[string]bool)

	for _, e := range s.Branches {
		roots[e.Name] = true
	}
	for _, e := range s.Branches {
		children[e.Base] = append(children[e.Base], e.Name)
		// If base is a tracked branch, this entry is not a root
		for _, other := range s.Branches {
			if other.Name == e.Base {
				delete(roots, e.Name)
				break
			}
		}
	}

	var printNode func(name, prefix string, isLast bool)
	printNode = func(name, prefix string, isLast bool) {
		connector := "├── "
		if isLast {
			connector = "└── "
		}
		fmt.Println(prefix + connector + name)

		childPrefix := prefix
		if isLast {
			childPrefix += "    "
		} else {
			childPrefix += "│   "
		}

		kids := children[name]
		for i, child := range kids {
			printNode(child, childPrefix, i == len(kids)-1)
		}
	}

	// Print from each root's base (usually "main")
	bases := make(map[string]bool)
	for _, e := range s.Branches {
		if roots[e.Name] {
			bases[e.Base] = true
		}
	}

	for base := range bases {
		fmt.Printf("(%s)\n", base)
		kids := children[base]
		for i, child := range kids {
			printNode(child, "", i == len(kids)-1)
		}
	}

	if len(s.Branches) == 0 {
		fmt.Println("No branches tracked. Use 'ts new <feature> <branch>' to add branches.")
	}
}

// FormatBranchStatus formats a branch sync result for display.
func FormatBranchStatus(name, status string) string {
	symbols := map[string]string{
		"synced":  "+",
		"failed":  "x",
		"skipped": "-",
	}
	sym := symbols[status]
	if sym == "" {
		sym = "?"
	}
	return fmt.Sprintf("  [%s] %s", sym, name)
}

// DescendantsList returns Descendants as a sorted display string.
func DescendantsList(s Stack, branch string) string {
	descs := Descendants(s, branch)
	var names []string
	for name := range descs {
		names = append(names, name)
	}
	return strings.Join(names, ", ")
}

package internal

import (
	"errors"
	"fmt"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"unicode"
)

// ---------- Enums ----------

// StackBaseKind describes how a stack entry's base was resolved to a Git ref.
type StackBaseKind string

// StackBaseRecord describes the state of the recorded LastBaseSHA.
type StackBaseRecord string

// StackRepoSource records which candidate produced the evaluated repository.
type StackRepoSource string

// StackAncestryReason is the precise cause behind a StackEdge status.
type StackAncestryReason string

// StackNoteKind enumerates informational per-edge notes.
type StackNoteKind string

// StackBasePolicy names the sync path whose base resolution the evaluator
// compares its own probe against when emitting identity notes. It is selected
// explicitly by the caller because the two sync implementations resolve a
// configured base differently, and reporting the wrong one is a false claim.
type StackBasePolicy string

const (
	StackBaseStackEntry StackBaseKind = "stack-entry"
	StackBaseLiteralRef StackBaseKind = "literal-ref"
	StackBaseNone       StackBaseKind = "none"
)

const (
	// StackBasePolicyNone makes no claim about any sync path and therefore
	// emits no identity note at all.
	StackBasePolicyNone StackBasePolicy = ""
	// StackBasePolicyRemoteDefault mirrors external sync, which maps a base
	// equal to the repository default branch to `origin/<default>`.
	StackBasePolicyRemoteDefault StackBasePolicy = "remote-default"
	// StackBasePolicyLiteralEntry mirrors checkout sync, which resolves
	// `entry.Base` literally instead of through the parent's GitBranch().
	StackBasePolicyLiteralEntry StackBasePolicy = "literal-entry"
)

// StackAncestryOptions carries the evaluator behaviour that depends on which
// sync path the caller's workspace mode would actually run. The zero value is
// safe: it emits no identity notes.
type StackAncestryOptions struct {
	BasePolicy StackBasePolicy
}

// StackBasePolicyForMode maps a workspace mode to the base resolution its sync
// path actually performs. External sync resolves the default branch through
// `origin/<default>`; checkout sync resolves `entry.Base` literally.
func StackBasePolicyForMode(mode WorkspaceMode) StackBasePolicy {
	if mode == ModeCheckout {
		return StackBasePolicyLiteralEntry
	}
	return StackBasePolicyRemoteDefault
}

const (
	StackBaseRecordAbsent       StackBaseRecord = "absent"
	StackBaseRecordPresent      StackBaseRecord = "present"
	StackBaseRecordUnresolvable StackBaseRecord = "unresolvable"
)

const (
	StackRepoWorkspace   StackRepoSource = "workspace"
	StackRepoWorktree    StackRepoSource = "worktree"
	StackRepoInferred    StackRepoSource = "inferred"
	StackRepoUnavailable StackRepoSource = "unavailable"
)

const (
	ReasonParentContained            StackAncestryReason = "parent-contained"
	ReasonParentAdvanced             StackAncestryReason = "parent-advanced"
	ReasonParentAdvancedNoBaseRecord StackAncestryReason = "parent-advanced-no-base-record"
	ReasonBaseRecordUnresolvable     StackAncestryReason = "base-record-unresolvable"
	ReasonBaseRewritten              StackAncestryReason = "base-rewritten"
	ReasonUnrelatedHistories         StackAncestryReason = "unrelated-histories"
	ReasonChildRefMissing            StackAncestryReason = "child-ref-missing"
	ReasonBaseRefMissing             StackAncestryReason = "base-ref-missing"
	ReasonCrossRepo                  StackAncestryReason = "cross-repo"
	ReasonBaseUnset                  StackAncestryReason = "base-unset"
	ReasonRepoUnavailable            StackAncestryReason = "repo-unavailable"
	ReasonAncestryProbeFailed        StackAncestryReason = "ancestry-probe-failed"
)

const (
	NoteBaseIdentityRemoteMismatch  StackNoteKind = "base-identity-remote-mismatch"
	NoteBaseIdentityLiteralMismatch StackNoteKind = "base-identity-literal-mismatch"
)

// RepoSourceMismatchLabel names the feature-level condition raised when the
// workspace and the feature's own worktree evidence resolve to two different
// main repository roots. It is derived from StackRepoResolution.Alternate and
// is never stored on a StackEdge.
const RepoSourceMismatchLabel = "repo-source-mismatch"

// ancestryUnevaluatedToken is the single source of the human display token for
// an edge that reached no ancestry conclusion. It is never an AncestryStatus.
const ancestryUnevaluatedToken = "unevaluated"

// ancestrySanitizeLimit bounds recorded metadata echoed back to the user.
const ancestrySanitizeLimit = 40

// ancestryPathLimit bounds filesystem paths echoed back to the user. Paths are
// routinely longer than a ref name and a 40-rune prefix identifies nothing.
const ancestryPathLimit = 200

// ancestryDetailLimit bounds error text echoed back to the user.
const ancestryDetailLimit = 200

// ancestryFullSHA matches a peeled object name exactly. rev-parse output is
// validated against it so a malformed or ambiguous answer is never carried
// into a comparison or into a command shown to the user.
var ancestryFullSHA = regexp.MustCompile(`^[0-9a-f]{40}$`)

// ancestryPlainCommandToken matches the tokens that need no shell quoting when
// interpolated into a runnable command.
var ancestryPlainCommandToken = regexp.MustCompile(`^[A-Za-z0-9._/@+-]+$`)

// ErrRepoUnavailable is returned when ancestry evaluation cannot start because
// the source repository directory is empty or is not a Git repository.
var ErrRepoUnavailable = errors.New("stack ancestry: source repository unavailable")

// ---------- Structs ----------

// StackEdgeNote is an informational observation attached to one edge. It never
// changes status, severity, or any issue count.
type StackEdgeNote struct {
	Kind   StackNoteKind `json:"kind"`
	Detail string        `json:"detail"`
}

// StackEdge is the read-only projection of one configured parent-child edge.
type StackEdge struct {
	Feature   string `json:"feature"`
	Name      string `json:"name"`
	GitBranch string `json:"git_branch"`
	Archived  bool   `json:"archived"`
	Repo      string `json:"repo,omitempty"`

	BaseName string        `json:"base_name"`
	BaseKind StackBaseKind `json:"base_kind"`
	BaseRef  string        `json:"base_ref,omitempty"`

	ChildRef  string `json:"child_ref,omitempty"`
	RefExists bool   `json:"ref_exists"`
	RefProbed bool   `json:"ref_probed"`

	LocalHead       string  `json:"local_head,omitempty"`
	LocalHeadShort  string  `json:"local_head_short,omitempty"`
	ParentHead      string  `json:"parent_head,omitempty"`
	ParentHeadShort string  `json:"parent_head_short,omitempty"`
	MergeBase       *string `json:"merge_base"`
	MergeBaseShort  string  `json:"merge_base_short,omitempty"`

	LastBaseSHA    string          `json:"last_base_sha,omitempty"`
	LastBaseCommit string          `json:"last_base_commit,omitempty"`
	LastBaseShort  string          `json:"last_base_short,omitempty"`
	BaseRecord     StackBaseRecord `json:"base_record"`

	Status   AncestryStatus      `json:"status"`
	Reason   StackAncestryReason `json:"reason"`
	Severity CheckoutSeverity    `json:"severity"`
	Guidance string              `json:"guidance,omitempty"`
	Notes    []StackEdgeNote     `json:"notes,omitempty"`

	RepoSource StackRepoSource `json:"repo_source"`
}

// StackRepoResolution is the outcome of mode-aware repository selection.
type StackRepoResolution struct {
	RepoDir   string
	Source    StackRepoSource
	Alternate string
	Reason    string
}

type refResolution struct {
	full  string
	short string
	ok    bool
}

// ancestryEvaluator holds the per-evaluation caches. It is never global, never
// persisted, and never shared between calls.
type ancestryEvaluator struct {
	repoDir       string
	basePolicy    StackBasePolicy
	refs          map[string]refResolution
	shorts        map[string]string
	defaultBranch string
	defaultDone   bool
}

// ---------- Git runner ----------

// ancestryGit builds a read-only Git invocation rooted at a pre-validated,
// non-empty repository directory. cmd.Dir is used rather than -C so results
// never depend on the caller's working directory.
func ancestryGit(repoDir string, args ...string) *exec.Cmd {
	cmd := exec.Command("git", args...)
	cmd.Dir = repoDir
	cmd.Stderr = nil
	return cmd
}

// ---------- Primitives ----------

func newAncestryEvaluator(repoDir string, opts StackAncestryOptions) (*ancestryEvaluator, error) {
	if repoDir == "" {
		return nil, fmt.Errorf("%w: %s", ErrRepoUnavailable, "empty repository directory")
	}
	if _, err := MainRepoRootIn(repoDir); err != nil {
		return nil, fmt.Errorf("%w: %s is not a git repository", ErrRepoUnavailable, ancestrySanitize(repoDir, ancestryPathLimit))
	}
	return &ancestryEvaluator{
		repoDir:    repoDir,
		basePolicy: opts.BasePolicy,
		refs:       make(map[string]refResolution),
		shorts:     make(map[string]string),
	}, nil
}

// resolveCommit peels ref to a commit. Negative results are cached, so a
// repeated unresolvable ref costs one process for the whole evaluation. Output
// that is not structurally a full object name is treated as no answer at all.
func (ev *ancestryEvaluator) resolveCommit(ref string) (string, string, bool) {
	if cached, ok := ev.refs[ref]; ok {
		return cached.full, cached.short, cached.ok
	}
	var res refResolution
	out, err := ancestryGit(ev.repoDir, "rev-parse", "--verify", "--quiet", "--end-of-options", ref+"^{commit}").Output()
	if err == nil {
		if full := strings.TrimSpace(string(out)); ancestryFullSHA.MatchString(full) {
			res.full = full
			res.ok = true
		}
	}
	if res.ok {
		res.short = ev.abbrev(res.full)
	}
	ev.refs[ref] = res
	return res.full, res.short, res.ok
}

func (ev *ancestryEvaluator) abbrev(full string) string {
	if full == "" {
		return ""
	}
	if cached, ok := ev.shorts[full]; ok {
		return cached
	}
	short := ""
	if out, err := ancestryGit(ev.repoDir, "rev-parse", "--short", full).Output(); err == nil {
		short = strings.TrimSpace(string(out))
	}
	if short == "" {
		if len(full) > 12 {
			short = full[:12]
		} else {
			short = full
		}
	}
	ev.shorts[full] = short
	return short
}

func (ev *ancestryEvaluator) defaultBranchName() string {
	if ev.defaultDone {
		return ev.defaultBranch
	}
	ev.defaultDone = true
	branch, err := DefaultBranchIn(ev.repoDir)
	if err != nil {
		branch = ""
	}
	ev.defaultBranch = branch
	return branch
}

// ancestryMergeBase reports the merge base of two peeled commits. Exit 1 with
// empty stdout means "no merge base"; any other non-zero exit is an error and
// is never read as a normal answer.
func ancestryMergeBase(repoDir, a, b string) (string, bool, error) {
	out, err := ancestryGit(repoDir, "merge-base", a, b).Output()
	trimmed := strings.TrimSpace(string(out))
	if err == nil {
		if trimmed == "" {
			return "", false, nil
		}
		return trimmed, true, nil
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 && trimmed == "" {
		return "", false, nil
	}
	return "", false, err
}

// ---------- Classification ----------

// stackBaseRef selects the ref actually probed for an entry's base. A logical
// stack-entry name wins over a literal ref, matching GetBranch's first-match
// order.
func stackBaseRef(stack Stack, se StackEntry) (string, StackBaseKind) {
	if se.Base == "" {
		return "", StackBaseNone
	}
	for _, parent := range stack.Branches {
		if parent.Name == se.Base {
			return "refs/heads/" + parent.GitBranch(), StackBaseStackEntry
		}
	}
	return se.Base, StackBaseLiteralRef
}

func ancestrySeverity(status AncestryStatus, archived bool) CheckoutSeverity {
	switch status {
	case AncestryStatusCurrent:
		return SeverityOK
	case AncestryStatusStale, AncestryStatusDivergent, AncestryStatusMissing:
		if archived {
			return SeverityInfo
		}
		return SeverityWarning
	default:
		return SeverityInfo
	}
}

// newStackEdge fills the identity and base-selection fields that every edge
// carries, whatever happens afterwards. BaseRecord is deliberately left at its
// zero value: it is a statement about an evaluation that has not run yet, and
// claiming `absent` here would be a claim the evaluator cannot support.
func newStackEdge(feature string, se StackEntry, stack Stack) StackEdge {
	baseRef, baseKind := stackBaseRef(stack, se)
	return StackEdge{
		Feature:     feature,
		Name:        se.Name,
		GitBranch:   se.GitBranch(),
		Archived:    se.Archived,
		Repo:        se.Repo,
		BaseName:    se.Base,
		BaseKind:    baseKind,
		BaseRef:     baseRef,
		LastBaseSHA: se.LastBaseSHA,
	}
}

func finishStackEdge(e StackEdge, status AncestryStatus, reason StackAncestryReason, detail string) StackEdge {
	e.Status = status
	e.Reason = reason
	e.Severity = ancestrySeverity(status, e.Archived)
	e.Guidance = ancestryGuidance(e, detail)
	return e
}

func (ev *ancestryEvaluator) edge(feature string, se StackEntry, stack Stack) StackEdge {
	e := newStackEdge(feature, se, stack)

	// Rule 1: a cross-repo entry is a metadata-only decision. No Git process
	// is started for it, against any path.
	if se.Repo != "" {
		return finishStackEdge(e, AncestryStatusCrossRepo, ReasonCrossRepo, "")
	}
	// Rule 2: nothing to compare against.
	if se.Base == "" {
		return finishStackEdge(e, "", ReasonBaseUnset, "")
	}

	// Rule 3: the child ref, always through refs/heads/ so a same-named tag
	// can never win.
	e.ChildRef = "refs/heads/" + e.GitBranch
	e.RefProbed = true
	childFull, childShort, childOK := ev.resolveCommit(e.ChildRef)
	if !childOK {
		return finishStackEdge(e, AncestryStatusMissing, ReasonChildRefMissing, "")
	}
	e.RefExists = true
	e.LocalHead = childFull
	e.LocalHeadShort = childShort

	// Rule 5: the base ref, exactly as selected above.
	parentFull, parentShort, parentOK := ev.resolveCommit(e.BaseRef)
	if !parentOK {
		return finishStackEdge(e, AncestryStatusMissing, ReasonBaseRefMissing, "")
	}
	e.ParentHead = parentFull
	e.ParentHeadShort = parentShort

	// Rule 6: the recorded base commit, peeled because both writers record an
	// unpeeled rev-parse result. This is the first point at which the record
	// is actually consulted, so it is also the first point at which any
	// BaseRecord verdict — including `absent` — can be stated truthfully.
	if se.LastBaseSHA == "" {
		e.BaseRecord = StackBaseRecordAbsent
	} else if lastFull, lastShort, ok := ev.resolveCommit(se.LastBaseSHA); ok {
		e.BaseRecord = StackBaseRecordPresent
		e.LastBaseCommit = lastFull
		e.LastBaseShort = lastShort
	} else {
		e.BaseRecord = StackBaseRecordUnresolvable
	}

	e = ev.classify(e)
	if e.Status != "" && e.Status != AncestryStatusCrossRepo {
		e.Notes = ev.identityNotes(e)
	}
	return e
}

// classify applies the first-match classification table. Order is normative.
func (ev *ancestryEvaluator) classify(e StackEdge) StackEdge {
	// 1. The parent is already contained in the child: nothing to replay,
	// whichever way the parent moved.
	contained, err := gitIsAncestor(ev.repoDir, e.ParentHead, e.LocalHead)
	if err != nil {
		return finishStackEdge(e, "", ReasonAncestryProbeFailed, err.Error())
	}
	if contained {
		merge := e.ParentHead
		e.MergeBase = &merge
		e.MergeBaseShort = ev.abbrev(merge)
		return finishStackEdge(e, AncestryStatusCurrent, ReasonParentContained, "")
	}

	// 2. Unrelated histories get their own reason instead of a rewrite claim.
	mergeBase, exists, mbErr := ancestryMergeBase(ev.repoDir, e.LocalHead, e.ParentHead)
	if mbErr != nil {
		return finishStackEdge(e, "", ReasonAncestryProbeFailed, mbErr.Error())
	}
	if !exists {
		return finishStackEdge(e, AncestryStatusDivergent, ReasonUnrelatedHistories, "")
	}
	merge := mergeBase
	e.MergeBase = &merge
	e.MergeBaseShort = ev.abbrev(merge)

	// 4/5. A resolvable record separates "the parent advanced" from "the
	// parent's history was rewritten".
	if e.BaseRecord == StackBaseRecordPresent {
		recorded, recErr := gitIsAncestor(ev.repoDir, e.LastBaseCommit, e.ParentHead)
		switch {
		case recErr != nil:
			// Degrade to rule 3 rather than reading a fatal exit as "no".
			e.BaseRecord = StackBaseRecordUnresolvable
			e.LastBaseCommit = ""
			e.LastBaseShort = ""
		case !recorded:
			return finishStackEdge(e, AncestryStatusDivergent, ReasonBaseRewritten, "")
		default:
			return finishStackEdge(e, AncestryStatusStale, ReasonParentAdvanced, "")
		}
	}

	// 3. A recorded base that is not in this repository can support no claim.
	if e.BaseRecord == StackBaseRecordUnresolvable {
		return finishStackEdge(e, AncestryStatusStale, ReasonBaseRecordUnresolvable, "")
	}

	// 6. Nothing was ever recorded.
	return finishStackEdge(e, AncestryStatusStale, ReasonParentAdvancedNoBaseRecord, "")
}

// identityNotes reports, without acting on it, that the caller's sync path
// would resolve this edge's base to a different commit than the one doctor
// probed. Only the policy the caller selected can be reported: emitting the
// other mode's note would describe a sync path that will never run here.
func (ev *ancestryEvaluator) identityNotes(e StackEdge) []StackEdgeNote {
	if e.ParentHead == "" {
		return nil
	}
	switch ev.basePolicy {
	case StackBasePolicyRemoteDefault:
		return ev.remoteMismatchNotes(e)
	case StackBasePolicyLiteralEntry:
		return ev.literalMismatchNotes(e)
	default:
		return nil
	}
}

// remoteMismatchNotes mirrors external sync, which maps a base equal to the
// default branch to origin/<default> and records that SHA.
func (ev *ancestryEvaluator) remoteMismatchNotes(e StackEdge) []StackEdgeNote {
	if e.BaseKind != StackBaseLiteralRef {
		return nil
	}
	if e.BaseName == "" || e.BaseName != ev.defaultBranchName() {
		return nil
	}
	altFull, altShort, ok := ev.resolveCommit("refs/remotes/origin/" + e.BaseName)
	if !ok || altFull == e.ParentHead {
		return nil
	}
	return []StackEdgeNote{{
		Kind: NoteBaseIdentityRemoteMismatch,
		Detail: fmt.Sprintf("base %q is probed as %s, but tws sync resolves it as origin/%s (%s)",
			ancestrySanitize(e.BaseName, ancestrySanitizeLimit), e.ParentHeadShort,
			ancestrySanitize(e.BaseName, ancestrySanitizeLimit), altShort),
	}}
}

// literalMismatchNotes mirrors checkout sync, which resolves entry.Base
// literally instead of through the parent entry's GitBranch().
func (ev *ancestryEvaluator) literalMismatchNotes(e StackEdge) []StackEdgeNote {
	if e.BaseKind != StackBaseStackEntry {
		return nil
	}
	parentBranch := strings.TrimPrefix(e.BaseRef, "refs/heads/")
	if parentBranch == e.BaseName {
		return nil
	}
	altFull, altShort, ok := ev.resolveCommit(e.BaseName)
	if !ok || altFull == e.ParentHead {
		return nil
	}
	return []StackEdgeNote{{
		Kind: NoteBaseIdentityLiteralMismatch,
		Detail: fmt.Sprintf("base name %q also resolves as a literal ref to %s, which differs from parent branch %q (%s); checkout sync resolves the literal name",
			ancestrySanitize(e.BaseName, ancestrySanitizeLimit), altShort,
			ancestrySanitize(parentBranch, ancestrySanitizeLimit), e.ParentHeadShort),
	}}
}

// ---------- Presentation ----------

// ancestryDisplayStatus is the only producer of the unevaluated display token.
func ancestryDisplayStatus(s AncestryStatus) string {
	if s == "" {
		return ancestryUnevaluatedToken
	}
	return string(s)
}

// ancestrySanitize replaces non-printable runes and bounds length. It is a
// display rule only; classification always uses raw values.
func ancestrySanitize(s string, limit int) string {
	var b strings.Builder
	count := 0
	truncated := false
	for _, r := range s {
		if count >= limit {
			truncated = true
			break
		}
		if unicode.IsPrint(r) {
			b.WriteRune(r)
		} else {
			b.WriteRune('?')
		}
		count++
	}
	if truncated {
		b.WriteRune('…')
	}
	return b.String()
}

// ancestryCommandToken renders a Git-validated ref or object name for
// interpolation into a runnable command. Control characters are replaced, but
// the token is never truncated: a shortened ref or SHA yields a command that
// silently targets the wrong thing or does not run at all. Anything outside
// the portable unquoted set is single-quoted so the command stays pasteable.
func ancestryCommandToken(s string) string {
	if s == "" {
		return ""
	}
	var b strings.Builder
	for _, r := range s {
		if unicode.IsPrint(r) {
			b.WriteRune(r)
		} else {
			b.WriteRune('?')
		}
	}
	token := b.String()
	if ancestryPlainCommandToken.MatchString(token) {
		return token
	}
	return "'" + strings.ReplaceAll(token, "'", `'\''`) + "'"
}

// ancestryChildCommandToken is the child branch the repair command must name
// explicitly, so the rebase can never take whatever happens to be checked out
// as its target.
//
// It is the bare branch name, not `refs/heads/<branch>`: `git rebase`'s third
// argument is checked out, and a fully-qualified ref does not resolve to a
// branch there — Git would detach HEAD, replay onto the detached HEAD, and
// leave the child branch untouched. A bare name resolves to the branch even
// when a tag shares the name, which is exactly the target intended here.
func ancestryChildCommandToken(e StackEdge) string {
	if e.GitBranch == "" {
		return ""
	}
	return ancestryCommandToken(e.GitBranch)
}

// ancestryDetail reduces arbitrary error text to a single sanitized line.
func ancestryDetail(detail string) string {
	line := detail
	if idx := strings.IndexAny(line, "\r\n"); idx >= 0 {
		line = line[:idx]
	}
	return ancestrySanitize(strings.TrimSpace(line), ancestryDetailLimit)
}

// ancestryGuidance is pure and total over every reason. It never returns a
// string containing a newline. Prose interpolations stay abbreviated for
// readability; every token inside a backticked command is complete.
func ancestryGuidance(e StackEdge, detail string) string {
	feature := ancestrySanitize(e.Feature, ancestrySanitizeLimit)
	name := ancestrySanitize(e.Name, ancestrySanitizeLimit)
	branch := ancestrySanitize(e.GitBranch, ancestrySanitizeLimit)
	baseRef := ancestrySanitize(e.BaseRef, ancestrySanitizeLimit)
	parent := e.ParentHeadShort

	recorded := e.LastBaseShort
	if e.BaseRecord != StackBaseRecordPresent {
		recorded = fmt.Sprintf("%q", ancestrySanitize(e.LastBaseSHA, ancestrySanitizeLimit))
	}

	switch e.Reason {
	case ReasonParentContained:
		return ""
	case ReasonParentAdvanced:
		return fmt.Sprintf("parent `%s` advanced to %s; run: tws sync %s", baseRef, parent, feature)
	case ReasonParentAdvancedNoBaseRecord:
		return fmt.Sprintf("parent `%s` advanced to %s; no recorded base commit for this branch, so sync uses a plain rebase — verify the parent history was not rewritten; run: tws sync %s", baseRef, parent, feature)
	case ReasonBaseRecordUnresolvable:
		return fmt.Sprintf("recorded base commit %s is not present in this repository; the replay strategy cannot be verified — inspect before running: tws sync %s", recorded, feature)
	case ReasonBaseRewritten:
		return fmt.Sprintf("recorded base commit %s is no longer in `%s` history;%s run: tws sync %s",
			recorded, baseRef, ancestryRebaseRepair(e), feature)
	case ReasonUnrelatedHistories:
		return fmt.Sprintf("`%s` and `%s` share no common history; check the configured base — a rebase would replay every commit", branch, baseRef)
	case ReasonChildRefMissing:
		if e.Archived {
			return fmt.Sprintf("archived branch `%s` has no git ref", branch)
		}
		// The stack entry already exists, so no creation command applies here.
		// The only honest recoveries are restoring the Git branch or
		// deliberately changing the recorded stack.
		return fmt.Sprintf("git branch `%s` does not exist while stack entry %q of feature %s is still configured; restore the branch from its remote or from a known commit, for example `git branch %s <known-commit>`, or deliberately remove and recreate the stack entry if no work must be preserved",
			branch, name, feature, ancestryCommandToken(e.GitBranch))
	case ReasonBaseRefMissing:
		return fmt.Sprintf("base ref `%s` does not exist; restore it or update `base` in stack.yaml", baseRef)
	case ReasonCrossRepo:
		return fmt.Sprintf("entry targets another repository (%s); cross-repo ancestry is not evaluated, so this edge is reported as cross-repo-unsupported", ancestrySanitize(e.Repo, ancestryPathLimit))
	case ReasonBaseUnset:
		return "no base configured for this entry; ancestry is not evaluated"
	case ReasonRepoUnavailable:
		return fmt.Sprintf("source repository could not be determined; ancestry is not evaluated (%s)", ancestryDetail(detail))
	case ReasonAncestryProbeFailed:
		return fmt.Sprintf("ancestry probe failed (%s); refs may have changed during evaluation — the recorded base was not consulted; re-run: tws doctor %s", ancestryDetail(detail), feature)
	default:
		return ""
	}
}

// ancestryRebaseRepair renders the complete `--onto` repair command, including
// the explicit target child branch. It is emitted only when every token is a
// value the evaluator itself resolved, so the command is always complete and
// pasteable, never a truncated fragment; otherwise the guidance simply omits
// it. It carries the same precondition tws sync's own `--onto` invocation
// carries — the recorded base is used as `<upstream>` in both — so it is
// offered as an equivalent repair, not as a guarantee about the child's own
// history.
//
// The wording deliberately stops at "an --onto rebase": the two sync paths do
// not run the same command. External sync adds `--update-refs` and rebases the
// checked-out worktree branch; checkout sync adds `--no-fork-point` and rebases
// onto the resolved new base SHA. Promising an identical strategy would be a
// claim this evaluator cannot support.
func ancestryRebaseRepair(e StackEdge) string {
	child := ancestryChildCommandToken(e)
	base := ancestryCommandToken(e.BaseRef)
	if child == "" || base == "" || !ancestryFullSHA.MatchString(e.LastBaseCommit) {
		return ""
	}
	return fmt.Sprintf(" an equivalent manual repair is `git rebase --onto %s %s %s`; tws sync also replays this edge with an --onto rebase, using the flags its own workspace mode requires;",
		base, e.LastBaseCommit, child)
}

// ---------- Core API ----------

// EvaluateStackAncestry classifies every configured edge of one feature's
// stack against a validated repository directory. It is mode-independent,
// strictly read-only, and never writes Git or metadata state. The caller
// states which sync path's base policy the identity notes should describe;
// the zero options value emits no notes.
func EvaluateStackAncestry(repoDir, feature string, stack Stack, opts StackAncestryOptions) ([]StackEdge, error) {
	ev, err := newAncestryEvaluator(repoDir, opts)
	if err != nil {
		return nil, err
	}
	edges := make([]StackEdge, 0, len(stack.Branches))
	for _, se := range stack.Branches {
		edges = append(edges, ev.edge(feature, se, stack))
	}
	return edges, nil
}

// EvaluateStackEdge is the single-edge form. It allocates a fresh cache and
// applies the same repository validation and base policy.
func EvaluateStackEdge(repoDir, feature string, se StackEntry, stack Stack, opts StackAncestryOptions) (StackEdge, error) {
	ev, err := newAncestryEvaluator(repoDir, opts)
	if err != nil {
		return StackEdge{}, err
	}
	return ev.edge(feature, se, stack), nil
}

// UnevaluatedStackEdges projects a stack without starting any Git process.
// Cross-repo and base-less entries keep their own meaning so an entry never
// changes classification merely because the repository was unresolvable.
func UnevaluatedStackEdges(feature string, stack Stack, reason StackAncestryReason, detail string) []StackEdge {
	edges := make([]StackEdge, 0, len(stack.Branches))
	for _, se := range stack.Branches {
		e := newStackEdge(feature, se, stack)
		e.RepoSource = StackRepoUnavailable
		switch {
		case se.Repo != "":
			e = finishStackEdge(e, AncestryStatusCrossRepo, ReasonCrossRepo, "")
		case se.Base == "":
			e = finishStackEdge(e, "", ReasonBaseUnset, "")
		default:
			e = finishStackEdge(e, "", reason, detail)
		}
		edges = append(edges, e)
	}
	return edges
}

// ---------- Mode-aware adapter ----------

// ancestryRepoCandidate normalises a filesystem path to a canonical main
// repository root, or reports that it is not usable. It never runs Git on an
// empty path.
func ancestryRepoCandidate(path string) (string, bool) {
	if path == "" {
		return "", false
	}
	root, err := MainRepoRootIn(path)
	if err != nil {
		return "", false
	}
	return canonicalize(root), true
}

// ancestryWorktreeCandidatePath contains an untrusted logical entry name below
// the feature's worktrees directory before any Git process is started.
func ancestryWorktreeCandidatePath(featurePath, name string) (string, error) {
	if name == "" || !filepath.IsLocal(name) || filepath.Clean(name) == "." {
		return "", fmt.Errorf("unsafe stack entry name %q", ancestrySanitize(name, ancestrySanitizeLimit))
	}
	worktreesRoot := filepath.Join(featurePath, "worktrees")
	candidate := filepath.Join(worktreesRoot, name)
	canonRoot := canonicalize(worktreesRoot)
	canonCandidate := canonicalize(candidate)
	rel, err := filepath.Rel(canonRoot, canonCandidate)
	if err != nil || rel == "." || !filepath.IsLocal(rel) {
		return "", fmt.Errorf("stack entry %q resolves outside the feature worktrees directory", ancestrySanitize(name, ancestrySanitizeLimit))
	}
	return candidate, nil
}

// ResolveStackAncestryRepo is the only mode-aware code in this feature. It
// returns a canonical main repository root, never a linked-worktree path.
func ResolveStackAncestryRepo(ws Workspace, cfg Config, featurePath string, stack Stack) StackRepoResolution {
	if ws.Mode == ModeCheckout {
		if root, ok := ancestryRepoCandidate(ws.RepoRoot); ok {
			return StackRepoResolution{RepoDir: root, Source: StackRepoWorkspace}
		}
		return StackRepoResolution{
			Source: StackRepoUnavailable,
			Reason: "checkout workspace repository root is not a git repository",
		}
	}

	// Candidate 1 — feature-scoped worktree evidence. It is the only source
	// that stays correct when TWS_ROOT points at another repository.
	for _, se := range stack.Branches {
		if se.Repo != "" || se.Archived {
			continue
		}
		candidate, err := ancestryWorktreeCandidatePath(featurePath, se.Name)
		if err != nil {
			return StackRepoResolution{Source: StackRepoUnavailable, Reason: err.Error()}
		}
		root, ok := ancestryRepoCandidate(candidate)
		if !ok {
			continue
		}
		res := StackRepoResolution{RepoDir: root, Source: StackRepoWorktree}
		if alt, altOK := ancestryRepoCandidate(ws.RepoRoot); altOK && alt != root {
			res.Alternate = alt
		}
		return res
	}

	// Candidate 2 — the resolved workspace repository root.
	if root, ok := ancestryRepoCandidate(ws.RepoRoot); ok {
		return StackRepoResolution{RepoDir: root, Source: StackRepoWorkspace}
	}

	// Candidate 3 — inference from the metadata root.
	metadataRoot := ws.MetadataRoot
	if metadataRoot == "" {
		metadataRoot = filepath.Dir(featurePath)
	}
	if metadataRoot != "" {
		inferred, err := inferExternalRepoRoot(metadataRoot, cfg)
		if err == nil && inferred != "" {
			return StackRepoResolution{RepoDir: canonicalize(inferred), Source: StackRepoInferred}
		}
		if err != nil {
			return StackRepoResolution{Source: StackRepoUnavailable, Reason: err.Error()}
		}
	}
	return StackRepoResolution{
		Source: StackRepoUnavailable,
		Reason: fmt.Sprintf("no source repository for feature %s", ancestrySanitize(filepath.Base(featurePath), ancestrySanitizeLimit)),
	}
}

// FeatureStackEdges resolves the repository for one feature and evaluates its
// stack. It fails soft: an unusable repository yields unevaluated edges, never
// an error and never a false ancestry claim. The identity-note base policy is
// selected from the workspace mode, so an edge only ever reports the base
// resolution the sync path that would actually run performs.
func FeatureStackEdges(ws Workspace, cfg Config, feature, featurePath string, stack Stack) ([]StackEdge, StackRepoResolution) {
	res := ResolveStackAncestryRepo(ws, cfg, featurePath, stack)
	if res.RepoDir == "" {
		return UnevaluatedStackEdges(feature, stack, ReasonRepoUnavailable, res.Reason), res
	}
	opts := StackAncestryOptions{BasePolicy: StackBasePolicyForMode(ws.Mode)}
	edges, err := EvaluateStackAncestry(res.RepoDir, feature, stack, opts)
	if err != nil {
		failed := StackRepoResolution{Source: StackRepoUnavailable, Reason: err.Error()}
		return UnevaluatedStackEdges(feature, stack, ReasonRepoUnavailable, err.Error()), failed
	}
	for i := range edges {
		edges[i].RepoSource = res.Source
	}
	return edges, res
}

// ---------------------------------------------------------------------------
// §11.10 rule 2 — the ancestry guidance suppression seam
//
// This is a SEAM ONLY: no ancestry decision changes. EvaluateStackAncestry,
// FeatureStackEdges, stackBaseRef and ancestryMergeBase are untouched, every
// edge keeps its Status, Reason, Severity and Notes, and only the repair
// GUIDANCE — the `tws sync <feature>` / manual `git rebase --onto` advice — is
// withheld while a reparent artifact exists. Following that advice mid-reparent
// would bypass the transaction, and the sync verbs it names are refused by
// §11.2 anyway.
// ---------------------------------------------------------------------------

// SuppressReparentAncestryGuidance returns a copy of edges with every
// Guidance string cleared. Notes keep their own details: a note is an
// observation, never an instruction to run a refused verb.
func SuppressReparentAncestryGuidance(edges []StackEdge) []StackEdge {
	out := make([]StackEdge, len(edges))
	copy(out, edges)
	for i := range out {
		out[i].Guidance = ""
	}
	return out
}

// ReparentGuidanceSuppressed answers whether a surface must apply the seam for
// one feature of one workspace. It is a bare os.Stat through
// HasReparentState: strictly read-only, no decode, no Git child, and it never
// evaluates the §12.3 remote follow-up record.
func ReparentGuidanceSuppressed(ws Workspace, feature, featurePath string) bool {
	return HasReparentState(ReparentLocationFor(ws, feature, featurePath))
}

package internal

import (
	"bytes"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// ---------- Constants ----------

// stackStatusSchema versions the stack status document. It is this document's
// own version and is independent of agentStatusSchema. Adding a key or an enum
// value is additive; removing a key, changing a type, or narrowing an enum
// bumps it.
const stackStatusSchema = 1

// stackStatusSanitizeLimit bounds dynamic values echoed into human output.
// Paths, branch names, and upstream displays are routinely longer than a ref
// name, so the ancestry evaluator's 40-rune metadata limit is too small here.
const stackStatusSanitizeLimit = 120

// StackStatusOpNone is the only value that means "the Git directory was
// resolved, verified, and carries no operation marker". A probe failure is
// never reported as this value.
const StackStatusOpNone = "none"

// Materialization kinds.
const (
	StackStatusKindWorktree = "worktree"
	StackStatusKindRef      = "ref"
)

// Materialization states.
const (
	StackStatusMaterializedPresent         = "present"
	StackStatusMaterializedArchived        = "archived"
	StackStatusMaterializedMissing         = "missing"
	StackStatusMaterializedPrunableMissing = "prunable-missing"
	StackStatusMaterializedCrossRepo       = "cross-repo-unsupported"
	StackStatusMaterializedUnknown         = "unknown"
)

// Upstream states.
const (
	StackStatusUpstreamNone     = "none"
	StackStatusUpstreamEqual    = "equal"
	StackStatusUpstreamAhead    = "ahead"
	StackStatusUpstreamBehind   = "behind"
	StackStatusUpstreamDiverged = "diverged"
	StackStatusUpstreamGone     = "gone"
)

// stackStatusRefFormat is the branch-ref inventory format. Fields are
// NUL-separated so no printable delimiter can appear inside a value, and only
// full refs are requested so a same-named tag can never win a lookup.
const stackStatusRefFormat = "%(refname)%00%(objectname)%00%(upstream)%00%(upstream:track)%00%(upstream:trackshort)"

const stackStatusHeadsPrefix = "refs/heads/"

// stackStatusObjectID matches an inventory object ID. It is object-format
// neutral on purpose: a SHA-256 repository prints 64 hex characters where a
// SHA-1 repository prints 40, and neither inventory may invalidate merely
// because the repository's object format is not SHA-1. It is parser validation
// only — it gates no identity claim, comparison, truncation, or derivation.
var stackStatusObjectID = regexp.MustCompile(`^[0-9a-f]+$`)

// stackStatusDecimal matches a non-negative decimal integer with no sign and
// no surrounding whitespace.
var stackStatusDecimal = regexp.MustCompile(`^[0-9]+$`)

// ---------- Report types ----------
//
// No field below is ever omitted when empty: every key is present in every
// document, absent scalars are null, and lists are never null.

// StackStatusReport is one versioned stack status document.
type StackStatusReport struct {
	SchemaVersion int                  `json:"schema_version"`
	Workspace     StackStatusWorkspace `json:"workspace"`
	Feature       string               `json:"feature"`
	Entries       []StackStatusEntry   `json:"entries"`
	Summary       StackStatusSummary   `json:"summary"`

	// Reparent is the §11.10 projection of an in-progress safe reparent. It is
	// the ONE deliberate exception to the "no field is ever omitted" rule
	// above: declaring it omitempty with a POINTER value keeps the key ABSENT
	// — never null — whenever no artifact exists, which is what leaves the
	// no-reparent document byte-identical to today and SchemaVersion at 1.
	Reparent *ReparentProjection `json:"reparent,omitempty"`
}

// StackStatusWorkspace describes the resolved workspace. Exactly one of
// External and Checkout is non-nil, selected by the workspace mode.
type StackStatusWorkspace struct {
	Mode         WorkspaceMode         `json:"mode"`
	StableID     *string               `json:"stable_id"`
	MetadataRoot string                `json:"metadata_root"`
	Repository   StackStatusRepository `json:"repository"`
	External     *StackStatusExternal  `json:"external"`
	Checkout     *StackStatusCheckout  `json:"checkout"`
}

// StackStatusRepository is the single repository resolution the shared
// ancestry evaluator already performed. It is never rediscovered here.
type StackStatusRepository struct {
	Dir       *string         `json:"dir"`
	Source    StackRepoSource `json:"source"`
	Alternate *string         `json:"alternate"`
}

// StackStatusExternal carries only the worktrees root: external mode has many
// linked worktrees and no single current checkout.
type StackStatusExternal struct {
	WorktreesRoot string `json:"worktrees_root"`
}

// StackStatusCheckout describes the single physical checkout of a checkout
// workspace. Every fact that could not be established locally is null.
type StackStatusCheckout struct {
	Path        *string `json:"path"`
	Branch      *string `json:"branch"`
	Detached    *bool   `json:"detached"`
	Dirty       *bool   `json:"dirty"`
	ActiveGitOp *string `json:"active_git_op"`
}

// StackStatusEntry is one row, one per stack.Branches element in slice order.
type StackStatusEntry struct {
	Name              string                     `json:"name"`
	GitBranch         string                     `json:"git_branch"`
	Archived          bool                       `json:"archived"`
	Repo              *string                    `json:"repo"`
	Base              StackStatusBase            `json:"base"`
	RefExists         *bool                      `json:"ref_exists"`
	Heads             StackStatusHeads           `json:"heads"`
	BaseRecord        StackStatusBaseRecord      `json:"base_record"`
	Ancestry          StackStatusAncestry        `json:"ancestry"`
	RepoSource        StackRepoSource            `json:"repo_source"`
	ParentCounts      StackStatusParentCounts    `json:"parent_counts"`
	Materialization   StackStatusMaterialization `json:"materialization"`
	IsCurrentCheckout *bool                      `json:"is_current_checkout"`
	Upstream          StackStatusUpstream        `json:"upstream"`
}

// StackStatusBase projects the evaluator's base selection.
type StackStatusBase struct {
	Name *string       `json:"name"`
	Kind StackBaseKind `json:"kind"`
	Ref  *string       `json:"ref"`
}

// StackStatusHeads projects the evaluator's peeled heads.
type StackStatusHeads struct {
	Local          *string `json:"local"`
	LocalShort     *string `json:"local_short"`
	Parent         *string `json:"parent"`
	ParentShort    *string `json:"parent_short"`
	MergeBase      *string `json:"merge_base"`
	MergeBaseShort *string `json:"merge_base_short"`
}

// StackStatusBaseRecord projects the recorded last_base_sha verdict. State is
// null when the record was never consulted: a verdict never formed is never
// published.
type StackStatusBaseRecord struct {
	SHA    *string `json:"sha"`
	Commit *string `json:"commit"`
	Short  *string `json:"short"`
	State  *string `json:"state"`
}

// StackStatusNote projects one informational evaluator note.
type StackStatusNote struct {
	Kind   StackNoteKind `json:"kind"`
	Detail string        `json:"detail"`
}

// StackStatusAncestry projects the shared evaluator's verdict verbatim. This
// command computes no ancestry of its own.
type StackStatusAncestry struct {
	Status   *string             `json:"status"`
	Reason   StackAncestryReason `json:"reason"`
	Severity CheckoutSeverity    `json:"severity"`
	Guidance *string             `json:"guidance"`
	Notes    []StackStatusNote   `json:"notes"`
}

// StackStatusParentCounts holds local commit counts against the parent head.
// It is never a remote-freshness claim.
type StackStatusParentCounts struct {
	Ahead  *int `json:"ahead"`
	Behind *int `json:"behind"`
}

// StackStatusMaterialization describes whether and how the row exists on disk.
type StackStatusMaterialization struct {
	Kind             string  `json:"kind"`
	State            string  `json:"state"`
	Path             *string `json:"path"`
	CheckedOutBranch *string `json:"checked_out_branch"`
	Detached         *bool   `json:"detached"`
	Dirty            *bool   `json:"dirty"`
	ActiveGitOp      *string `json:"active_git_op"`
}

// StackStatusUpstream describes the configured upstream ref exactly as it
// exists in this repository right now.
type StackStatusUpstream struct {
	Configured *bool   `json:"configured"`
	Ref        *string `json:"ref"`
	Display    *string `json:"display"`
	State      *string `json:"state"`
	Ahead      *int    `json:"ahead"`
	Behind     *int    `json:"behind"`
	LocalOnly  bool    `json:"local_only"`
}

// StackStatusSummary counts the finished rows. Every counter is a plain int,
// always present, and its encoded order is a fixed struct field order, so no
// map is ever iterated.
type StackStatusSummary struct {
	Entries         int                              `json:"entries"`
	Ancestry        StackStatusAncestryCounts        `json:"ancestry"`
	Materialization StackStatusMaterializationCounts `json:"materialization"`
	Upstream        StackStatusUpstreamCounts        `json:"upstream"`
	Unknown         StackStatusUnknownCounts         `json:"unknown"`
	LocalOnly       bool                             `json:"local_only"`
}

// StackStatusAncestryCounts partitions entries by ancestry status.
type StackStatusAncestryCounts struct {
	Current              int `json:"current"`
	Stale                int `json:"stale"`
	Divergent            int `json:"divergent"`
	Missing              int `json:"missing"`
	CrossRepoUnsupported int `json:"cross_repo_unsupported"`
	Unevaluated          int `json:"unevaluated"`
}

// StackStatusMaterializationCounts partitions entries by materialization.
type StackStatusMaterializationCounts struct {
	Present              int `json:"present"`
	Archived             int `json:"archived"`
	Missing              int `json:"missing"`
	PrunableMissing      int `json:"prunable_missing"`
	CrossRepoUnsupported int `json:"cross_repo_unsupported"`
	Unknown              int `json:"unknown"`
}

// StackStatusUpstreamCounts partitions entries by upstream state.
type StackStatusUpstreamCounts struct {
	None     int `json:"none"`
	Equal    int `json:"equal"`
	Ahead    int `json:"ahead"`
	Behind   int `json:"behind"`
	Diverged int `json:"diverged"`
	Gone     int `json:"gone"`
	Unknown  int `json:"unknown"`
}

// StackStatusUnknownCounts counts rows whose corresponding value is null. It
// partitions nothing.
type StackStatusUnknownCounts struct {
	RefExists    int `json:"ref_exists"`
	ParentCounts int `json:"parent_counts"`
	Dirty        int `json:"dirty"`
	ActiveGitOp  int `json:"active_git_op"`
}

// ---------- Stack loading ----------

// LoadStackForStatus reads and classifies one feature's stack.yaml. LoadStack
// collapses missing, unreadable, and invalid YAML into one opaque error, which
// is why status needs its own loader. A successfully returned Stack is
// structurally valid by construction: validation runs as the last step here,
// so "loaded" and "structurally valid" are the same condition.
func LoadStackForStatus(featurePath, feature string) (Stack, error) {
	data, err := os.ReadFile(StackPath(featurePath))
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return Stack{}, fmt.Errorf("no stack.yaml found for feature: %s", feature)
		}
		return Stack{}, fmt.Errorf("stack.yaml unreadable for feature %s: %w", feature, err)
	}
	var stack Stack
	if err := yaml.Unmarshal(data, &stack); err != nil {
		return Stack{}, fmt.Errorf("stack.yaml invalid for feature %s: %w", feature, err)
	}
	if err := validateStackForStatus(stack); err != nil {
		return Stack{}, fmt.Errorf("invalid stack.yaml for feature %s: %w", feature, err)
	}
	return stack, nil
}

// validateStackForStatus rejects a structurally invalid stack. An empty
// branches list is valid, a duplicate GitBranch() across distinct names is
// valid, and a cycle is valid for this command.
func validateStackForStatus(stack Stack) error {
	for i, se := range stack.Branches {
		if se.Name == "" {
			return fmt.Errorf("entry %d: empty name", i)
		}
	}
	seen := make(map[string]bool, len(stack.Branches))
	for _, se := range stack.Branches {
		if seen[se.Name] {
			return fmt.Errorf("duplicate entry name %s", se.Name)
		}
		seen[se.Name] = true
	}
	for _, se := range stack.Branches {
		if !filepath.IsLocal(se.Name) || filepath.Clean(se.Name) == "." {
			return fmt.Errorf("unsafe entry name %s", se.Name)
		}
	}
	return nil
}

// ---------- Read-only tri-state probes ----------

// probeDirty reports whether a worktree has uncommitted changes. It runs with
// GIT_OPTIONAL_LOCKS=0 so even the index is left untouched, and it returns an
// error rather than a fabricated clean verdict when the probe fails.
func probeDirty(path string) (bool, error) {
	if path == "" {
		return false, errors.New("dirty probe requires a non-empty path")
	}
	cmd := exec.Command("git", "-C", path, "status", "--porcelain")
	cmd.Env = append(os.Environ(), "GIT_OPTIONAL_LOCKS=0")
	out, err := cmd.Output()
	if err != nil {
		return false, err
	}
	return len(bytes.TrimSpace(out)) > 0, nil
}

// stackStatusOpMarkers is the fixed marker order shared with the shipped
// health helper. The first marker whose stat succeeds wins.
var stackStatusOpMarkers = []struct {
	marker string
	name   string
}{
	{"rebase-merge", "rebase"},
	{"rebase-apply", "rebase"},
	{"MERGE_HEAD", "merge"},
	{"CHERRY_PICK_HEAD", "cherry-pick"},
	{"REVERT_HEAD", "revert"},
	{"BISECT_LOG", "bisect"},
}

// probeActiveGitOp reports the in-progress Git operation for a worktree.
//
// It resolves the Git directory first and then stats the resolved directory
// itself: without that check, a `.git` file whose gitdir target no longer
// exists would make every marker stat return fs.ErrNotExist and the helper
// would fabricate "none" for a repository whose Git directory is gone. A
// missing `.git`, an unreadable or malformed gitdir pointer, a vanished or
// non-directory target, and a non-ENOENT marker stat are each an error.
func probeActiveGitOp(path string) (string, error) {
	if path == "" {
		return "", errors.New("active operation probe requires a non-empty path")
	}
	gitDir := filepath.Join(path, ".git")
	info, err := os.Stat(gitDir)
	if err != nil {
		return "", err
	}
	if !info.IsDir() {
		data, readErr := os.ReadFile(gitDir)
		if readErr != nil {
			return "", readErr
		}
		after, ok := strings.CutPrefix(strings.TrimSpace(string(data)), "gitdir: ")
		if !ok || after == "" {
			return "", fmt.Errorf("malformed gitdir pointer in %s", gitDir)
		}
		if !filepath.IsAbs(after) {
			after = filepath.Join(path, after)
		}
		gitDir = filepath.Clean(after)
	}
	resolved, err := os.Stat(gitDir)
	if err != nil {
		return "", err
	}
	if !resolved.IsDir() {
		return "", fmt.Errorf("resolved git directory %s is not a directory", gitDir)
	}
	for _, check := range stackStatusOpMarkers {
		_, statErr := os.Stat(filepath.Join(gitDir, check.marker))
		if statErr == nil {
			return check.name, nil
		}
		if !errors.Is(statErr, fs.ErrNotExist) {
			return "", statErr
		}
	}
	return StackStatusOpNone, nil
}

// ---------- Branch-ref inventory ----------

// BranchRefRecord is one parsed refs/heads/ record. Every field is stored
// verbatim as Git printed it.
type BranchRefRecord struct {
	Ref        string
	ObjectID   string
	Upstream   string
	Track      string
	TrackShort string
}

// BranchRefInventory is a single fail-closed `for-each-ref` result. A
// partially parsed map is never published: any violation makes the whole
// inventory unavailable and every dependent field null.
type BranchRefInventory struct {
	Available bool
	ByRef     map[string]BranchRefRecord
	Err       error
}

// BuildBranchRefInventory runs one `git -C <repoDir> for-each-ref` over
// refs/heads/. Every argument except the directory is a compile-time constant,
// and the directory is always the validated, non-empty repository dir.
func BuildBranchRefInventory(repoDir string) BranchRefInventory {
	inv := BranchRefInventory{ByRef: map[string]BranchRefRecord{}}
	if repoDir == "" {
		inv.Err = errors.New("branch ref inventory requires a non-empty repository directory")
		return inv
	}
	out, err := exec.Command("git", "-C", repoDir, "for-each-ref",
		"--format="+stackStatusRefFormat, stackStatusHeadsPrefix).Output()
	if err != nil {
		inv.Err = err
		return inv
	}
	records, parseErr := parseBranchRefInventory(out)
	if parseErr != nil {
		inv.Err = parseErr
		return inv
	}
	inv.Available = true
	inv.ByRef = records
	return inv
}

// parseBranchRefInventory is fail-closed: a violation invalidates the whole
// inventory rather than publishing a partial map, because a partial upstream
// map is exactly the input that would let status claim a false upstream state.
func parseBranchRefInventory(out []byte) (map[string]BranchRefRecord, error) {
	records := map[string]BranchRefRecord{}
	lines := strings.Split(string(out), "\n")
	for i, line := range lines {
		if line == "" {
			// for-each-ref appends one newline per expansion, so exactly one
			// trailing empty record is expected.
			if i == len(lines)-1 {
				continue
			}
			return nil, fmt.Errorf("branch ref inventory: empty record at position %d", i)
		}
		fields := strings.Split(line, "\x00")
		if len(fields) != 5 {
			return nil, fmt.Errorf("branch ref inventory: record %d has %d fields, want 5", i, len(fields))
		}
		ref, objectID, upstream, track, trackShort := fields[0], fields[1], fields[2], fields[3], fields[4]
		if !strings.HasPrefix(ref, stackStatusHeadsPrefix) || len(ref) <= len(stackStatusHeadsPrefix) {
			return nil, fmt.Errorf("branch ref inventory: record %d has malformed branch ref %q", i, ref)
		}
		if !stackStatusObjectID.MatchString(objectID) {
			return nil, fmt.Errorf("branch ref inventory: record %d has malformed object id %q", i, objectID)
		}
		if upstream != "" && (!strings.HasPrefix(upstream, "refs/") || len(upstream) <= len("refs/")) {
			return nil, fmt.Errorf("branch ref inventory: record %d has malformed upstream ref %q", i, upstream)
		}
		if _, _, _, err := parseUpstreamTracking(upstream, track, trackShort); err != nil {
			return nil, fmt.Errorf("branch ref inventory: record %d: %w", i, err)
		}
		if _, dup := records[ref]; dup {
			return nil, fmt.Errorf("branch ref inventory: duplicate branch ref %q", ref)
		}
		records[ref] = BranchRefRecord{
			Ref:        ref,
			ObjectID:   objectID,
			Upstream:   upstream,
			Track:      track,
			TrackShort: trackShort,
		}
	}
	return records, nil
}

// parseUpstreamTracking maps the six accepted (upstream, track, trackshort)
// shapes real Git emits. `equal`, `none`, and `gone` are three distinct states
// and are never conflated; `[gone]` really does come with an empty trackshort.
func parseUpstreamTracking(upstream, track, trackShort string) (string, *int, *int, error) {
	if upstream == "" {
		if track != "" || trackShort != "" {
			return "", nil, nil, fmt.Errorf("no upstream but tracking is (%q, %q)", track, trackShort)
		}
		return StackStatusUpstreamNone, nil, nil, nil
	}
	switch trackShort {
	case "=":
		if track != "" {
			return "", nil, nil, fmt.Errorf("unsupported tracking pair (%q, %q)", track, trackShort)
		}
		return StackStatusUpstreamEqual, intPtr(0), intPtr(0), nil
	case ">":
		n, err := stackStatusTrackCount(track, "[ahead ", "]")
		if err != nil {
			return "", nil, nil, err
		}
		return StackStatusUpstreamAhead, intPtr(n), intPtr(0), nil
	case "<":
		n, err := stackStatusTrackCount(track, "[behind ", "]")
		if err != nil {
			return "", nil, nil, err
		}
		return StackStatusUpstreamBehind, intPtr(0), intPtr(n), nil
	case "<>":
		inner, ok := strings.CutPrefix(track, "[ahead ")
		if !ok {
			return "", nil, nil, fmt.Errorf("malformed diverged tracking %q", track)
		}
		inner, ok = strings.CutSuffix(inner, "]")
		if !ok {
			return "", nil, nil, fmt.Errorf("malformed diverged tracking %q", track)
		}
		parts := strings.SplitN(inner, ", behind ", 2)
		if len(parts) != 2 {
			return "", nil, nil, fmt.Errorf("malformed diverged tracking %q", track)
		}
		ahead, err := stackStatusDecimalValue(parts[0])
		if err != nil {
			return "", nil, nil, fmt.Errorf("malformed diverged tracking %q: %w", track, err)
		}
		behind, err := stackStatusDecimalValue(parts[1])
		if err != nil {
			return "", nil, nil, fmt.Errorf("malformed diverged tracking %q: %w", track, err)
		}
		return StackStatusUpstreamDiverged, intPtr(ahead), intPtr(behind), nil
	case "":
		if track == "[gone]" {
			return StackStatusUpstreamGone, nil, nil, nil
		}
		return "", nil, nil, fmt.Errorf("unsupported tracking pair (%q, %q)", track, trackShort)
	default:
		return "", nil, nil, fmt.Errorf("unsupported tracking pair (%q, %q)", track, trackShort)
	}
}

func stackStatusTrackCount(track, prefix, suffix string) (int, error) {
	inner, ok := strings.CutPrefix(track, prefix)
	if !ok {
		return 0, fmt.Errorf("malformed tracking %q", track)
	}
	inner, ok = strings.CutSuffix(inner, suffix)
	if !ok {
		return 0, fmt.Errorf("malformed tracking %q", track)
	}
	n, err := stackStatusDecimalValue(inner)
	if err != nil {
		return 0, fmt.Errorf("malformed tracking %q: %w", track, err)
	}
	return n, nil
}

func stackStatusDecimalValue(s string) (int, error) {
	if !stackStatusDecimal.MatchString(s) {
		return 0, fmt.Errorf("not a non-negative decimal integer: %q", s)
	}
	return strconv.Atoi(s)
}

// ---------- Parent counts ----------

// stackStatusParentCounts counts the symmetric difference between two local
// peeled commits. Both operands come from the shipped evaluator, which only
// publishes 40-hex peeled heads, so ancestryFullSHA is the correct precondition
// here and nowhere else in this feature. No process starts unless every
// precondition holds, and a failure yields two nulls, never zeros.
func stackStatusParentCounts(repoDir, localHead, parentHead string) (*int, *int) {
	if repoDir == "" || !ancestryFullSHA.MatchString(localHead) || !ancestryFullSHA.MatchString(parentHead) {
		return nil, nil
	}
	out, err := exec.Command("git", "-C", repoDir, "rev-list", "--left-right", "--count",
		localHead+"..."+parentHead).Output()
	if err != nil {
		return nil, nil
	}
	fields := strings.Split(strings.TrimSuffix(string(out), "\n"), "\t")
	if len(fields) != 2 {
		return nil, nil
	}
	ahead, err := stackStatusDecimalValue(fields[0])
	if err != nil {
		return nil, nil
	}
	behind, err := stackStatusDecimalValue(fields[1])
	if err != nil {
		return nil, nil
	}
	return intPtr(ahead), intPtr(behind)
}

// ---------- Builder ----------

// BuildStackStatus projects one feature's stack. It calls FeatureStackEdges
// exactly once, computes no ancestry of its own, issues no second ref probe or
// repository resolution, and starts at most 2 + C + D Git processes of its own.
func BuildStackStatus(ws Workspace, cfg Config, feature, featurePath string, stack Stack) (*StackStatusReport, error) {
	return BuildStackStatusWithReparentPath(ws, cfg, feature, featurePath, featurePath, stack)
}

// BuildStackStatusWithReparentPath keeps ordinary ancestry and materialization
// routed through featurePath while reading reparent state from the path the
// reparent layout resolver selected. The paths differ only for a configured
// external TWS_ROOT override.
func BuildStackStatusWithReparentPath(ws Workspace, cfg Config, feature, featurePath, reparentFeaturePath string, stack Stack) (*StackStatusReport, error) {
	edges, res := FeatureStackEdges(ws, cfg, feature, featurePath, stack)
	edges = ancestryEdgesFor(feature, stack, edges)
	// §11.10 rule 2: ancestry status and reason are still reported; only the
	// repair guidance is replaced by the anchored reparent line.
	if ReparentGuidanceSuppressed(ws, feature, reparentFeaturePath) {
		edges = SuppressReparentAncestryGuidance(edges)
	}
	repoDir := res.RepoDir

	report := &StackStatusReport{
		SchemaVersion: stackStatusSchema,
		Feature:       feature,
		Entries:       make([]StackStatusEntry, 0, len(stack.Branches)),
		Workspace: StackStatusWorkspace{
			Mode: ws.Mode,
			// Emitted as held: a configured external workspace root is stored
			// verbatim and may legitimately be non-canonical. Every
			// authoritative join is canonicalized independently of this field.
			MetadataRoot: ws.MetadataRoot,
			Repository: StackStatusRepository{
				Dir:       stackStatusOptString(res.RepoDir),
				Source:    res.Source,
				Alternate: stackStatusOptString(res.Alternate),
			},
		},
	}
	report.Workspace.StableID = stackStatusOptString(ws.StableID)

	// §11.10: the read-only reparent projection. BuildReparentProjection
	// returns nil when no artifact exists, so the key stays absent and the
	// document is byte-identical to today. It is strictly read-only: no fetch,
	// no ref write, no state repair, and it never evaluates the §12.3 remote
	// follow-up record.
	reparentLoc := ReparentLocationFor(ws, feature, reparentFeaturePath)
	report.Reparent = BuildReparentProjection(reparentLoc)

	var branchInv BranchRefInventory
	var worktreeInv WorktreeInventory
	if repoDir != "" {
		branchInv = BuildBranchRefInventory(repoDir)
		worktreeInv = ExcludeReparentScratchWorktrees(BuildWorktreeInventory(repoDir), ActiveReparentScratchPath(reparentLoc))
	}

	var checkout *StackStatusCheckout
	if ws.Mode == ModeCheckout {
		checkout = stackStatusCheckoutFacts(repoDir, worktreeInv)
		report.Workspace.Checkout = checkout
	} else {
		report.Workspace.External = &StackStatusExternal{
			WorktreesRoot: canonicalize(filepath.Join(featurePath, "worktrees")),
		}
	}

	for i, se := range stack.Branches {
		edge := edges[i]
		entry := stackStatusProjectEdge(se, edge)
		entry.Upstream = stackStatusUpstreamFor(se, edge, branchInv)

		if ws.Mode == ModeCheckout {
			entry.Materialization = stackStatusCheckoutMaterialization(edge, checkout)
			entry.IsCurrentCheckout = stackStatusIsCurrentCheckout(edge, checkout)
		} else {
			entry.Materialization = stackStatusExternalMaterialization(featurePath, se, edge, worktreeInv)
		}

		if edge.Repo == "" {
			entry.ParentCounts.Ahead, entry.ParentCounts.Behind =
				stackStatusParentCounts(repoDir, edge.LocalHead, edge.ParentHead)
		}
		report.Entries = append(report.Entries, entry)
	}

	report.Summary = stackStatusSummarize(report.Entries)
	return report, nil
}

// stackStatusCheckoutFacts reads the single physical checkout. The current
// branch is never inferred from a session record, from HEAD parsing, or from a
// ref merely existing: only Git's worktree inventory may name it.
func stackStatusCheckoutFacts(repoDir string, inv WorktreeInventory) *StackStatusCheckout {
	checkout := &StackStatusCheckout{}
	if repoDir == "" {
		return checkout
	}
	checkout.Path = strPtr(repoDir)
	if inv.Available {
		if rec, ok := inv.ByPath[canonicalize(repoDir)]; ok {
			switch {
			case rec.Detached != nil && *rec.Detached:
				checkout.Detached = boolPtr(true)
			case rec.BranchRef != nil:
				checkout.Detached = boolPtr(false)
				checkout.Branch = strPtr(stackStatusStripHeads(*rec.BranchRef))
			}
		}
	}
	if dirty, err := probeDirty(repoDir); err == nil {
		checkout.Dirty = boolPtr(dirty)
	}
	if op, err := probeActiveGitOp(repoDir); err == nil {
		checkout.ActiveGitOp = strPtr(op)
	}
	return checkout
}

// stackStatusProjectEdge copies the evaluator's evidence field for field. No
// value is recomputed, re-probed, or reinterpreted here.
func stackStatusProjectEdge(se StackEntry, edge StackEdge) StackStatusEntry {
	entry := StackStatusEntry{
		Name:      se.Name,
		GitBranch: edge.GitBranch,
		Archived:  edge.Archived,
		Repo:      stackStatusOptString(edge.Repo),
		Base: StackStatusBase{
			Name: stackStatusOptString(edge.BaseName),
			Kind: edge.BaseKind,
			Ref:  stackStatusOptString(edge.BaseRef),
		},
		Heads: StackStatusHeads{
			Local:          stackStatusOptString(edge.LocalHead),
			LocalShort:     stackStatusOptString(edge.LocalHeadShort),
			Parent:         stackStatusOptString(edge.ParentHead),
			ParentShort:    stackStatusOptString(edge.ParentHeadShort),
			MergeBaseShort: stackStatusOptString(edge.MergeBaseShort),
		},
		BaseRecord: StackStatusBaseRecord{
			SHA:    stackStatusOptString(edge.LastBaseSHA),
			Commit: stackStatusOptString(edge.LastBaseCommit),
			Short:  stackStatusOptString(edge.LastBaseShort),
			State:  stackStatusOptString(string(edge.BaseRecord)),
		},
		Ancestry: StackStatusAncestry{
			Status:   stackStatusOptString(string(edge.Status)),
			Reason:   edge.Reason,
			Severity: edge.Severity,
			Guidance: stackStatusOptString(edge.Guidance),
			Notes:    make([]StackStatusNote, 0, len(edge.Notes)),
		},
		RepoSource: edge.RepoSource,
	}
	if edge.GitBranch == "" {
		entry.GitBranch = se.GitBranch()
	}
	// The evaluator's MergeBase points at a local in classify; copy the value
	// so a later mutation of the edge slice can never rewrite an emitted
	// document.
	if edge.MergeBase != nil {
		merge := *edge.MergeBase
		entry.Heads.MergeBase = &merge
	}
	// ref_exists is only RefProbed/RefExists: no second ref probe exists in
	// this feature, so it can never disagree with ancestry.status.
	if edge.RefProbed {
		entry.RefExists = boolPtr(edge.RefExists)
	}
	for _, note := range edge.Notes {
		entry.Ancestry.Notes = append(entry.Ancestry.Notes, StackStatusNote(note))
	}
	return entry
}

// stackStatusUpstreamFor joins one row against the branch-ref inventory. Both
// sides of the join are complete refs/heads/ names, so a same-named tag can
// neither change a key nor win a lookup.
func stackStatusUpstreamFor(se StackEntry, edge StackEdge, inv BranchRefInventory) StackStatusUpstream {
	up := StackStatusUpstream{LocalOnly: true}
	// A cross-repo row's branch lives in a repository this feature never
	// probes, so it performs no lookup at all.
	if edge.Repo != "" || !inv.Available {
		return up
	}
	key := edge.ChildRef
	if key == "" {
		key = stackStatusHeadsPrefix + se.GitBranch()
	}
	rec, ok := inv.ByRef[key]
	if !ok {
		return up
	}
	state, ahead, behind, err := parseUpstreamTracking(rec.Upstream, rec.Track, rec.TrackShort)
	if err != nil {
		return up
	}
	up.Configured = boolPtr(rec.Upstream != "")
	up.State = strPtr(state)
	up.Ahead = ahead
	up.Behind = behind
	if rec.Upstream != "" {
		up.Ref = strPtr(rec.Upstream)
		up.Display = strPtr(stackStatusUpstreamDisplay(rec.Upstream))
	}
	return up
}

// stackStatusUpstreamDisplay strips exactly one known prefix after validation.
// Any other validated refs/... value is displayed verbatim.
func stackStatusUpstreamDisplay(ref string) string {
	if after, ok := strings.CutPrefix(ref, "refs/remotes/"); ok {
		return after
	}
	if after, ok := strings.CutPrefix(ref, stackStatusHeadsPrefix); ok {
		return after
	}
	return ref
}

func stackStatusStripHeads(ref string) string {
	return strings.TrimPrefix(ref, stackStatusHeadsPrefix)
}

// stackStatusExternalMaterialization decides external materialization from
// Git's own porcelain path map rather than from a directory stat, so a
// leftover directory Git does not know about reports `missing`. There is no
// per-row branch probe, stat, or prunability call.
func stackStatusExternalMaterialization(featurePath string, se StackEntry, edge StackEdge, inv WorktreeInventory) StackStatusMaterialization {
	m := StackStatusMaterialization{Kind: StackStatusKindWorktree, State: StackStatusMaterializedUnknown}
	if edge.Repo != "" {
		m.State = StackStatusMaterializedCrossRepo
		return m
	}
	candidate, err := ancestryWorktreeCandidatePath(featurePath, se.Name)
	if err != nil {
		return m
	}
	if !inv.Available {
		return m
	}
	canonical := canonicalize(candidate)
	rec, ok := inv.ByPath[canonical]
	if !ok {
		if se.Archived {
			m.State = StackStatusMaterializedArchived
		} else {
			m.State = StackStatusMaterializedMissing
		}
		return m
	}
	if rec.Prunable {
		m.State = StackStatusMaterializedPrunableMissing
	} else {
		m.State = StackStatusMaterializedPresent
	}
	m.Path = strPtr(canonical)
	if rec.BranchRef != nil {
		m.CheckedOutBranch = strPtr(stackStatusStripHeads(*rec.BranchRef))
	}
	if rec.Detached != nil {
		m.Detached = boolPtr(*rec.Detached)
	}
	if m.State == StackStatusMaterializedPresent {
		if dirty, dErr := probeDirty(canonical); dErr == nil {
			m.Dirty = boolPtr(dirty)
		}
		if op, oErr := probeActiveGitOp(canonical); oErr == nil {
			m.ActiveGitOp = strPtr(op)
		}
	}
	return m
}

// stackStatusCheckoutMaterialization derives state only from the evaluator's
// evidence. Checkout mode never uses the `archived` materialization state:
// a checkout entry has no worktree to be absent, and the row's own archived
// field already reports it. A cross-repo row is owned by another repository,
// so it reports the unsupported state and nothing else: this checkout's branch,
// dirtiness, and active operation are not facts about it, however its Git
// branch name happens to collide with the branch checked out here.
func stackStatusCheckoutMaterialization(edge StackEdge, checkout *StackStatusCheckout) StackStatusMaterialization {
	m := StackStatusMaterialization{Kind: StackStatusKindRef, State: StackStatusMaterializedUnknown}
	if edge.Repo != "" {
		m.State = StackStatusMaterializedCrossRepo
		return m
	}
	switch {
	case edge.RefProbed && edge.RefExists:
		m.State = StackStatusMaterializedPresent
	case edge.RefProbed:
		m.State = StackStatusMaterializedMissing
	}
	if checkout == nil || checkout.Branch == nil || edge.GitBranch != *checkout.Branch {
		return m
	}
	m.CheckedOutBranch = strPtr(*checkout.Branch)
	if checkout.Dirty != nil {
		m.Dirty = boolPtr(*checkout.Dirty)
	}
	if checkout.ActiveGitOp != nil {
		m.ActiveGitOp = strPtr(*checkout.ActiveGitOp)
	}
	return m
}

// stackStatusIsCurrentCheckout is a bool only when a branch is really checked
// out. A detached checkout, an unavailable inventory, an unavailable
// repository, and a cross-repo row each yield null.
func stackStatusIsCurrentCheckout(edge StackEdge, checkout *StackStatusCheckout) *bool {
	if edge.Repo != "" {
		return nil
	}
	if checkout == nil || checkout.Branch == nil || checkout.Detached == nil || *checkout.Detached {
		return nil
	}
	return boolPtr(edge.GitBranch == *checkout.Branch)
}

// stackStatusSummarize counts the finished rows in one pass, so "the three
// groups partition entries" is true by construction.
func stackStatusSummarize(entries []StackStatusEntry) StackStatusSummary {
	summary := StackStatusSummary{Entries: len(entries), LocalOnly: true}
	for _, e := range entries {
		switch stackStatusDeref(e.Ancestry.Status) {
		case string(AncestryStatusCurrent):
			summary.Ancestry.Current++
		case string(AncestryStatusStale):
			summary.Ancestry.Stale++
		case string(AncestryStatusDivergent):
			summary.Ancestry.Divergent++
		case string(AncestryStatusMissing):
			summary.Ancestry.Missing++
		case string(AncestryStatusCrossRepo):
			summary.Ancestry.CrossRepoUnsupported++
		default:
			summary.Ancestry.Unevaluated++
		}

		switch e.Materialization.State {
		case StackStatusMaterializedPresent:
			summary.Materialization.Present++
		case StackStatusMaterializedArchived:
			summary.Materialization.Archived++
		case StackStatusMaterializedMissing:
			summary.Materialization.Missing++
		case StackStatusMaterializedPrunableMissing:
			summary.Materialization.PrunableMissing++
		case StackStatusMaterializedCrossRepo:
			summary.Materialization.CrossRepoUnsupported++
		default:
			summary.Materialization.Unknown++
		}

		switch stackStatusDeref(e.Upstream.State) {
		case StackStatusUpstreamNone:
			summary.Upstream.None++
		case StackStatusUpstreamEqual:
			summary.Upstream.Equal++
		case StackStatusUpstreamAhead:
			summary.Upstream.Ahead++
		case StackStatusUpstreamBehind:
			summary.Upstream.Behind++
		case StackStatusUpstreamDiverged:
			summary.Upstream.Diverged++
		case StackStatusUpstreamGone:
			summary.Upstream.Gone++
		default:
			summary.Upstream.Unknown++
		}

		if e.RefExists == nil {
			summary.Unknown.RefExists++
		}
		if e.ParentCounts.Ahead == nil || e.ParentCounts.Behind == nil {
			summary.Unknown.ParentCounts++
		}
		if e.Materialization.Dirty == nil {
			summary.Unknown.Dirty++
		}
		if e.Materialization.ActiveGitOp == nil {
			summary.Unknown.ActiveGitOp++
		}
	}
	return summary
}

// NormalizeStackStatus converts nil slices to empty slices. It is idempotent
// and must run before encoding and before formatting.
func NormalizeStackStatus(r *StackStatusReport) {
	if r == nil {
		return
	}
	if r.Entries == nil {
		r.Entries = []StackStatusEntry{}
	}
	for i := range r.Entries {
		if r.Entries[i].Ancestry.Notes == nil {
			r.Entries[i].Ancestry.Notes = []StackStatusNote{}
		}
	}
}

// ---------- Human output ----------

// FormatStackStatus renders the report deterministically: header, table,
// per-row detail lines, summary, footer. It contains no generated timestamp,
// so two runs over an unchanged repository are byte-identical.
func FormatStackStatus(r *StackStatusReport) string {
	if r == nil {
		return ""
	}
	var b strings.Builder
	stackStatusWriteHeader(&b, r)
	b.WriteString("\n")
	if len(r.Entries) == 0 {
		b.WriteString("No branches tracked in stack.yaml.\n")
	} else {
		stackStatusWriteTable(&b, r.Entries)
	}
	b.WriteString("\n")
	stackStatusWriteSummary(&b, r.Summary)
	b.WriteString("\n")
	b.WriteString("Local-only report: no fetch was performed. Upstream and parent counts describe local refs only.\n")
	return b.String()
}

func stackStatusLabel(label, value string) string {
	return fmt.Sprintf("  %-11s %s\n", label+":", value)
}

func stackStatusWriteHeader(b *strings.Builder, r *StackStatusReport) {
	fmt.Fprintf(b, "Stack status: %s (mode: %s)\n",
		ancestrySanitize(r.Feature, stackStatusSanitizeLimit), r.Workspace.Mode)
	b.WriteString(stackStatusLabel("Workspace",
		ancestrySanitize(r.Workspace.MetadataRoot, stackStatusSanitizeLimit)))

	repo := "unavailable"
	if r.Workspace.Repository.Dir != nil {
		repo = ancestrySanitize(*r.Workspace.Repository.Dir, stackStatusSanitizeLimit)
	}
	b.WriteString(stackStatusLabel("Repository", fmt.Sprintf("%s (source: %s)", repo, r.Workspace.Repository.Source)))
	if r.Workspace.Repository.Alternate != nil {
		b.WriteString(stackStatusLabel("Alternate", fmt.Sprintf("%s (%s)",
			ancestrySanitize(*r.Workspace.Repository.Alternate, stackStatusSanitizeLimit), RepoSourceMismatchLabel)))
	}

	if r.Workspace.External != nil {
		b.WriteString(stackStatusLabel("Worktrees",
			ancestrySanitize(r.Workspace.External.WorktreesRoot, stackStatusSanitizeLimit)))
	}
	if r.Workspace.Checkout != nil {
		c := r.Workspace.Checkout
		if c.Path == nil {
			b.WriteString(stackStatusLabel("Checkout", "unavailable"))
			return
		}
		fmt.Fprintf(b, "  %-11s %s (branch: %s, detached: %s, dirty: %s, op: %s)\n",
			"Checkout:", ancestrySanitize(*c.Path, stackStatusSanitizeLimit),
			stackStatusOptDisplay(c.Branch, stackStatusSanitizeLimit),
			stackStatusBoolDisplay(c.Detached),
			stackStatusBoolDisplay(c.Dirty),
			stackStatusOptDisplay(c.ActiveGitOp, stackStatusSanitizeLimit))
	}
}

var stackStatusColumns = []string{"BRANCH", "ANCESTRY", "HEAD", "PARENT", "A/B", "UPSTREAM", "MATERIALIZATION", "FLAGS"}

func stackStatusWriteTable(b *strings.Builder, entries []StackStatusEntry) {
	rows := make([][]string, 0, len(entries))
	for _, e := range entries {
		rows = append(rows, stackStatusRowCells(e))
	}
	widths := make([]int, len(stackStatusColumns))
	for i, head := range stackStatusColumns {
		widths[i] = len(head)
	}
	for _, row := range rows {
		for i, cell := range row {
			if len(cell) > widths[i] {
				widths[i] = len(cell)
			}
		}
	}
	b.WriteString(stackStatusJoinCells(stackStatusColumns, widths))
	for i, row := range rows {
		b.WriteString(stackStatusJoinCells(row, widths))
		for _, line := range stackStatusDetailLines(entries[i]) {
			fmt.Fprintf(b, "      %s\n", line)
		}
	}
}

func stackStatusJoinCells(cells []string, widths []int) string {
	var b strings.Builder
	for i, cell := range cells {
		if i == len(cells)-1 {
			b.WriteString(cell)
			break
		}
		fmt.Fprintf(&b, "%-*s  ", widths[i], cell)
	}
	b.WriteString("\n")
	return b.String()
}

func stackStatusRowCells(e StackStatusEntry) []string {
	branch := ancestrySanitize(e.Name, stackStatusSanitizeLimit)
	if e.GitBranch != e.Name {
		branch += fmt.Sprintf(" (git: %s)", ancestrySanitize(e.GitBranch, stackStatusSanitizeLimit))
	}
	return []string{
		branch,
		ancestryDisplayStatus(AncestryStatus(stackStatusDeref(e.Ancestry.Status))),
		stackStatusOrDash(e.Heads.LocalShort),
		stackStatusOrDash(e.Heads.ParentShort),
		stackStatusCountsCell(e.ParentCounts),
		stackStatusUpstreamCell(e.Upstream),
		e.Materialization.State,
		stackStatusFlagsCell(e),
	}
}

func stackStatusCountsCell(c StackStatusParentCounts) string {
	if c.Ahead == nil || c.Behind == nil {
		return "-"
	}
	return fmt.Sprintf("%d/%d", *c.Ahead, *c.Behind)
}

func stackStatusUpstreamCell(u StackStatusUpstream) string {
	if u.Configured == nil || u.State == nil {
		return "?"
	}
	if !*u.Configured {
		return StackStatusUpstreamNone
	}
	display := ancestrySanitize(stackStatusDeref(u.Display), stackStatusSanitizeLimit)
	switch *u.State {
	case StackStatusUpstreamEqual:
		return "equal:" + display
	case StackStatusUpstreamAhead:
		return fmt.Sprintf("ahead+%d:%s", stackStatusDerefInt(u.Ahead), display)
	case StackStatusUpstreamBehind:
		return fmt.Sprintf("behind-%d:%s", stackStatusDerefInt(u.Behind), display)
	case StackStatusUpstreamDiverged:
		return fmt.Sprintf("diverged+%d-%d:%s", stackStatusDerefInt(u.Ahead), stackStatusDerefInt(u.Behind), display)
	case StackStatusUpstreamGone:
		return "gone:" + display
	default:
		return "?"
	}
}

// stackStatusFlagsCell emits its tokens in one fixed order that is never
// re-ordered.
func stackStatusFlagsCell(e StackStatusEntry) string {
	var flags []string
	if e.IsCurrentCheckout != nil && *e.IsCurrentCheckout {
		flags = append(flags, "current")
	}
	if e.Archived {
		flags = append(flags, "archived")
	}
	if e.Repo != nil {
		flags = append(flags, "cross-repo")
	}
	if e.Materialization.Detached != nil && *e.Materialization.Detached {
		flags = append(flags, "detached")
	}
	present := e.Materialization.State == StackStatusMaterializedPresent
	switch {
	case e.Materialization.Dirty != nil && *e.Materialization.Dirty:
		flags = append(flags, "dirty")
	case e.Materialization.Dirty == nil && present:
		flags = append(flags, "dirty?")
	}
	switch {
	case e.Materialization.ActiveGitOp != nil && *e.Materialization.ActiveGitOp != StackStatusOpNone:
		flags = append(flags, "op="+ancestrySanitize(*e.Materialization.ActiveGitOp, stackStatusSanitizeLimit))
	case e.Materialization.ActiveGitOp == nil && present:
		flags = append(flags, "op?")
	}
	switch {
	case e.RefExists != nil && !*e.RefExists:
		flags = append(flags, "ref-missing")
	case e.RefExists == nil:
		flags = append(flags, "ref?")
	}
	if len(flags) == 0 {
		return "-"
	}
	return strings.Join(flags, ",")
}

// stackStatusDetailLines mirrors the shipped checkout detail-line grammar, so
// an edge that never consulted the recorded base cannot claim a verdict about
// it. Guidance and note details are printed verbatim: the evaluator already
// sanitized them and re-sanitizing would double-truncate.
func stackStatusDetailLines(e StackStatusEntry) []string {
	var lines []string
	if stackStatusDeref(e.Ancestry.Status) != string(AncestryStatusCurrent) {
		reason := fmt.Sprintf("reason: %s", e.Ancestry.Reason)
		if e.BaseRecord.Short != nil {
			reason += fmt.Sprintf(" last-base=%s", *e.BaseRecord.Short)
		}
		if e.Heads.MergeBase != nil {
			reason += fmt.Sprintf(" merge-base=%s", stackStatusDeref(e.Heads.MergeBaseShort))
		}
		if e.BaseRecord.State != nil && *e.BaseRecord.State != string(StackBaseRecordPresent) {
			reason += fmt.Sprintf(" base-record=%s", *e.BaseRecord.State)
		}
		lines = append(lines, reason)
	}
	if e.Ancestry.Guidance != nil {
		lines = append(lines, *e.Ancestry.Guidance)
	}
	for _, note := range e.Ancestry.Notes {
		lines = append(lines, fmt.Sprintf("note: %s", note.Detail))
	}
	if e.Materialization.Path != nil {
		lines = append(lines, fmt.Sprintf("path: %s",
			ancestrySanitize(*e.Materialization.Path, stackStatusSanitizeLimit)))
	}
	if e.Materialization.CheckedOutBranch != nil {
		lines = append(lines, fmt.Sprintf("checked-out: %s",
			ancestrySanitize(*e.Materialization.CheckedOutBranch, stackStatusSanitizeLimit)))
	}
	return lines
}

func stackStatusWriteSummary(b *strings.Builder, s StackStatusSummary) {
	b.WriteString("Summary:\n")
	fmt.Fprintf(b, "  entries: %d\n", s.Entries)
	fmt.Fprintf(b, "  ancestry: current=%d stale=%d divergent=%d missing=%d cross-repo-unsupported=%d unevaluated=%d\n",
		s.Ancestry.Current, s.Ancestry.Stale, s.Ancestry.Divergent, s.Ancestry.Missing,
		s.Ancestry.CrossRepoUnsupported, s.Ancestry.Unevaluated)
	fmt.Fprintf(b, "  materialization: present=%d archived=%d missing=%d prunable-missing=%d cross-repo-unsupported=%d unknown=%d\n",
		s.Materialization.Present, s.Materialization.Archived, s.Materialization.Missing,
		s.Materialization.PrunableMissing, s.Materialization.CrossRepoUnsupported, s.Materialization.Unknown)
	fmt.Fprintf(b, "  upstream: none=%d equal=%d ahead=%d behind=%d diverged=%d gone=%d unknown=%d\n",
		s.Upstream.None, s.Upstream.Equal, s.Upstream.Ahead, s.Upstream.Behind,
		s.Upstream.Diverged, s.Upstream.Gone, s.Upstream.Unknown)
	fmt.Fprintf(b, "  unknown: ref-exists=%d parent-counts=%d dirty=%d active-op=%d\n",
		s.Unknown.RefExists, s.Unknown.ParentCounts, s.Unknown.Dirty, s.Unknown.ActiveGitOp)
}

// ---------- small helpers ----------

func stackStatusOptString(s string) *string {
	if s == "" {
		return nil
	}
	return strPtr(s)
}

func stackStatusDeref(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func stackStatusDerefInt(i *int) int {
	if i == nil {
		return 0
	}
	return *i
}

func stackStatusOrDash(s *string) string {
	if s == nil || *s == "" {
		return "-"
	}
	return ancestrySanitize(*s, stackStatusSanitizeLimit)
}

func stackStatusOptDisplay(s *string, limit int) string {
	if s == nil {
		return "?"
	}
	return ancestrySanitize(*s, limit)
}

func stackStatusBoolDisplay(b *bool) string {
	if b == nil {
		return "?"
	}
	if *b {
		return "yes"
	}
	return "no"
}

