package internal

import (
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"time"

	"gopkg.in/yaml.v3"
)

type SyncState struct {
	StartedAt    string   `yaml:"started_at"`
	FailedBranch string   `yaml:"failed_branch"`
	Pending      []string `yaml:"pending"`
	Completed    []string `yaml:"completed"`
	Skipped      []string `yaml:"skipped"`
}

func SyncStatePath(featurePath string) string {
	return filepath.Join(featurePath, ".sync-state.yaml")
}

func LoadSyncState(featurePath string) (*SyncState, error) {
	if err := syncIOFault(SyncIOReadSyncState, SyncStatePath(featurePath)); err != nil {
		return nil, err
	}
	data, err := os.ReadFile(SyncStatePath(featurePath))
	if err != nil {
		return nil, err
	}
	var s SyncState
	if err := yaml.Unmarshal(data, &s); err != nil {
		return nil, err
	}
	return &s, nil
}

func SaveSyncState(featurePath string, s *SyncState) error {
	data, err := yaml.Marshal(s)
	if err != nil {
		return err
	}
	return atomicWriteFile(SyncStatePath(featurePath), data, 0644)
}

// RemoveSyncState removes the legacy state/sentinel file, returning any error
// other than "already gone" (§12.2c rule 2).
func RemoveSyncState(featurePath string) error {
	path := SyncStatePath(featurePath)
	if err := syncIOFault(SyncIORemoveSyncState, path); err != nil {
		return err
	}
	if err := os.Remove(path); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("remove sync state %s: %w", path, err)
	}
	return nil
}

func DeleteSyncState(featurePath string) {
	_ = RemoveSyncState(featurePath)
}

func HasSyncState(featurePath string) bool {
	_, err := os.Stat(SyncStatePath(featurePath))
	return err == nil
}

func NewSyncState() *SyncState {
	return &SyncState{
		StartedAt: time.Now().UTC().Format(time.RFC3339),
	}
}

// SyncStateIOFault is §23.1 item 4's injected reader/remover/restorer/writer
// seam. It is nil in production and MUST NOT be reachable from the CLI. A
// test sets it to force a NON-ErrNotExist I/O failure at a named operation
// on a named path, which is the only way to exercise the error arms of the
// state writers on a filesystem where permissions cannot be made to fail
// (root, ACLs, CI containers). Returning nil lets the real operation
// proceed.
//
// op is one of the closed labels below; path is the artefact's absolute
// path, so a fault can be scoped to exactly one file.
var SyncStateIOFault func(op, path string) error

// The closed op label domain of SyncStateIOFault.
const (
	SyncIOReadSyncState        = "read-sync-state"        // the .sync-state.yaml capture read
	SyncIOReadSyncRunState     = "read-sync-run-state"    // the payload read path
	SyncIORemoveSyncState      = "remove-sync-state"      // §12.2c rule 2 remover
	SyncIORemoveSyncRunState   = "remove-sync-run-state"  // §12.2c rule 2 remover
	SyncIORemoveSyncRunGuard   = "remove-sync-run-guard"  // §12.2c rule 2 remover
	SyncIOWriteSentinel        = "write-sentinel"         // SaveGuardedLegacySentinel
	SyncIORestoreSyncState     = "restore-sync-state"     // RestoreSyncStateBytes
	SyncIORemoveStateUnchanged = "remove-state-unchanged" // RemoveSyncStateIfUnchanged
	SyncIOWriteSyncRunState    = "write-sync-run-state"   // SaveSyncRunState
	SyncIOWriteTransaction     = "write-checkout-tx"      // SaveCheckoutTransaction
	SyncIOReloadStack          = "reload-stack"           // the JIT seam's stack.yaml reload

	// The four safe-reparent tokens (§10.3b). They are APPENDED to the
	// domain above and are never reordered: an existing token's position
	// is part of the shipped seam's contract. Each one is consulted TWICE
	// by durableWriteFile — once before the rename and once after the
	// rename but before the parent-directory fsync — so a test can force a
	// failure in either window by counting its own invocations.
	SyncIOWriteStack           = "write-stack"           // WriteStackBytesAtomic
	SyncIOWriteReparentState   = "write-reparent-state"  // the §11.1 reparent state artifact
	SyncIOWriteReparentCompat  = "write-reparent-compat" // the §11.2 compatibility artifacts
	SyncIOWriteReparentRemote  = "write-reparent-remote" // the §12.3 remote follow-up record
	SyncIORemoveReparentRemote = "remove-reparent-remote"
)

// syncIOFault consults the injected seam. It returns nil in production,
// where SyncStateIOFault is nil.
func syncIOFault(op, path string) error {
	if SyncStateIOFault == nil {
		return nil
	}
	return SyncStateIOFault(op, path)
}

// ---------- guarded legacy rollback: conditional restore/remove ----------

// ErrSyncStateChanged and ErrSyncStateHasPayload are the two distinguished
// "restored nothing" outcomes of RestoreSyncStateBytes, RemoveSyncStateIfUnchanged
// and SaveGuardedLegacySentinel: both mean the file on disk was left exactly
// as found.
var ErrSyncStateChanged = errors.New("sync state changed since it was captured")
var ErrSyncStateHasPayload = errors.New("a scoped sync payload exists beside the sync state")

// RestoreSyncStateBytes writes prior back over .sync-state.yaml through the
// shipped atomic writer, but ONLY when both preconditions hold:
//
//  1. the file's current bytes are byte-identical to expect — the exact
//     sentinel this invocation installed — so a restore can never clobber a
//     document another party wrote (ErrSyncStateChanged otherwise); and
//  2. no scoped payload exists beside it (HasSyncRunState is false), so a
//     restore can never place a REAL legacy state next to a live payload,
//     which would be classifier cell 8 (ErrSyncStateHasPayload otherwise).
//
// The result is therefore either the captured bytes or the value the file had
// before the attempt — never a partial document and never a cell-8 pair.
// len(prior) == 0 is a programming error and returns an error rather than
// truncating the file; the caller uses RemoveSyncStateIfUnchanged for the
// fresh cell, where there were no prior bytes at all. The guarded legacy
// rollback NEVER calls the unconditional RemoveSyncState.
func RestoreSyncStateBytes(featurePath string, prior, expect []byte) error {
	if len(prior) == 0 {
		return fmt.Errorf("restore sync state: refusing to write an empty prior document")
	}
	if err := syncIOFault(SyncIORestoreSyncState, SyncStatePath(featurePath)); err != nil {
		return err
	}
	current, err := os.ReadFile(SyncStatePath(featurePath))
	if err != nil || !bytes.Equal(current, expect) {
		return ErrSyncStateChanged
	}
	if HasSyncRunState(featurePath) {
		return ErrSyncStateHasPayload
	}
	return atomicWriteFile(SyncStatePath(featurePath), prior, 0644)
}

// RemoveSyncStateIfUnchanged is the fresh route's rollback counterpart of
// RestoreSyncStateBytes: it removes .sync-state.yaml only while its bytes are
// still expect AND no payload exists beside it, returning ErrSyncStateChanged
// or ErrSyncStateHasPayload otherwise and removing nothing.
func RemoveSyncStateIfUnchanged(featurePath string, expect []byte) error {
	if err := syncIOFault(SyncIORemoveStateUnchanged, SyncStatePath(featurePath)); err != nil {
		return err
	}
	current, err := os.ReadFile(SyncStatePath(featurePath))
	if err != nil || !bytes.Equal(current, expect) {
		return ErrSyncStateChanged
	}
	if HasSyncRunState(featurePath) {
		return ErrSyncStateHasPayload
	}
	return RemoveSyncState(featurePath)
}

// ---------- the guarded legacy sentinel (§13.6 rule 2c) ----------

// GuardedLegacySentinelVersion is the guarded legacy sentinel's own version.
// It is deliberately a SEPARATE constant from SyncRunStateGuardedVersion: the
// payload and the sentinel are different documents with different readers.
const GuardedLegacySentinelVersion = 3

// GuardedLegacySentinel is .sync-state.yaml as a guarded legacy run writes
// it. The shipped SyncState is embedded INLINE and written exactly as the
// shipped sentinel writes it, so a binary whose decoder ignores unknown keys
// sees a sentinel and nothing else, and fails closed on the marker in every
// cell.
type GuardedLegacySentinel struct {
	SyncState `yaml:",inline"` // started_at, failed_branch = the marker, pending/completed/
	// skipped = [], byte-for-byte the shipped sentinel shape

	GuardedStateVersion int    `yaml:"guarded_state_version"` // always 3
	Route               string `yaml:"route"`                 // always "legacy"
	Feature             string `yaml:"feature"`
	Marker              string `yaml:"marker"`      // MUST equal FailedBranch
	OwnerToken          string `yaml:"owner_token"` // the token step 2 claimed with
	CreatedAt           string `yaml:"created_at"`  // RFC3339 UTC
	WriterPID           int    `yaml:"writer_pid"`  // diagnostic only; never a verdict

	MaxReplayPerEntry *int   `yaml:"max_replay_per_entry,omitempty"` // the EFFECTIVE limits, so a
	MaxReplayTotal    *int   `yaml:"max_replay_total,omitempty"`     // persisted 0 survives
	Push              bool   `yaml:"push"`                           // provenance; the flag still wins
	TestCommand       string `yaml:"test_command,omitempty"`         // the FROZEN validation command
	ValidationSource  string `yaml:"validation_source,omitempty"`    // its provenance. There is NO
	// digest member and no validation_digest key: §15's identity is DERIVED
	// from TestCommand by whoever needs it (§13.1 rule 2, §25.3)

	Universe []string `yaml:"universe"` // the full-stack Selected list in
	// the invocation's ONE TopoSort order
	PendingIntent     []string `yaml:"pending_intent"`        // the remaining set of §13.3
	CarriedCompleted  []string `yaml:"carried_completed"`     // the prior state's Completed, verbatim
	CarriedFailed     string   `yaml:"carried_failed_branch"` // the prior state's FailedBranch
	PriorPendingCount int      `yaml:"prior_pending_count"`   // len(prior.Pending) — the number the
	// shipped resume prints (§12.3 row 7)

	PriorLegacyPresent bool   `yaml:"prior_legacy_present"`          // false on a FRESH run only
	PriorLegacySHA256  string `yaml:"prior_legacy_sha256,omitempty"` // 64-lower-hex over the bytes
	PriorLegacyBase64  string `yaml:"prior_legacy_base64,omitempty"` // std base64 of the CAPTURED
	// bytes, verbatim
}

// SaveGuardedLegacySentinel installs the sentinel at .sync-state.yaml through
// ONE conditional atomic write at the shipped 0644 mode. expect is the
// captured prior bytes; nil means "expect the path to be absent" (the fresh
// route). The write refuses — writing nothing, returning ErrSyncStateChanged
// — when the current file is not what expect says it is, so the path is
// either the old bytes/absent or the complete sentinel, never anything
// between.
// MarshalGuardedLegacySentinel renders the exact bytes
// SaveGuardedLegacySentinel installs. Both go through this one function, so
// the setup of §13.2a can hand its rollback the precise `expect` bytes it is
// about to write without re-deriving them from a second, possibly divergent
// encoder — and without silently swallowing a marshal failure.
func MarshalGuardedLegacySentinel(s *GuardedLegacySentinel) ([]byte, error) {
	data, err := yaml.Marshal(s)
	if err != nil {
		return nil, fmt.Errorf("marshal guarded sentinel: %w", err)
	}
	return data, nil
}

func SaveGuardedLegacySentinel(featurePath string, s *GuardedLegacySentinel, expect []byte) error {
	path := SyncStatePath(featurePath)
	if err := syncIOFault(SyncIOWriteSentinel, path); err != nil {
		return err
	}
	current, err := os.ReadFile(path)
	switch {
	case err == nil:
		if expect == nil || !bytes.Equal(current, expect) {
			return ErrSyncStateChanged
		}
	case errors.Is(err, fs.ErrNotExist):
		if expect != nil {
			return ErrSyncStateChanged
		}
	default:
		return fmt.Errorf("read sync state: %w", err)
	}
	data, err := MarshalGuardedLegacySentinel(s)
	if err != nil {
		return err
	}
	if err := atomicWriteFile(path, data, 0644); err != nil {
		return fmt.Errorf("write sync sentinel: %w", err)
	}
	return nil
}

// GuardedLegacySentinelVerdict is the closed verdict domain of
// InspectGuardedLegacySentinel.
type GuardedLegacySentinelVerdict string

const (
	SentinelNotApplicable GuardedLegacySentinelVerdict = "not-applicable" // the zero value
	SentinelAbsent        GuardedLegacySentinelVerdict = "absent"
	SentinelNotGuarded    GuardedLegacySentinelVerdict = "not-guarded" // real legacy state, or
	// a PLAIN shipped sentinel
	SentinelValid        GuardedLegacySentinelVerdict = "valid"
	SentinelSymlink      GuardedLegacySentinelVerdict = "symlink"
	SentinelUnreadable   GuardedLegacySentinelVerdict = "unreadable"
	SentinelUnsupported  GuardedLegacySentinelVerdict = "unsupported-version"
	SentinelCorrupt      GuardedLegacySentinelVerdict = "corrupt"
	SentinelForeign      GuardedLegacySentinelVerdict = "foreign"
	SentinelHashMismatch GuardedLegacySentinelVerdict = "hash-mismatch"
)

// GuardedLegacySentinelView is the decided view. Sentinel and Prior are
// non-nil ONLY under SentinelValid, so no caller can resume from a document
// this ladder did not accept.
type GuardedLegacySentinelView struct {
	Verdict  GuardedLegacySentinelVerdict
	Path     string
	Sentinel *GuardedLegacySentinel // the decoded extension
	Prior    *SyncState             // the VERIFIED backed-up legacy state; nil when
	// PriorLegacyPresent is false
	Version int   // the raw guarded_state_version, for the unsupported sentence
	Err     error // the underlying I/O or decode error; sanitized by cli
}

// isLowerHex64 reports whether s is exactly 64 lowercase hex characters, the
// shape of a SHA-256 digest as this sentinel persists it.
func isLowerHex64(s string) bool {
	if len(s) != 64 {
		return false
	}
	for _, r := range s {
		if (r < '0' || r > '9') && (r < 'a' || r > 'f') {
			return false
		}
	}
	return true
}

// InspectGuardedLegacySentinel performs ONE Lstat and at most ONE read of a
// regular file, follows no symlink, and applies the ordered ladder of §13.6
// rule 2c: the first failing clause decides, and only SentinelValid resumes.
// It refuses nothing and prints nothing: internal decides, cli speaks.
func InspectGuardedLegacySentinel(featurePath, feature string) GuardedLegacySentinelView {
	path := SyncStatePath(featurePath)
	view := GuardedLegacySentinelView{Path: path}

	info, err := os.Lstat(path)
	switch {
	case errors.Is(err, fs.ErrNotExist):
		view.Verdict = SentinelAbsent
		return view
	case err != nil:
		view.Verdict = SentinelUnreadable
		view.Err = err
		return view
	case info.Mode()&os.ModeSymlink != 0:
		view.Verdict = SentinelSymlink
		return view
	case !info.Mode().IsRegular():
		view.Verdict = SentinelUnreadable
		return view
	}

	data, err := os.ReadFile(path)
	if err != nil {
		view.Verdict = SentinelUnreadable
		view.Err = err
		return view
	}
	if len(data) == 0 {
		view.Verdict = SentinelUnreadable
		return view
	}
	var raw GuardedLegacySentinel
	if err := yaml.Unmarshal(data, &raw); err != nil {
		view.Verdict = SentinelUnreadable
		view.Err = err
		return view
	}

	if !isSyncMarker(raw.FailedBranch) {
		view.Verdict = SentinelNotGuarded
		return view
	}
	if raw.GuardedStateVersion == 0 {
		view.Verdict = SentinelNotGuarded
		return view
	}
	if raw.GuardedStateVersion != GuardedLegacySentinelVersion {
		view.Verdict = SentinelUnsupported
		view.Version = raw.GuardedStateVersion
		return view
	}
	if raw.Route != RouteLegacy || raw.Marker != raw.FailedBranch || !isSyncMarker(raw.Marker) ||
		raw.OwnerToken == "" || raw.Feature == "" {
		view.Verdict = SentinelCorrupt
		return view
	}
	if raw.Feature != feature {
		view.Verdict = SentinelForeign
		return view
	}

	if !raw.PriorLegacyPresent {
		if raw.PriorLegacyBase64 != "" || raw.PriorLegacySHA256 != "" || raw.PriorPendingCount != 0 ||
			len(raw.CarriedCompleted) != 0 || raw.CarriedFailed != "" {
			view.Verdict = SentinelCorrupt
			return view
		}
		view.Verdict = SentinelValid
		view.Sentinel = &raw
		return view
	}

	decoded, err := base64.StdEncoding.DecodeString(raw.PriorLegacyBase64)
	if err != nil {
		view.Verdict = SentinelHashMismatch
		return view
	}
	if !isLowerHex64(raw.PriorLegacySHA256) {
		view.Verdict = SentinelHashMismatch
		return view
	}
	sum := sha256.Sum256(decoded)
	if raw.PriorLegacySHA256 != hex.EncodeToString(sum[:]) {
		view.Verdict = SentinelHashMismatch
		return view
	}

	var prior SyncState
	if err := yaml.Unmarshal(decoded, &prior); err != nil {
		view.Verdict = SentinelCorrupt
		return view
	}
	if isSyncMarker(prior.FailedBranch) {
		view.Verdict = SentinelCorrupt
		return view
	}
	if raw.PriorPendingCount != len(prior.Pending) {
		view.Verdict = SentinelCorrupt
		return view
	}

	view.Verdict = SentinelValid
	view.Sentinel = &raw
	view.Prior = &prior
	return view
}

// GuardedLegacySentinelResumable is the ONE dispatch predicate (§19.2): a
// classifier cell 4 — sentinel present, payload absent — whose sentinel this
// ladder accepted. It is evaluated on NO other cell.
func GuardedLegacySentinelResumable(st SyncExternalState, v GuardedLegacySentinelView) bool {
	return st.Cell == 4 && v.Verdict == SentinelValid
}

package internal

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

// WorkspaceMode describes how tws stores metadata for a repository.
type WorkspaceMode string

const (
	// ModeExternal stores metadata in a sibling directory (<repo>.tws).
	// This is the default and preserves the original behaviour.
	ModeExternal WorkspaceMode = "external"

	// ModeCheckout stores metadata inside the repository at <repo>/.tws.
	ModeCheckout WorkspaceMode = "checkout"
)

// Capabilities reports what features a given workspace mode supports.
// Checkout mode retains logical stacks and decisions but cannot create
// linked worktrees because it stores metadata inside the repo tree.
type Capabilities struct {
	Stack           bool // logical stack/decisions
	LinkedWorktrees bool // git worktree add support
}

// Workspace is the resolved identity and layout for a single repository.
type Workspace struct {
	// RepoRoot is the absolute, cleaned repository path.
	RepoRoot string

	// Mode is the resolved workspace mode (external or checkout).
	Mode WorkspaceMode

	// MetadataRoot is the absolute path that holds tws state.
	// External: <repo>.tws   Checkout: <repo>/.tws
	MetadataRoot string

	// StableID is a deterministic identifier derived from the canonical
	// repo path. Computed on each resolution, not persisted.
	StableID string

	// Caps describes mode-specific capabilities.
	Caps Capabilities
}

// capsFor returns capabilities for a given mode.
func capsFor(mode WorkspaceMode) Capabilities {
	switch mode {
	case ModeCheckout:
		return Capabilities{Stack: true, LinkedWorktrees: false}
	default: // external
		return Capabilities{Stack: true, LinkedWorktrees: true}
	}
}

// stableID computes a deterministic hex ID from a canonical path.
// It uses the absolute, cleaned path (with symlinks resolved when
// possible). Relocating the repository changes the ID; use the
// persisted workspace marker identity for move-stable identity.
func stableID(canonicalPath string) string {
	h := sha256.Sum256([]byte(canonicalPath))
	return fmt.Sprintf("%x", h[:8])
}

// workspaceMarkerIDFile is the tool-owned file holding a workspace's
// persistent opaque identity. It lives inside the tool-owned metadata
// directory: <repo>/.tws for checkout workspaces and
// <workspace>/.tws-workspace for external workspaces.
const workspaceMarkerIDFile = "workspace-id"

var markerIDRegexp = regexp.MustCompile(`^[0-9a-f]{32}$`)

// CheckoutMarkerDir returns the shared Git metadata directory that holds the
// persistent marker identity of a checkout workspace.
func CheckoutMarkerDir(repoRoot string) string {
	if dir, err := GitMarkerDir(repoRoot); err == nil {
		return dir
	}
	return filepath.Join(repoRoot, ".git", "tws")
}

// ExternalMarkerDir returns the tool-owned metadata directory that holds
// the persistent marker identity of an external workspace.
func ExternalMarkerDir(workspaceRoot string) string {
	return filepath.Join(workspaceRoot, workspaceMarker)
}

// GitMarkerDir returns the shared Git metadata directory for a repository.
// Linked worktrees resolve to the same common directory as the main checkout.
func GitMarkerDir(repoRoot string) (string, error) {
	out, err := exec.Command("git", "-C", repoRoot, "rev-parse", "--git-common-dir").Output()
	if err != nil {
		return "", fmt.Errorf("resolving Git marker directory: %w", err)
	}
	dir := strings.TrimSpace(string(out))
	if !filepath.IsAbs(dir) {
		dir = filepath.Join(repoRoot, dir)
	}
	return filepath.Join(canonicalize(dir), "tws"), nil
}

// ReadWorkspaceMarkerID reads the persistent marker identity stored in a
// tool-owned metadata directory. It returns an empty string when no marker
// file exists, and an error when the marker file is unreadable or malformed.
// It never creates or mutates anything on disk.
func ReadWorkspaceMarkerID(markerDir string) (string, error) {
	path := filepath.Join(markerDir, workspaceMarkerIDFile)
	data, err := os.ReadFile(path)
	if errors.Is(err, fs.ErrNotExist) {
		return "", nil
	}
	if err != nil {
		return "", fmt.Errorf("reading workspace marker %s: %w", path, err)
	}
	id := strings.TrimSpace(string(data))
	if !markerIDRegexp.MatchString(id) {
		return "", fmt.Errorf("workspace marker %s is malformed", path)
	}
	return id, nil
}

// EnsureWorkspaceMarkerID returns the persistent marker identity for a
// tool-owned metadata directory, creating it when absent. Creation is
// atomic: the identity is written to a temporary file and linked into
// place, so a concurrent creator never loses its identity and a partial
// write is never observed as a valid marker.
func EnsureWorkspaceMarkerID(markerDir string) (string, error) {
	if id, err := ReadWorkspaceMarkerID(markerDir); err != nil || id != "" {
		return id, err
	}
	if err := os.MkdirAll(markerDir, 0755); err != nil {
		return "", fmt.Errorf("creating workspace marker dir %s: %w", markerDir, err)
	}

	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		return "", fmt.Errorf("generating workspace marker: %w", err)
	}
	id := hex.EncodeToString(buf)

	tmp, err := os.CreateTemp(markerDir, ".workspace-id-*.tmp")
	if err != nil {
		return "", fmt.Errorf("creating workspace marker: %w", err)
	}
	tmpName := tmp.Name()
	cleanup := func(primary error) error {
		return errors.Join(primary, os.Remove(tmpName))
	}
	if _, err := tmp.WriteString(id + "\n"); err != nil {
		return "", cleanup(errors.Join(fmt.Errorf("writing workspace marker: %w", err), tmp.Close()))
	}
	if err := tmp.Sync(); err != nil {
		return "", cleanup(errors.Join(fmt.Errorf("syncing workspace marker: %w", err), tmp.Close()))
	}
	if err := tmp.Close(); err != nil {
		return "", cleanup(fmt.Errorf("closing workspace marker: %w", err))
	}
	if err := os.Chmod(tmpName, 0600); err != nil {
		return "", cleanup(fmt.Errorf("setting workspace marker permissions: %w", err))
	}

	target := filepath.Join(markerDir, workspaceMarkerIDFile)
	if err := os.Link(tmpName, target); err != nil {
		if errors.Is(err, fs.ErrExist) {
			// Another writer won the race; adopt its identity.
			existing, readErr := ReadWorkspaceMarkerID(markerDir)
			return existing, cleanup(readErr)
		}
		return "", cleanup(fmt.Errorf("installing workspace marker atomically: %w", err))
	}
	if err := os.Remove(tmpName); err != nil {
		return "", fmt.Errorf("cleaning up workspace marker temp file: %w", err)
	}
	return id, nil
}

// EnsureExternalWorkspaceMarker creates the standard `.tws-workspace`
// marker directory for an external workspace root. The persistent identity
// file is created separately on explicit registry enrollment.
func EnsureExternalWorkspaceMarker(workspaceRoot string) error {
	if workspaceRoot == "" {
		return fmt.Errorf("empty workspace root")
	}
	markerDir := ExternalMarkerDir(workspaceRoot)
	if err := os.MkdirAll(markerDir, 0755); err != nil {
		return fmt.Errorf("creating workspace marker: %w", err)
	}
	return nil
}

// canonicalize returns an absolute, cleaned path. It resolves symlinks
// when possible; on error it falls back to filepath.Abs + filepath.Clean.
func canonicalize(p string) string {
	if resolved, err := filepath.EvalSymlinks(p); err == nil {
		return filepath.Clean(resolved)
	}
	return cleanAbsolute(p)
}

func cleanAbsolute(p string) string {
	abs, err := filepath.Abs(p)
	if err != nil {
		return filepath.Clean(p)
	}
	return filepath.Clean(abs)
}

// parseMode interprets a raw string as a WorkspaceMode.
// Unknown values return empty string and false.
func parseMode(raw string) (WorkspaceMode, bool) {
	switch WorkspaceMode(raw) {
	case ModeExternal:
		return ModeExternal, true
	case ModeCheckout:
		return ModeCheckout, true
	case "":
		return "", false
	default:
		return "", false
	}
}

// ResolveCurrentWorkspace determines the workspace for a given repo root
// and config. It checks, in order:
//
//  1. Explicit workspace_mode in the per-repo config (.tws/config.yaml).
//  2. Presence of .tws/config.yaml without workspace_mode -> external (legacy).
//  3. Default: external.
//
// This function is a pure resolver; it never calls TwsRoot or any path
// function that might recurse back into resolution.
func ResolveCurrentWorkspace(repoRoot string, cfg Config) Workspace {
	original := cleanAbsolute(repoRoot)
	canon := canonicalize(repoRoot)

	// Read per-repo config to look for explicit workspace_mode.
	repoConfigFile := filepath.Join(canon, ".tws", "config.yaml")
	repoCfg := loadConfigFile(repoConfigFile)

	var mode WorkspaceMode
	if m, ok := parseMode(repoCfg.WorkspaceMode); ok {
		mode = m
	} else {
		// Legacy: .tws/config.yaml exists but no workspace_mode -> external.
		// Or no config at all -> external.
		mode = ModeExternal
	}

	var metadataRoot string
	switch mode {
	case ModeCheckout:
		metadataRoot = filepath.Join(canon, ".tws")
	default: // external
		metadataRoot = resolveExternalRoot(original, canon, cfg)
	}

	return Workspace{
		RepoRoot:     canon,
		Mode:         mode,
		MetadataRoot: metadataRoot,
		StableID:     stableID(canon),
		Caps:         capsFor(mode),
	}
}

// resolveExternalRoot computes the external metadata root for a repo.
// Priority: original-path config key -> canonical-path config key -> sibling directory.
// This preserves legacy config entries that intentionally use a symlinked repo path.
func resolveExternalRoot(originalRepoRoot, canonicalRepoRoot string, cfg Config) string {
	if root, ok := cfg.Workspaces[originalRepoRoot]; ok {
		return root
	}
	if root, ok := cfg.Workspaces[canonicalRepoRoot]; ok {
		return root
	}
	return canonicalRepoRoot + ".tws"
}

// FeaturePath returns the canonical write path for NEW features.
// For external mode: MetadataRoot/<feature>.
// For checkout mode: MetadataRoot/features/<feature> (new layout).
// Use this for creating new features. For reading existing features that may
// be in legacy layout, use ResolveFeaturePath.
func (w Workspace) FeaturePath(feature string) string {
	if w.Mode == ModeCheckout {
		return filepath.Join(w.MetadataRoot, "features", feature)
	}
	return filepath.Join(w.MetadataRoot, feature)
}

// LegacyFeaturePath returns the legacy feature path (MetadataRoot/<feature>).
// Used only for migration reads and backward-compatible lookup.
func (w Workspace) LegacyFeaturePath(feature string) string {
	return filepath.Join(w.MetadataRoot, feature)
}

// WorktreePath returns the worktree directory within a feature.
// In checkout mode, linked worktrees are not supported; returns empty string.
func (w Workspace) WorktreePath(feature, worktree string) string {
	if w.Mode == ModeCheckout {
		return ""
	}
	return filepath.Join(w.MetadataRoot, feature, "worktrees", worktree)
}

// resolveWorkspaceMetadataRoot is the backend boundary function.
// It resolves the metadata root for a given repo, accounting for
// workspace mode. Called by resolveTwsRoot to route through the
// workspace layer while preserving byte-for-byte external outputs.
//
// If repoRoot is empty or repoErr is non-nil, this returns empty
// string (caller should fall back to home dir or env override).
func resolveWorkspaceMetadataRoot(repoRoot string, repoErr error, cfg Config) string {
	if repoErr != nil || repoRoot == "" {
		return ""
	}
	ws := ResolveCurrentWorkspace(repoRoot, cfg)
	return ws.MetadataRoot
}

// metadataRootExists checks if the metadata root directory exists on disk.
func metadataRootExists(root string) bool {
	info, err := os.Stat(root)
	return err == nil && info.IsDir()
}

func inferExternalRepoRoot(metadataRoot string, cfg Config) (string, error) {
	return inferExternalRepoRootWith(metadataRoot, cfg, MainRepoRootIn)
}

func inferExternalRepoRootWith(metadataRoot string, cfg Config, resolveRepoRoot func(string) (string, error)) (string, error) {
	metadataRoot = canonicalize(metadataRoot)
	candidates := make(map[string]bool)
	addCandidate := func(path string) {
		if path == "" {
			return
		}
		if root, err := resolveRepoRoot(path); err == nil {
			candidates[canonicalize(root)] = true
		}
	}

	for repo, configuredRoot := range cfg.Workspaces {
		if canonicalize(configuredRoot) == metadataRoot {
			addCandidate(repo)
		}
	}
	if siblingRepo, ok := strings.CutSuffix(metadataRoot, ".tws"); ok {
		addCandidate(siblingRepo)
	}

	entries, _ := os.ReadDir(metadataRoot)
	for _, featureEntry := range entries {
		if !featureEntry.IsDir() || featureEntry.Name() == workspaceMarker {
			continue
		}
		featurePath := filepath.Join(metadataRoot, featureEntry.Name())
		stack, err := LoadStack(featurePath)
		if err != nil {
			continue
		}
		for _, entry := range stack.Branches {
			if entry.Repo != "" || entry.Archived {
				continue
			}
			worktreePath := filepath.Join(featurePath, "worktrees", entry.Name)
			if _, err := os.Stat(worktreePath); err == nil {
				addCandidate(worktreePath)
			}
		}
	}

	if len(candidates) == 1 {
		for root := range candidates {
			return root, nil
		}
	}
	if len(candidates) > 1 {
		var roots []string
		for root := range candidates {
			roots = append(roots, root)
		}
		sort.Strings(roots)
		return "", fmt.Errorf("external workspace %s maps to multiple default repositories (%s); run from a worktree or repository", metadataRoot, strings.Join(roots, ", "))
	}
	return "", fmt.Errorf("cannot determine source repository for external workspace %s; run from a worktree or configure the workspace path", metadataRoot)
}

// ResolveReparentWorkspaceWithoutGit is the missing-executable fallback used
// only by the reparent plan route. It never treats cwd itself as a repository:
// a repository root must be proven by a real .git directory/file, or inferred
// from a real external workspace whose configured/worktree candidates carry
// such a marker.
func ResolveReparentWorkspaceWithoutGit(cwd string, cfg Config) (Workspace, error) {
	if repoRoot, err := filesystemGitWorktreeRootIn(cwd); err == nil {
		return ResolveCurrentWorkspaceE(repoRoot, cfg)
	}
	metadataRoot := ""
	if envRoot := strings.TrimSpace(os.Getenv("TWS_ROOT")); envRoot != "" {
		root := canonicalize(cleanAbsolute(envRoot))
		current := canonicalize(cleanAbsolute(cwd))
		if current == root || strings.HasPrefix(current, root+string(filepath.Separator)) {
			metadataRoot = root
		}
	}
	if metadataRoot == "" {
		metadataRoot = DetectWorkspaceRoot(cwd, cfg)
	}
	if metadataRoot == "" || !metadataRootExists(metadataRoot) {
		return Workspace{}, fmt.Errorf("not inside a filesystem-proven git repository or tws workspace")
	}
	repoRoot, err := inferExternalRepoRootWith(metadataRoot, cfg, filesystemGitWorktreeRootIn)
	if err != nil {
		return Workspace{}, err
	}
	return Workspace{
		RepoRoot:     repoRoot,
		Mode:         ModeExternal,
		MetadataRoot: canonicalize(metadataRoot),
		StableID:     stableID(repoRoot),
		Caps:         capsFor(ModeExternal),
	}, nil
}

func filesystemGitWorktreeRootIn(path string) (string, error) {
	current := cleanAbsolute(path)
	if info, err := os.Stat(current); err == nil && !info.IsDir() {
		current = filepath.Dir(current)
	}
	for {
		if root, ok := filesystemGitRepositoryRoot(current); ok {
			return root, nil
		}
		parent := filepath.Dir(current)
		if parent == current {
			break
		}
		current = parent
	}
	return "", fmt.Errorf("%s is not inside a filesystem-proven git worktree", path)
}

func filesystemGitRepositoryRoot(root string) (string, bool) {
	marker := filepath.Join(root, ".git")
	info, err := os.Lstat(marker)
	if err != nil || info.Mode()&os.ModeSymlink != 0 {
		return "", false
	}
	if info.IsDir() {
		head, headErr := os.Lstat(filepath.Join(marker, "HEAD"))
		objects, objectsErr := os.Lstat(filepath.Join(marker, "objects"))
		if headErr != nil || !head.Mode().IsRegular() ||
			objectsErr != nil || !objects.IsDir() {
			return "", false
		}
		return canonicalize(root), true
	}
	if !info.Mode().IsRegular() {
		return "", false
	}
	data, err := os.ReadFile(marker)
	if err != nil || len(data) > 4096 {
		return "", false
	}
	line := strings.TrimSpace(string(data))
	if !strings.HasPrefix(line, "gitdir:") {
		return "", false
	}
	gitDir := strings.TrimSpace(strings.TrimPrefix(line, "gitdir:"))
	if !filepath.IsAbs(gitDir) {
		gitDir = filepath.Join(root, gitDir)
	}
	gitDir = filepath.Clean(gitDir)
	dirInfo, err := os.Lstat(gitDir)
	if err != nil || !dirInfo.IsDir() || dirInfo.Mode()&os.ModeSymlink != 0 {
		return "", false
	}
	head, err := os.Lstat(filepath.Join(gitDir, "HEAD"))
	if err != nil || !head.Mode().IsRegular() {
		return "", false
	}
	commonDir := gitDir
	if commonData, readErr := os.ReadFile(filepath.Join(gitDir, "commondir")); readErr == nil {
		commonDir = strings.TrimSpace(string(commonData))
		if !filepath.IsAbs(commonDir) {
			commonDir = filepath.Join(gitDir, commonDir)
		}
		commonDir = filepath.Clean(commonDir)
	}
	if filepath.Base(commonDir) == ".git" {
		return canonicalize(filepath.Dir(commonDir)), true
	}
	return canonicalize(root), true
}

// ResolveCurrentWorkspaceE is an error-returning resolver for use in CLI
// commands. Unlike ResolveCurrentWorkspace (which silently defaults to
// external mode), this function returns an error when the per-repo config
// contains an invalid workspace_mode value.
func ResolveCurrentWorkspaceE(repoRoot string, cfg Config) (Workspace, error) {
	original := cleanAbsolute(repoRoot)
	canon := canonicalize(repoRoot)

	repoConfigFile := filepath.Join(canon, ".tws", "config.yaml")
	repoCfg := loadConfigFile(repoConfigFile)

	var mode WorkspaceMode
	if repoCfg.WorkspaceMode != "" {
		m, ok := parseMode(repoCfg.WorkspaceMode)
		if !ok {
			return Workspace{}, fmt.Errorf("invalid workspace_mode %q in %s", repoCfg.WorkspaceMode, repoConfigFile)
		}
		mode = m
	} else {
		mode = ModeExternal
	}

	var metadataRoot string
	switch mode {
	case ModeCheckout:
		metadataRoot = filepath.Join(canon, ".tws")
	default:
		metadataRoot = resolveExternalRoot(original, canon, cfg)
	}

	return Workspace{
		RepoRoot:     canon,
		Mode:         mode,
		MetadataRoot: metadataRoot,
		StableID:     stableID(canon),
		Caps:         capsFor(mode),
	}, nil
}

// RequireWorkspace resolves the workspace for the current repo root,
// returning a stable CLI error if the repo root cannot be determined
// or the workspace mode is invalid. Commands should use this instead
// of silently ignoring errors from MainRepoRoot or ResolveCurrentWorkspace.
func RequireWorkspace() (Workspace, error) {
	cfg := LoadConfig()
	if repoRoot, err := MainRepoRoot(); err == nil {
		return ResolveCurrentWorkspaceE(repoRoot, cfg)
	}

	cwd, err := os.Getwd()
	if err != nil {
		return Workspace{}, err
	}
	metadataRoot := DetectWorkspaceRoot(cwd, cfg)
	if metadataRoot == "" || !metadataRootExists(metadataRoot) {
		return Workspace{}, fmt.Errorf("not inside a git repository or tws workspace")
	}
	repoRoot, err := inferExternalRepoRoot(metadataRoot, cfg)
	if err != nil {
		return Workspace{}, err
	}
	return Workspace{
		RepoRoot:     repoRoot,
		Mode:         ModeExternal,
		MetadataRoot: canonicalize(metadataRoot),
		StableID:     stableID(repoRoot),
		Caps:         capsFor(ModeExternal),
	}, nil
}
